#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
=====================================================================
  EMBERFALL  -  The Depths of Hollowdeep
  A retro 2D action-RPG in ONE Python file.   (pygame 2.x)

  Run:   pip install pygame
         python emberfall.py

  Everything is generated by code: pixel art, tiles, animation,
  sound effects and the chiptune soundtrack. No asset files needed.

  CONTROLS
    Move ........ Arrow keys / WASD
    Attack ...... J or Z          Fireball .. K or X   (3 MP)
    Dash ........ Space or L      Interact .. E or Enter
    Health potion Q               Mana potion R
    Inventory ... I or Tab        Pause ..... Esc
    Mute ........ M               Fullscreen  F11

  ENDGAME (after you defeat the Hollow King)
    Guard Torvin  -> Guild bounty board + the endless ABYSS
    Old Gus       -> fishing (buy better rods)
    Hero menu (I) -> SKILLS tree, TROPHIES, guild BOUNTIES
    Rematch the king on the throne for scaling rewards.

  THE VILLAGE OF EMBERFALL (a big open village, press E near anything)
    Farm (plots grow in real time, even while you adventure), Orchard, Quarry (mine ore, upgrade your pick),
    Lake and pier (fishing), Colosseum (4 tiers of wave fights), Lucky Corner (dice), Hot Springs (heal),
    Library (bestiary), Chapel (blessings), Town Hall (7 town projects and Daily Errands with a streak),
    Rowan's daily wares, the Bakery, 12 hidden Ember Sprites (find all for a wisp companion),
    daily buried treasure, a jukebox with every song, and the Workbench and Cauldron on the plaza.

  python emberfall.py --trailer     plays the cinematic trailer
  python emberfall.py --teaser      plays the 90 second teaser
=====================================================================
"""
