class Audio:
    def __init__(self):
        self.ok = False
        self.sfx = {}
        self.music = {}
        self.cur = None
        self.want = None
        self.loop = True
        self.music_vol = 0.5
        self.sfx_vol = 0.8
        self.muted = False
        self.last = {}
        self.sr = 22050
        self.chn = 1
        self.switch_t = 0.0
        self.mch = None
        self.progress = 0
        self.lock = False
        self.rec = None
        self.clock = 0.0
        try:
            if not pygame.mixer.get_init():
                pygame.mixer.init(22050, -16, 1, 512)
            self.sr, fmt, self.chn = pygame.mixer.get_init()
            pygame.mixer.set_num_channels(20)
            pygame.mixer.set_reserved(1)
            self.mch = pygame.mixer.Channel(0)
            self.ok = (fmt == -16)
        except Exception:
            self.ok = False
        if self.ok:
            try:
                th = threading.Thread(target=self._build, daemon=True)
                th.start()
            except Exception:           # no threads (some web builds): run silent rather than freeze
                self.ok = False

    def build_score(self):
        """background-thread: compose the trailer score (takes a few seconds)"""
        try:
            for _ in range(400):
                if 'victory' in self.music or not self.ok:
                    break
                time.sleep(0.05)
            self.score_pct = 0.0
            buf = getattr(self, 'score_fn', build_trailer_score)(lambda f: setattr(self, 'score_pct', f))
            self.music['trailer'] = self._pack(buf, 0.6)
        except Exception as e:
            sys.stderr.write("score build failed: %r\n" % (e,))
            self.music['trailer'] = self._pack([0.0] * self.sr, 0.1)

    def _pack(self, buf, gain=1.0):
        pk = []
        g = 30000 * gain
        if self.chn == 2:
            pk = array.array('h', [0]) * (len(buf) * 2)
            for i, x in enumerate(buf):
                v = int(max(-1.0, min(1.0, x)) * g)
                pk[2 * i] = v
                pk[2 * i + 1] = v
        else:
            pk = array.array('h', [int(max(-1.0, min(1.0, x)) * g) for x in buf])
        return pygame.mixer.Sound(buffer=pk.tobytes())

    def _build(self):
        global SR
        try:
            SR = self.sr
            for k, v in make_sfx().items():
                if v:
                    self.sfx[k] = self._pack(v, 0.9)
            for name in ('title', 'town', 'shop', 'crypt', 'depths', 'boss', 'abyss', 'spore', 'grotto', 'tomb', 'frost', 'foundry', 'manor'):
                self.music[name] = self._pack(build_track(MUSIC[name]), 0.85)
                time.sleep(0.01)
            self.music['victory'] = self._pack(build_jingle('victory'), 0.9)
            self.music['gameover'] = self._pack(build_jingle('gameover'), 0.9)
        except Exception as e:  # never let audio kill the game
            sys.stderr.write("audio build failed: %r\n" % (e,))

    # -- playback
    def play(self, name, vol=1.0, gap=0.0):
        if self.rec is not None:
            self.rec.append((self.clock, name, vol))
        if not self.ok or self.muted:
            return
        s = self.sfx.get(name)
        if s is None:
            return
        now = time.time()
        if gap and now - self.last.get(name, 0) < gap:
            return
        self.last[name] = now
        s.set_volume(clamp(vol * self.sfx_vol, 0, 1))
        s.play()

    def music_play(self, name, loop=True, force=False):
        if self.lock and not force:
            return
        self.want = name
        self.loop = loop

    def music_stop(self):
        if self.lock:
            return
        self.want = None

    def update(self, dt):
        if not self.ok or self.mch is None:
            return
        self.mch.set_volume(0.0 if self.muted else self.music_vol)
        if self.switch_t > 0:
            self.switch_t -= dt
            return
        if self.want != self.cur:
            if self.cur is not None:
                self.mch.fadeout(300)
                self.cur = None
                self.switch_t = 0.32
                return
            snd = self.music.get(self.want) if self.want else None
            if snd is not None:
                self.mch.play(snd, loops=-1 if self.loop else 0, fade_ms=500)
                self.cur = self.want
        elif self.cur is not None and not self.loop and not self.mch.get_busy():
            self.cur = None
            self.want = None


# ---------------------------------------------------------------------
#  PIXEL-ART GENERATION  (every sprite / tile is drawn by code)
# ---------------------------------------------------------------------
OUT = (24, 14, 30)


def S(w, h):
    return pygame.Surface((w, h), pygame.SRCALPHA)


def R(s, c, x, y, w=1, h=1):
    s.fill(c, (int(x), int(y), int(w), int(h)))


def outline(s, col=OUT):
    w, h = s.get_size()
    src = s.copy()
    for y in range(h):
        for x in range(w):
            if src.get_at((x, y))[3] == 0:
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < w and 0 <= ny < h and src.get_at((nx, ny))[3] > 0:
                        s.set_at((x, y), col)
                        break
    return s


def from_art(rows, pal):
    s = S(len(rows[0]), len(rows))
    for y, row in enumerate(rows):
        for x, ch in enumerate(row):
            if ch in pal:
                s.set_at((x, y), pal[ch])
    return s


_flash_cache = {}


def flashed(img):
    k = id(img)
    f = _flash_cache.get(k)
    if f is None or f[0] is not img:
        c = img.copy()
        c.fill((255, 255, 255), special_flags=pygame.BLEND_RGB_ADD)
        f = (img, c)
        if len(_flash_cache) > 600:
            _flash_cache.clear()
        _flash_cache[k] = f
    return f[1]


_tint_cache = {}


def tinted(img, col):
    k = (id(img), col)
    f = _tint_cache.get(k)
    if f is None or f[0] is not img:
        c = img.copy()
        c.fill(col, special_flags=pygame.BLEND_RGB_ADD)
        f = (img, c)
        if len(_tint_cache) > 400:
            _tint_cache.clear()
        _tint_cache[k] = f
    return f[1]


def flip_x(s):
    return pygame.transform.flip(s, True, False)


# ---------------------------------------------------------------------
#  PEOPLE   (hero, villagers, skeletons)  -  16 x 20 canvas, feet at y=18
# ---------------------------------------------------------------------
PERSON_W, PERSON_H = 16, 20
_person_cache = {}

SKIN = (240, 196, 150)
SKIN_D = (208, 150, 112)


#  pose table: frame code -> body pose.  Frames 0-4 are the old idle/step frames (still valid).
#  oy: body drop in px, la/ra: lifted left/right leg (front/back view), wide: legs spread, nx/fx: side-view
#  near/far foot x, nl/fl: side-view foot lift, hx/tx: head / torso lean toward the facing direction,
#  hdy: head raise (-1) / drop (+1), arms: arm pose name, blink: eyes shut
POSE = {
    0: dict(),
    1: dict(oy=1, wide=1, nx=4, fx=10, arms='swingA'),
    2: dict(),
    3: dict(oy=1, wide=1, nx=10, fx=4, arms='swingB'),
    4: dict(oy=1),
    5: dict(oy=0, la=1, nx=7, fx=7, nl=1, arms='rest'),
    6: dict(oy=0, ra=1, nx=7, fx=7, fl=1, arms='rest'),
    7: dict(oy=0, wide=1, nx=8, fx=5, hx=-1, tx=-1, hdy=-1, arms='windup'),
    8: dict(oy=1, wide=1, nx=3, fx=10, hx=2, tx=2, hdy=1, arms='strike'),
    9: dict(oy=1, wide=1, nx=4, fx=9, hx=1, tx=1, arms='follow'),
    10: dict(oy=0, hx=-1, hdy=-1, blink=1, arms='drink'),
    11: dict(oy=0, hx=-1, tx=-1, hdy=-1, nx=7, fx=8, arms='flinch'),
    12: dict(oy=1, wide=1, nx=3, fx=11, hx=2, tx=1, hdy=1, arms='dash'),
    13: dict(oy=0, wide=1, nx=5, fx=9, hx=1, tx=1, arms='cast'),
    14: dict(arms='wave1'),
    15: dict(arms='wave2'),
    16: dict(blink=1),
    17: dict(oy=0, arms='hammer_up', hx=-1),
    18: dict(oy=1, arms='hammer_down', hx=1, hdy=1),
    19: dict(arms='stir1'),
    20: dict(arms='stir2'),
    21: dict(arms='wipe1'),
    22: dict(arms='wipe2'),
    23: dict(arms='talk1'),
    24: dict(arms='talk2'),
    25: dict(oy=1, wide=1, nx=5, fx=9, hdy=1, arms='rest'),          # crouch / brace
    26: dict(oy=0, arms='cheer'),
}


def _arms_front(c, name, Y, sl, sk):
    """front / back view arms.  c: canvas.  sl: sleeve colour, sk: skin"""
    def L(x, y, w, h):
        R(c, sl, x, y, w, h)

    def Hd(x, y):
        R(c, sk, x, y, 1, 1)
    a = name
    if a == 'swingA':
        L(3, Y + 7, 1, 3); Hd(3, Y + 10); L(12, Y + 9, 1, 3); Hd(12, Y + 12)
    elif a == 'swingB':
        L(3, Y + 9, 1, 3); Hd(3, Y + 12); L(12, Y + 7, 1, 3); Hd(12, Y + 10)
    elif a == 'windup':
        L(3, Y + 8, 1, 3); Hd(3, Y + 11); L(12, Y + 4, 1, 4); Hd(12, Y + 3)
    elif a == 'strike':
        L(3, Y + 8, 1, 3); Hd(3, Y + 11); L(12, Y + 8, 3, 1); Hd(15, Y + 8)
    elif a == 'follow':
        L(3, Y + 8, 1, 3); Hd(3, Y + 11); L(10, Y + 9, 3, 1); Hd(9, Y + 10)
    elif a == 'drink':
        L(3, Y + 8, 1, 3); Hd(3, Y + 11); L(12, Y + 6, 1, 3); L(11, Y + 6, 1, 1); Hd(10, Y + 5)
    elif a == 'flinch':
        L(3, Y + 6, 1, 3); Hd(3, Y + 5); L(12, Y + 6, 1, 3); Hd(12, Y + 5)
    elif a == 'dash':
        L(3, Y + 9, 1, 2); Hd(3, Y + 11); L(12, Y + 9, 1, 2); Hd(12, Y + 11)
    elif a == 'cast':
        L(4, Y + 7, 1, 2); Hd(5, Y + 6); L(11, Y + 7, 1, 2); Hd(10, Y + 6)
    elif a in ('wave1', 'wave2'):
        L(3, Y + 8, 1, 3); Hd(3, Y + 11); L(12, Y + 5, 1, 3)
        Hd(12 if a == 'wave1' else 13, Y + 4)
    elif a == 'cheer':
        L(3, Y + 4, 1, 4); Hd(3, Y + 3); L(12, Y + 4, 1, 4); Hd(12, Y + 3)
    elif a == 'hammer_up':
        L(3, Y + 8, 1, 3); Hd(3, Y + 11); L(12, Y + 4, 1, 4); Hd(12, Y + 3)
        R(c, (120, 84, 50), 12, Y + 1, 1, 2); R(c, (150, 150, 165), 11, Y - 1, 4, 2)
    elif a == 'hammer_down':
        L(3, Y + 8, 1, 3); Hd(3, Y + 11); L(12, Y + 8, 1, 3); Hd(12, Y + 11)
        R(c, (120, 84, 50), 12, Y + 12, 1, 1); R(c, (150, 150, 165), 11, Y + 13, 4, 2)
    elif a in ('stir1', 'stir2'):
        dx = 0 if a == 'stir1' else 2
        L(3, Y + 8, 1, 3); Hd(3, Y + 11); L(11, Y + 8, 2, 2); Hd(10 + dx, Y + 10)
        R(c, (150, 110, 70), 9 + dx, Y + 11, 1, 3)
    elif a in ('wipe1', 'wipe2'):
        dx = 0 if a == 'wipe1' else 2
        L(4, Y + 9, 2, 2); Hd(6, Y + 10); R(c, (200, 190, 170), 5, Y + 10, 3, 3)
        L(10, Y + 9, 2, 1); Hd(8 + dx, Y + 10)
    elif a in ('talk1', 'talk2'):
        L(3, Y + 8, 1, 3); Hd(3, Y + 11)
        if a == 'talk1':
            L(12, Y + 7, 1, 3); Hd(12, Y + 10)
        else:
            L(11, Y + 7, 2, 2); Hd(10, Y + 7)
    else:                                         # rest
        L(3, Y + 8, 1, 3); Hd(3, Y + 11); L(12, Y + 8, 1, 3); Hd(12, Y + 11)


def _arms_side(c, name, Y, sl, sk):
    """left-facing side view arm (the near arm)"""
    def L(x, y, w, h):
        R(c, sl, x, y, w, h)

    def Hd(x, y, w=1, h=1):
        R(c, sk, x, y, w, h)
    a = name
    if a == 'swingA':
        L(5, Y + 8, 3, 3); Hd(5, Y + 11, 2)
    elif a == 'swingB':
        L(7, Y + 8, 3, 3); Hd(7, Y + 11, 2)
    elif a == 'windup':
        L(9, Y + 5, 2, 3); Hd(10, Y + 4)
    elif a == 'strike':
        L(3, Y + 8, 4, 2); Hd(2, Y + 8, 1, 2)
    elif a == 'follow':
        L(4, Y + 10, 4, 2); Hd(3, Y + 11)
    elif a == 'drink':
        L(5, Y + 6, 3, 2); Hd(4, Y + 5)
    elif a == 'flinch':
        L(8, Y + 5, 2, 3); Hd(9, Y + 4)
    elif a == 'dash':
        L(8, Y + 8, 3, 2); Hd(11, Y + 8)
    elif a == 'cast':
        L(3, Y + 7, 4, 2); Hd(2, Y + 7, 1, 2)
    elif a in ('wave1', 'wave2'):
        L(5, Y + 4, 2, 4); Hd(5 if a == 'wave1' else 6, Y + 3)
    elif a == 'cheer':
        L(5, Y + 3, 2, 5); Hd(5, Y + 2)
    elif a == 'hammer_up':
        L(4, Y + 5, 3, 2); Hd(4, Y + 4)
        R(c, (120, 84, 50), 3, Y + 2, 2, 1); R(c, (150, 150, 165), 1, Y, 4, 3)
    elif a == 'hammer_down':
        L(3, Y + 8, 3, 2); Hd(3, Y + 10)
        R(c, (120, 84, 50), 2, Y + 11, 2, 1); R(c, (150, 150, 165), 0, Y + 11, 4, 3)
    elif a in ('stir1', 'stir2'):
        dx = 0 if a == 'stir1' else 1
        L(4, Y + 9, 3, 2); Hd(3 + dx, Y + 10); R(c, (150, 110, 70), 2 + dx, Y + 10, 1, 3)
    elif a in ('wipe1', 'wipe2'):
        dx = 0 if a == 'wipe1' else 1
        L(4 + dx, Y + 9, 3, 2); Hd(3 + dx, Y + 9); R(c, (200, 190, 170), 0 + dx, Y + 8, 3, 3)
    elif a in ('talk1', 'talk2'):
        if a == 'talk1':
            L(5, Y + 7, 3, 2); Hd(4, Y + 7)
        else:
            L(5, Y + 8, 3, 3); Hd(5, Y + 11, 2)
    else:
        L(6, Y + 8, 3, 3); Hd(6, Y + 11, 2)


def person_sprite(d, f, p):
    """d: 0 down, 1 up, 2 left, 3 right.  f: pose code (see POSE)"""
    key = (d, f, tuple(sorted((k, v) for k, v in p.items())))
    c = _person_cache.get(key)
    if c is not None:
        return c
    if d == 3:
        s = flip_x(person_sprite(2, f, p))
        _person_cache[key] = s
        return s
    po = POSE.get(f, {})
    s = S(PERSON_W, PERSON_H)
    legs, body, head = S(PERSON_W, PERSON_H), S(PERSON_W, PERSON_H), S(PERSON_W, PERSON_H)
    sk = p.get('skel')
    skin = p.get('skin', SKIN)
    skin_d = mul_c(skin, 0.82)
    hair = p.get('hair', (92, 58, 40))
    tun = p.get('tun', (60, 110, 200))
    trim = p.get('trim', mul_c(tun, 0.65))
    legc = p.get('leg', (74, 64, 100))
    boot = p.get('boot', (96, 62, 44))
    eye = (30, 20, 40)
    oy = po.get('oy', 0)
    B = 3
    robe = p.get('robe')
    la, ra = po.get('la', 0), po.get('ra', 0)
    blink = po.get('blink', 0)
    hdy = po.get('hdy', 0)
    arms = po.get('arms', 'rest')
    if sk:
        tun = (46, 36, 52)
        trim = (200, 192, 170)
        legc = p.get('bone', (226, 220, 200))
        boot = legc
        skin = legc
        skin_d = (180, 172, 150)
    sleeve = tun if not sk else trim
    # --- legs
    if d in (0, 1):
        spread = 1 if po.get('wide') else 0
        for lx, up in ((5 - spread, la), (9 + spread, ra)):
            top = B + 11 + oy
            bot = B + 14 - up
            if not robe:
                R(legs, legc if lx <= 5 else mul_c(legc, 0.88), lx, top, 2, max(1, bot - top - 1))
                R(legs, boot, lx, bot - 1, 2, 2)
            else:
                R(legs, boot, lx, B + 14 - up, 2, 1)
        if robe:
            R(legs, tun, 4, B + 10 + oy, 8, 4)
            R(legs, trim, 4, B + 13, 8, 1)
    else:
        nx = po.get('nx', 6)
        fxx = po.get('fx', 8)
        nl, fl = po.get('nl', 0), po.get('fl', 0)
        top = B + 11 + oy
        if not robe:
            R(legs, mul_c(legc, 0.75), fxx, top, 2, max(1, B + 13 - fl - top))
            R(legs, mul_c(boot, 0.8), fxx, B + 13 - fl, 2, 2)
            R(legs, legc, nx, top, 2, max(1, B + 13 - nl - top))
            R(legs, boot, nx, B + 13 - nl, 3, 2)
        else:
            R(legs, tun, 5, B + 10 + oy, 6, 4)
            R(legs, trim, 5, B + 13, 6, 1)
            R(legs, boot, nx if nx < 8 else 6, B + 14 - nl, 3, 1)
    # --- torso
    Y = B + oy
    if d in (0, 1):
        R(body, tun, 4, Y + 7, 8, 4)
        if sk:
            R(body, trim, 5, Y + 8, 6, 1)
            R(body, trim, 5, Y + 10, 6, 1)
            if d == 0:
                R(body, trim, 7, Y + 7, 2, 4)
        else:
            R(body, mul_c(tun, 1.18), 4, Y + 7, 8, 1)
            R(body, trim, 4, Y + 10, 8, 1)
            if d == 0:
                R(body, trim, 6, Y + 7, 4, 1)
                R(body, skin, 7, Y + 7, 2, 1)
                if p.get('buckle', True):
                    R(body, GOLD, 7, Y + 10, 2, 1)
            if p.get('apron') and d == 0:
                R(body, p['apron'], 5, Y + 8, 6, 5)
                R(body, mul_c(p['apron'], 0.8), 5, Y + 12, 6, 1)
        if p.get('cape') and d == 1:
            R(body, p['cape'], 3, Y + 7, 10, 7)
            R(body, mul_c(p['cape'], 0.7), 3, Y + 13, 10, 1)
        _arms_front(body, arms, Y, sleeve, skin)
    else:
        R(body, tun, 5, Y + 7, 6, 4)
        R(body, mul_c(tun, 1.18), 5, Y + 7, 6, 1)
        R(body, trim, 5, Y + 10, 6, 1)
        if p.get('apron'):
            R(body, p['apron'], 4, Y + 8, 2, 5)
        if p.get('cape'):
            R(body, p['cape'], 9, Y + 7, 3, 7)
        _arms_side(body, arms, Y, sleeve, skin)
    # --- head
    hy = B + 1 + oy + hdy
    if hdy < 0:
        R(body, skin_d, 7 if d != 2 else 6, B + 6 + oy, 2, 1)
    if d == 0:
        R(head, skin, 4, hy + 2, 8, 4)
        R(head, skin_d, 4, hy + 5, 8, 1)
        if not sk and not p.get('bald'):
            R(head, hair, 4, hy, 8, 2)
            R(head, hair, 4, hy + 2, 1, 2)
            R(head, hair, 11, hy + 2, 1, 2)
            if p.get('fringe', True):
                R(head, hair, 5, hy + 2, 2, 1)
        elif p.get('bald'):
            R(head, skin, 4, hy, 8, 2)
            R(head, mul_c(skin, 1.1), 5, hy, 3, 1)
        if sk:
            R(head, skin, 4, hy, 8, 2)
            R(head, (20, 12, 28), 5, hy + 3, 2, 2)
            R(head, (20, 12, 28), 9, hy + 3, 2, 2)
            R(head, (255, 90, 60), 6, hy + 3, 1, 1)
            R(head, (255, 90, 60), 10, hy + 3, 1, 1)
            R(head, (20, 12, 28), 7, hy + 5, 2, 1)
        else:
            if blink:
                R(head, eye, 6, hy + 4, 1, 1)
                R(head, eye, 9, hy + 4, 1, 1)
            else:
                R(head, eye, 6, hy + 3, 1, 2)
                R(head, eye, 9, hy + 3, 1, 2)
            if p.get('beard'):
                R(head, p['beard'], 5, hy + 4, 6, 3)
                R(head, mul_c(p['beard'], 1.2), 6, hy + 5, 4, 1)
                R(head, skin, 7, hy + 4, 2, 1)
            elif p.get('female'):
                R(head, (255, 150, 150), 5, hy + 4, 1, 1)
                R(head, (255, 150, 150), 10, hy + 4, 1, 1)
            if arms == 'drink':
                R(head, (40, 20, 30), 7, hy + 5, 2, 1)       # open mouth
    elif d == 1:
        R(head, skin, 4, hy + 2, 8, 4)
        if not sk:
            R(head, hair, 4, hy, 8, 6)
            R(head, mul_c(hair, 0.8), 4, hy + 5, 8, 1)
            if p.get('long'):
                R(head, hair, 4, hy + 6, 8, 3)
        else:
            R(head, skin, 4, hy, 8, 6)
            R(head, skin_d, 5, hy + 3, 6, 1)
    else:
        R(head, skin, 4, hy + 2, 7, 4)
        R(head, skin_d, 4, hy + 5, 7, 1)
        if not sk:
            R(head, hair, 4, hy, 8, 2)
            R(head, hair, 8, hy + 2, 4, 4)
            R(head, hair, 4, hy + 2, 1, 1)
            if p.get('long'):
                R(head, hair, 8, hy + 6, 4, 3)
            if blink:
                R(head, eye, 5, hy + 4, 1, 1)
            else:
                R(head, eye, 5, hy + 3, 1, 2)
            if p.get('beard'):
                R(head, p['beard'], 4, hy + 4, 5, 3)
        else:
            R(head, skin, 4, hy, 8, 2)
            R(head, skin, 8, hy + 2, 3, 4)
            R(head, (20, 12, 28), 5, hy + 3, 2, 2)
            R(head, (255, 90, 60), 5, hy + 3, 1, 1)
            R(head, (20, 12, 28), 4, hy + 5, 4, 1)
    # --- headwear
    hat = p.get('hat')
    hc = p.get('hatc', (150, 60, 50))
    if hat == 'cap':
        R(head, hc, 4, hy - 1, 8, 3)
        R(head, mul_c(hc, 0.7), 3 if d != 2 else 4, hy + 1, 9, 1)
    elif hat == 'helm':
        R(head, hc, 4, hy - 1, 8, 4)
        R(head, mul_c(hc, 1.25), 5, hy - 1, 5, 1)
        R(head, mul_c(hc, 0.7), 4, hy + 2, 8, 1)
        if d == 0:
            R(head, hc, 4, hy + 3, 1, 3)
            R(head, hc, 11, hy + 3, 1, 3)
            R(head, hc, 7, hy + 3, 2, 2)
        elif d == 2:
            R(head, hc, 8, hy + 3, 3, 3)
        if p.get('plume'):
            R(head, p['plume'], 7, hy - 3, 2, 2)
            R(head, p['plume'], 6, hy - 2, 4, 1)
    elif hat == 'hood':
        R(head, hc, 3, hy - 1, 10, 4)
        R(head, mul_c(hc, 0.75), 3, hy + 3, 1, 4)
        R(head, mul_c(hc, 0.75), 12, hy + 3, 1, 4)
        R(head, mul_c(hc, 1.2), 5, hy - 1, 4, 1)
    elif hat == 'wizard':
        R(head, hc, 3, hy + 1, 10, 2)
        R(head, hc, 5, hy - 1, 6, 2)
        R(head, hc, 6, hy - 3, 4, 2)
        R(head, hc, 8, hy - 5, 2, 2)
        R(head, GOLD, 5, hy + 1, 6, 1)
    elif hat == 'crown':
        R(head, GOLD, 4, hy - 1, 8, 2)
        for cx in (4, 7, 10):
            R(head, GOLD, cx, hy - 2, 2, 1)
    elif hat == 'bandana':
        R(head, hc, 4, hy, 8, 2)
        if d == 1:
            R(head, hc, 4, hy, 8, 5)
    elif hat == 'straw':
        R(head, (232, 200, 110), 2, hy + 1, 12, 1)
        R(head, (240, 214, 130), 4, hy - 1, 8, 2)
        R(head, (190, 60, 50), 4, hy + 0, 8, 1)
    if p.get('shoulder') and d in (0, 1):
        sc = p['shoulder']
        R(body, sc, 3, Y + 7, 2, 2)
        R(body, sc, 11, Y + 7, 2, 2)
    # --- composite with lean offsets (side view leans toward the facing direction = -x)
    hx = -po.get('hx', 0) if d == 2 else 0
    tx = -po.get('tx', 0) if d == 2 else 0
    s.blit(legs, (0, 0))
    s.blit(body, (tx, 0))
    s.blit(head, (hx, 0))
    outline(s)
    _person_cache[key] = s
    return s


def hero_palette(armor_tier, hurt=False):
    tiers = [
        dict(tun=(70, 120, 200), trim=(50, 80, 150)),
        dict(tun=(150, 100, 60), trim=(100, 66, 40), hat='cap', hatc=(110, 76, 48)),
        dict(tun=(150, 156, 170), trim=(96, 100, 120), hat='helm', hatc=(150, 156, 170), shoulder=(170, 176, 190)),
        dict(tun=(196, 204, 220), trim=(120, 130, 160), hat='helm', hatc=(206, 214, 232), shoulder=(220, 226, 240),
             cape=(160, 40, 50)),
        dict(tun=(150, 40, 60), trim=(255, 190, 70), hat='helm', hatc=(200, 50, 60), shoulder=(255, 190, 70),
             cape=(70, 20, 50), plume=(255, 150, 40)),
        dict(tun=(236, 216, 150), trim=(200, 150, 60), hat='helm', hatc=(246, 232, 172), shoulder=(255, 240, 190),
             cape=(240, 240, 252), plume=(255, 255, 255)),
        dict(tun=(70, 44, 120), trim=(190, 100, 255), hat='helm', hatc=(52, 30, 92), shoulder=(130, 76, 210),
             cape=(30, 16, 60), plume=(210, 110, 255)),
    ]
    p = dict(tiers[clamp(armor_tier, 0, 6)])
    p['hair'] = (92, 58, 40)
    return p


# ---------------------------------------------------------------------
#  CREATURES
# ---------------------------------------------------------------------
_creature_cache = {}


def slime_sprite(f, col):
    key = ('slime', f, col)
    c = _creature_cache.get(key)
    if c:
        return c
    s = S(16, 16)
    hs = [9, 8, 6, 8][f % 4]
    ws = [11, 12, 14, 12][f % 4]
    x = 8 - ws // 2
    y = 15 - hs
    dark = mul_c(col, 0.62)
    lite = lerp_c(col, WHITE, 0.45)
    pygame.draw.ellipse(s, dark, (x, y, ws, hs))
    pygame.draw.ellipse(s, col, (x, y, ws, max(2, hs - 2)))
    R(s, lite, x + 2, y + 1, 3, 1)
    R(s, lite, x + 2, y + 2, 1, 1)
    ey = y + hs // 2 - 1
    R(s, WHITE, 5, ey, 2, 2)
    R(s, WHITE, 9, ey, 2, 2)
    R(s, OUT, 6, ey + 1, 1, 1)
    R(s, OUT, 10, ey + 1, 1, 1)
    outline(s)
    _creature_cache[key] = s
    return s


def bat_sprite(f):
    key = ('bat', f)
    c = _creature_cache.get(key)
    if c:
        return c
    s = S(16, 16)
    body, wing, wd = (70, 50, 100), (96, 68, 130), (54, 36, 80)
    wy = [3, 6, 9][f % 3]
    for sgn in (-1, 1):
        cx = 8
        pts = [(cx + sgn * 2, 7), (cx + sgn * 7, wy), (cx + sgn * 7, wy + 4), (cx + sgn * 5, wy + 3),
               (cx + sgn * 4, wy + 5), (cx + sgn * 2, 10)]
        pygame.draw.polygon(s, wing, pts)
        pygame.draw.line(s, wd, (cx + sgn * 2, 8), (cx + sgn * 7, wy + 1))
    pygame.draw.ellipse(s, body, (6, 6, 4, 6))
    R(s, body, 6, 5, 1, 2)
    R(s, body, 9, 5, 1, 2)
    R(s, (255, 70, 70), 6, 8, 1, 1)
    R(s, (255, 70, 70), 9, 8, 1, 1)
    R(s, WHITE, 7, 10, 1, 1)
    R(s, WHITE, 8, 10, 1, 1)
    outline(s)
    _creature_cache[key] = s
    return s


def wraith_sprite(f):
    key = ('wraith', f)
    c = _creature_cache.get(key)
    if c:
        return c
    s = S(16, 20)
    cl, cd = (120, 90, 190), (72, 48, 130)
    pygame.draw.ellipse(s, cl, (3, 2, 10, 10))
    R(s, cl, 3, 7, 10, 9)
    R(s, cd, 3, 12, 10, 3)
    for i in range(5):
        h = 2 + (1 if (i + f) % 2 else 0) + (i % 2)
        R(s, cl if i % 2 else cd, 3 + i * 2, 16, 2, h)
    R(s, (30, 14, 50), 5, 6, 6, 4)
    R(s, (120, 255, 200), 6, 7, 2, 2)
    R(s, (120, 255, 200), 9, 7, 2, 2)
    R(s, (230, 220, 255), 5, 3, 3, 1)
    outline(s, (30, 14, 56))
    _creature_cache[key] = s
    return s


def spider_sprite(f):
    key = ('spider', f)
    c = _creature_cache.get(key)
    if c:
        return c
    s = S(16, 16)
    body, lite, leg = (62, 40, 84), (118, 82, 150), (42, 28, 60)
    for sgn in (-1, 1):
        for i, ly in enumerate((5, 7, 9, 11)):
            o = 1 if (i + f) % 2 else 0
            pygame.draw.line(s, leg, (8 + sgn * 2, 9), (8 + sgn * 6, ly - 1 + o))
            pygame.draw.line(s, leg, (8 + sgn * 6, ly - 1 + o), (8 + sgn * 7, ly + 3 + o))
    pygame.draw.ellipse(s, body, (4, 7, 8, 7))
    R(s, lite, 5, 8, 3, 1)
    R(s, (200, 70, 90), 7, 11, 2, 2)
    pygame.draw.ellipse(s, (84, 54, 108), (5, 4, 6, 5))
    R(s, (255, 70, 70), 6, 6, 1, 1)
    R(s, (255, 70, 70), 9, 6, 1, 1)
    R(s, WHITE, 7, 8, 1, 1)
    R(s, WHITE, 8, 8, 1, 1)
    outline(s)
    _creature_cache[key] = s
    return s


def golem_sprite(f):
    key = ('golem', f)
    c = _creature_cache.get(key)
    if c:
        return c
    s = S(22, 24)
    stone, dark, lite = (122, 122, 140), (80, 80, 98), (166, 166, 184)
    up = 3 if f == 2 else 0
    R(s, dark, 5, 17, 5, 6)
    R(s, dark, 12, 17, 5, 6)
    R(s, stone, 5, 17, 5, 2)
    R(s, stone, 12, 17, 5, 2)
    R(s, stone, 4, 8, 14, 10)
    R(s, lite, 4, 8, 14, 2)
    R(s, dark, 4, 16, 14, 2)
    bob = 1 if f == 1 else 0
    R(s, stone, 0, 9 - up * 2 + bob, 4, 9)
    R(s, stone, 18, 9 - up * 2 + bob, 4, 9)
    R(s, dark, 0, 16 - up * 3 + bob, 4, 3)
    R(s, dark, 18, 16 - up * 3 + bob, 4, 3)
    R(s, lite, 0, 9 - up * 2 + bob, 4, 1)
    R(s, lite, 18, 9 - up * 2 + bob, 4, 1)
    R(s, stone, 7, 2, 8, 7)
    R(s, lite, 7, 2, 8, 1)
    R(s, dark, 7, 8, 8, 1)
    ec = (255, 200, 80) if f == 2 else (255, 140, 40)
    R(s, ec, 8, 4, 2, 2)
    R(s, ec, 12, 4, 2, 2)
    R(s, (255, 120, 30), 9, 11, 4, 3)
    R(s, (255, 230, 140), 10, 12, 2, 1)
    R(s, dark, 6, 13, 2, 1)
    R(s, dark, 14, 10, 1, 2)
    outline(s)
    _creature_cache[key] = s
    return s


def imp_sprite(f):
    key = ('imp', f)
    c = _creature_cache.get(key)
    if c:
        return c
    s = S(16, 18)
    red, dark, belly = (212, 56, 52), (140, 30, 40), (240, 120, 90)
    wy = 3 if f == 0 else 5
    for sgn in (-1, 1):
        pygame.draw.polygon(s, dark, [(8 + sgn * 2, 8), (8 + sgn * 7, wy), (8 + sgn * 6, wy + 5), (8 + sgn * 3, 11)])
    pygame.draw.ellipse(s, red, (5, 7, 6, 7))
    R(s, belly, 7, 9, 2, 3)
    pygame.draw.ellipse(s, red, (4, 2, 8, 7))
    R(s, (250, 236, 200), 4, 0, 1, 3)
    R(s, (250, 236, 200), 11, 0, 1, 3)
    R(s, (255, 240, 120), 6, 5, 1, 1)
    R(s, (255, 240, 120), 9, 5, 1, 1)
    R(s, (40, 10, 20), 7, 7, 2, 1)
    R(s, red, 5, 14, 2, 2)
    R(s, red, 9, 14, 2, 2)
    R(s, dark, 11, 12, 3, 1)
    R(s, (255, 190, 60) if f == 0 else (255, 120, 40), 13, 10, 2, 3)
    R(s, (255, 250, 190), 13, 11, 1, 1)
    outline(s)
    _creature_cache[key] = s
    return s


ELITE_COL = {'frenzied': (255, 90, 60), 'volatile': (255, 210, 70), 'thorned': (120, 255, 140)}
_elite_cache = {}


def elite_wrap(im, col):
    k = (id(im), col)
    f = _elite_cache.get(k)
    if f is None or f[0] is not im:
        w, h = im.get_size()
        c = S(w + 2, h + 2)
        c.blit(im, (1, 1))
        outline(c, col)
        f = (im, c)
        if len(_elite_cache) > 300:
            _elite_cache.clear()
        _elite_cache[k] = f
    return f[1]


def boss_sprite(f):
    key = ('boss', f)
    c = _creature_cache.get(key)
    if c:
        return c
    s = S(40, 44)
    cape, capd = (92, 30, 120), (58, 18, 80)
    steel, stl, std = (92, 96, 120), (140, 146, 176), (54, 56, 78)
    # cape
    w = 2 if f else 0
    pts = [(8, 14), (32, 14), (38 + w, 40), (30, 37), (24, 41), (16, 37), (8, 41), (2 - w, 40)]
    pygame.draw.polygon(s, cape, pts)
    pygame.draw.polygon(s, capd, [(8, 14), (14, 14), (10, 40), (2 - w, 40)])
    # legs
    R(s, std, 12, 30, 6, 10)
    R(s, std, 22, 30, 6, 10)
    R(s, steel, 12, 38, 7, 3)
    R(s, steel, 21, 38, 7, 3)
    # torso armor
    pygame.draw.rect(s, steel, (9, 13, 22, 18))
    R(s, stl, 9, 13, 22, 2)
    R(s, std, 9, 28, 22, 3)
    R(s, (200, 60, 60), 18, 17, 4, 8)           # glowing core
    R(s, (255, 170, 90), 19, 18, 2, 5)
    for i in range(3):
        R(s, std, 11 + i * 0, 17 + i * 4, 6, 1)
        R(s, std, 23, 17 + i * 4, 6, 1)
    # shoulders / arms
    pygame.draw.ellipse(s, stl, (3, 10, 12, 9))
    pygame.draw.ellipse(s, stl, (25, 10, 12, 9))
    R(s, std, 4, 16, 4, 12)
    R(s, std, 32, 16, 4, 12)
    R(s, (210, 205, 190), 4, 28, 4, 3)
    R(s, (210, 205, 190), 32, 28, 4, 3)
    # spikes on shoulders
    pygame.draw.polygon(s, WHITE, [(6, 10), (8, 4), (10, 10)])
    pygame.draw.polygon(s, WHITE, [(30, 10), (32, 4), (34, 10)])
    # head / skull
    R(s, (222, 216, 196), 13, 1, 14, 12)
    R(s, (180, 172, 150), 13, 10, 14, 3)
    R(s, (22, 10, 30), 15, 5, 4, 4)
    R(s, (22, 10, 30), 21, 5, 4, 4)
    R(s, (255, 110, 40), 16, 6, 2, 2)
    R(s, (255, 110, 40), 22, 6, 2, 2)
    R(s, (22, 10, 30), 19, 9, 2, 2)
    for i in range(4):
        R(s, (22, 10, 30), 15 + i * 3, 11, 1, 2)
    # crown
    R(s, GOLD, 12, 0, 16, 3)
    for cx in (12, 17, 22, 27):
        R(s, GOLD, cx, -1 if False else 0, 2, 1)
    pygame.draw.polygon(s, GOLD, [(12, 1), (14, -2 + 2), (16, 1)])
    for cx in (13, 19, 25):
        pygame.draw.polygon(s, (255, 236, 140), [(cx, 1), (cx + 1, 0), (cx + 2, 1)])
    R(s, (230, 50, 80), 19, 1, 2, 2)
    outline(s, (18, 8, 26))
    _creature_cache[key] = s
    return s



# ---------------------------------------------------------------------
#  BOSS SPRITES (eight new bosses)
# ---------------------------------------------------------------------
def _cached(key, w, h, fn, line=(18, 8, 26)):
    c = _creature_cache.get(key)
    if c:
        return c
    s = S(w, h)
    fn(s)
    outline(s, line)
    _creature_cache[key] = s
    return s


def spr_spore(f):
    def draw(s):
        cap, capd, capl = (160, 62, 128), (104, 36, 90), (210, 110, 176)
        stem, stemd = (222, 204, 170), (176, 154, 122)
        glow = (170, 255, 120)
        b = f
        # stem / body
        pygame.draw.ellipse(s, stem, (13, 20 + b, 18, 22))
        pygame.draw.ellipse(s, stemd, (13, 32 + b, 18, 10))
        R(s, stemd, 14, 24 + b, 2, 12)
        # arms (vines)
        pygame.draw.line(s, (80, 150, 70), (14, 26 + b), (6, 34 + b - f), 3)
        pygame.draw.line(s, (80, 150, 70), (30, 26 + b), (38, 34 + b + f), 3)
        R(s, glow, 4, 33 + b - f, 3, 3)
        R(s, glow, 37, 33 + b + f, 3, 3)
        # face
        R(s, (40, 20, 40), 17, 27 + b, 3, 4)
        R(s, (40, 20, 40), 24, 27 + b, 3, 4)
        R(s, glow, 18, 28 + b, 1, 2)
        R(s, glow, 25, 28 + b, 1, 2)
        R(s, (60, 24, 50), 19, 34 + b, 6, 2)
        # roots
        for x in (11, 15, 22, 28, 31):
            R(s, (96, 150, 76), x, 41 + b - f * (x % 2), 2, 4)
        # cap
        pygame.draw.ellipse(s, capd, (2, 4 + b, 40, 22))
        pygame.draw.ellipse(s, cap, (2, 3 + b, 40, 20))
        pygame.draw.ellipse(s, capl, (8, 5 + b, 14, 6))
        for (x, y, r) in ((10, 8, 3), (22, 6, 2), (31, 10, 3), (17, 14, 2), (27, 16, 2), (6, 15, 2)):
            pygame.draw.circle(s, (246, 226, 246), (x, y + b), r)
        # gills glow
        for x in range(8, 38, 4):
            R(s, glow, x, 23 + b, 1, 2)
        # spores floating
        for (x, y) in ((4, 4), (40, 8), (36, 2), (8, 1)):
            R(s, glow, x, y + (f * 2 if x % 8 else -f), 1, 1)
    return _cached(('b_spore', f), 44, 46, draw)


def spr_tide(f):
    def draw(s):
        skin, skind = (150, 214, 200), (100, 168, 160)
        scale, scaled, scalel = (40, 150, 170), (24, 96, 124), (110, 230, 230)
        hair = (30, 120, 150)
        coral = (255, 120, 120)
        w = f
        # tail
        pygame.draw.polygon(s, scale, [(12, 26), (28, 26), (26 + w, 38), (30 + w * 2, 46), (22, 42), (12 - w * 2, 46), (14 - w, 38)])
        pygame.draw.polygon(s, scaled, [(12, 26), (17, 26), (14 - w, 38), (12 - w * 2, 46), (14, 36)])
        for (x, y) in ((16, 30), (22, 30), (19, 34), (16, 38), (22, 38)):
            R(s, scalel, x, y, 2, 1)
        pygame.draw.polygon(s, (255, 150, 140), [(12 - w * 2, 46), (6 - w * 2, 44), (10 - w, 40)])
        pygame.draw.polygon(s, (255, 150, 140), [(30 + w * 2, 46), (36 + w * 2, 44), (32 + w, 40)])
        # hair
        pygame.draw.polygon(s, hair, [(9, 6), (31, 6), (34 + w, 26), (28, 20), (12, 20), (6 - w, 26)])
        # torso
        pygame.draw.rect(s, skin, (14, 15, 12, 12))
        R(s, skind, 14, 24, 12, 3)
        R(s, scale, 13, 18, 14, 5)
        R(s, scalel, 13, 18, 14, 1)
        # arms
        R(s, skin, 9, 17, 4, 9)
        R(s, skin, 27, 17, 4, 9)
        # trident held right
        pygame.draw.line(s, (230, 200, 90), (33, 4), (33, 36), 1)
        pygame.draw.polygon(s, (240, 220, 120), [(30, 6), (36, 6), (36, 1), (35, 3), (33, 0), (31, 3), (30, 1)])
        # head
        pygame.draw.rect(s, skin, (14, 5, 12, 11))
        R(s, (20, 40, 60), 16, 9, 2, 2)
        R(s, (20, 40, 60), 22, 9, 2, 2)
        R(s, (255, 240, 120), 16, 9, 1, 1)
        R(s, (255, 240, 120), 22, 9, 1, 1)
        R(s, (200, 70, 90), 18, 13, 4, 1)
        # coral crown
        for x, hh in ((13, 4), (16, 6), (19, 8), (22, 6), (25, 4)):
            R(s, coral, x, 5 - hh // 2 - 1, 2, hh // 2 + 1)
        R(s, (255, 230, 200), 19, -0 + 0, 2, 2)
    return _cached(('b_tide', f), 42, 48, draw)


def spr_sun(f):
    def draw(s):
        gold, goldd = (240, 200, 70), (170, 130, 40)
        wrap, wrapd = (228, 218, 190), (176, 164, 134)
        blue = (50, 110, 200)
        b = f
        # robe / floating body
        pygame.draw.polygon(s, wrapd, [(8, 22), (32, 22), (36, 46 + b), (30, 42), (24, 48), (16, 42), (10, 48 + b), (4, 46)])
        pygame.draw.polygon(s, wrap, [(10, 22), (30, 22), (32, 40), (8, 40)])
        for y in range(25, 42, 4):
            R(s, wrapd, 9, y, 22, 1)
        # sash gold
        R(s, gold, 8, 28, 24, 3)
        R(s, goldd, 8, 30, 24, 1)
        # collar
        pygame.draw.polygon(s, gold, [(10, 17), (30, 17), (32, 24), (8, 24)])
        for x in range(11, 30, 4):
            R(s, blue, x, 19, 2, 3)
        # arms crossed: crook & flail
        pygame.draw.line(s, goldd, (6, 20), (34, 38), 2)
        pygame.draw.line(s, goldd, (34, 20), (6, 38), 2)
        pygame.draw.circle(s, gold, (5, 19), 2)
        pygame.draw.circle(s, (180, 60, 60), (35, 38), 2)
        R(s, wrap, 6, 24, 5, 4)
        R(s, wrap, 29, 24, 5, 4)
        # head w/ nemes
        pygame.draw.polygon(s, gold, [(10, 3), (30, 3), (35, 22), (28, 20), (28, 10), (12, 10), (12, 20), (5, 22)])
        for x in range(8, 34, 4):
            if 12 < x < 28:
                continue
            R(s, blue, x, 12, 2, 8)
        pygame.draw.rect(s, (196, 160, 110), (13, 5, 14, 14))
        R(s, (30, 20, 20), 15, 9, 4, 3)
        R(s, (30, 20, 20), 22, 9, 4, 3)
        R(s, (120, 255, 240), 16, 10, 2, 1)
        R(s, (120, 255, 240), 23, 10, 2, 1)
        R(s, (60, 40, 30), 18, 15, 4, 1)
        # cobra on forehead
        R(s, (60, 200, 90), 19, 0, 2, 5)
        R(s, (230, 60, 60), 19, 1, 2, 1)
        # beard
        R(s, blue, 19, 19, 3, 5)
    return _cached(('b_sun', f), 40, 50, draw)


def spr_frost(f):
    def draw(s):
        ice, iced, icel = (170, 220, 250), (96, 150, 210), (240, 252, 255)
        dress, dressd = (120, 170, 235), (70, 110, 190)
        skin = (226, 238, 250)
        w = f
        # train
        pygame.draw.polygon(s, dressd, [(8, 18), (28, 18), (34 + w, 46), (26, 41), (18, 47), (10, 41), (2 - w, 46)])
        pygame.draw.polygon(s, dress, [(10, 18), (26, 18), (30, 42), (6, 42)])
        for x in (11, 17, 23):
            R(s, icel, x, 24 + (x % 3), 1, 12)
        # bodice
        pygame.draw.polygon(s, ice, [(11, 14), (25, 14), (26, 26), (10, 26)])
        R(s, icel, 11, 14, 14, 1)
        # arms and scepter
        R(s, skin, 6, 16, 4, 10)
        R(s, skin, 26, 16, 4, 10)
        pygame.draw.line(s, icel, (32, 4), (32, 38), 1)
        pygame.draw.polygon(s, (130, 240, 255), [(32, 0), (35, 5), (32, 9), (29, 5)])
        pygame.draw.polygon(s, WHITE, [(32, 2), (33, 5), (32, 7), (31, 5)])
        # hair
        pygame.draw.polygon(s, (236, 244, 255), [(8, 4), (28, 4), (31 + w, 28), (26, 14), (10, 14), (5 - w, 28)])
        # head
        pygame.draw.rect(s, skin, (12, 5, 12, 11))
        R(s, (40, 70, 130), 14, 9, 2, 2)
        R(s, (40, 70, 130), 20, 9, 2, 2)
        R(s, (150, 240, 255), 14, 9, 1, 1)
        R(s, (150, 240, 255), 20, 9, 1, 1)
        R(s, (120, 140, 200), 16, 13, 4, 1)
        # crown spikes
        for x, hh in ((10, 5), (13, 8), (16, 5), (18, 10), (20, 5), (23, 8), (26, 5)):
            R(s, icel, x, 5 - hh, 2, hh)
            R(s, ice, x, 5 - hh + 2, 1, hh - 2)
        # sparkles
        for (x, y) in ((3, 8), (33, 14), (4, 30), (30, 36)):
            R(s, WHITE, x + w, y, 1, 1)
    return _cached(('b_frost', f), 38, 48, draw)


def spr_gear(f):
    def draw(s):
        br, brd, brl = (196, 140, 70), (120, 80, 40), (240, 200, 120)
        steel, steeld = (120, 130, 150), (70, 78, 96)
        b = f
        # legs / treads
        R(s, steeld, 8, 38 + b, 12, 10)
        R(s, steeld, 32, 38 + b, 12, 10)
        for x in (9, 13, 17, 33, 37, 41):
            R(s, (40, 44, 58), x, 44 + b, 2, 3)
        # torso
        pygame.draw.rect(s, br, (10, 14 + b, 32, 26))
        R(s, brl, 10, 14 + b, 32, 2)
        R(s, brd, 10, 37 + b, 32, 3)
        for x in (12, 38):
            for y in (17, 33):
                R(s, brd, x, y + b, 2, 2)
        # chest gear
        cx, cy = 26, 27 + b
        pygame.draw.circle(s, steeld, (cx, cy), 8)
        for i in range(8):
            a = i * math.pi / 4 + f * 0.4
            R(s, steeld, int(cx + math.cos(a) * 8) - 1, int(cy + math.sin(a) * 8) - 1, 3, 3)
        pygame.draw.circle(s, steel, (cx, cy), 6)
        pygame.draw.circle(s, (230, 80, 50), (cx, cy), 3)
        R(s, (255, 200, 120), cx - 1, cy - 1, 2, 2)
        # arms with pistons
        R(s, steel, 2, 18 + b, 8, 5)
        R(s, steeld, 2, 23 + b, 6, 14)
        R(s, steel, 4, 30 + b - f, 2, 8)
        R(s, steel, 42, 18 + b, 8, 5)
        R(s, steeld, 44, 23 + b, 6, 14)
        R(s, steel, 46, 30 + b - f, 2, 8)
        R(s, (230, 80, 50), 1, 37 + b, 8, 3)
        R(s, (230, 80, 50), 43, 37 + b, 8, 3)
        # head
        pygame.draw.rect(s, steel, (18, 3 + b, 16, 12))
        R(s, steeld, 18, 12 + b, 16, 3)
        R(s, (30, 10, 14), 20, 6 + b, 12, 4)
        R(s, (255, 60, 40), 22 + f * 4, 7 + b, 3, 2)
        # stacks
        R(s, steeld, 12, 0, 4, 12 + b)
        R(s, steeld, 36, 1, 4, 11 + b)
        R(s, (150, 150, 160), 11, 0, 6, 2)
        R(s, (150, 150, 160), 35, 1, 6, 2)
    return _cached(('b_gear', f), 52, 50, draw)


def spr_curator(f):
    def draw(s):
        coat, coatd = (70, 60, 100), (44, 36, 70)
        pale = (232, 232, 244)
        b = f
        # ghostly tail
        pygame.draw.polygon(s, (110, 110, 160), [(8, 28), (28, 28), (26, 40), (22, 36), (18, 46 + b), (14, 38), (10, 44)])
        pygame.draw.polygon(s, (150, 150, 200), [(10, 28), (26, 28), (24, 36), (18, 42), (12, 36)])
        # tailcoat
        pygame.draw.polygon(s, coat, [(8, 16), (28, 16), (30, 34), (24, 30), (18, 38), (12, 30), (6, 34)])
        pygame.draw.polygon(s, coatd, [(8, 16), (13, 16), (10, 34), (6, 34)])
        R(s, (240, 230, 220), 15, 17, 6, 10)
        R(s, (190, 40, 70), 17, 18, 2, 6)
        # arms and book
        R(s, coat, 4, 18, 5, 10)
        R(s, coat, 27, 18, 5, 10)
        R(s, pale, 3, 27, 4, 3)
        R(s, pale, 29, 27, 4, 3)
        R(s, (140, 40, 50), 27, 24 + b, 9, 7)
        R(s, (240, 220, 160), 28, 25 + b, 7, 1)
        R(s, (240, 220, 160), 28, 29 + b, 7, 1)
        # head
        pygame.draw.rect(s, pale, (12, 6, 12, 11))
        R(s, (20, 14, 30), 14, 9, 3, 3)
        R(s, (20, 14, 30), 20, 9, 3, 3)
        R(s, (255, 230, 120), 15, 10, 1, 1)
        pygame.draw.circle(s, (255, 220, 100), (21, 10), 3, 1)   # monocle
        R(s, (255, 230, 120), 21, 10, 1, 1)
        R(s, (60, 40, 70), 15, 14, 6, 1)
        # top hat
        R(s, (30, 26, 44), 9, 5, 18, 2)
        R(s, (30, 26, 44), 12, -0, 12, 6)
        R(s, (150, 40, 70), 12, 4, 12, 1)
        # floating wisps
        for (x, y) in ((2, 8), (33, 10), (1, 36), (34, 40)):
            R(s, (180, 190, 255), x, y + (f if x % 2 else -f), 1, 2)
    return _cached(('b_curator', f), 38, 48, draw)


def spr_magma(f):
    def draw(s):
        sc, scd, scl = (110, 36, 36), (66, 20, 24), (170, 70, 56)
        lava, lavab = (255, 130, 40), (255, 220, 120)
        j = f * 3
        # wings behind
        pygame.draw.polygon(s, scd, [(6, 24), (0, 4), (14, 16), (22, 8), (26, 26)])
        pygame.draw.polygon(s, scd, [(58, 24), (64, 4), (50, 16), (42, 8), (38, 26)])
        pygame.draw.line(s, scl, (6, 24), (1, 6), 1)
        pygame.draw.line(s, scl, (58, 24), (63, 6), 1)
        # body
        pygame.draw.ellipse(s, sc, (10, 20, 44, 28))
        pygame.draw.ellipse(s, scd, (14, 34, 36, 14))
        for (x, y) in ((18, 28), (26, 36), (38, 30), (44, 38), (30, 26)):
            R(s, lava, x, y, 3, 1)
            R(s, lava, x + 1, y + 1, 1, 3)
        # belly plates
        for y in range(36, 46, 3):
            R(s, (200, 120, 70), 24, y, 16, 1)
        # forelegs
        R(s, scd, 10, 40, 8, 8)
        R(s, scd, 46, 40, 8, 8)
        for x in (10, 13, 16, 46, 49, 52):
            R(s, (240, 220, 200), x, 47, 2, 2)
        # neck + head
        pygame.draw.polygon(s, sc, [(22, 24), (42, 24), (44, 8), (20, 8)])
        pygame.draw.polygon(s, sc, [(16, 8), (48, 8), (46, 20), (32, 24 + j // 2 + 0), (18, 20)])
        R(s, scl, 20, 9, 24, 2)
        # horns
        pygame.draw.polygon(s, (230, 220, 200), [(18, 9), (10, 0), (16, 2), (22, 8)])
        pygame.draw.polygon(s, (230, 220, 200), [(46, 9), (54, 0), (48, 2), (42, 8)])
        # eyes
        R(s, (20, 6, 8), 22, 12, 6, 3)
        R(s, (20, 6, 8), 36, 12, 6, 3)
        R(s, lavab, 24, 12, 3, 2)
        R(s, lavab, 37, 12, 3, 2)
        # jaw
        pygame.draw.polygon(s, scd, [(20, 20), (44, 20), (42, 24 + j), (22, 24 + j)])
        for x in (23, 27, 31, 35, 39):
            R(s, (246, 240, 226), x, 20, 2, 3)
        R(s, lava, 26, 21 + j // 2, 12, 2 + j // 2)
        # nostrils smoke
        R(s, (90, 90, 100), 28, 9, 2, 1)
        R(s, (90, 90, 100), 34, 9, 2, 1)
    return _cached(('b_magma', f), 64, 50, draw)


def spr_void(f):
    def draw(s):
        cl, cld, clh = (44, 24, 90), (24, 12, 56), (90, 56, 160)
        b = f
        # cloak
        pygame.draw.polygon(s, cl, [(10, 14), (34, 14), (40, 44 + b), (34, 40), (28, 47), (22, 41), (16, 47), (10, 40), (4, 44 + b)])
        pygame.draw.polygon(s, cld, [(10, 14), (16, 14), (10, 40), (4, 44 + b)])
        # star pattern
        for (x, y) in ((14, 24), (28, 22), (20, 32), (31, 36), (12, 38), (24, 42)):
            R(s, (255, 220, 255), x, y, 1, 1)
        # hood
        pygame.draw.ellipse(s, cl, (8, 2, 28, 24))
        pygame.draw.ellipse(s, (10, 4, 24), (12, 7, 20, 16))
        pygame.draw.ellipse(s, clh, (10, 3, 24, 5), 1)
        # the eye
        pygame.draw.ellipse(s, (250, 240, 255), (14, 11, 16, 9))
        pygame.draw.circle(s, (230, 40, 190), (22 + (f * 2 - 1), 15), 4)
        pygame.draw.circle(s, (30, 0, 40), (22 + (f * 2 - 1), 15), 2)
        R(s, WHITE, 21 + (f * 2 - 1), 13, 1, 1)
        # floating hands
        pygame.draw.circle(s, (210, 190, 240), (4, 30 + b), 3)
        pygame.draw.circle(s, (210, 190, 240), (40, 30 - b + 2), 3)
        R(s, (230, 40, 190), 3, 28 + b, 2, 1)
        R(s, (230, 40, 190), 39, 28 - b + 2, 2, 1)
        # halo ring
        pygame.draw.ellipse(s, (255, 90, 220), (6, 0, 32, 6), 1)
        # tendrils
        for x in (14, 20, 26):
            R(s, (160, 90, 230), x, 46 + (b if x % 2 else 0), 2, 2)
    return _cached(('b_void', f), 44, 50, draw)


