def prop_house(wt, ht, wall, roof, trim, door_col=(110, 70, 44), sign=None, chimney=True):
    w, h = wt * 16, ht * 16
    s = S(w, h)
    roof_h = h * 5 // 9
    wall_y = roof_h - 6
    # wall
    R(s, wall, 3, wall_y, w - 6, h - wall_y)
    for x in range(3, w - 3, 8):
        R(s, mul_c(wall, 0.92), x, wall_y, 1, h - wall_y)
    R(s, mul_c(wall, 0.7), 3, wall_y, w - 6, 5)          # roof shadow
    R(s, mul_c(wall, 0.65), 3, h - 3, w - 6, 3)         # foundation
    R(s, trim, 3, wall_y, 3, h - wall_y)
    R(s, trim, w - 6, wall_y, 3, h - wall_y)
    # timber cross
    R(s, trim, 3, h - 14, w - 6, 2)
    # roof
    rows = roof_h
    for y in range(rows):
        t = y / max(1, rows - 1)
        inset = int(lerp(w * 0.18, 0, t))
        c = roof if (y // 4) % 2 == 0 else mul_c(roof, 0.88)
        R(s, c, inset, y, w - inset * 2, 1)
        if y % 4 == 3:
            R(s, mul_c(roof, 0.6), inset, y, w - inset * 2, 1)
        else:
            for x in range(inset + (y // 4 % 2) * 4, w - inset, 8):
                R(s, mul_c(roof, 0.75), x, y, 1, 1)
    R(s, mul_c(roof, 1.3), int(w * 0.18) + 2, 0, w - int(w * 0.36) - 4, 2)
    R(s, mul_c(roof, 0.5), 0, rows - 1, w, 1)
    R(s, mul_c(roof, 0.8), 0, rows, w, 2)
    if chimney:
        cx = w - 22
        R(s, (130, 100, 90), cx, -0 if False else 4, 8, 14)
        R(s, (90, 66, 60), cx, 4, 8, 2)
        R(s, (160, 126, 110), cx, 6, 2, 12)
    # door
    dw, dh = 14, 22
    dx = w // 2 - dw // 2
    dy = h - dh
    pygame.draw.rect(s, mul_c(door_col, 0.6), (dx - 2, dy - 2, dw + 4, dh + 2))
    pygame.draw.rect(s, door_col, (dx, dy, dw, dh))
    R(s, mul_c(door_col, 1.25), dx, dy, 2, dh)
    R(s, mul_c(door_col, 0.75), dx + 6, dy, 1, dh)
    R(s, GOLD, dx + dw - 4, dy + 11, 2, 2)
    pygame.draw.ellipse(s, mul_c(door_col, 0.6), (dx - 2, dy - 6, dw + 4, 10))
    pygame.draw.ellipse(s, door_col, (dx, dy - 4, dw, 8))
    R(s, (170, 160, 150), dx - 3, h - 2, dw + 6, 2)
    # windows
    for wx in (10, w - 10 - 12):
        if abs(wx - dx) < 12 or abs(wx + 12 - (dx + dw)) < 8:
            continue
        wy = wall_y + 12
        R(s, trim, wx - 1, wy - 1, 14, 14)
        R(s, (255, 226, 130), wx, wy, 12, 12)
        R(s, (255, 248, 200), wx, wy, 12, 2)
        R(s, trim, wx + 5, wy, 2, 12)
        R(s, trim, wx, wy + 5, 12, 2)
        R(s, mul_c(trim, 0.6), wx - 2, wy + 12, 16, 2)
    if sign:
        sx = dx + dw + 3 if wt >= 5 else 4
        R(s, (90, 56, 36), w // 2 - 1, wall_y - 2 if False else wall_y + 1, 1, 1)
        board = S(26, 11)
        board.fill((176, 126, 80))
        R(board, (96, 62, 40), 0, 0, 26, 1)
        R(board, (96, 62, 40), 0, 10, 26, 1)
        R(board, (96, 62, 40), 0, 0, 1, 11)
        R(board, (96, 62, 40), 25, 0, 1, 11)
        ic = sign
        board.blit(ic, (5, -2 if False else -2), (0, 0, 16, 16)) if False else None
        s.blit(board, (w // 2 - 13, wall_y + 2 - 0))
        s.blit(pygame.transform.scale(icon(ic), (9, 9)) if isinstance(ic, str) else ic, (w // 2 - 4, wall_y + 3))
    outline(s)
    return s


