def make_light(radius, color=(255, 255, 255)):
    s = pygame.Surface((radius * 2, radius * 2))
    s.fill((0, 0, 0))
    steps = max(8, radius // 2)
    for i in range(steps, 0, -1):
        t = i / steps
        k = (1 - t) ** 1.6
        c = (int(color[0] * k), int(color[1] * k), int(color[2] * k))
        pygame.draw.circle(s, c, (radius, radius), int(radius * t))
    return s


_light_cache = {}


def light(radius, color=(255, 255, 255)):
    k = (int(radius), color)
    l = _light_cache.get(k)
    if l is None:
        l = make_light(int(radius), color)
        if len(_light_cache) > 80:
            _light_cache.clear()
        _light_cache[k] = l
    return l


_shadow_cache = {}


def shadow(w, h=None, a=90):
    h = h or max(3, w // 3)
    k = (w, h, a)
    s = _shadow_cache.get(k)
    if s is None:
        s = S(w, h)
        pygame.draw.ellipse(s, (0, 0, 0, a), (0, 0, w, h))
        _shadow_cache[k] = s
    return s


