# ---------------------------------------------------------------------
#  PARTICLES & FLOATING TEXT
# ---------------------------------------------------------------------
class Particles:
    def __init__(self):
        self.p = []
        self.texts = []

    def add(self, x, y, vx, vy, life, col, size=1, grav=0.0, drag=0.0):
        if len(self.p) < 1000:
            self.p.append([x, y, vx, vy, life, life, col, size, grav, drag])

    def burst(self, x, y, n, cols, speed=60, life=0.5, size=1, grav=0.0, drag=1.5, up=0.0):
        for _ in range(n):
            a = random.random() * math.tau
            sp = speed * (0.35 + random.random() * 0.65)
            self.add(x, y, math.cos(a) * sp, math.sin(a) * sp - up, life * (0.6 + random.random() * 0.6),
                     random.choice(cols), size, grav, drag)

    def text(self, x, y, s, col=WHITE, life=0.8, big_=False):
        self.texts.append([x, y, s, col, life, life, big_])

    def update(self, dt):
        out = []
        for p in self.p:
            p[4] -= dt
            if p[4] <= 0:
                continue
            p[0] += p[2] * dt
            p[1] += p[3] * dt
            p[3] += p[8] * dt
            if p[9]:
                k = max(0.0, 1 - p[9] * dt)
                p[2] *= k
                p[3] *= k
            out.append(p)
        self.p = out
        out = []
        for t in self.texts:
            t[4] -= dt
            if t[4] <= 0:
                continue
            t[1] -= 22 * dt * (t[4] / t[5]) + 4 * dt
            out.append(t)
        self.texts = out

    def draw(self, surf, cx, cy):
        for p in self.p:
            k = p[4] / p[5]
            sz = max(1, int(p[7] * (0.4 + 0.6 * k))) if p[7] > 1 else 1
            x, y = int(p[0] - cx), int(p[1] - cy)
            if -4 < x < W + 4 and -4 < y < H + 4:
                col = p[6] if k > 0.25 else mul_c(p[6], 0.5 + k)
                surf.fill(col, (x, y, sz, sz))

    def draw_text(self, surf, cx, cy):
        for t in self.texts:
            x, y = int(t[0] - cx), int(t[1] - cy)
            k = t[4] / t[5]
            col = t[3] if k > 0.25 else mul_c(t[3], 0.6 + k)
            if t[6]:
                big(surf, t[2], x, y - 4, col, 2)
            else:
                txt(surf, t[2], x, y, col, True, 'c', outline=True)


