def prop_plot(stage=0, crop='turnip'):
    s = S(16, 16)
    R(s, (70, 44, 30), 0, 3, 16, 13)
    R(s, (104, 68, 44), 1, 4, 14, 11)
    for x in (2, 6, 10, 13):
        R(s, (84, 54, 36), x, 7, 2, 1)
        R(s, (84, 54, 36), x - 1, 12, 2, 1)
    c = CROPS[crop][4]
    if stage == 1:
        for x in (3, 7, 11):
            R(s, (110, 200, 90), x, 9, 1, 3)
            R(s, (150, 230, 110), x - 1, 9, 1, 1)
            R(s, (150, 230, 110), x + 1, 8, 1, 1)
    elif stage == 2:
        for x in (3, 8, 12):
            R(s, (70, 160, 70), x, 6, 1, 6)
            R(s, (110, 200, 90), x - 2, 6, 2, 2)
            R(s, (110, 200, 90), x + 1, 5, 2, 2)
    elif stage >= 3:
        for (x, y) in ((3, 9), (8, 7), (12, 10)):
            R(s, (70, 160, 70), x, y - 3, 1, 3)
            R(s, (90, 180, 80), x - 2, y - 4, 2, 2)
            R(s, (90, 180, 80), x + 1, y - 4, 2, 2)
            if crop == 'turnip':
                R(s, c, x - 1, y, 3, 3)
                R(s, (170, 90, 190), x - 1, y, 3, 1)
            elif crop == 'pumpkin':
                R(s, c, x - 2, y, 5, 4)
                R(s, mul_c(c, 0.7), x, y, 1, 4)
                R(s, (80, 160, 70), x, y - 1, 1, 1)
            elif crop == 'starberry':
                R(s, c, x - 1, y, 3, 3)
                R(s, (255, 230, 120), x, y + 1, 1, 1)
                R(s, (255, 230, 120), x - 3, y - 2, 1, 1)
            else:
                R(s, c, x - 1, y - 1, 3, 3)
                R(s, WHITE, x, y, 1, 1)
                R(s, lerp_c(c, WHITE, 0.6), x - 3, y - 3, 1, 1)
                R(s, lerp_c(c, WHITE, 0.6), x + 3, y - 2, 1, 1)
    outline(s)
    return s


