def prop_colosseum():
    w, h = 128, 84
    s = S(w, h)
    stone, st_d, st_l = (150, 142, 132), (108, 100, 94), (186, 178, 166)
    R(s, st_d, 0, 10, w, h - 10)
    for y in range(10, h):
        for x in range(0, w):
            if (x + (y // 8) * 9) % 18 == 0 or y % 8 == 0:
                s.set_at((x, y), mul_c(stone, 0.78))
            else:
                s.set_at((x, y), stone if (x // 18 + y // 8) % 2 else mul_c(stone, 1.06))
    R(s, st_l, 0, 8, w, 4)
    R(s, st_d, 0, 12, w, 1)
    for x in range(2, w, 8):
        R(s, st_l, x, 4, 5, 5)
        R(s, st_d, x, 8, 5, 1)
    for k in range(3):
        cx = 22 + k * 42
        if k == 1:
            continue
        pygame.draw.rect(s, (24, 18, 28), (cx - 9, 36, 18, 36))
        pygame.draw.ellipse(s, (24, 18, 28), (cx - 9, 28, 18, 18))
    R(s, (24, 18, 28), 53, 40, 22, 44)
    pygame.draw.ellipse(s, (24, 18, 28), (53, 28, 22, 24))
    for x in (48, 78):
        R(s, st_l, x, 34, 4, 50)
        R(s, st_d, x + 3, 34, 1, 50)
    # banners
    for (bx, col) in ((12, (200, 60, 60)), (104, (60, 90, 200))):
        R(s, col, bx, 16, 12, 22)
        R(s, mul_c(col, 0.7), bx, 36, 12, 2)
        pygame.draw.polygon(s, (24, 18, 28), [(bx, 38), (bx + 6, 33), (bx + 12, 38)])
        R(s, (255, 214, 92), bx + 5, 22, 2, 8)
        R(s, (255, 214, 92), bx + 3, 25, 6, 2)
    # plaque
    R(s, (60, 40, 30), 40, 15, 48, 11)
    R(s, (186, 140, 90), 41, 16, 46, 9)
    R(s, (60, 36, 24), 42, 17, 44, 1)
    outline(s)
    txt(s, "ARENA", 64, 17, (60, 36, 24), False, 'c')
    return s


