    def sp_gravity(self, sp):
        p = self.player
        tx, ty = self.aim_pos(60, 130)
        self.hazards.append(Hazard('circle', tx, ty, 42, warn=0.25, life=3.0, dmg=self.sdmg(0.3, 'gravity'), owner='p',
                                   col=(170, 90, 255), tick=0.5, force=62, name='gravity', fxc=[(190, 110, 255), WHITE]))
        d = self.sdmg(2.2, 'gravity')
        self.later(3.3, lambda: self.explode_at(tx, ty, d, 40, (190, 110, 255)))
        self.audio.play('portal', 0.7)

    def sp_wall(self, sp):
        p = self.player
        nx, ny = -p.fy, p.fx
        if abs(p.fx) > abs(p.fy):
            nx, ny = 0, 1
        else:
            nx, ny = 1, 0
        cx, cy = p.x + p.fx * 30, p.y - 2 + p.fy * 30
        for i in (-1, 0, 1):
            x, y = cx + nx * i * 16, cy + ny * i * 16
            r = (x - 8, y - 10, 16, 10)
            if self.map.blocked(r, 'player', p):
                continue
            ok = True
            for e in self.map.enemies:
                if not e.dead and abs(e.x - x) < 11 and abs(e.y - 5 - y) < 9:
                    ok = False
            if ok:
                self.hazards.append(Hazard('rect', x, y - 5, 16, 10, warn=0.0, life=8.0, dmg=0, owner='p', wall=True,
                                           name='wall', col=(170, 160, 150), sound=None, fxc=[(170, 160, 150), (120, 112, 106)]))
        self.audio.play('slam', 0.7)
        self.shake(2)

    def sp_blades(self, sp):
        p = self.player
        p.blades_t = 9.0
        p.blades_dmg = self.sdmg(0.5, 'blades')
