    def sp_quake(self, sp):
        p = self.player
        dmg = self.sdmg(1.0, 'quake')
        fx_, fy_ = p.fx, p.fy
        for i in range(1, 8):
            x, y = p.x + fx_ * (12 + i * 16), p.y - 2 + fy_ * (12 + i * 16)

            def go(x=x, y=y):
                if self.map.point_solid(x, y):
                    return
                self.hazards.append(Hazard('circle', x, y, 14, warn=0.28, life=0.14, dmg=dmg, owner='p', col=(210, 170, 100),
                                           knock=90, shake=2, sound='slam', kb=120, fxc=[(190, 160, 110), (140, 120, 90), WHITE]))
