    def sp_timewarp(self, sp):
        p = self.player
        self.hazards.append(Hazard('circle', p.x, p.y - 4, 78, warn=0.0, life=6.0, dmg=0, owner='p', col=(120, 230, 220),
                                   tick=0.2, eff='slow', eff_t=0.6, name='timewarp', fxc=[(160, 255, 240), WHITE]))
        self.hazards[-1].follow = True
