    def sp_drain(self, sp):
        p = self.player
        e = nearest_enemy(self, p.x + p.fx * 14, p.y, 72)
        if e is None:
            self.fx.text(p.x, p.y - 22, "No target", GREY, 0.6)
            p.sp_cd['drain'] = 0.3
            p.mp += self.spell_cost('drain')
            return
        d = self.sdmg(0.9, 'drain')
        tx, ty = e.center()
        pts = [(p.x, p.y - 8)]
        for k in range(1, 5):
            t_ = k / 5
            pts.append((p.x + (tx - p.x) * t_ + math.sin(k * 2 + self.time * 20) * 4,
                        p.y - 8 + (ty - p.y + 8) * t_ + math.cos(k * 2) * 3))
        pts.append((tx, ty))
        self.zap(pts, (210, 60, 130), 0.4)
        hurt_enemy(self, e, d, p.x, p.y, 40)
        h = max(1, int(d * 0.4))
        p.hp = min(p.max_hp, p.hp + h)
        self.fx.text(p.x, p.y - 26, "+%d" % h, (255, 130, 170), 0.7)
        self.fx.burst(tx, ty, 8, [(220, 60, 130), (255, 150, 190)], 60, 0.4, 1, 0, 2)
        for _ in range(6):
            self.fx.add(tx, ty, (p.x - tx) * 2.2 + random.uniform(-20, 20), (p.y - 8 - ty) * 2.2 + random.uniform(-20, 20),
                        0.45, (255, 120, 170), 2)
        self.audio.play('hit', 0.7)
        self.audio.play('heart', 0.5) if 'heart' in getattr(self.audio, 'sfx', {}) else None

    def sp_volley(self, sp):
        p = self.player
        base = math.atan2(p.fy, p.fx)
        dmg = self.sdmg(0.55, 'volley')
        for i in range(10):
            a = base + random.uniform(-0.55, 0.55)
            d = random.uniform(26, 92)
            x, y = p.x + math.cos(a) * d, p.y - 2 + math.sin(a) * d

            def go(x=x, y=y):
                if self.map.point_solid(x, y):
                    return
                self.hazards.append(Hazard('circle', x, y, 10, warn=0.45, life=0.1, dmg=dmg, owner='p', col=(230, 200, 140),
                                           sound='arrow', kb=40, name='arrow', fxc=[(240, 220, 170), WHITE]))
            self.later(0.05 * i, go)
        self.audio.play('arrow', 0.7)

    def sp_storm(self, sp):
        p = self.player
        dmg = self.sdmg(0.95, 'storm')
        for i in range(14):
            def go():
                e = nearest_enemy(self, p.x + random.uniform(-70, 70), p.y + random.uniform(-50, 50), 70) \
                    if random.random() < 0.7 else None
                if e:
                    x, y = e.x, e.y - 3
                else:
                    a = random.random() * math.tau
                    r = random.uniform(20, 90)
                    x, y = p.x + math.cos(a) * r, p.y + math.sin(a) * r * 0.7
                    if self.map.point_solid(x, y):
                        return
                self.hazards.append(Hazard('circle', x, y, 13, warn=0.38, life=0.12, dmg=dmg, owner='p', col=(255, 245, 140),
                                           sound='crit', shake=1.5, name='strike', kb=70,
                                           fxc=[(255, 250, 170), WHITE, (200, 220, 255)]))
            self.later(0.28 * i, go)
        self.audio.play('warn', 0.6)
        self.flash = [(200, 210, 255), 0.12, 0.12, 40]

    def sp_dive(self, sp):
        p = self.player
        p.dvx, p.dvy = p.fx, p.fy
