        p.hp = max(1, p.hp - loss)
        p.blood_t = 10.0
        self.fx.text(p.x, p.y - 22, "-%d" % loss, (255, 80, 100), 0.8)
        self.fx.burst(p.x, p.y - 8, 20, [(230, 40, 70), (150, 20, 50)], 70, 0.6, 2, -10, 2)
