BOSS_FLAG = {'king': 'boss_dead'}


def boss_flag(bid):
    return BOSS_FLAG.get(bid, 'dead_' + bid)


def dungeon_unlocked(p, dg):
    u = dg['unlock']
    if u[0] == 'open':
        return True
    if u[0] == 'flag':
        return u[1] in p.flags
    if u[0] == 'count':
        return sum(1 for f in u[1] if f in p.flags) >= u[2]
    return False


def unlock_hint(dg):
    u = dg['unlock']
    if u[0] == 'flag':
        bid = u[1][5:] if u[1].startswith('dead_') else 'king'
        return "Defeat %s" % BOSS_NAMES.get(bid, bid)
    if u[0] == 'count':
        names = [BOSS_NAMES.get(f[5:], f) for f in u[1]]
        return "Defeat any %d: %s" % (u[2], ", ".join(n.replace('the ', '') for n in names))
    return ""


# ---- decor sprites ----------------------------------------------------------------------------
_decor_cache = {}


def prop_decor(kind, var=0):
    k = (kind, var)
    s = _decor_cache.get(k)
    if s is not None:
        return s
    rr = random.Random(hash(k) % 10007)
    if kind == 'mush':
        s = S(16, 14)
        for i, (x, w_, hh) in enumerate(((1, 6, 5), (7, 7, 7), (4, 5, 4))):
            col = ((176, 80, 150), (110, 220, 140), (230, 160, 90))[(i + var) % 3]
            R(s, (214, 196, 160), x + w_ // 2 - 1, 14 - hh - 1, 2, hh)
            pygame.draw.ellipse(s, col, (x, 14 - hh - 5, w_ + 2, 5))
            R(s, WHITE, x + 2, 14 - hh - 4, 1, 1)
    elif kind == 'coral':
        s = S(14, 14)
        col = ((255, 110, 110), (255, 170, 90), (190, 110, 255))[var % 3]
        for (x, y0) in ((3, 4), (7, 1), (11, 5)):
            pygame.draw.line(s, col, (7, 13), (x, y0), 2)
            R(s, mul_c(col, 1.2), x - 1, y0 - 1, 2, 2)
    elif kind == 'sarco':
        s = S(18, 24)
        R(s, (150, 112, 50), 2, 8, 14, 15)
        R(s, (236, 200, 90), 2, 8, 14, 2)
        R(s, (50, 110, 200), 4, 12, 10, 8)
        R(s, (236, 200, 90), 8, 5, 2, 4)
        pygame.draw.circle(s, (236, 200, 90), (9, 4), 3)
        R(s, (30, 20, 20), 8, 3, 1, 1)
        R(s, (30, 20, 20), 10, 3, 1, 1)
        for y in (13, 16):
            R(s, (236, 200, 90), 5, y, 8, 1)
    elif kind == 'icecr':
        s = S(14, 20)
        for (x, hh) in ((2, 10), (5, 17), (9, 12)):
            pygame.draw.polygon(s, (170, 226, 255), [(x, 19), (x + 2, 19 - hh), (x + 4, 19)])
            pygame.draw.line(s, WHITE, (x + 2, 19 - hh), (x + 2, 17), 1)
    elif kind == 'gearp':
        s = S(18, 14)
        for (cx, cy, r, c) in ((6, 8, 5, (200, 150, 80)), (13, 9, 4, (150, 156, 170))):
            pygame.draw.circle(s, c, (cx, cy), r)
            for i in range(8):
                a = i * math.pi / 4
                R(s, c, int(cx + math.cos(a) * (r + 1)), int(cy + math.sin(a) * (r + 1)), 2, 2)
            pygame.draw.circle(s, (70, 60, 50), (cx, cy), 2)
    elif kind == 'shelf':
        s = S(20, 24)
        R(s, (100, 62, 40), 0, 0, 20, 24)
        for y in (2, 9, 16):
            R(s, (70, 40, 26), 1, y + 6, 18, 2)
            x = 2
            while x < 18:
                w_ = rr.randint(2, 3)
                R(s, rr.choice(((180, 60, 70), (70, 100, 170), (200, 170, 80), (90, 150, 100), (150, 90, 170))), x, y,
                  w_, 6)
                x += w_ + 0
    elif kind == 'candle':
        s = S(10, 16)
        R(s, (150, 130, 60), 4, 8, 2, 8)
        R(s, (150, 130, 60), 2, 6, 6, 2)
        for x in (2, 4, 7):
            R(s, (240, 236, 220), x, 3, 1, 3)
            R(s, (255, 200, 80), x, 2, 1, 1)
    elif kind == 'obsid':
        s = S(14, 18)
        for (x, hh) in ((1, 9), (5, 16), (9, 11)):
            pygame.draw.polygon(s, (50, 36, 62), [(x, 17), (x + 2, 17 - hh), (x + 4, 17)])
            pygame.draw.line(s, (255, 120, 50), (x + 2, 17 - hh + 2), (x + 2, 15), 1)
    elif kind == 'lavacr':
        s = S(16, 8)
        pygame.draw.lines(s, (255, 130, 40), False, [(0, 4), (4, 2), (7, 5), (11, 2), (15, 4)], 1)
    elif kind == 'voidcr':
        s = S(14, 20)
        for (x, hh) in ((2, 11), (5, 18), (9, 13)):
            pygame.draw.polygon(s, (150, 40, 190), [(x, 19), (x + 2, 19 - hh), (x + 4, 19)])
            pygame.draw.line(s, (255, 120, 230), (x + 2, 19 - hh), (x + 2, 17), 1)
    else:
        s = S(8, 8)
    outline(s)
    _decor_cache[k] = s
    return s


DECOR = {   # theme -> (solid image kind, glow colour or None, ground kind)
    'spore': [('mush', (130, 255, 150))], 'grotto': [('coral', (110, 230, 240))], 'tomb': [('sarco', None)],
    'frost': [('icecr', (150, 220, 255))], 'foundry': [('gearp', (255, 160, 70))], 'manor': [('shelf', None), ('candle', (255, 200, 100))],
    'magma': [('obsid', (255, 120, 50)), ('lavacr', None)], 'void': [('voidcr', (255, 90, 220))],
}


def decorate_dungeon(m, rng, rooms, t, dg, start, used):
    """Scatter theme dressing through the rooms."""
    th = dg['theme']
    for kind, glow in DECOR.get(th, []):
        for i, (x, y, rw, rh) in enumerate(rooms):
            if i == start:
                continue
            for _ in range(rng.randint(1, 3)):
                bx, by = rng.randint(x + 1, x + rw - 2), rng.randint(y + 1, y + rh - 2)
                if t[by][bx] != FLOOR or (bx, by) in used:
                    continue
                used.add((bx, by))
                im = prop_decor(kind, rng.randint(0, 2))
                if kind == 'lavacr':
                    m.add_prop(Prop(bx * 16 + 8, by * 16 + 12, im, ground=True))
                    continue
                solid = (-5, -5, 10, 5) if kind not in ('candle',) else (-2, -3, 4, 3)
                lt = (30, glow, 0.2) if glow else None
                m.add_prop(Prop(bx * 16 + 8, by * 16 + 14, im, solid=solid, shd=(14, 5), light=lt))


# ---- boss arenas -------------------------------------------------------------------------------
def build_arena(dg):
    bid = dg['boss']
    th = dg['theme']
    W_, H_ = 28, 22
    m = GameMap('%s_boss' % dg['id'], BOSSES[bid]['name'], W_, H_, th, 'boss')
    m.dg = dg
    m.floor_no = dg['floors']
    m.music = None
    m.ambient = THEMES[th]['amb']
    m.weather = dg['weather']
    t = m.tiles
    for y in range(H_):
        for x in range(W_):
            t[y][x] = WALL
    for y in range(2, H_ - 2):
        for x in range(2, W_ - 2):
            t[y][x] = FLOOR
    t[H_ - 3][13] = STAIRS_UP
    t[H_ - 3][14] = STAIRS_UP
    m.warps.append(dict(rect=(13 * 16 + 2, (H_ - 3) * 16 + 2, 28, 12), to='up', name='up'))
    m.spawn = (14 * 16, (H_ - 4) * 16 + 8)
    P = lambda x, y, img, **k: m.add_prop(Prop(x, y, img, **k))
    pil = prop_pillar()
    # themed arena dressing
    if bid == 'tide':
        for (x0, y0) in ((3, 4), (22, 4), (3, 13), (22, 13)):
            for yy in range(y0, y0 + 3):
                for xx in range(x0, x0 + 3):
                    t[yy][xx] = WATER
        for (px_, py_) in ((8, 8), (19, 8), (8, 14), (19, 14)):
            P(px_ * 16 + 8, py_ * 16 + 8, prop_decor('coral', px_), solid=(-5, -5, 10, 5), shd=(14, 5), light=(40, (110, 230, 240), 0.2))
    elif bid == 'magma':
        for (x0, y0) in ((3, 3), (23, 3), (3, 14), (23, 14)):
            for yy in range(y0, y0 + 3):
                for xx in range(x0, x0 + 2):
                    t[yy][xx] = LAVA
        for yy in (7, 12):
            for xx in (9, 18):
                P(xx * 16 + 8, yy * 16 + 14, prop_decor('obsid', xx), solid=(-5, -5, 10, 5), shd=(14, 5), light=(46, (255, 120, 50), 0.3))
    elif bid == 'frost':
        for yy in (5, 9, 13, 17):
            for xx in (6, 21):
                P(xx * 16 + 8, yy * 16 + 14, prop_decor('icecr', xx + yy), solid=(-5, -5, 10, 5), shd=(14, 5), light=(40, (150, 220, 255), 0.15))
    elif bid == 'gear':
        for yy in (6, 11, 16):
            for xx in (5, 22):
                P(xx * 16 + 8, yy * 16 + 14, prop_decor('gearp', xx), solid=(-6, -5, 12, 5), shd=(16, 5))
    elif bid == 'curator':
        for yy in range(2, H_ - 2):
            t[yy][13] = CARPET
            t[yy][14] = CARPET
        for xx in (4, 8, 19, 23):
            P(xx * 16 + 8, 3 * 16 + 20, prop_decor('shelf'), solid=(-10, -8, 20, 8), shd=(22, 6))
        for (xx, yy) in ((6, 9), (21, 9), (6, 15), (21, 15)):
            P(xx * 16 + 8, yy * 16 + 14, prop_decor('candle'), solid=(-2, -3, 4, 3), light=(60, (255, 200, 100), 0.3))
    elif bid == 'sun':
        for yy in range(2, H_ - 2):
            for xx in range(2, W_ - 2):
                if rng_hash(xx, yy) % 9 == 0:
                    t[yy][xx] = SAND
        for yy in (6, 11, 16):
            for xx in (5, 22):
                P(xx * 16 + 8, yy * 16 + 16, pil, solid=(-6, -8, 12, 8), shd=(16, 6))
        for xx in (9, 18):
            P(xx * 16 + 8, 4 * 16 + 24, prop_decor('sarco'), solid=(-8, -10, 16, 10), shd=(20, 6))
    elif bid == 'spore':
        for yy in (6, 10, 14):
            for xx in (5, 22):
                P(xx * 16 + 8, yy * 16 + 14, prop_decor('mush', xx + yy), solid=(-5, -5, 10, 5), shd=(14, 5), light=(46, (130, 255, 150), 0.3))
    elif bid == 'void':
        for (xx, yy) in ((6, 6), (21, 6), (6, 16), (21, 16)):
            P(xx * 16 + 8, yy * 16 + 14, prop_decor('voidcr', xx), solid=(-5, -5, 10, 5), shd=(14, 5), light=(60, (255, 90, 220), 0.3))
    for xx in (4, 8, 12, 16, 20, 23):
        if bid not in ('curator',):
            P(xx * 16 + 8, 2 * 16 + 4, prop_banner(THEMES[th]['accent']))
    m.lights.append((14 * 16, 6 * 16, 110, mul_c(THEMES[th]['accent'], 0.8), 0.1, False))
    m.lights.append((14 * 16, 15 * 16, 90, mul_c(THEMES[th]['accent'], 0.5), 0.05, False))
    m.trigger = (4 * 16, 12 * 16, (W_ - 8) * 16, 12)
    b = BOSS_CLASSES[bid](bid, 14 * 16, 6 * 16)
    m.enemies.append(b)
    m.boss = b
    return m


def rng_hash(x, y):
    return (x * 73856093) ^ (y * 19349663)


class DungeonMixin:
    """The Waygate (dungeon select), dungeon floors, boss arenas and boss rewards."""

    def open_gate(self):
        if self.trailer:
            self.warp(dict(to='floor1'))
            return
        self.state = 'gate'
        self.gate_sel = 0
        self.audio.play('menu')

    def get_dfloor(self, dg, n):
        k = (dg['id'], n)
        m = self.floors.get(k)
        if m is None:
            if n >= dg['floors']:
                m = build_arena(dg)
                kk = self.player.st.get('bk_' + dg['boss'], 0)
                if kk:
                    b = m.boss
                    b.maxhp = b.hp = int(b.maxhp * (1 + 0.5 * kk))
                    b.dmg = int(b.dmg * (1 + 0.15 * kk))
                    b.rematch = kk
            else:
                m = gen_dungeon(n, self.seed, dg=dg)
            m.bake()
            self.floors[k] = m
        return m

    def enter_dungeon(self, dg):
        p = self.player
        if dg['id'] == 'crypt':
            self.warp(dict(to='floor1'))
            return

        def fn():
            self.new_dive()
            self.dive_t = 0.0
            self.enter_map(self.get_dfloor(dg, 1))
            p.maxfloor = max(p.maxfloor, 1)
            self.toast("%s  (recommended level %d)" % (dg['name'], dg['lvl']), CREAM, 4)
            self.stat('dg_' + dg['id'])
        self.audio.play('portal')
        self.start_trans(fn, 1.6)
        self.warp_cd = 2.0

    def update_gate(self):
        p = self.player
        n = len(DUNGEONS)
        if self.jp('back') or self.jp('pause'):
            self.state = 'play'
            p.y += 28
            self.warp_cd = 1.0
            self.audio.play('back')
            return
        if self.jp('up'):
            self.gate_sel = (self.gate_sel - 1) % n
            self.audio.play('menu')
        if self.jp('down'):
            self.gate_sel = (self.gate_sel + 1) % n
            self.audio.play('menu')
        if self.jp('ok'):
            dg = DUNGEONS[self.gate_sel]
            if dungeon_unlocked(p, dg):
                self.state = 'play'
                self.enter_dungeon(dg)
            else:
                self.audio.play('error')
                self.toast(unlock_hint(dg), RED, 2.5)

    def draw_gate(self, surf):
        p = self.player
        dim = self.overlay
        dim.fill((8, 4, 18))
        dim.set_alpha(225)
        surf.blit(dim, (0, 0))
        panel(surf, 8, 8, W - 16, H - 16, None)
        txt(surf, "THE WAYGATE", W // 2, 12, GOLD, True, 'c')
        n = len(DUNGEONS)
        for i, dg in enumerate(DUNGEONS):
            y = 24 + i * 14
            on = i == self.gate_sel
            ok = dungeon_unlocked(p, dg)
            if on:
                surf.fill((64, 46, 100), (14, y - 1, 138, 13))
                pygame.draw.rect(surf, GOLD, (14, y - 1, 138, 13), 1)
            acc = THEMES[dg['theme']]['accent']
            surf.fill(acc if ok else (60, 56, 76), (18, y + 2, 5, 7))
            txt(surf, dg['name'], 28, y + 2, CREAM if ok else (100, 94, 120))
            if boss_flag(dg['boss']) in p.flags:
                pygame.draw.line(surf, GREEN, (141, y + 6), (143, y + 8), 1)
                pygame.draw.line(surf, GREEN, (143, y + 8), (148, y + 3), 1)
            elif not ok:
                txt(surf, "?", 146, y + 2, (150, 90, 100), True, 'r')
        dg = DUNGEONS[self.gate_sel]
        ok = dungeon_unlocked(p, dg)
        acc = THEMES[dg['theme']]['accent']
        panel(surf, 158, 24, 146, 130, None, (36, 28, 62), mul_c(acc, 0.7))
        txt(surf, dg['name'], 231, 28, acc, True, 'c')
        for i, ln in enumerate(self.wrap(dg['tag'], 134)[:2]):
            txt(surf, ln, 164, 38 + i * 9, DIM)
        bid = dg['boss']
        if bid == 'king':
            bs = boss_sprite(0)
        else:
            bs = BOSS_SPR[bid](0)
        sc = 1 if max(bs.get_size()) > 44 else 1
        if ok or boss_flag(bid) in p.flags:
            surf.blit(bs, (164, 60))
        else:
            sil = bs.copy()
            sil.fill((20, 16, 34), special_flags=pygame.BLEND_RGB_MULT)
            sil.fill((50, 40, 70), special_flags=pygame.BLEND_RGB_ADD)
            surf.blit(sil, (164, 60))
        nm = BOSS_NAMES.get(bid, bid) if (ok or boss_flag(bid) in p.flags) else "???"
        txt(surf, "Boss:", 216, 62, DIM)
        for i, ln in enumerate(self.wrap(nm, 86)[:2]):
            txt(surf, ln, 216, 71 + i * 9, CREAM)
        txt(surf, "Level %d+" % dg['lvl'], 216, 92, GREEN if p.level >= dg['lvl'] else (255, 170, 90))
        best = p.st.get('best_' + dg['id'])
        if best:
            txt(surf, "Best %d:%02d" % (best // 60, best % 60), 216, 101, GOLD)
        x = 164
        txt(surf, "Loot:", 164, 108, DIM)
        for mk in dg['mats'][:3]:
            surf.blit(icon(mk), (x + 24, 105))
            x += 17
        spl = [s for s in SPELLS if s[6] == ('boss', bid)]
        if spl:
            have = spl[0][0] in p.spells
            surf.blit(spell_icon(spl[0][0], 12), (164, 122))
            txt(surf, spl[0][1] + (" (learned)" if have else ""), 180, 124, GREEN if have else GOLD)
        if not ok:
            txt(surf, "Locked:", 164, 138, RED)
            for ln in self.wrap(unlock_hint(dg), 100)[:1]:
                txt(surf, ln, 196, 138, (255, 150, 150))
        else:
            txt(surf, "ENTER: descend", 231, 140, GREEN, True, 'c')
        if getattr(self, 'trailer', None) is None:
            txt(surf, "ESC: back", 14, 160, DIM)

    # ---- bosses ---------------------------------------------------------------
    def after_boss2(self):
        self.state = 'play'
        p = self.player
        p.hp, p.mp = p.max_hp, p.max_mp
        p.reset_state()
        self.floors.clear()
        self.enter_map(self.get_village(), VPOS['gate_out'])
        self.save_game(quiet=True)

    def unlocked_set(self):
        return {d['id'] for d in DUNGEONS if dungeon_unlocked(self.player, d)}


ACTIONS = {}
PADK = {n: 20001 + i for i, n in enumerate(
    "up down left right cross circle square triangle l1 r1 l2 r2 options share l3 r3 chord".split())}


def init_keys():
    K = pygame
    ACTIONS.update({
        'up': (K.K_UP, K.K_w), 'down': (K.K_DOWN, K.K_s), 'left': (K.K_LEFT, K.K_a), 'right': (K.K_RIGHT, K.K_d),
        'attack': (K.K_j, K.K_z), 'magic': (K.K_k, K.K_x), 'dash': (K.K_SPACE, K.K_l, K.K_c),
        'interact': (K.K_e, K.K_RETURN, K.K_KP_ENTER), 'hp': (K.K_q,), 'mp': (K.K_r,), 'elixir': (K.K_f,),
        'inv': (K.K_i, K.K_TAB), 'pause': (K.K_ESCAPE, K.K_p), 'mute': (K.K_m,), 'full': (K.K_F11,),
        'ok': (K.K_RETURN, K.K_KP_ENTER, K.K_e, K.K_j, K.K_z, K.K_SPACE),
        'back': (K.K_ESCAPE, K.K_x, K.K_k, K.K_BACKSPACE),
        'sp1': (K.K_1,), 'sp2': (K.K_2,), 'sp3': (K.K_3,), 'sp4': (K.K_4,),
        'spnext': (K.K_v,), 'spprev': (K.K_b,), 'gadget': (K.K_g,), 'gadnext': (K.K_t,),
    })
    # PlayStation pad: virtual key codes produced by the Gamepad class below
    for act, names in (('up', ['up']), ('down', ['down']), ('left', ['left']), ('right', ['right']),
                       ('attack', ['square']), ('magic', ['triangle']), ('dash', ['circle']),
                       ('interact', ['cross']), ('hp', ['r2']), ('mp', ['l2']), ('elixir', ['l3']),
                       ('inv', ['share']), ('pause', ['options']), ('ok', ['cross']),
                       ('spnext', ['r1']), ('spprev', ['l1']), ('gadget', ['r3']), ('gadnext', ['chord']),
                       ('back', ['circle', 'triangle'])):
        ACTIONS[act] = tuple(ACTIONS[act]) + tuple(PADK[n] for n in names)


