class Boss2(Boss):
    """Coroutine-driven boss: every attack is a generator that yields the seconds to wait."""
    MOVES = {1: [], 2: [], 3: []}
    rest = 1.2

    def __init__(self, bid, x, y):
        super().__init__(x, y)
        d = BOSSES[bid]
        self.bid = bid
        self.is_boss = True
        self.name = d['name']
        self.rage_text = d['rage']
        self.fxcol = d['col']
        self.cy = d['cy']
        self.st = dict(ENEMY['boss'], name=d['name'], xp=d['xp'], gold=(d['gold'], d['gold']))
        self.maxhp = self.hp = int(d['hp'] * MODS.get('hp', 1.0) * MODS.get('bhp', 1.0))
        self.dmg = int(d['dmg'] * MODS.get('dmg', 1.0) * MODS.get('bdmg', 1.0))
        self.speed = d['spd'] * MODS.get('spd', 1.0)
        self.bw, self.bh = d['box']
        self.co = None
        self.wait = 0.0
        self.mv = None
        self.bounce = 0
        self.open_t = 0.0
        self.hidden = False
        self.lift = 0.0
        self.alpha = 1.0
        self.cr = 16
        self.contact_mult = 1.0
        self.last = ''
        self.slam_r = -1
        self.warns = []
        self.rings = []
        self.sub = 0
        self.minions = []
        self.phase_n = 1

    # ---- helpers ------------------------------------------------------------
    def bounds(self, g):
        return 36, g.map.w * T - 36, 40, g.map.h * T - 30

    def cen(self):
        return self.x, self.y - self.cy

    def center(self):
        return self.x, self.y - self.cy

    def pp(self, g):
        return g.player.x, g.player.y - 4

    def aim(self, g):
        cx, cy = self.cen()
        return math.atan2(g.player.y - 6 - cy, g.player.x - cx)

    def proj(self, g, ang, spd, kind, mult=0.7, life=5.0, home=0.0):
        cx, cy = self.cen()
        pr = Projectile(cx, cy, math.cos(ang) * spd, math.sin(ang) * spd, max(1, int(self.dmg * mult)), kind, False, life, home)
        g.projs.append(pr)
        return pr

    def ring(self, g, n, spd, kind, mult=0.6, off=0.0, life=5.0):
        for i in range(n):
            self.proj(g, off + i * math.tau / n, spd, kind, mult, life)

    def hz(self, g, shape, x, y, a, b=0, mult=1.0, **kw):
        kw.setdefault('col', self.fxcol)
        h = Hazard(shape, x, y, a, b, dmg=int(self.dmg * mult), owner='e', **kw)
        g.hazards.append(h)
        return h

    def summon(self, g, kind, n, rad=50):
        for i in range(n):
            for _ in range(8):
                a = random.random() * math.tau
                sx, sy = self.x + math.cos(a) * rad, self.y + 14 + math.sin(a) * rad * 0.6
                x0, x1, y0, y1 = self.bounds(g)
                sx, sy = clamp(sx, x0 + 10, x1 - 10), clamp(sy, y0 + 10, y1 - 10)
                if not g.map.blocked((sx - 4, sy - 5, 8, 5), 'enemy'):
                    break
            e = Enemy(kind, sx, sy, 3)
            e.aggro = True
            e.spawn_t = 0.5
            e.minion = 1
            e.dmg = int(e.dmg * 0.9)
            g.map.enemies.append(e)
            g.fx.burst(sx, sy - 6, 14, [self.fxcol, WHITE], 60, 0.5, 2, 0, 2)
        g.audio.play('roar', 0.5)

    def minion_count(self, g):
        return sum(1 for e in g.map.enemies if e.minion and not e.dead)

    def dash(self, nx, ny, sp, t):
        self.mv = [nx * sp, ny * sp, t]

    def teleport(self, g, x, y):
        g.fx.burst(self.x, self.y - 14, 18, [self.fxcol, WHITE], 80, 0.5, 2, -10, 2)
        self.x, self.y = x, y
        g.fx.burst(self.x, self.y - 14, 18, [self.fxcol, WHITE], 80, 0.5, 2, -10, 2)
        g.glow(self.x, self.y - 14, 50, self.fxcol, 0.3)
        g.audio.play('portal', 0.6)

    def rand_spot(self, g, margin=40):
        x0, x1, y0, y1 = self.bounds(g)
        for _ in range(20):
            x, y = random.uniform(x0 + margin, x1 - margin), random.uniform(y0 + margin, y1 - margin)
            if not g.map.blocked((x - 5, y - 5, 10, 5), 'enemy'):
                return x, y
        return (x0 + x1) / 2, (y0 + y1) / 2

    def arena_center(self, g):
        x0, x1, y0, y1 = self.bounds(g)
        return (x0 + x1) / 2, (y0 + y1) / 2

    # ---- brain ---------------------------------------------------------------
    def pick(self, g):
        opts = []
        for ph in range(1, self.phase + 1):
            opts += self.MOVES.get(ph, [])
        c = [o for o in opts if o != self.last] or opts
        a = random.choice(c)
        self.last = a
        self.attack_n += 1
        return a

    def idle(self, g, dt, d, px, py):
        if d > 56:
            self.chase(g, dt, px, py, self.speed * (0.8 + 0.2 * self.phase))

    def on_phase(self, g):
        self.co = None
        self.mv = None
        self.hidden = False
        self.lift = 0.0
        g.hazards = [h for h in g.hazards if h.owner != 'e']

    def update(self, g, dt):
        dt = enemy_status_dt(self, g, dt)
        if dt <= 0:
            return
        self.t += dt
        self.flash = max(0, self.flash - dt)
        self.hurt_t = max(0, self.hurt_t - dt)
        self.hurt_cd = max(0, self.hurt_cd - dt)
        self.invuln = max(0, self.invuln - dt)
        p = g.player
        px, py = p.x, p.y - 6
        cx, cy = self.cen()
        d = dist(cx, cy, px, py)
        if self.state == 'dormant':
            return
        if self.state == 'phase':
            self.timer -= dt
            if self.timer <= 0:
                self.state = 'idle'
                self.timer = 0.9
            return
        self.open_t = max(0, self.open_t - dt)
        if self.open_t > 0 and random.random() < dt * 14:
            g.fx.add(self.x + random.uniform(-10, 10), self.y - random.uniform(6, 30), random.uniform(-10, 10), -20,
                     0.4, (255, 240, 140), 1)
        # forced movement (dashes, leaps)
        if self.mv:
            vx, vy, t = self.mv
            ox, oy = self.x, self.y
            self.step(g.map, vx * dt, vy * dt, 'enemy')
            self.mv[2] -= dt
            if self.bounce > 0 and abs(self.x - ox) + abs(self.y - oy) < (abs(vx) + abs(vy)) * dt * 0.4:
                if abs(self.x - ox) < abs(vx) * dt * 0.4:
                    self.mv[0] = -vx
                if abs(self.y - oy) < abs(vy) * dt * 0.4:
                    self.mv[1] = -vy
                self.bounce -= 1
                g.shake(3)
                g.audio.play('slam', 0.6)
                g.fx.burst(self.x, self.y - 6, 10, [self.fxcol, WHITE], 70, 0.4, 2, 0, 2)
            if self.mv[2] <= 0:
                self.mv = None
        if self.co is None:
            if not self.mv:
                self.idle(g, dt, d, px, py)
            self.timer -= dt
            if self.timer <= 0:
                name = self.pick(g)
                self.co = getattr(self, 'atk_' + name)(g)
                self.wait = 0.0
                self.cur = name
                g.audio.play('warn', 0.8)
        else:
            self.wait -= dt
            guard = 0
            while self.wait <= 0 and self.co is not None and guard < 8:
                guard += 1
                try:
                    self.wait = max(0.02, float(next(self.co)))
                except StopIteration:
                    self.co = None
                    self.timer = max(0.35, self.rest - 0.18 * (self.phase - 1))
                    break
        self.contact(g, d, self.cr)
        if self.slam_r >= 0:
            self.slam_r = -1

    def take_hit(self, g, dmg, kx, ky, crit=False, kb=0):
        if self.open_t > 0:
            dmg = int(dmg * 1.5)
        return g.boss_hit(self, dmg, crit)

    def draw(self, g, out, cx, cy):
        s = BOSS_SPR[self.bid](int(self.t * 3) % 2)
        w, h = s.get_size()
        hov = 2 + math.sin(self.t * 2.5) * 2 if self.bid not in ('gear', 'magma') else 0
        sw = w - 10
        out.append((self.y - 0.5, shadow(sw, 10, max(30, 110 - int(self.lift * 2))), self.x - sw / 2, self.y - 4))
        im = flashed(s) if self.flash > 0 else s
        if self.invuln > 0 and int(self.t * 20) % 2 == 0:
            im = tinted(s, (60, 0, 80))
        elif self.open_t > 0 and int(self.t * 10) % 2 == 0 and self.flash <= 0:
            im = tinted(s, (90, 80, 0))
        elif self.co is not None and self.wait > 0.25 and int(self.t * 16) % 4 == 0 and self.flash <= 0 and self.timer <= 0:
            im = tinted(s, (60, 10, 10))
        a = 0.0 if self.hidden else self.alpha
        if a < 1.0:
            im = im.copy()
            im.set_alpha(int(255 * a))
        if a > 0.01:
            out.append((self.y, im, self.x - w / 2, self.y - h + 8 - hov - self.lift))


# ---------------------------------------------------------------------------------------------
def _boss_class(bid):
    return BOSS_CLASSES[bid]


class SporeBoss(Boss2):
    MOVES = {1: ['spores', 'roots'], 2: ['ring', 'shrooms'], 3: ['slam', 'bloom']}
    rest = 1.3

    def atk_spores(self, g):
        n = 4 + self.phase
        for i in range(n):
            px, py = self.pp(g)
            if i:
                px += random.uniform(-34, 34)
                py += random.uniform(-26, 26)
            warn = 1.0 + 0.1 * i
            self.hz(g, 'circle', px, py, 17, warn=warn, life=0.12, mult=0.9, sound='fire_hit', shake=2,
                    fxc=[(150, 255, 110), (90, 190, 60), WHITE], eff='poison', eff_t=2.0)
            g.later(warn + 0.05, lambda x=px, y=py: self.hz(g, 'circle', x, y, 21, warn=0.0, life=4.5, mult=0.22, tick=0.6,
                                                         eff='poison', eff_t=2.5, col=(110, 200, 70), light=True))
            g.fx.burst(self.x, self.y - 30, 5, [(150, 255, 110)], 60, 0.4, 1, 0, 3)
            yield 0.28
        yield 1.0

    def atk_roots(self, g):
        base = self.aim(g)
        n = 3 if self.phase < 2 else 5
        for k in range(n):
            a = base + (k - (n - 1) / 2) * 0.38
            self.hz(g, 'line', self.x, self.y - 6, 190, 12, ang=a, warn=0.9 + 0.08 * k, life=0.25, mult=1.0,
                    col=(110, 160, 60), sound='slam', fxc=[(110, 160, 60), (170, 120, 60), WHITE])
            yield 0.12
        yield 1.4

    def atk_ring(self, g):
        for w in range(3):
            self.ring(g, 14, 48, 'spore', 0.6, off=w * 0.22)
            g.audio.play('fire', 0.6)
            yield 0.7
        yield 0.8

    def atk_shrooms(self, g):
        if self.minion_count(g) < 4:
            self.summon(g, 'shroom', 2 + self.phase, 56)
        yield 1.6

    def atk_slam(self, g):
        px, py = self.pp(g)
        self.hz(g, 'circle', px, py, 32, warn=1.1, life=0.15, mult=1.4, sound='slam', shake=6,
                fxc=[(150, 255, 110), (90, 190, 60), WHITE], eff='poison', eff_t=3)
        self.invuln = 1.3
        for i in range(8):
            self.lift = math.sin(i / 8 * math.pi) * 26
            self.x += (px - self.x) * 0.22
            self.y += (py - self.y) * 0.22
            yield 0.1
        self.lift = 0
        self.x, self.y = px, py + 4
        g.audio.play('slam', 0.9)
        self.hz(g, 'ring', px, py, 6, 7, warn=0, life=0.9, mult=0.8, grow=120, eff='poison', eff_t=2)
        yield 1.2

    def atk_bloom(self, g):
        x0, x1, y0, y1 = self.bounds(g)
        cx, cy = self.arena_center(g)
        safe = []
        for _ in range(3):
            for _t in range(20):
                sx, sy = random.uniform(x0 + 40, x1 - 40), random.uniform(y0 + 40, y1 - 40)
                if all(dist(sx, sy, a, b) > 70 for a, b, _r in safe):
                    break
            safe.append((sx, sy, 26))
        g.toast("Find the clean air!", (170, 255, 140), 2)
        self.hz(g, 'rect', cx, cy, x1 - x0, y1 - y0, warn=2.2, life=0.5, mult=1.6, safe=safe, sound='boom', shake=4,
                eff='poison', eff_t=4, col=(120, 220, 70), fxc=[(150, 255, 110), WHITE])
        yield 3.2


class TideBoss(Boss2):
    MOVES = {1: ['trident', 'bubbles'], 2: ['wave', 'dive'], 3: ['whirl', 'trident']}
    rest = 1.0

    def idle(self, g, dt, d, px, py):
        a = self.t * 0.9
        tx, ty = px + math.cos(a) * 78, py + math.sin(a) * 52
        x0, x1, y0, y1 = self.bounds(g)
        tx, ty = clamp(tx, x0 + 10, x1 - 10), clamp(ty, y0 + 14, y1 - 10)
        if dist(self.x, self.y, tx, ty) > 4:
            self.chase(g, dt, tx, ty, self.speed)

    def atk_trident(self, g):
        for k in range(2 if self.phase >= 3 else 1):
            px, py = self.pp(g)
            a = math.atan2(py - (self.y - 8), px - self.x)
            self.hz(g, 'line', self.x, self.y - 8, 175, 15, ang=a, warn=0.75, life=0.3, mult=1.1, sound='swing',
                    fxc=[(120, 230, 255), WHITE])
            yield 0.75
            self.dash(math.cos(a), math.sin(a), 330, 0.5)
            g.audio.play('dash', 0.9)
            yield 0.6
        yield 0.6

    def atk_bubbles(self, g):
        a0 = self.aim(g)
        for i in range(6 + 2 * (self.phase > 1)):
            self.proj(g, a0 + (i - 2.5) * 0.28, 44, 'bubble', 0.7, 7.0, home=0.35)
            g.audio.play('arrow', 0.4, 0.1)
            yield 0.12
        yield 1.4

    def atk_wave(self, g):
        x0, x1, y0, y1 = self.bounds(g)
        rows = 5
        rh = (y1 - y0) / rows
        gap = random.randrange(rows)
        left = random.random() < 0.5
        g.toast("Tidal wave! Find the gap!", (140, 230, 255), 2)
        for r in range(rows):
            if r == gap:
                continue
            yy = y0 + rh * (r + 0.5)
            self.hz(g, 'rect', (x0 + x1) / 2, yy, x1 - x0, rh - 4, warn=1.3, life=0.05, mult=0, col=(100, 200, 255), light=False)
        yield 1.35
        for r in range(rows):
            if r == gap:
                continue
            yy = y0 + rh * (r + 0.5)
            sx = x0 - 30 if left else x1 + 30
            self.hz(g, 'rect', sx, yy, 50, rh - 4, warn=0.0, life=2.6, mult=1.2, vx=(260 if left else -260), eff='slow',
                    eff_t=1.5, col=(90, 190, 255), sound=None, fxc=[(120, 220, 255), WHITE], knock=60)
        g.audio.play('slam', 0.6)
        g.shake(3)
        yield 2.8

    def atk_dive(self, g):
        self.hidden = True
        self.invuln = 1.8
        g.fx.burst(self.x, self.y - 10, 20, [(120, 220, 255), WHITE], 90, 0.6, 2, 30, 2)
        g.audio.play('boom', 0.3)
        px, py = self.pp(g)
        h = self.hz(g, 'circle', px, py, 28, warn=1.7, life=0.15, mult=1.3, sound='slam', shake=5,
                    fxc=[(120, 230, 255), WHITE, (60, 150, 220)])
        for i in range(15):
            p = g.player
            h.x += (p.x - h.x) * 0.35
            h.y += (p.y - 4 - h.y) * 0.35
            self.x += (h.x - self.x) * 0.3
            self.y += (h.y - self.y) * 0.3
            yield 0.1
        self.x, self.y = h.x, h.y
        yield 0.22
        self.hidden = False
        self.invuln = 0
        self.open_t = 2.4
        self.hz(g, 'ring', self.x, self.y, 6, 7, warn=0, life=0.6, mult=0.7, grow=120, knock=60)
        yield 2.6

    def atk_whirl(self, g):
        cx, cy = self.arena_center(g)
        self.hz(g, 'circle', cx, cy, 84, warn=0.9, life=5.0, mult=0.2, tick=0.5, force=52, eff='slow', eff_t=1.0,
                col=(60, 160, 210), fxc=[(120, 220, 255), WHITE], name='gravity')
        yield 1.0
        for i in range(5):
            px, py = self.pp(g)
            a = math.atan2(py - (self.y - 8), px - self.x)
            self.hz(g, 'line', self.x, self.y - 8, 190, 11, ang=a, warn=0.65, life=0.2, mult=0.9, sound='swing')
            yield 0.9
        yield 0.6


class SunBoss(Boss2):
    MOVES = {1: ['sandblast', 'curse'], 2: ['scarabs', 'pillars'], 3: ['sandstorm', 'mummies']}
    rest = 1.2

    def atk_sandblast(self, g):
        for w in range(3):
            a0 = self.aim(g)
            for i in range(9):
                self.proj(g, a0 + (i - 4) * 0.15, 92, 'sand', 0.55, 3.5)
            g.audio.play('arrow', 0.7)
            yield 0.55
        yield 0.9

    def atk_curse(self, g):
        n = 1 + (self.phase > 1)
        for i in range(n):
            px, py = self.pp(g)
            if i:
                px += random.uniform(-40, 40)
                py += random.uniform(-30, 30)
            self.hz(g, 'circle', px, py, 25, warn=1.1, life=0.2, mult=0.5, eff='curse', eff_t=4.5, sound='warn',
                    col=(210, 120, 255), fxc=[(210, 120, 255), (255, 220, 120)])
            yield 0.3
        g.toast("Don't get cursed! Your controls will invert!", (230, 170, 255), 2.2)
        yield 1.8

    def atk_scarabs(self, g):
        if self.minion_count(g) < 6:
            self.summon(g, 'scarab', 4 + self.phase, 54)
        yield 1.8

    def atk_pillars(self, g):
        x0, x1, y0, y1 = self.bounds(g)
        n = 7
        gap = random.randrange(n)
        colw = (x1 - x0) / n
        for i in range(n):
            if i == gap:
                continue
            self.hz(g, 'rect', x0 + colw * (i + 0.5), (y0 + y1) / 2, colw - 6, y1 - y0, warn=1.2, life=0.25, mult=1.1,
                    sound='slam', shake=2, col=(230, 190, 90), fxc=[(240, 205, 120), (190, 150, 70), WHITE])
        yield 1.7
        rows = 5
        gap = random.randrange(rows)
        rh = (y1 - y0) / rows
        for i in range(rows):
            if i == gap:
                continue
            self.hz(g, 'rect', (x0 + x1) / 2, y0 + rh * (i + 0.5), x1 - x0, rh - 6, warn=1.2, life=0.25, mult=1.1,
                    sound='slam', shake=2, col=(230, 190, 90), fxc=[(240, 205, 120), (190, 150, 70), WHITE])
        yield 2.0

    def atk_sandstorm(self, g):
        x0, x1, y0, y1 = self.bounds(g)
        cx, cy = self.arena_center(g)
        d = random.choice((-1, 1))
        g.toast("A sandstorm! Fight the wind!", (240, 215, 130), 2)
        self.hz(g, 'rect', cx, cy, x1 - x0, y1 - y0, warn=0.9, life=6.5, mult=0, wind=(70.0 * d, 0.0), col=(220, 190, 110),
                light=False, fxc=[(230, 200, 120)])
        yield 1.0
        for i in range(9):
            for k in range(3):
                yy = random.uniform(y0 + 10, y1 - 10)
                sx = x0 + 6 if d > 0 else x1 - 6
                pr = Projectile(sx, yy, 100 * d, 0, int(self.dmg * 0.5), 'sand', False, 5.0)
                g.projs.append(pr)
            g.fx.burst(x0 if d > 0 else x1, random.uniform(y0, y1), 4, [(230, 200, 120)], 80, 0.4, 1, 0, 2)
            yield 0.6
        yield 0.5

    def atk_mummies(self, g):
        if self.minion_count(g) < 4:
            self.summon(g, 'mummy', 2, 60)
        yield 1.6


class FrostBoss(Boss2):
    MOVES = {1: ['icicles', 'frostbeam'], 2: ['mirrors', 'nova'], 3: ['blizzard', 'icicles']}
    rest = 1.1

    def idle(self, g, dt, d, px, py):
        if d < 78:
            self.chase(g, dt, px, py, self.speed * 1.1, away=True)
        elif d > 120:
            self.chase(g, dt, px, py, self.speed)

    def atk_icicles(self, g):
        n = 7 + 2 * self.phase
        for i in range(n):
            px, py = self.pp(g)
            if i % 3:
                px += random.uniform(-60, 60)
                py += random.uniform(-44, 44)
            self.hz(g, 'circle', px, py, 11, warn=0.85, life=0.12, mult=0.95, sound='crit', eff='freeze', eff_t=1.2,
                    col=(150, 215, 255), fxc=[(200, 240, 255), WHITE])
            yield 0.14
        yield 1.2

    def atk_frostbeam(self, g):
        a0 = self.aim(g)
        sgn = random.choice((-1, 1))
        cx, cy = self.cen()
        self.hz(g, 'line', cx, cy, 200, 8, ang=a0 - sgn * 0.9, warn=1.0, life=2.0, mult=0.3, tick=0.14, spin=sgn * 0.95,
                eff='slow', eff_t=1.0, col=(140, 220, 255), fxc=[(200, 240, 255), WHITE], sound='crit')
        yield 3.4

    def atk_mirrors(self, g):
        x0, x1, y0, y1 = self.bounds(g)
        spots = [self.rand_spot(g, 50) for _ in range(3)]
        self.hidden = True
        self.invuln = 0.8
        g.fx.burst(self.x, self.y - 14, 24, [(200, 240, 255), WHITE], 90, 0.6, 2, 0, 2)
        yield 0.6
        real = random.randrange(3)
        for i, (sx, sy) in enumerate(spots):
            if i == real:
                self.teleport(g, sx, sy)
                self.hidden = False
            else:
                e = Enemy('mirage', sx, sy, 3)
                e.minion = 1
                e.aggro = True
                e.look = 'frost'
                e.life = 9.0
                e.maxhp = e.hp = 1
                g.map.enemies.append(e)
                g.fx.burst(sx, sy - 14, 14, [(200, 240, 255), WHITE], 70, 0.5, 2, 0, 2)
        g.toast("Which one is real?", (190, 235, 255), 2)
        yield 3.2

    def atk_nova(self, g):
        cx, cy = self.cen()
        for k in range(2 if self.phase < 3 else 3):
            self.hz(g, 'ring', cx, cy, 6, 8, warn=0.7, life=1.3, mult=0.9, grow=100, eff='freeze', eff_t=1.4,
                    col=(150, 215, 255), sound='crit', fxc=[(200, 240, 255), WHITE])
            yield 1.0
        yield 0.8

    def atk_blizzard(self, g):
        g.blizzard_t = 9.0
        g.toast("A blizzard sweeps the hall!", (200, 235, 255), 2.5)
        cx, cy = self.arena_center(g)
        x0, x1, y0, y1 = self.bounds(g)
        self.hz(g, 'rect', cx, cy, x1 - x0, y1 - y0, warn=0.5, life=9.0, mult=0, tick=0.4, eff='slow', eff_t=0.8,
                col=(190, 225, 255), light=False, fxc=[(220, 240, 255)])
        for i in range(12):
            px, py = self.pp(g)
            for k in range(2):
                tx, ty = px + random.uniform(-50, 50), py + random.uniform(-40, 40)
                self.hz(g, 'circle', tx, ty, 11, warn=0.8, life=0.12, mult=0.95, sound='crit', eff='freeze', eff_t=1.2,
                        col=(150, 215, 255), fxc=[(200, 240, 255), WHITE])
            yield 0.7
        yield 0.5


class GearBoss(Boss2):
    MOVES = {1: ['pistons', 'lasers'], 2: ['sawcharge', 'drones', 'overload'], 3: ['overload', 'pistons']}
    rest = 1.2

    def __init__(self, bid, x, y):
        super().__init__(bid, x, y)
        self.cr = 20

    def atk_pistons(self, g):
        x0, x1, y0, y1 = self.bounds(g)
        cs = 46
        nx, ny = int((x1 - x0) // cs), int((y1 - y0) // cs)
        ox = x0 + ((x1 - x0) - nx * cs) / 2
        oy = y0 + ((y1 - y0) - ny * cs) / 2
        for par in (0, 1):
            for i in range(nx):
                for j in range(ny):
                    if (i + j) % 2 == par:
                        self.hz(g, 'rect', ox + (i + 0.5) * cs, oy + (j + 0.5) * cs, cs - 4, cs - 4, warn=0.9, life=0.2,
                                mult=1.0, sound=None, col=(255, 190, 80), fxc=[(255, 200, 100), (160, 160, 170), WHITE])
            g.audio.play('slam', 0.6)
            yield 1.4
        yield 0.6

    def atk_lasers(self, g):
        cx, cy = self.cen()
        n = 2 if self.phase < 3 else 4
        a0 = self.aim(g)
        sgn = random.choice((-1, 1))
        for i in range(n):
            self.hz(g, 'line', cx, cy, 230, 7, ang=a0 + i * math.tau / n, warn=1.2, life=3.2, mult=0.4, tick=0.12,
                    spin=sgn * 0.75, col=(255, 70, 60), fxc=[(255, 120, 80), WHITE], sound='warn')
        g.toast("Lasers! Keep moving!", (255, 150, 120), 2)
        yield 4.8

    def atk_sawcharge(self, g):
        px, py = self.pp(g)
        a = math.atan2(py - self.y, px - self.x)
        self.hz(g, 'line', self.x, self.y - 6, 150, 20, ang=a, warn=0.8, life=0.1, mult=0, col=(255, 190, 80), light=False)
        yield 0.85
        self.bounce = 3
        self.contact_mult = 1.3
        self.dash(math.cos(a), math.sin(a), 215, 3.2)
        g.audio.play('dash', 0.9)
        yield 3.3
        self.bounce = 0
        self.contact_mult = 1.0
        self.open_t = 1.0
        yield 0.8

    def atk_drones(self, g):
        if self.minion_count(g) < 3:
            self.summon(g, 'turret', 2, 70)
        yield 1.6

    def atk_overload(self, g):
        g.toast("Overheating! Steam vents!", (255, 190, 120), 2)
        cx, cy = self.cen()
        for w in range(3):
            base = random.random() * math.tau
            for i in range(6):
                self.hz(g, 'line', cx, cy, 150, 13, ang=base + i * math.tau / 6, warn=0.9, life=0.3, mult=1.0,
                        col=(210, 220, 235), fxc=[(230, 236, 246), (160, 170, 190)], sound='fire_hit' if i == 0 else None)
            yield 1.3
        self.open_t = 3.6
        g.fx.burst(self.x, self.y - 20, 30, [(255, 240, 160), WHITE], 100, 0.8, 2, 20, 1.5)
        g.toast("The core is exposed! Strike now!", (255, 240, 150), 2.4)
        yield 3.8


class CuratorBoss(Boss2):
    MOVES = {1: ['books', 'frames'], 2: ['chandelier', 'blackout'], 3: ['encore', 'books']}
    rest = 1.1

    def idle(self, g, dt, d, px, py):
        a = self.t * 0.6
        tx, ty = px + math.cos(a) * 90, py + math.sin(a) * 60
        x0, x1, y0, y1 = self.bounds(g)
        tx, ty = clamp(tx, x0 + 16, x1 - 16), clamp(ty, y0 + 20, y1 - 10)
        if dist(self.x, self.y, tx, ty) > 4:
            self.chase(g, dt, tx, ty, self.speed)

    def atk_books(self, g):
        cx, cy = self.cen()
        pages = []
        n = 6 + 2 * (self.phase > 2)
        for i in range(n):
            pr = Projectile(cx, cy, 0, 0, int(self.dmg * 0.7), 'page', False, 9.0)
            g.projs.append(pr)
            pages.append(pr)
        for tick in range(12):
            cx, cy = self.cen()
            for i, pr in enumerate(pages):
                a = self.t * 3 + i * math.tau / n
                r = min(34, tick * 4.0)
                pr.x, pr.y = cx + math.cos(a) * r, cy + math.sin(a) * r * 0.8
                pr.life = 9.0
            yield 0.08
        for pr in pages:
            if pr.dead:
                continue
            a = math.atan2(g.player.y - 6 - pr.y, g.player.x - pr.x)
            pr.vx, pr.vy = math.cos(a) * 95, math.sin(a) * 95
            g.audio.play('arrow', 0.4, 0.1)
            yield 0.18
        yield 1.0

    def atk_frames(self, g):
        x0, x1, y0, y1 = self.bounds(g)
        frames = [(x0 + 30, y0 + 40), (x1 - 30, y0 + 40), (x0 + 30, y1 - 20), (x1 - 30, y1 - 20)]
        for k in range(3):
            self.hidden = True
            self.invuln = 0.6
            g.fx.burst(self.x, self.y - 14, 16, [(190, 170, 255), WHITE], 80, 0.5, 2, -10, 2)
            yield 0.35
            fx_, fy_ = random.choice(frames)
            self.x, self.y = fx_, fy_
            self.hidden = False
            g.fx.burst(self.x, self.y - 14, 16, [(190, 170, 255), WHITE], 80, 0.5, 2, -10, 2)
            g.audio.play('portal', 0.5)
            a0 = self.aim(g)
            for i in range(5):
                self.proj(g, a0 + (i - 2) * 0.22, 80, 'page', 0.6, 5.0)
            yield 0.8
        yield 0.6

    def atk_chandelier(self, g):
        for i in range(3):
            px, py = self.pp(g)
            if i:
                px += random.uniform(-70, 70)
                py += random.uniform(-50, 50)
            self.hz(g, 'circle', px, py, 25, warn=1.3, life=0.15, mult=1.3, sound='slam', shake=5,
                    col=(255, 190, 90), fxc=[(255, 210, 120), (255, 120, 40), WHITE])
            g.later(1.35, lambda x=px, y=py: self.hz(g, 'circle', x, y, 20, warn=0.0, life=3.0, mult=0.25, tick=0.4, eff='burn',
                                                  col=(255, 120, 40)))
            yield 0.45
        yield 2.2

    def atk_blackout(self, g):
        g.blackout_t = 8.0
        g.toast("The lights go out!", (190, 170, 255), 2)
        self.alpha = 0.3
        for i in range(8):
            self.ring(g, 8, 40, 'orb', 0.55, off=random.random())
            yield 0.9
        self.alpha = 1.0
        yield 0.4

    def atk_encore(self, g):
        if self.minion_count(g) < 4:
            self.summon(g, 'poltergeist', 3, 60)
        yield 0.8
        px, py = self.pp(g)
        h = self.hz(g, 'circle', px, py, 30, warn=2.4, life=0.2, mult=1.5, sound='slam', shake=5, col=(255, 240, 160),
                    fxc=[(255, 240, 170), WHITE])
        for i in range(20):
            p = g.player
            h.x += (p.x - h.x) * 0.25
            h.y += (p.y - 4 - h.y) * 0.25
            yield 0.1
        yield 1.4


class MagmaBoss(Boss2):
    MOVES = {1: ['breath', 'stomp'], 2: ['eruptions', 'spiral'], 3: ['flood', 'breath']}
    rest = 1.3

    def __init__(self, bid, x, y):
        super().__init__(bid, x, y)
        self.cr = 24

    def atk_breath(self, g):
        a = self.aim(g)
        sgn = random.choice((-1, 1))
        cx, cy = self.cen()
        sets = 2 if self.phase >= 3 else 1
        for k in range(sets):
            self.hz(g, 'cone', cx, cy, 175, 0.26, ang=a - sgn * 0.8 + k * math.pi, warn=0.9, life=1.5, mult=0.42, tick=0.12,
                    spin=sgn * 1.1, eff='burn', eff_t=2.0, col=(255, 130, 40), fxc=[(255, 190, 80), (255, 100, 30)],
                    sound='fire_hit')
        yield 3.0

    def atk_stomp(self, g):
        px, py = self.pp(g)
        self.hz(g, 'circle', px, py, 36, warn=1.1, life=0.15, mult=1.4, sound='slam', shake=7,
                fxc=[(255, 190, 80), (255, 100, 30), WHITE], eff='burn', eff_t=2)
        self.invuln = 1.4
        for i in range(9):
            self.lift = math.sin(i / 9 * math.pi) * 34
            self.x += (px - self.x) * 0.25
            self.y += (py - self.y) * 0.25
            yield 0.1
        self.lift = 0
        self.x, self.y = px, py + 4
        self.hz(g, 'ring', px, py, 6, 8, warn=0, life=0.9, mult=0.8, grow=125, col=(255, 130, 40))
        self.open_t = 1.2
        yield 1.4

    def atk_eruptions(self, g):
        for i in range(8 + 2 * self.phase):
            px, py = self.pp(g)
            if i % 3:
                px, py = self.rand_spot(g, 30)
            self.hz(g, 'circle', px, py, 15, warn=0.9, life=0.5, mult=0.75, tick=0.12, sound='fire_hit',
                    fxc=[(255, 200, 80), (255, 100, 30), WHITE], col=(255, 100, 30), eff='burn', eff_t=1.5)
            yield 0.25
        yield 1.2

    def atk_spiral(self, g):
        rot = random.random() * 6
        for i in range(26):
            for k in range(3):
                self.proj(g, rot + k * math.tau / 3, 78, 'lava', 0.6, 5)
            rot += 0.5
            if i % 4 == 0:
                g.audio.play('fire', 0.4, 0.1)
            yield 0.1
        yield 1.0

    def atk_flood(self, g):
        x0, x1, y0, y1 = self.bounds(g)
        cx, cy = self.arena_center(g)
        safe = []
        for _ in range(3 if self.phase < 3 else 2):
            for _t in range(20):
                sx, sy = random.uniform(x0 + 40, x1 - 40), random.uniform(y0 + 40, y1 - 40)
                if all(dist(sx, sy, a, b) > 90 for a, b, _r in safe):
                    break
            safe.append((sx, sy, 24))
        g.toast("The floor turns to lava! Reach the stone!", (255, 190, 110), 2.4)
        self.hz(g, 'rect', cx, cy, x1 - x0, y1 - y0, warn=2.3, life=3.2, mult=1.1, tick=0.4, safe=safe, sound='boom', shake=4,
                eff='burn', eff_t=2, col=(255, 100, 30), fxc=[(255, 190, 80), (255, 100, 30)])
        yield 6.0


class VoidBoss(Boss2):
    MOVES = {1: ['singularity', 'gridlaser'], 2: ['tears', 'clones'], 3: ['horizon', 'eyebeams']}
    rest = 1.0

    def idle(self, g, dt, d, px, py):
        cx, cy = self.arena_center(g)
        a = self.t * 0.35
        tx, ty = cx + math.cos(a) * 60, cy + math.sin(a * 1.3) * 34
        if dist(self.x, self.y, tx, ty) > 5:
            self.chase(g, dt, tx, ty, self.speed * 0.9)

    def atk_singularity(self, g):
        cx, cy = self.cen()
        self.hz(g, 'circle', cx, cy + 14, 104, warn=0.9, life=3.2, mult=0.15, tick=0.5, force=64, col=(150, 50, 200),
                fxc=[(255, 90, 220), WHITE], name='gravity')
        self.hz(g, 'circle', cx, cy + 14, 14, warn=0.9, life=3.2, mult=0.9, tick=0.4, col=(255, 60, 200))
        g.toast("The singularity pulls you in!", (255, 150, 230), 2)
        yield 4.2
        self.ring(g, 16, 70, 'void', 0.65)
        g.audio.play('boom', 0.5)
        yield 1.0

    def atk_gridlaser(self, g):
        x0, x1, y0, y1 = self.bounds(g)
        rows = 6
        gap = random.randrange(rows)
        rh = (y1 - y0) / rows
        for i in range(rows):
            if i == gap:
                continue
            self.hz(g, 'rect', (x0 + x1) / 2, y0 + rh * (i + 0.5), x1 - x0, rh * 0.7, warn=1.1, life=0.25, mult=1.1,
                    col=(255, 60, 200), sound='crit', shake=2, fxc=[(255, 120, 230), WHITE])
        yield 1.7
        cols = 8
        gap = random.randrange(cols)
        cw = (x1 - x0) / cols
        for i in range(cols):
            if i == gap:
                continue
            self.hz(g, 'rect', x0 + cw * (i + 0.5), (y0 + y1) / 2, cw * 0.7, y1 - y0, warn=1.1, life=0.25, mult=1.1,
                    col=(255, 60, 200), sound='crit', shake=2, fxc=[(255, 120, 230), WHITE])
        yield 2.0

    def atk_tears(self, g):
        for i in range(10 + 2 * self.phase):
            px, py = self.pp(g)
            if i % 2:
                px, py = self.rand_spot(g, 20)
            self.hz(g, 'circle', px, py, 17, warn=0.9, life=0.15, mult=1.0, sound='crit', shake=1.5,
                    col=(255, 60, 200), fxc=[(255, 120, 230), (60, 10, 90), WHITE])
            yield 0.2
        yield 1.3

    def atk_clones(self, g):
        spots = [self.rand_spot(g, 50) for _ in range(3)]
        self.hidden = True
        self.invuln = 0.8
        g.fx.burst(self.x, self.y - 14, 24, [(255, 120, 230), WHITE], 90, 0.6, 2, 0, 2)
        yield 0.6
        real = random.randrange(3)
        for i, (sx, sy) in enumerate(spots):
            if i == real:
                self.teleport(g, sx, sy)
                self.hidden = False
            else:
                e = Enemy('mirage', sx, sy, 3)
                e.minion = 1
                e.aggro = True
                e.look = 'void'
                e.life = 9.0
                e.maxhp = e.hp = 1
                g.map.enemies.append(e)
        g.toast("Which Seer is real?", (255, 160, 235), 2)
        yield 3.2

    def atk_horizon(self, g):
        cx, cy = self.arena_center(g)
        g.toast("The event horizon closes in!", (255, 150, 230), 2.4)
        h = self.hz(g, 'outside', cx, cy, 215, warn=1.5, life=7.5, mult=0.45, tick=0.4, col=(120, 20, 160),
                    fxc=[(255, 90, 220)], light=False)
        yield 1.5
        for i in range(60):
            h.a = max(90, h.a - 2.1)
            if i % 12 == 0:
                self.ring(g, 10, 52, 'void', 0.55, off=i * 0.1)
            yield 0.1
        yield 1.0

    def atk_eyebeams(self, g):
        cx, cy = self.cen()
        a0 = self.aim(g)
        sgn = random.choice((-1, 1))
        for i in range(3):
            self.hz(g, 'line', cx, cy, 250, 7, ang=a0 + i * math.tau / 3, warn=1.1, life=3.6, mult=0.42, tick=0.12,
                    spin=sgn * 0.7, col=(255, 60, 200), fxc=[(255, 120, 230), WHITE], sound='warn')
        yield 5.0


BOSS_CLASSES = {'spore': SporeBoss, 'tide': TideBoss, 'sun': SunBoss, 'frost': FrostBoss, 'gear': GearBoss,
                'curator': CuratorBoss, 'magma': MagmaBoss, 'void': VoidBoss}



