NEW_ENEMY = {}
NEW_LOOT = {}
ON_DEATH = {}


def _new(kind, hp, dmg, spd, xp, gold, box, sh, name, spr, hover=0, loot=()):
    ENEMY[kind] = dict(hp=hp, dmg=dmg, spd=spd, xp=xp, gold=gold, box=box, sh=sh, name=name)
    NEW_ENEMY[kind] = dict(spr=spr, hover=hover)
    NEW_LOOT[kind] = list(loot)


def _spr(key, w, h, fn, line=OUT):
    c = _creature_cache.get(key)
    if c:
        return c
    s = S(w, h)
    fn(s)
    outline(s, line)
    _creature_cache[key] = s
    return s


