    ang = key[1] / 16 * math.tau
    pygame.draw.line(s, (60, 64, 80), (8, 8), (8 + math.cos(ang) * 8, 8 + math.sin(ang) * 6), 3)
    R(s, (255, 60, 40) if key[2] else (230, 150, 60), 7, 7, 2, 2)
    outline(s)
    _creature_cache[key] = s
    return s


