# ---- AI ------------------------------------------------------------------------------------
def _ai_melee(self, g, dt, d, px, py, rng=24, wind=0.5, reach=17, dash=80, rec=0.55, sm=1.0, aggro=105, eff=None, hold=0.16):
    self.timer -= dt
    self.moving = False
    if self.state == 'idle':
        if d < aggro and g.map.los(self.x, self.y - 6, px, py):
            self.aggro = True
        if self.aggro:
            self.state = 'chase'
        elif self.timer <= 0:
            self.timer = 1.5 + random.random() * 2
            self.dir = random.randrange(4)
    elif self.state == 'chase':
        if d > 230:
            self.aggro = False
            self.state = 'idle'
            return
        if d < rng:
            self.state = 'windup'
            self.timer = wind
            self.face_to(px, py)
            g.audio.play('warn', 0.5)
            return
        self.chase(g, dt, px, py, self.speed * sm)
    elif self.state == 'windup':
        if self.timer <= 0:
            self.state = 'attack'
            self.timer = hold
            self.atk_hit = False
            g.audio.play('swing', 0.6)
            nx, ny = norm(px - self.x, py - self.y)
            self.vx, self.vy = nx, ny
    elif self.state == 'attack':
        self.step(g.map, self.vx * dash * dt, self.vy * dash * dt, 'enemy')
        if not self.atk_hit and d < reach:
            self.atk_hit = True
            if g.player.inv_t <= 0 and g.player.dash_t <= 0:
                g.hurt_player(self.dmg, self.x, self.y)
                if eff == 'slow':
                    g.player.slow_t = max(g.player.slow_t, 2.5)
                elif eff == 'poison':
                    g.player.pois_t = max(g.player.pois_t, 3.0)
                elif eff == 'freeze':
                    g.player.slow_t = max(g.player.slow_t, 2.0)
        if self.timer <= 0:
            self.state = 'recover'
            self.timer = rec
    elif self.state == 'recover':
        if self.timer <= 0:
            self.state = 'chase'
    self.contact(g, d, 6)


def _ai_rooted(self, g, dt, d, px, py, rng=150, cool=1.7, wind=0.45, shots=None):
    self.timer -= dt
    self.cd -= dt
    self.moving = False
    self.aim_a = math.atan2(py - (self.y - 6), px - self.x)
    self.g_ref = g
    if self.state == 'idle':
        if d < rng and g.map.los(self.x, self.y - 6, px, py):
            self.aggro = True
        if self.aggro and self.cd <= 0:
            self.state = 'windup'
            self.timer = wind
            g.audio.play('warn', 0.4)
    elif self.state == 'windup':
        if self.timer <= 0:
            shots(self, g)
            self.state = 'idle'
            self.cd = cool + random.random() * 0.6
            if d > rng * 1.5:
                self.aggro = False


def _thorn_shots(self, g):
    a = self.aim_a
    for k in (-1, 0, 1):
        g.projs.append(Projectile(self.x, self.y - 8, math.cos(a + k * 0.28) * 74, math.sin(a + k * 0.28) * 74,
                                  int(self.dmg * 0.8), 'thorn', False, 3.0))
    g.audio.play('arrow', 0.5)


def _bolt_shots(self, g):
    a = self.aim_a
    n = 3 if self.floor >= 3 else 1
    for k in range(n):
        g.later(0.12 * k, lambda a=a: g.projs.append(Projectile(self.x, self.y - 8, math.cos(a) * 118, math.sin(a) * 118,
                                                                 int(self.dmg * 0.8), 'bolt', False, 2.5)) if not self.dead else None)
    g.audio.play('arrow', 0.6)


def ai_shroom(self, g, dt, d, px, py):
    _ai_melee(self, g, dt, d, px, py, rng=18, wind=0.6, reach=15, dash=60, sm=0.9, eff='poison')


def ai_thornling(self, g, dt, d, px, py):
    _ai_rooted(self, g, dt, d, px, py, shots=_thorn_shots)


def ai_turret(self, g, dt, d, px, py):
    _ai_rooted(self, g, dt, d, px, py, rng=170, cool=1.5, wind=0.5, shots=_bolt_shots)


def ai_crab(self, g, dt, d, px, py):
    _ai_melee(self, g, dt, d, px, py, rng=22, wind=0.35, reach=18, dash=150, rec=0.7, sm=1.1)


def ai_scarab(self, g, dt, d, px, py):
    _ai_melee(self, g, dt, d, px, py, rng=14, wind=0.18, reach=12, dash=150, rec=0.35, sm=1.0, aggro=140, hold=0.12)


def ai_mummy(self, g, dt, d, px, py):
    _ai_melee(self, g, dt, d, px, py, rng=22, wind=0.7, reach=19, dash=70, rec=0.9, sm=1.0, eff='slow')


def ai_automaton(self, g, dt, d, px, py):
    _ai_melee(self, g, dt, d, px, py, rng=22, wind=0.5, reach=20, dash=90, rec=0.7, sm=1.0, hold=0.2)


def ai_lavaslime(self, g, dt, d, px, py):
    self.ai_slime(g, dt, d, px, py)


def ai_jelly(self, g, dt, d, px, py):
    self.timer -= dt
    self.moving = False
    if self.state == 'idle':
        if d < 120:
            self.aggro = True
        if self.aggro:
            self.state = 'chase'
            self.cd = 2.0
    elif self.state == 'chase':
        if d > 240:
            self.aggro = False
            self.state = 'idle'
            return
        if d > 34:
            self.chase(g, dt, px, py, self.speed, ghost=False)
        self.cd -= dt
        if self.cd <= 0 and d < 60:
            self.cd = 2.8
            g.hazards.append(Hazard('circle', self.x, self.y - 4, 28, warn=0.7, life=0.12, dmg=int(self.dmg * 1.1), owner='e',
                                    col=(120, 240, 230), sound='crit', eff='slow', eff_t=1.5,
                                    fxc=[(150, 255, 245), WHITE]))
    self.contact(g, d, 9)


def ai_frostwolf(self, g, dt, d, px, py):
    self.ai_spider(g, dt, d, px, py)


def ai_icemage(self, g, dt, d, px, py):
    self.timer -= dt
    self.cd -= dt
    self.moving = False
    if self.state == 'idle':
        if d < 130 and g.map.los(self.x, self.y - 6, px, py):
            self.aggro = True
        if self.aggro:
            self.state = 'chase'
    elif self.state == 'chase':
        if d > 250:
            self.aggro = False
            self.state = 'idle'
            return
        if d < 66:
            self.chase(g, dt, px, py, self.speed * 1.2, away=True)
        elif d > 105:
            self.chase(g, dt, px, py, self.speed)
        if self.cd <= 0 and g.map.los(self.x, self.y - 6, px, py):
            self.state = 'windup'
            self.timer = 0.55
            g.audio.play('warn', 0.5)
    elif self.state == 'windup':
        if self.timer <= 0:
            if random.random() < 0.5:
                a = math.atan2(py - self.y + 6, px - self.x)
                for k in (-1, 0, 1):
                    g.projs.append(Projectile(self.x, self.y - 10, math.cos(a + k * 0.3) * 80, math.sin(a + k * 0.3) * 80,
                                              int(self.dmg * 0.8), 'ice', False, 3.0))
                g.audio.play('arrow', 0.5)
            else:
                g.hazards.append(Hazard('circle', px, py + 6, 17, warn=0.9, life=0.12, dmg=int(self.dmg * 1.1), owner='e',
                                        col=(150, 215, 255), sound='crit', eff='freeze', eff_t=1.3,
                                        fxc=[(200, 240, 255), WHITE]))
            self.state = 'chase'
            self.cd = 2.4 + random.random()


def ai_poltergeist(self, g, dt, d, px, py):
    self.timer -= dt
    self.cd -= dt
    self.moving = True
    if self.state == 'idle':
        if d < 140:
            self.aggro = True
        if self.aggro:
            self.state = 'chase'
            self.cd = 1.0
    elif self.state == 'chase':
        a = self.t * 0.9 + id(self) % 7
        tx, ty = px + math.cos(a) * 62, py + math.sin(a) * 42
        if dist(self.x, self.y, tx, ty) > 4:
            self.chase(g, dt, tx, ty, self.speed, ghost=True)
        if self.cd <= 0:
            self.cd = 2.2 + random.random() * 0.8
            a2 = math.atan2(py - self.y + 8, px - self.x)
            for k in (0,) if self.floor < 3 else (-1, 1):
                g.projs.append(Projectile(self.x, self.y - 8, math.cos(a2 + k * 0.2) * 90, math.sin(a2 + k * 0.2) * 90,
                                          int(self.dmg * 0.8), 'page', False, 3.5))
            g.audio.play('arrow', 0.4, 0.1)
    self.contact(g, d, 7)


def ai_salamander(self, g, dt, d, px, py):
    self.timer -= dt
    self.cd -= dt
    self.moving = False
    if self.state == 'idle':
        if d < 120 and g.map.los(self.x, self.y - 6, px, py):
            self.aggro = True
        if self.aggro:
            self.state = 'chase'
        elif self.timer <= 0:
            self.timer = 1.5 + random.random() * 2
            self.dir = random.randrange(4)
    elif self.state == 'chase':
        if d > 250:
            self.aggro = False
            self.state = 'idle'
            return
        if d > 64:
            self.chase(g, dt, px, py)
        elif d < 40:
            self.chase(g, dt, px, py, self.speed * 0.8, away=True)
        if self.cd <= 0 and d < 90 and g.map.los(self.x, self.y - 6, px, py):
            self.state = 'windup'
            self.timer = 0.55
            self.aim_a = math.atan2(py - self.y, px - self.x)
            g.audio.play('warn', 0.5)
    elif self.state == 'windup':
        if self.timer <= 0:
            g.hazards.append(Hazard('line', self.x, self.y - 4, 96, 11, ang=self.aim_a, warn=0.01, life=0.45,
                                    dmg=int(self.dmg * 1.1), owner='e', col=(255, 140, 50), sound='fire_hit', eff='burn',
                                    fxc=[(255, 190, 80), (255, 100, 30)]))
            self.state = 'recover'
            self.timer = 0.9
            self.cd = 2.0
    elif self.state == 'recover':
        if self.timer <= 0:
            self.state = 'chase'
    self.contact(g, d, 8)


def ai_voidling(self, g, dt, d, px, py):
    self.timer -= dt
    self.cd -= dt
    self.moving = False
    if self.state == 'idle':
        if d < 130:
            self.aggro = True
        if self.aggro:
            self.state = 'chase'
            self.cd = 1.0
    elif self.state == 'chase':
        if d > 260:
            self.aggro = False
            self.state = 'idle'
            return
        self.chase(g, dt, px, py, self.speed * 0.7)
        if self.cd <= 0 and d > 30:
            a = random.random() * math.tau
            nx, ny = px + math.cos(a) * 22, py + 6 + math.sin(a) * 14
            if not g.map.blocked((nx - 4, ny - 5, 8, 5), 'enemy'):
                g.fx.burst(self.x, self.y - 8, 10, [(255, 90, 220), (90, 30, 160)], 60, 0.4, 2, 0, 2)
                self.x, self.y = nx, ny
                g.fx.burst(self.x, self.y - 8, 10, [(255, 90, 220), (90, 30, 160)], 60, 0.4, 2, 0, 2)
                self.state = 'windup'
                self.timer = 0.4
                self.face_to(px, py)
                g.audio.play('portal', 0.3)
                self.cd = 3.0
        elif d < 22:
            self.state = 'windup'
            self.timer = 0.4
    elif self.state == 'windup':
        if self.timer <= 0:
            self.state = 'attack'
            self.timer = 0.15
            self.atk_hit = False
            g.audio.play('swing', 0.6)
    elif self.state == 'attack':
        if not self.atk_hit and d < 21:
            self.atk_hit = True
            g.hurt_player(self.dmg, self.x, self.y)
        if self.timer <= 0:
            self.state = 'recover'
            self.timer = 0.6
    elif self.state == 'recover':
        if self.timer <= 0:
            self.state = 'chase'
    self.contact(g, d, 6)


def ai_watcher(self, g, dt, d, px, py):
    self.timer -= dt
    self.cd -= dt
    self.moving = False
    if self.state == 'idle':
        if d < 140 and g.map.los(self.x, self.y - 6, px, py):
            self.aggro = True
        if self.aggro:
            self.state = 'chase'
            self.cd = 1.4
    elif self.state == 'chase':
        if d > 270:
            self.aggro = False
            self.state = 'idle'
            return
        if d < 80:
            self.chase(g, dt, px, py, self.speed, ghost=True, away=True)
        elif d > 120:
            self.chase(g, dt, px, py, self.speed, ghost=True)
        if self.cd <= 0 and g.map.los(self.x, self.y - 6, px, py):
            self.state = 'windup'
            self.timer = 0.95
