for _k, (_n, _v, _f, _c) in NEW_MATS.items():
    LOOT[_k] = (_n, _v)
KEEP_LOOT = KEEP_LOOT + tuple(NEW_MATS)
_mat_icons = {}


def mat_icon(name):
    im = _mat_icons.get(name)
    if im is not None:
        return im
    nm, val, form, c = NEW_MATS[name]
    s = S(16, 16)
    dk = mul_c(c, 0.5)
    lt = lerp_c(c, WHITE, 0.55)
    if form == 'orb':
        pygame.draw.circle(s, dk, (8, 8), 6)
        pygame.draw.circle(s, c, (8, 8), 5)
        R(s, lt, 5, 5, 2, 2)
    elif form == 'drop':
        pygame.draw.polygon(s, c, [(8, 2), (12, 9), (8, 14), (4, 9)])
        pygame.draw.circle(s, c, (8, 10), 4)
        R(s, lt, 6, 7, 1, 3)
    elif form == 'scale':
        pygame.draw.ellipse(s, c, (3, 3, 10, 10))
        pygame.draw.ellipse(s, dk, (3, 3, 10, 10), 1)
        pygame.draw.line(s, lt, (6, 5), (6, 11), 1)
        pygame.draw.line(s, lt, (9, 5), (9, 11), 1)
    elif form == 'coral':
        for (x, y0) in ((5, 8), (8, 4), (11, 7)):
            pygame.draw.line(s, c, (8, 14), (x, y0), 2)
        R(s, lt, 8, 4, 1, 1)
    elif form == 'beetle':
        pygame.draw.ellipse(s, (60, 110, 210), (3, 4, 10, 9))
        R(s, c, 7, 4, 2, 9)
        R(s, dk, 6, 2, 4, 3)
    elif form == 'cloth':
        pygame.draw.polygon(s, c, [(3, 4), (13, 3), (12, 13), (4, 12)])
        for y in (6, 9):
            pygame.draw.line(s, dk, (3, y), (12, y), 1)
    elif form == 'shard':
        pygame.draw.polygon(s, c, [(8, 1), (12, 7), (9, 14), (5, 8)])
        pygame.draw.polygon(s, lt, [(8, 1), (9, 6), (7, 7)])
        pygame.draw.polygon(s, dk, [(5, 8), (9, 14), (8, 8)])
    elif form == 'gear':
        pygame.draw.circle(s, c, (8, 8), 5)
        for i in range(8):
            a = i * math.pi / 4
            R(s, c, int(8 + math.cos(a) * 6) - 1, int(8 + math.sin(a) * 6) - 1, 2, 2)
        pygame.draw.circle(s, dk, (8, 8), 2)
    elif form == 'coil':
        for y in (3, 6, 9, 12):
            pygame.draw.line(s, c, (4, y), (12, y + 1), 2)
    elif form == 'page':
        R(s, c, 3, 2, 10, 12)
        R(s, dk, 3, 2, 10, 1)
        for y in (5, 7, 9, 11):
            R(s, (140, 100, 70), 5, y, 6, 1)
    elif form == 'gem':
        pygame.draw.polygon(s, c, [(8, 1), (14, 6), (12, 14), (4, 14), (2, 6)])
        pygame.draw.polygon(s, lt, [(8, 1), (14, 6), (8, 7)])
        pygame.draw.polygon(s, dk, [(2, 6), (8, 7), (4, 14)])
        R(s, WHITE, 7, 3, 2, 2)
    outline(s)
    _mat_icons[name] = s
    return s


def make_bounty(rank, abyss_best, boss_dead, taken):
    pool = [b for b in BOUNTY_POOL if (b[0] != 'abyss' or boss_dead) and b[2] not in taken]
    typ, kinds, label, (lo, hi), unit = random.choice(pool)
    mult = 1 + 0.3 * rank
    if typ == 'abyss':
        n = abyss_best + random.randint(lo, hi)
        name = "Reach Abyss depth %d" % n
        gold = int((n - abyss_best) * unit * 2 * mult)
    else:
        n = random.randint(lo, hi)
        verb = {'kill': "Slay", 'elite': "Slay", 'chest': "Open", 'fish': "Catch"}[typ]
        name = "%s %d %s" % (verb, n, label)
        gold = int(n * unit * mult)
    return dict(type=typ, kinds=list(kinds), n=n, prog=0, gold=gold, rep=max(3, gold // 18), xp=gold // 2,
                name=name, label=label, done=False)


class Player(Ent):
    def __init__(self):
        super().__init__(0, 0, 8, 5)
        self.reset_all()

    def reset_all(self):
        self.relics = []
        self.ash_used = False
        self.diff, self.heat, self.asc = DEFAULT_DIFF, 0, 0
        self.level, self.xp, self.gold = 1, 0, 30
        self.wt = self.at = self.wplus = self.aplus = self.tonics = 0
        self.charms = set()
        self.inv = {'hp_potion': 2, 'mp_potion': 1, 'elixir': 0}
        self.q = {}
        self.flags = set()
        self.kills = 0
        self.deaths = 0
        self.playtime = 0.0
        self.maxfloor = 0
        self.sp = 0
        self.skills = {}
        self.rep = 0
        self.abyss_best = 0
        self.arena_best = 0
        self.st = {}
        self.trophies = set()
        self.bounties = []
        self.rod = 0
        self.phoenix_ready = False
        self.spells = ['fire']
        self.slots = ['fire', None, None, None]
        self.spuse = {}
        self.rune = None
        self.gsel = None
        self.sel = 0
        self.reset_state()
        self.hp = self.max_hp
        self.mp = self.max_mp
        self.ghost = 1.0

    def reset_state(self):
        self.dir, self.fx, self.fy = 0, 0.0, 1.0
        self.atk_t = -1.0
        self.atk_dur = 0.28
        self.combo, self.combo_t, self.cool = 0, 0.0, 0.0
        self.atk_hit = set()
        self.atk_ang = 0.0
        self.sweep = 1
        self.dash_t = self.dash_cd = 0.0
        self.dvx = self.dvy = 0.0
        self.inv_t = 0.0
        self.z = 0.0
        self.t = 0.0
        self.moving = False
        self.elixir_t = 0.0
        self.power_t = self.fortune_t = self.stone_t = 0.0
        self.regen_t = 0.0
        self.mp_t = 0.0
        self.fire_cd = 0.0
        self.step_t = 0.0
        self.last_safe = (self.x, self.y)
        self.dead = False
        self.after = []
        self.kbx = self.kby = 0.0
        self.lunge = 0.0
        self.drink_t, self.drink_kind, self.drink_done, self.potion_cd = -1.0, None, False, 0.0
        self.hurt_t = self.cast_t = 0.0
        self.focus_t = self.perfect_cd = 0.0
        self.walk_ph, self.last_ph = 0.0, 0
        self.dox = self.doy = 0.0
        self.sp_cd = {}
        self.slow_t = self.rev_t = self.blind_t = self.pois_t = self.pois_acc = 0.0
        self.aegis, self.aegis_t, self.blood_t = 0, 0.0, 0.0
        self.blades_t, self.blade_ph, self.blade_cd, self.blades_dmg = 0.0, 0.0, {}, 1
        self.swift_t = self.brew_t = self.meal_t = self.gad_cd = self.meal_acc = 0.0
        self.meal_id = None

    def sk(self, k):
        return self.skills.get(k, 0)

    def meal_fx(self, k, default):
        if self.meal_t > 0 and self.meal_id in MEAL_FX:
            return MEAL_FX[self.meal_id].get(k, default)
        return default

    def has(self, r):
        return r in self.relics

    @property
    def rank(self):
        return rank_index(self.rep)

    @property
    def max_hp(self):
        return 60 + 12 * (self.level - 1) + 10 * self.tonics + 8 * self.sk('vital') + (25 if self.has('heart') else 0)

    @property
    def max_mp(self):
        return 12 + 3 * (self.level - 1) + (10 if 'crystal' in self.charms else 0)

    @property
    def atk(self):
        a = WEAPONS[self.wt][1] + 2 * self.wplus + 1.5 * (self.level - 1)
        a *= 1 + 0.06 * self.sk('might')
        if self.elixir_t > 0:
            a *= 1.5
        if self.power_t > 0:
            a *= 1.3
        if self.has('glass'):
            a *= 1.4
        if self.focus_t > 0:
            a *= 1.5
        if self.blood_t > 0:
            a *= 1.4
        a *= self.meal_fx('atk', 1.0)
        return a

    @property
    def dfn(self):
        return ARMORS[self.at][1] + self.aplus + self.sk('skin') + (4 if self.stone_t > 0 else 0) + self.meal_fx('dfn', 0) + (2 if 'warden' in self.charms else 0)

    @property
    def speed(self):
        return 58 * (1.12 if 'boots' in self.charms else 1.0) * (1 + 0.04 * self.sk('swift')) * \
            (1.15 if self.power_t > 0 else 1.0) * (1.15 if self.has('boots') else 1.0) * (0.55 if self.slow_t > 0 else 1.0) * (1.25 if self.swift_t > 0 else 1.0)

    @property
    def crit(self):
        return 0.06 + (0.12 if 'clover' in self.charms else 0.0) + 0.03 * self.sk('keen') + \
            (0.15 if self.has('sigil') else 0.0)

    @property
    def crit_mult(self):
        return 2.0 + 0.15 * self.sk('deadly')

    @property
    def dash_cdmax(self):
        return 0.65 * MODS.get('dcd', 1.0) * (1 - 0.1 * self.sk('fleet')) * (0.8 if self.has('boots') else 1.0)

    @property
    def gold_mult(self):
        return (1 + 0.08 * self.sk('hunter')) * (1.5 if self.fortune_t > 0 else 1.0) * (1 + 0.02 * self.rank) * \
            MODS.get('gold', 1.0) * (1.4 if self.has('midas') else 1.0) * self.meal_fx('gold', 1.0)

    @property
    def xp_mult(self):
        return (1 + 0.06 * self.sk('scholar')) * (1 + 0.02 * self.rank) * MODS.get('xp', 1.0) * self.meal_fx('xp', 1.0) * \
            (1.15 if 'sunstone' in self.charms else 1.0)

    def to_dict(self):
        return dict(level=self.level, xp=self.xp, gold=self.gold, wt=self.wt, at=self.at, wplus=self.wplus,
                    aplus=self.aplus, tonics=self.tonics, charms=sorted(self.charms), inv=self.inv, q=self.q,
                    flags=sorted(self.flags), kills=self.kills, deaths=self.deaths, playtime=self.playtime,
                    maxfloor=self.maxfloor, hp=self.hp, mp=self.mp, sp=self.sp, skills=self.skills,
                    rep=self.rep, abyss_best=self.abyss_best, arena_best=self.arena_best, st=self.st,
                    trophies=sorted(self.trophies), bounties=self.bounties, rod=self.rod,
                    dv=2, diff=self.diff, heat=self.heat, asc=self.asc, spells=self.spells, slots=self.slots, spuse=self.spuse, rune=self.rune, gsel=self.gsel)

    def from_dict(self, d):
        self.reset_all()
        for k in ('level', 'xp', 'gold', 'wt', 'at', 'wplus', 'aplus', 'tonics', 'kills', 'deaths', 'playtime',
                  'maxfloor', 'sp', 'rep', 'abyss_best', 'arena_best', 'rod', 'diff', 'heat', 'asc'):
            if k in d:
                setattr(self, k, d[k])
        self.charms = set(d.get('charms', []))
        self.inv.update(d.get('inv', {}))
        self.q = d.get('q', {})
        self.flags = set(d.get('flags', []))
        self.skills = d.get('skills', {})
        self.st = d.get('st', {})
        self.spells = d.get('spells', ['fire'])
        self.slots = (d.get('slots', ['fire', None, None, None]) + [None] * 4)[:4]
        self.spuse = d.get('spuse', {})
        self.rune = d.get('rune')
        self.gsel = d.get('gsel')
        self.trophies = set(d.get('trophies', []))
        self.bounties = d.get('bounties', [])
        if d.get('dv', 1) < 2:              # old saves: Wanderer/Veteran/Nightmare/Ironman -> new ladder
            self.diff = {0: 1, 1: 2, 2: 3, 3: 5}.get(self.diff, 2)
        self.diff = max(0, min(len(DIFFS) - 1, self.diff))
        self.hp = min(self.max_hp, d.get('hp', self.max_hp))
        self.mp = min(self.max_mp, d.get('mp', self.max_mp))
        self.ghost = self.hp / self.max_hp
        recalc_mods(self)


def shorten(s, n):
    return s if len(s) <= n else s[:n - 1] + "."


recalc_mods(Player())


class Gamepad:
    """PS4 / DualShock 4 (and any SDL-mapped pad). Polled each frame -> set of virtual keys held."""
    DEAD = 0.34

    def __init__(self):
        self.c = None
        self.js = None
        self.name = ""
        self.sdl = None
        self.scan_t = 0.0
        try:
            from pygame._sdl2 import controller as sdlc
            sdlc.init()
            self.sdl = sdlc
        except Exception:
            self.sdl = None
        try:
            pygame.joystick.init()
        except Exception:
            pass
        self.scan()

    @property
    def connected(self):
        return self.c is not None or self.js is not None

    def scan(self):
        self.c = self.js = None
        self.name = ""
        try:
            if self.sdl:
                for i in range(self.sdl.get_count()):
                    if self.sdl.is_controller(i):
                        self.c = self.sdl.Controller(i)
                        try:
                            self.name = self.sdl.name_forindex(i) or "Controller"
                        except Exception:
                            self.name = "Controller"
                        return
        except Exception:
            self.c = None
        try:
            if pygame.joystick.get_count() > 0:
                self.js = pygame.joystick.Joystick(0)
                self.js.init()
                self.name = self.js.get_name()
        except Exception:
            self.js = None

    def rumble(self, lo=0.5, hi=0.7, ms=160):
        try:
            if self.c is not None:
                self.c.rumble(lo, hi, ms)
            elif self.js is not None:
                self.js.rumble(lo, hi, ms)
        except Exception:
            pass

    def poll(self, dt):
        held = set()
        if not self.connected:
            self.scan_t -= dt
            if self.scan_t <= 0:
                self.scan_t = 2.0
                self.scan()
            return held
        try:
            if self.c is not None:
                if not self.c.attached():
                    self.scan()
                    return held
                P = pygame
                b = lambda n: bool(self.c.get_button(getattr(P, n, -99))) if hasattr(P, n) else False
                ax = lambda n: self.c.get_axis(getattr(P, n)) / 32768.0 if hasattr(P, n) else 0.0
                lx, ly = ax('CONTROLLER_AXIS_LEFTX'), ax('CONTROLLER_AXIS_LEFTY')
                for name, btn in (('up', 'CONTROLLER_BUTTON_DPAD_UP'), ('down', 'CONTROLLER_BUTTON_DPAD_DOWN'),
                                  ('left', 'CONTROLLER_BUTTON_DPAD_LEFT'), ('right', 'CONTROLLER_BUTTON_DPAD_RIGHT'),
                                  ('cross', 'CONTROLLER_BUTTON_A'), ('circle', 'CONTROLLER_BUTTON_B'),
                                  ('square', 'CONTROLLER_BUTTON_X'), ('triangle', 'CONTROLLER_BUTTON_Y'),
                                  ('l1', 'CONTROLLER_BUTTON_LEFTSHOULDER'), ('r1', 'CONTROLLER_BUTTON_RIGHTSHOULDER'),
                                  ('options', 'CONTROLLER_BUTTON_START'), ('share', 'CONTROLLER_BUTTON_BACK'),
                                  ('share', 'CONTROLLER_BUTTON_TOUCHPAD'),
                                  ('l3', 'CONTROLLER_BUTTON_LEFTSTICK'), ('r3', 'CONTROLLER_BUTTON_RIGHTSTICK')):
                    if b(btn):
                        held.add(name)
                if ax('CONTROLLER_AXIS_TRIGGERLEFT') > 0.4:
                    held.add('l2')
                if ax('CONTROLLER_AXIS_TRIGGERRIGHT') > 0.4:
                    held.add('r2')
            else:
                j = self.js
                nb = j.get_numbuttons()
                bt = lambda i: i < nb and bool(j.get_button(i))
                lx = j.get_axis(0) if j.get_numaxes() > 0 else 0.0
                ly = j.get_axis(1) if j.get_numaxes() > 1 else 0.0
                for name, i in (('cross', 0), ('circle', 1), ('square', 2), ('triangle', 3), ('share', 4),
                                ('options', 6), ('l3', 7), ('r3', 8), ('l1', 9), ('r1', 10), ('share', 13)):
                    if bt(i):
                        held.add(name)
                if j.get_numhats() > 0:
                    hx, hy = j.get_hat(0)
                    if hx < 0:
                        held.add('left')
                    if hx > 0:
                        held.add('right')
                    if hy > 0:
                        held.add('up')
                    if hy < 0:
                        held.add('down')
                elif nb > 14:
                    for name, i in (('up', 11), ('down', 12), ('left', 13), ('right', 14)):
                        if bt(i):
                            held.add(name)
                na = j.get_numaxes()
                if na > 5:
                    if j.get_axis(4) > 0.2:
                        held.add('l2')
                    if j.get_axis(5) > 0.2:
                        held.add('r2')
            if lx < -self.DEAD:
                held.add('left')
            if lx > self.DEAD:
                held.add('right')
            if ly < -self.DEAD:
                held.add('up')
            if ly > self.DEAD:
                held.add('down')
        except Exception:
            self.scan()
            return set()
        if 'l1' in held and 'r1' in held:           # L1 + R1 together = next gadget
            held.discard('l1')
            held.discard('r1')
            held.add('chord')
        return {PADK[n] for n in held}


