def tod_color(t):
    for i in range(len(TOD_KEYS) - 1):
        a, b = TOD_KEYS[i], TOD_KEYS[i + 1]
        if a[0] <= t <= b[0]:
            return lerp_c(a[1], b[1], (t - a[0]) / (b[0] - a[0]))
    return (255, 255, 255)


