def recipe_name(r):
    k, x = r['kind'], r['res']
    if k == 'item':
        return ITEM_NAMES.get(x, x) + (" x%d" % r['qty'] if r['qty'] > 1 else "")
    if k == 'tome':
        return "Tome: " + SPELL_BY_ID[x][1]
    if k == 'rune':
        return RUNES[x][0]
    return CRAFT_CHARMS[x][0] if x in CRAFT_CHARMS else CHARMS[x][0]


def recipe_desc(r):
    k, x = r['kind'], r['res']
    if k == 'item':
        if x in EXTRA_ITEMS:
            return EXTRA_ITEMS[x][1]
        return {'hp_potion': "Restores 50 HP", 'mp_potion': "Restores 18 MP", 'big_hp': "Restores 130 HP",
                'big_mp': "Restores 50 MP", 'elixir': "+50% ATK for 50s", 'fortune': "+50% gold for 2 min",
                'stoneskin': "+4 DEF for 2 min"}.get(x, "")
    if k == 'tome':
        return SPELL_BY_ID[x][5]
    if k == 'rune':
        return RUNES[x][2] + " Replaces your current rune."
    return CRAFT_CHARMS[x][1]


def recipe_icon(r):
    k, x = r['kind'], r['res']
    if k == 'tome':
        return spell_icon(x, 16)
    if k == 'rune':
        return icon('rune_' + x)
    return icon(x)


