RIFT_MODS = [
    ("Brittle Rift", "Foes +50% HP, +30% XP & gold", dict(hp=1.5, xp=1.3, gold=1.3)),
    ("Hasted Rift", "Foes +25% speed, +40% gold", dict(spd=1.25, gold=1.4)),
    ("Bloodthirst Rift", "Foes +35% damage, +50% drops", dict(dmg=1.35, drop=1.5)),
    ("Famine Rift", "Healing halved, +50% XP", dict(heal=0.5, xp=1.5)),
    ("Golden Rift", "+100% gold, foes +20% HP", dict(gold=2.0, hp=1.2)),
    ("Glass Rift", "Foes hit 60% harder but have 40% less HP", dict(dmg=1.6, hp=0.6)),
    ("Scholar's Rift", "+80% XP, foes +25% HP", dict(xp=1.8, hp=1.25)),
]


def rift_today():
    import datetime
    d = datetime.date.today()
    day = d.year * 10000 + d.month * 100 + d.day
    r = random.Random(day)
    return day, r.sample(RIFT_MODS, 2)


