class VillageMixin:
    """Everything that makes Emberfall a place to live: farm, quarry, arena, projects, daily secrets, ..."""

    # ------------------------------------------------------------ helpers
    def day_no(self):
        import datetime
        return datetime.date.today().toordinal()

    def has_proj(self, k):
        return ('proj_' + k) in self.player.flags

    def district_at(self, tx, ty):
        for (nm, x0, y0, x1, y1) in DISTRICTS:
            if x0 <= tx <= x1 and y0 <= ty <= y1:
                return nm
        return "EMBERFALL"

    def item_label(self, k):
        if k in ITEM_NAMES:
            return ITEM_NAMES[k]
        if k in LOOT:
            return LOOT[k][0]
        return k.title()

    def pay_ok(self, gold, mats):
        p = self.player
        if p.gold < gold:
            return False
        return all(p.inv.get(k, 0) >= v for k, v in mats.items())

    def pay(self, gold, mats):
        p = self.player
        p.gold -= gold
        for k, v in mats.items():
            p.inv[k] = p.inv.get(k, 0) - v

    def give_item(self, k, n=1, announce=True):
        p = self.player
        p.inv[k] = p.inv.get(k, 0) + n
        if announce:
            self.toast("+%d %s" % (n, self.item_label(k)), GOLD if k in ('nugget', 'geode', 'moonbloom') else CREAM, 2.4)

    def obj_pal(self, col=(176, 126, 80)):
        return dict(tun=col, bald=True, skin=col)

    # ------------------------------------------------------------ population
    def populate_village(self, m):
        A = m.npcs
        N = lambda x, y, name, pal, dlg, wander=0, reach=26, face=0, pitch=1.0: A.append(
            NPC(x * 16, y * 16, name, PAL[pal], dlg, wander, reach, face, pitch))
        N(45.5, 34.6, "Elder Maren", 'elder', 'elder', 14, 28, 3, 0.8)
        N(51, 8.5, "Guard Torvin", 'guard', 'guard', 0, 28, 2, 0.6)
        N(50, 31, "Lio", 'child', 'child', 55, 24, 0, 1.8)
        N(27, 31, "Pim", 'kid2', 'kid2', 60, 24, 0, 1.7)
        N(23, 35.6, "Tessa", 'woman', 'woman', 0, 26, 1, 1.4)
        N(28, 35.6, "Dorrie", 'baker', 'baker', 0, 26, 1, 1.3)
        N(33, 35.6, "Rowan", 'rover', 'rover', 0, 26, 1, 0.9)
        N(45.5, 50.4, "Old Gus", 'fisher', 'fisher', 0, 26, 2, 0.9)
        N(75, 31.5, "Hobb", 'farmer', 'farmer', 12, 26, 3, 0.7)
        N(10, 32.4, "Vex", 'gladiator', 'gladiator', 0, 28, 0, 0.6)
        N(13, 51, "Dagna", 'miner', 'miner', 0, 28, 3, 0.8)
        N(32, 22.2, "Lyric", 'bard', 'bard', 0, 28, 0, 1.5)
        N(67, 37.5, "Mags", 'gambler', 'gambler', 0, 28, 0, 1.1)
        N(65.5, 22.6, "Wren", 'ghost', 'ghost', 6, 28, 0, 1.9)
        N(82, 66.4, "Ozzo", 'hermit', 'hermit', 0, 28, 0, 0.7)
        placed = False
        px0, py0 = 47, 32
        for ring in range(0, 7):
            for dx in range(-ring, ring + 1):
                for dy in range(-ring, ring + 1):
                    if max(abs(dx), abs(dy)) != ring or placed:
                        continue
                    tx_, ty_ = px0 + dx, py0 + dy
                    bx_, by_ = tx_ * 16 + 8, ty_ * 16 + 14
                    ok = all(not m.blocked(Ent(bx_ + ox_, by_ + oy_, 10, 6).rect(), 'enemy', None)
                             for ox_ in (-14, 0, 14) for oy_ in (-12, 0, 12))
                    if ok:
                        m.add_prop(Prop(bx_, by_, [prop_pact(i) for i in range(4)], solid=(-5, -6, 10, 6), fps=8,
                                        light=(54, (255, 90, 50), 0.35), shd=(16, 5)))
                        m.interacts.append((bx_, by_, 22, 'pact', None))
                        m.pact_pos = (bx_, by_)
                        placed = True
        m.animals = [Animal(53 * 16, 31 * 16, 'cat'), Animal(21 * 16, 22 * 16, 'cat'), Animal(69 * 16, 40 * 16, 'cat'),
                     Animal(30 * 16, 20 * 16, 'dog'), Animal(46 * 16, 39 * 16, 'dog'), Animal(10 * 16, 38 * 16, 'dog')]
        for (x, y) in ((78, 42), (80, 43), (82, 42), (84, 43), (87, 42)):
            m.animals.append(Animal(x * 16, y * 16 + 6, 'chicken'))
        for o in list(m.npcs) + list(m.animals):
            for _ in range(30):
                if not m.blocked(o.rect(), 'enemy', o):
                    break
                o.y += 4
        self.vill_props(m)
        self.refresh_digs(m)
        self.refresh_sprites(m)
        self.apply_projects(m)

    def vill_props(self, m):
        self._plot_pr = {}
        self._ore_pr = {}
        self._apple_pr = {}
        for pr in m.props:
            if pr.name == 'plot':
                self._plot_pr[pr.data] = pr
            elif pr.name == 'vein':
                self._ore_pr[pr.data] = pr
            elif pr.name == 'apple':
                self._apple_pr[pr.data] = pr
        self._vsig = {}
        self._vtick = 0.0
        self._last_dist = None
        self._dist_t = 0.0

    def refresh_digs(self, m):
        p = self.player
        day = self.day_no()
        d = p.st.get('dig')
        if not d or d.get('d') != day:
            d = p.st['dig'] = {'d': day, 'got': []}
        m.props = [pr for pr in m.props if pr.name != 'dig']
        m.interacts = [it for it in m.interacts if it[3] != 'dig']
        n = 9 if self.has_proj('lanterns') else 6
        r = random.Random(day * 7919 + 13)
        spots = r.sample(range(len(DIG_TILES)), n)
        self._dig_spots = spots
        self._dig_day = day
        for idx in spots:
            if idx in d['got']:
                continue
            tx, ty = DIG_TILES[idx]
            m.props.append(Prop(tx * 16 + 8, ty * 16 + 14, [prop_dig(0), prop_dig(1)], fps=2.5, name='dig', data=idx))
            m.interacts.append((tx * 16 + 8, ty * 16 + 12, 14, 'dig', idx))

    def refresh_sprites(self, m):
        p = self.player
        got = p.st.get('sprites', [])
        m.props = [pr for pr in m.props if pr.name != 'wisp']
        m.interacts = [it for it in m.interacts if it[3] != 'sprite']
        for i, (tx, ty) in enumerate(SPRITE_TILES):
            if i in got:
                continue
            m.props.append(Prop(tx * 16 + 8, ty * 16 + 16, [prop_wisp(k) for k in range(4)], fps=5, name='wisp', data=i,
                                light=(46, (255, 170, 80), 0.3)))
            m.lights.append((tx * 16 + 8, ty * 16 + 8, 46, (255, 170, 80), 0.3, False))
            m.interacts.append((tx * 16 + 8, ty * 16 + 10, 14, 'sprite', i))

    def apply_projects(self, m):
        """add the landmark props of finished projects (idempotent)"""
        have = getattr(m, 'built', None)
        if have is None:
            have = m.built = set()
        for k, (pos, kind, sol, lt) in {
            'greenhouse': ((89 * 16, 43 * 16 + 4), 'greenhouse', (-22, -14, 44, 12), (60, (200, 255, 220), 0.1)),
            'belltower': ((78 * 16 + 4, 13 * 16), 'belltower', (-10, -8, 20, 8), (54, (255, 230, 150), 0.1)),
            'minecart': ((17 * 16, 59 * 16), 'rails', None, None),
            'grandstand': ((5 * 16, 31 * 16), 'stands', (-3, -4, 6, 4), (40, (255, 220, 120), 0.1)),
            'suites': ((58 * 16 + 4, 44 * 16 - 4), 'suites', (-3, -3, 6, 3), None),
            'lanterns': ((44 * 16, 33 * 16), 'lantern0', None, (64, (255, 120, 120), 0.15)),
        }.items():
            if k in have or not self.has_proj(k):
                continue
            have.add(k)
            m.add_prop(Prop(pos[0], pos[1], prop_landmark(kind), solid=sol, shd=(22, 7), light=lt))
            if k == 'lanterns':
                for i, (lx, ly) in enumerate(((52, 33), (44, 23), (52, 23), (41, 30), (54, 30), (46, 12), (50, 12),
                                              (40, 36), (56, 36))):
                    m.add_prop(Prop(lx * 16 + 8, ly * 16 + 12, prop_landmark('lantern%d' % (i % 3)), solid=None,
                                    light=(54, [(255, 120, 120), (110, 200, 255), (255, 214, 92)][i % 3], 0.15)))
            if k == 'pier':
                pass
        if self.has_proj('pier') and 'pier' not in have:
            have.add('pier')
            for yy in (53, 57):
                m.add_prop(Prop(49 * 16 + 4, yy * 16 + 14, prop_lamp(), solid=(-2, -3, 4, 3), shd=(10, 4),
                                light=(58, (255, 214, 130), 0.1, True)))
        if self.has_proj('minecart') and 'minecart2' not in have:
            have.add('minecart2')

    # ------------------------------------------------------------ per-frame
    def update_village(self, dt):
        m = self.map
        if m.kind != 'village' or not hasattr(self, '_plot_pr'):
            return
        p = self.player
        self._vtick -= dt
        self._dist_t -= dt
        if self._vtick <= 0:
            self._vtick = 0.5
            now = time.time()
            farm = p.st.get('farm', {})
            for idx, pr in self._plot_pr.items():
                e = farm.get(str(idx))
                if e is None:
                    sig = (0, 'turnip')
                else:
                    fr = (now - e[1]) / self.crop_time(e[0])
                    sig = (1 if fr < 0.34 else (2 if fr < 1 else 3), e[0])
                if self._vsig.get(('p', idx)) != sig:
                    self._vsig[('p', idx)] = sig
                    pr.frames = [prop_plot(sig[0], sig[1])]
                    if sig[0] == 3:
                        pr.frames = [prop_plot(3, sig[1]), prop_plot(3, sig[1])]
            ores = p.st.get('ore', {})
            for idx, pr in self._ore_pr.items():
                sig = now >= ores.get(str(idx), 0)
                if self._vsig.get(('o', idx)) != sig:
                    self._vsig[('o', idx)] = sig
                    pr.frames = [prop_vein(sig, idx)]
            ap = p.st.get('apples', {})
            for idx, pr in self._apple_pr.items():
                sig = now >= ap.get(str(idx), 0)
                if self._vsig.get(('a', idx)) != sig:
                    self._vsig[('a', idx)] = sig
                    pr.frames = [prop_apple_tree(sig)]
            if self.day_no() != getattr(self, '_dig_day', None):
                self.refresh_digs(m)
        # ripe crops sparkle
        if random.random() < dt * 3:
            for idx, pr in self._plot_pr.items():
                if self._vsig.get(('p', idx), (0,))[0] == 3 and abs(pr.x - p.x) < 150 and abs(pr.y - p.y) < 100:
                    self.fx.add(pr.x + random.uniform(-6, 6), pr.y - 8, 0, -12, 0.7, (255, 240, 160), 1)
                    break
        # district banner
        if self._dist_t <= 0 and self.state == 'play':
            dn = self.district_at(int(p.x // 16), int(p.y // 16))
            if dn != self._last_dist:
                if self._last_dist is not None or True:
                    self.banner = [dn, 0.0]
                    self.banner_gold = False
                self._last_dist = dn
                self._dist_t = 2.0

    def interact_label(self, it):
        kind, obj = it[0], it[1]
        if kind == 'npc':
            return obj.name
        p = self.player
        now = time.time()
        if kind == 'plot':
            e = p.st.get('farm', {}).get(str(obj))
            if e is None:
                return "Plant"
            left = e[1] + self.crop_time(e[0]) - now
            return "Harvest" if left <= 0 else "%s %s" % (CROPS[e[0]][0], fmt_dur(left))
        if kind == 'ore':
            return "Mine" if now >= p.st.get('ore', {}).get(str(obj), 0) else "Recovering"
        if kind == 'apple':
            return "Shake tree" if now >= p.st.get('apples', {}).get(str(obj), 0) else "No fruit yet"
        return {'dig': "Dig!", 'sprite': "Ember Sprite", 'spring': "Soak", 'dummy': "Hit dummy", 'jukebox': "Jukebox",
                'dice': "Play dice", 'fishspot': "Fish", 'board': "Bounty board", 'bench': "Workbench",
                'cauldron': "Cauldron", 'pact': "Ember Pact", 'text': "Read", 'cat': "Pet", 'dog': "Pet",
                'chest': "Open", 'beacon': "Beacon"}.get(kind)

    def wisp_pos(self):
        p = self.player
        t = self.time
        return p.x - 16 * p.fx * 0 + math.cos(t * 1.6) * 15, p.y - 24 + math.sin(t * 2.3) * 5

    def vmap_surface(self, m):
        cols = {GRASS: (58, 108, 58), FLOWER: (70, 120, 64), PATH: (176, 140, 92), COBBLE: (170, 170, 190),
                WATER: (50, 100, 190), SAND: (214, 194, 130), WOOD: (150, 106, 64), DGRASS: (46, 80, 50),
                FLOOR: (80, 80, 108), WALL: (46, 46, 70), BRIDGE: (150, 106, 64)}
        w, h = m.w // 2, m.h // 2
        s = S(w, h)
        for y in range(h):
            for x in range(w):
                c = cols.get(m.tiles[y * 2 + 1][x * 2 + 1], (58, 108, 58))
                s.set_at((x, y), c)
        for k, (cx, by) in m.houses.items():
            tx, ty = int(cx // 32), int((by - 24) // 32)
            c = (210, 100, 90) if k in ('smith', 'alch', 'general', 'inn', 'library', 'hall', 'chapel') else (150, 110, 90)
            R(s, c, tx - 1, ty, 3, 2)
        for (px_, py_, ccol) in ((VPOS['gate'][0], VPOS['gate'][1], (255, 190, 80)), (10 * 16, 29 * 16, (240, 90, 90)),
                                 (VPOS['plaza'][0], VPOS['plaza'][1], (130, 210, 255))):
            R(s, ccol, int(px_ // 32) - 1, int(py_ // 32) - 1, 2, 2)
        return s

    def draw_vmap(self, surf):
        m = self.map
        p = self.player
        if getattr(m, 'vmm', None) is None:
            m.vmm = self.vmap_surface(m)
        mw, mh = m.vmm.get_size()
        bx, by = W - mw - 6, 22
        panel(surf, bx - 2, by - 2, mw + 4, mh + 4, None, (10, 8, 20), (110, 100, 150))
        surf.blit(m.vmm, (bx, by))
        if int(self.time * 3) % 2 == 0:
            surf.fill(WHITE, (bx + int(p.x // 32) - 1, by + int(p.y // 32) - 1, 3, 3))
        else:
            surf.fill(RED, (bx + int(p.x // 32), by + int(p.y // 32), 1, 1))

    def crop_time(self, crop):
        t = CROPS[crop][2]
        return t * (0.65 if self.has_proj('greenhouse') else 1.0)

    # ------------------------------------------------------------ interaction dispatcher
    def village_interact(self, kind, obj):
        fn = getattr(self, 'vi_' + kind, None)
        if fn:
            fn(obj)

    # ---- farm
    def vi_plot(self, idx):
        p = self.player
        farm = p.st.setdefault('farm', {})
        e = farm.get(str(idx))
        now = time.time()
        pal = self.obj_pal((110, 170, 80))
        if e is None:
            ch = []
            for cid in CROP_IDS:
                nm, cost, gt, yl, col = CROPS[cid]
                ch.append(("%s  %dg  %s" % (nm, cost, fmt_dur(self.crop_time(cid))), (lambda c=cid: self.plant(idx, c))))
            ch.append(("Leave it", None))
            self.say("Farm Plot", pal, ["Empty soil. Plant something? Crops keep growing while you adventure."], choices=ch)
            return
        crop, t0 = e
        left = t0 + self.crop_time(crop) - now
        nm = CROPS[crop][0]
        if left > 0:
            self.audio.play('menu', 0.5)
            self.say("Farm Plot", pal, ["%s is growing. Ripe in %s." % (nm, fmt_dur(left))])
            return
        lo, hi = CROPS[crop][3]
        n = random.randint(lo, hi) + (1 if self.has_proj('greenhouse') and random.random() < 0.5 else 0)
        farm.pop(str(idx), None)
        p.inv[crop] = min(99, p.inv.get(crop, 0) + n)
        self.audio.play('pickup', 0.8)
        pr = self._plot_pr.get(idx)
        if pr:
            self.fx.burst(pr.x, pr.y - 8, 12, [CROPS[crop][4], (120, 200, 90)], 50, 0.7, 1, -30, 2)
        self.toast("Harvested %d %s!" % (n, nm), CROPS[crop][4], 2.6)
        self.give_xp(3 * n * (1 + CROP_IDS.index(crop)))
        self.stat('harvests', n)

    def plant(self, idx, crop):
        p = self.player
        nm, cost = CROPS[crop][0], CROPS[crop][1]
        if p.gold < cost:
            self.audio.play('error')
            self.toast("Not enough gold (%dg)." % cost, RED)
            return
        p.gold -= cost
        p.st.setdefault('farm', {})[str(idx)] = [crop, time.time()]
        self.audio.play('drop', 0.7)
        pr = self._plot_pr.get(idx)
        if pr:
            self.fx.burst(pr.x, pr.y - 6, 8, [(120, 84, 56), (150, 110, 76)], 40, 0.5, 1, 20, 2)
        self.toast("Planted %s. Ripe in %s." % (nm, fmt_dur(self.crop_time(crop))), GREEN, 2.6)
        self.stat('planted')

    # ---- orchard
    def vi_apple(self, idx):
        p = self.player
        ap = p.st.setdefault('apples', {})
        now = time.time()
        rdy = ap.get(str(idx), 0)
        if now < rdy:
            self.audio.play('error', 0.5)
            self.toast("No ripe apples. Come back in %s." % fmt_dur(rdy - now), GREY)
            return
        n = random.randint(1, 3)
        ap[str(idx)] = now + 360
        pr = self._apple_pr.get(idx)
        if pr:
            self.fx.burst(pr.x, pr.y - 24, 14, [(70, 150, 70), (230, 60, 60)], 50, 0.8, 1, 60, 2)
        self.audio.play('pickup', 0.8)
        self.give_item('apple', n)
        self.stat('apples_picked', n)

    # ---- quarry
    def pick_tier(self):
        return self.player.st.get('pick', 0)

    def vi_ore(self, idx):
        p = self.player
        ores = p.st.setdefault('ore', {})
        now = time.time()
        rdy = ores.get(str(idx), 0)
        if now < rdy:
            self.audio.play('error', 0.5)
            self.toast("The vein is still recovering. %s." % fmt_dur(rdy - now), GREY)
            return
        tier = self.pick_tier()
        cd = (150 if self.has_proj('minecart') else 240) * (0.85 ** tier)
        ores[str(idx)] = now + cd
        pr = self._ore_pr.get(idx)
        if pr:
            self.fx.burst(pr.x, pr.y - 8, 18, [(200, 200, 220), (255, 214, 92), (110, 220, 230)], 80, 0.6, 1, 60, 2)
        self.audio.play('anvil', 0.7, 0.1)
        self.audio.play('smash', 0.4)
        self.shake(2)
        n = 1 + (1 if tier >= 1 and random.random() < 0.5 else 0) + (1 if tier >= 3 else 0) + \
            (1 if self.has_proj('minecart') else 0)
        r = random.random()
        if r < 0.52:
            self.give_item('ore', n)
        elif r < 0.78:
            self.give_item('cavecrystal', n)
        elif r < 0.90:
            self.give_item('nugget', max(1, n - 1))
        elif r < 0.96:
            self.give_item('geode', 1)
        else:
            self.give_item('obsidian', n)
        if random.random() < 0.3:
            self.drop(p.x, p.y - 4, 'coin', random.randint(4, 14))
        self.stat('mined')

    # ---- daily treasure
    def vi_dig(self, idx):
        p = self.player
        d = p.st.get('dig')
        if not d or idx in d['got']:
            return
        d['got'].append(idx)
        tx, ty = DIG_TILES[idx]
        self.audio.play('drop', 0.8)
        self.fx.burst(tx * 16 + 8, ty * 16 + 8, 22, [(140, 100, 62), (255, 214, 92), WHITE], 70, 0.8, 1, 60, 2)
        m = self.map
        m.props = [pr for pr in m.props if not (pr.name == 'dig' and pr.data == idx)]
        m.interacts = [it for it in m.interacts if not (it[3] == 'dig' and it[4] == idx)]
        r = random.random()
        lv = max(1, p.level)
        if r < 0.40:
            g = random.randint(30, 60) + 12 * lv
            for _ in range(5):
                self.drop(p.x, p.y - 6, 'coin', max(1, g // 5))
            self.toast("Buried coins! About %dg." % g, GOLD, 3)
        elif r < 0.75:
            k = random.choice(['ore', 'cavecrystal', 'nugget', 'sap', 'wax', 'cog', 'coil', 'bone', 'scarab'])
            self.give_item(k, random.randint(1, 3))
        elif r < 0.92:
            self.give_item(random.choice(['hp_potion', 'mp_potion', 'big_hp', 'big_mp', 'elixir']), 1)
        else:
            self.give_item(random.choice(['geode', 'moonbloom', 'stardust', 'moltencore']), 1)
            self.audio.play('trophy', 0.6)
        self.stat('digs')

    # ---- ember sprites
    def vi_sprite(self, i):
        p = self.player
        got = p.st.setdefault('sprites', [])
        if i in got:
            return
        got.append(i)
        tx, ty = SPRITE_TILES[i]
        self.audio.play('shimmer', 0.9)
        self.fx.burst(tx * 16 + 8, ty * 16, 30, [(255, 170, 80), (255, 230, 160), WHITE], 80, 1.0, 1, -40, 2)
        self.glow(tx * 16 + 8, ty * 16, 70, (255, 170, 80), 0.9)
        m = self.map
        m.props = [pr for pr in m.props if not (pr.name == 'wisp' and pr.data == i)]
        m.interacts = [it for it in m.interacts if not (it[3] == 'sprite' and it[4] == i)]
        m.lights = [l for l in m.lights if not (abs(l[0] - (tx * 16 + 8)) < 1 and abs(l[1] - (ty * 16 + 8)) < 1)]
        n = len(got)
        self.stat('n_sprites')
        msg = "Ember Sprite %d / %d" % (n, len(SPRITE_TILES))
        if n == 3:
            self.give_item('stardust', 2, False)
            self.drop(p.x, p.y - 6, 'coin', 100)
            msg += "  +2 Stardust, +100g"
        elif n == 6:
            self.give_item('wax', 3, False)
            self.drop(p.x, p.y - 6, 'coin', 250)
            msg += "  +3 Ghostwax, +250g"
        elif n == 9:
            self.give_item('geode', 2, False)
            self.drop(p.x, p.y - 6, 'coin', 500)
            msg += "  +2 Geodes, +500g"
        elif n >= len(SPRITE_TILES):
            p.flags.add('wisp_pet')
            p.sp += 1
            self.banner = ["WISP COMPANION!", 0.0]
            self.banner_gold = True
            self.audio.play('levelup')
            msg = "All sprites found! A wisp now follows you. +1 skill point."
        else:
            self.drop(p.x, p.y - 6, 'coin', 25)
        self.toast(msg, (255, 190, 110), 4)

    # ---- misc world interactions
    def vi_spring(self, _):
        p = self.player
        self.audio.play('heal', 0.8)
        self.audio.play('splash', 0.5)
        self.fx.burst(p.x, p.y - 8, 20, [(220, 240, 255), WHITE], 40, 1.0, 1, -30, 2)
        if p.hp >= p.max_hp and p.mp >= p.max_mp:
            self.toast("The water is lovely. You are already at your best.", (160, 220, 255), 3)
            return
        p.hp, p.mp = p.max_hp, p.max_mp
        p.meal_id, p.meal_t = 'm_grill', max(p.meal_t, 120.0)
        p.ghost = 1.0
        self.toast("Hot spring soak: HP and MP restored, regenerating.", (160, 220, 255), 3.5)
        self.stat('soaks')

    def vi_dummy(self, _):
        p = self.player
        self.audio.play('hit', 0.8)
        d = int(p.atk * random.uniform(0.85, 1.25)) if hasattr(p, 'atk') else random.randint(8, 20)
        self.fx.text(p.x + p.fx * 14, p.y - 26, "%d" % d, WHITE, 0.7)
        self.toast(random.choice(["The dummy takes it like a champ.", "It does not flinch.", "Clean hit! The dummy is unimpressed.",
                                  "Somewhere, a dummy filed a complaint."]), CREAM, 2)

    def vi_fishspot(self, _):
        self.start_fishing()

    def vi_board(self, _):
        g = [n for n in self.map.npcs if n.dlg == 'guard']
        if g:
            self.bounty_board(g[0])

    def vi_jukebox(self, _, page=0):
        names = {'town': "Emberfall Waltz", 'shop': "The Hearth Song", 'title': "Ember Theme", 'crypt': "Hollow Halls",
                 'depths': "The Ember Depths", 'abyss': "Abyssal Drift", 'boss': "Boss Fight!", 'spore': "Spore Hollow",
                 'grotto': "Drowned Grotto", 'tomb': "Sunken Tomb", 'frost': "Frozen Wastes", 'foundry': "Clockwork Foundry",
                 'manor': "Phantom Manor"}
        keys = [k for k in names if k in MUSIC]
        per = 4
        chunk = keys[page * per:(page + 1) * per]
        ch = []
        for k in chunk:
            ch.append((names[k], lambda k=k: self.set_track(k, names[k])))
        if (page + 1) * per < len(keys):
            ch.append(("More songs...", lambda: self.vi_jukebox(None, page + 1)))
        else:
            ch.append(("Back to the start", lambda: self.vi_jukebox(None, 0)))
        ch.append(("Leave", None))
        self.say("Jukebox", self.obj_pal((170, 90, 100)), ["A magic jukebox hums, ready to play any tune it has heard in the realms."], choices=ch)

    def set_track(self, k, nm):
        self.map.music = k
        self.audio.music_play(k, force=True)
        self.toast("Now playing: %s" % nm, (255, 180, 220), 3)

    # ---- dice
    def vi_dice(self, _):
        n = [x for x in self.map.npcs if x.dlg == 'gambler']
        if n:
            self.talk_gambler(n[0])

    def dice_menu(self, n):
        p = self.player
        ch = []
        for bet in (10, 50, 200, 500):
            ch.append(("Bet %dg" % bet, lambda b=bet: self.dice_roll(n, b)))
        ch.append(("Walk away", None))
        self.line(n, ["Two dice each. Beat my total and take double. Doubles pay triple! Ties are mine. Your purse: %dg." % p.gold], choices=ch)

    def dice_roll(self, n, bet):
        p = self.player
        if p.gold < bet:
            self.audio.play('error')
            self.line(n, ["You're short, friend. Come back with real coin."])
            return
        a1, a2, b1, b2 = [random.randint(1, 6) for _ in range(4)]
        pa, pb = a1 + a2, b1 + b2
        p.gold -= bet
        if pa > pb:
            win = bet * (3 if a1 == a2 else 2)
            p.gold += win
            self.audio.play('buy')
            self.stat('dice_wins')
            self.stat('gold_earned', win - bet)
            res = "You win %dg!%s" % (win - bet, " Doubles!" if a1 == a2 else "")
        elif pa == pb:
            self.audio.play('error', 0.6)
            res = "A tie. The house wins ties. Lovely, isn't it?"
        else:
            self.audio.play('error', 0.6)
            res = "The house wins. Better luck next roll."
        self.line(n, ["You rolled %d + %d = %d.  I rolled %d + %d = %d." % (a1, a2, pa, b1, b2, pb), res],
                  on_end=lambda: self.dice_menu(n))

    # ------------------------------------------------------------ NPC talk
    def hint_sprite(self):
        p = self.player
        got = p.st.get('sprites', [])
        left = [i for i in range(len(SPRITE_TILES)) if i not in got]
        if not left:
            return "You've found every sprite. They sing about you in the trees."
        px, py = p.x / 16, p.y / 16
        i = min(left, key=lambda j: (SPRITE_TILES[j][0] - px) ** 2 + (SPRITE_TILES[j][1] - py) ** 2)
        return "%d of %d sprites found. The nearest I sense is somewhere in %s." % (
            len(got), len(SPRITE_TILES), self.district_at(*SPRITE_TILES[i]).title())

    def hint_dig(self):
        d = self.player.st.get('dig') or {}
        if d.get('d') != self.day_no():
            self.refresh_digs(self.map) if self.map.kind == 'village' else None
            d = self.player.st.get('dig') or {}
        left = [i for i in getattr(self, '_dig_spots', []) if i not in d.get('got', [])]
        if not left:
            return "Nothing left to dig up today. Come back tomorrow!"
        i = random.choice(left)
        return "Something glints under the earth near %s. %d spots remain today." % (
            self.district_at(*DIG_TILES[i]).title(), len(left))

    def talk_kid2(self, n):
        self.line(n, [random.choice([self.hint_sprite(), "Lyric's jukebox plays every song from the dungeons! Even the scary ones.",
                                     "I dug a hole. Found a bone. Then another bone. Then a worse bone.",
                                     "Tag! You're it. ...Never mind, you're too fast."])])

    def talk_baker(self, n):
        p = self.player
        menu = [('m_grill', 70), ('m_stew', 110), ('m_roast', 170)]

        def buy(k, c):
            if p.gold < c:
                self.audio.play('error')
                self.toast("Not enough gold (%dg)." % c, RED)
                return
            p.gold -= c
            self.audio.play('buy')
            self.give_item(k, 1)
        ch = [("%s  %dg" % (ITEM_NAMES[k], c), (lambda k=k, c=c: buy(k, c))) for k, c in menu]
        ch.append(("Just browsing", None))
        self.line(n, ["Dorrie's Bakes! Hot meals for hungry heroes. Everything's fresh, even the gossip."], choices=ch)

    def talk_rover(self, n):
        p = self.player
        day = self.day_no()
        st = p.st.get('rowan')
        if not st or st.get('d') != day:
            st = p.st['rowan'] = {'d': day, 'bought': []}
        r = random.Random(day * 31 + 5)
        cnt = 5 if self.has_proj('lanterns') else 4
        picks = r.sample(DAILY_POOL, cnt)
        stock = [(k, c, r.randint(1, 3)) for k, c in picks]
        ch = []
        for i, (k, c, q) in enumerate(stock):
            if i in st['bought']:
                continue
            price = c * q
            ch.append(("%s x%d  %dg" % (self.item_label(k), q, price), (lambda i=i, k=k, q=q, price=price: self.rowan_buy(n, i, k, q, price))))
        ch.append(("Maybe later", None))
        if len(ch) == 1:
            self.line(n, ["Sold out for today, friend! New wares at dawn. The road provides."])
            return
        self.line(n, ["Rowan's Wandering Wares! Fresh stock every dawn. Once it's gone, it's gone."], choices=ch)

    def rowan_buy(self, n, i, k, q, price):
        p = self.player
        if p.gold < price:
            self.audio.play('error')
            self.toast("Not enough gold (%dg)." % price, RED)
            return
        p.gold -= price
        p.st['rowan']['bought'].append(i)
        self.audio.play('buy')
        self.give_item(k, q)

    def talk_gladiator(self, n):
        self.arena_menu(n)

    def talk_miner(self, n):
        p = self.player
        tier = self.pick_tier()
        picks = ["Rusty Pick", "Iron Pick", "Steel Pick", "Mithril Pick"]
        costs = [250, 600, 1400]
        ch = []
        if tier < 3:
            c = costs[tier]

            def up():
                if p.gold < c:
                    self.audio.play('error')
                    self.line(n, ["%s costs %dg. Come back with the coin, friend." % (picks[tier + 1], c)])
                    return
                p.gold -= c
                p.st['pick'] = tier + 1
                self.audio.play('buy')
                self.line(n, ["A fine %s! Veins give more, and they grow back %d%% faster." % (picks[tier + 1], int((1 - 0.85 ** (tier + 1)) * 100))])
            ch.append(("Upgrade to %s (%dg)" % (picks[tier + 1], c), up))
        ch.append(("Quarry tips", lambda: self.line(n, [random.choice([
            "Veins sparkle when ripe. Dull rubble means give it a few minutes.",
            "Cave crystals fetch a fine price. Geodes? Pip nearly cries.",
            "Nuggets and cogs make a bell tower. Ask the steward at the Hall."])])))
        ch.append(("Leave", None))
        self.line(n, ["Dagna's Quarry! Swing away, the rock won't mind. Your tool: %s." % picks[tier]], choices=ch)

    def talk_bard(self, n):
        self.line(n, ["Songs from every realm, right here in the park!"],
                  choices=[("Play a song", lambda: self.vi_jukebox(None)),
                           ("Heard any rumours?", lambda: self.line(n, [self.hint_dig()])), ("Just listening", None)])

    def talk_ghost(self, n):
        self.line(n, [random.choice(["Boo. ...Sorry, reflex.", "I can feel treasure beneath the earth, you know. Dead folk know these things."]),
                      self.hint_dig()])

    def talk_hermit(self, n):
        self.line(n, [random.choice(["The wisps remember being fires. Be kind to them.", "I came for the peace. Then the springs got popular."]),
                      self.hint_sprite()])

    def talk_gambler(self, n):
        self.line(n, ["Care for a game of Bones, friend? Lucky Corner never sleeps."],
                  choices=[("Play dice", lambda: self.dice_menu(n)), ("Not today", None)])

    def talk_archer(self, n):
        self.line(n, ["Keep your eyes on the target."])

    # ---- Hobb (override the old farmer talk)
    def talk_farmer(self, n):
        p = self.player
        farm = p.st.get('farm', {})

        def fert():
            if not farm:
                self.line(n, ["Nothing's planted! Fertilizer won't help bare soil."])
                return
            if p.gold < 40:
                self.audio.play('error')
                self.line(n, ["Fertilizer is 40g a sack. Come back when you're flush."])
                return
            p.gold -= 40
            for k in list(farm):
                farm[k][1] -= 180
            self.audio.play('buy')
            self.line(n, ["Spread it myself! Every crop just grew three minutes' worth."])

        def tips():
            self.line(n, [random.choice(["Turnips are quick. Moonbloom takes a good half hour. Worth every minute.",
                                         "Crops grow while you're in the dungeon. Plant before you go!",
                                         "The Greenhouse speeds everything up. Ask the steward about projects.",
                                         "Apples? Shake the orchard trees. They regrow in a few minutes."])])
        self.line(n, ["Good soil, honest work. Rent a plot, plant something, and come back later."],
                  choices=[("Buy fertilizer (40g)", fert), ("Farming tips", tips), ("Leave", None)])

    # ---- Library
    def talk_scholar(self, n):
        p = self.player

        def bestiary():
            pages = []
            for k, e in ENEMY.items():
                c = p.st.get('k_' + k, 0)
                if c and k != 'boss':
                    pages.append("%s: slain %d. HP %d, hits for %d. %s" % (e['name'], c, e['hp'], e['dmg'], ENEMY_BLURB.get(k, "")))
            if not pages:
                pages = ["Your bestiary is empty. Go slay something and report back."]
            self.line(n, pages[:10])

        def lore():
            self.line(n, [random.choice(LORE)])
        self.line(n, ["Welcome to the Archive. Knowledge is the only treasure that survives a fire. Mostly."],
                  choices=[("Bestiary", bestiary), ("Realm lore", lore), ("Sprite hints", lambda: self.line(n, [self.hint_sprite()])),
                           ("Leave", None)])

    # ---- Chapel
    def talk_nun(self, n):
        p = self.player
        k = 1.5 if self.has_proj('belltower') else 1.0

        def bless(name, attr, secs, cost):
            if p.gold < cost:
                self.audio.play('error')
                self.line(n, ["The temple asks %dg for %s. Come back when you can." % (cost, name)])
                return
            p.gold -= cost
            setattr(p, attr, secs * k)
            self.audio.play('shrine')
            self.glow(p.x, p.y - 12, 60, (255, 240, 180), 0.8)
            self.fx.burst(p.x, p.y - 12, 18, [(255, 240, 180), WHITE], 60, 0.9, 1, -40, 2)
            self.toast("%s! Lasts %ds." % (name, int(secs * k)), (255, 240, 180), 3)

        def heal():
            if p.hp >= p.max_hp and p.mp >= p.max_mp:
                self.line(n, ["You are in perfect health. Go and wound yourself properly first."])
                return
            p.hp = min(p.max_hp, p.hp + p.max_hp * (0.7 if self.has_proj('belltower') else 0.5))
            p.mp = min(p.max_mp, p.mp + p.max_mp * 0.5)
            p.ghost = p.hp / p.max_hp
            self.audio.play('heal')
            self.toast("The sister's prayer mends you.", GREEN, 2.5)
        self.line(n, ["Light guard you, traveller. The chapel offers blessings for the road below."],
                  choices=[("Blessing of Might  60g", lambda: bless("Blessing of Might", 'power_t', 120.0, 60)),
                           ("Blessing of Fortune  60g", lambda: bless("Blessing of Fortune", 'fortune_t', 180.0, 60)),
                           ("Blessing of Stone  80g", lambda: bless("Blessing of Stone", 'stone_t', 180.0, 80)),
                           ("Healing prayer (free)", heal), ("Leave", None)])

    # ---- Town Hall
    def errand_state(self):
        p = self.player
        day = self.day_no()
        e = p.st.get('errand')
        if not e or e.get('d') != day:
            r = random.Random(day * 17 + 3)
            picks = r.sample(range(len(ERRAND_POOL)), 3)
            old = e or {}
            streak = old.get('streak', 0)
            if old.get('d') != day - 1 or not old.get('all'):
                streak = 0
            e = p.st['errand'] = {'d': day, 'picks': picks, 'base': {ERRAND_POOL[i][0]: self.stat_value(ERRAND_POOL[i][0]) for i in picks},
                                  'claimed': [], 'all': False, 'streak': streak}
        return e

    def errand_progress(self, i):
        e = self.errand_state()
        k, n, lab, rew = ERRAND_POOL[i]
        return min(n, self.stat_value(k) - e['base'].get(k, 0)), n

    def errand_menu(self, n):
        p = self.player
        e = self.errand_state()
        ch = []
        pages = ["Daily Errands. Fresh every dawn. Finish all three to extend your streak (now %d day%s)." % (
            e['streak'], "" if e['streak'] == 1 else "s")]
        for i in e['picks']:
            k, amt, lab, rew = ERRAND_POOL[i]
            cur, _ = self.errand_progress(i)
            mark = "DONE" if i in e['claimed'] else ("READY" if cur >= amt else "%d/%d" % (cur, amt))
            if cur >= amt and i not in e['claimed']:
                ch.append(("Claim: %s  %dg" % (lab, rew), (lambda i=i: self.errand_claim(n, i))))
            else:
                ch.append(("%s  [%s]" % (lab, mark), lambda: None))
        ch.append(("Back", None))
        self.line(n, pages, choices=ch)

    def errand_claim(self, n, i):
        p = self.player
        e = self.errand_state()
        k, amt, lab, rew = ERRAND_POOL[i]
        e['claimed'].append(i)
        gold = rew + 10 * min(e['streak'], 7)
        p.gold += gold
        self.audio.play('bounty')
        self.stat('gold_earned', gold)
        self.give_xp(30 + 5 * p.level)
        self.toast("Errand complete: %s  +%dg" % (lab, gold), GOLD, 3.2)
        if len(e['claimed']) >= 3 and not e['all']:
            e['all'] = True
            e['streak'] += 1
            self.stat('errand_days')
            bonus = 150 + 50 * min(e['streak'], 7)
            p.gold += bonus
            self.give_item(random.choice(['geode', 'stardust', 'moonbloom', 'nugget']), 1)
            self.banner = ["DAILY STREAK: %d" % e['streak'], 0.0]
            self.banner_gold = True
            self.audio.play('trophy')
            self.toast("All errands done! Bonus +%dg and a rare find." % bonus, GOLD, 4)
        self.save_game(quiet=True)
        self.errand_menu(n)

    def talk_mayor(self, n):
        p = self.player
        ch = []
        done = sum(1 for k, *_ in PROJECTS if self.has_proj(k))
        for (k, nm, gold, mats, desc) in PROJECTS:
            if self.has_proj(k):
                ch.append(("[BUILT] " + nm, lambda: self.line(n, ["Already built, and the town loves it."])))
            else:
                ch.append(("%s  %dg" % (nm, gold), (lambda k=k: self.proj_view(n, k))))
        ch.append(("Daily Errands", lambda: self.errand_menu(n)))
        ch.append(("Leave", None))
        self.line(n, ["Emberfall grows with every coin and crate you bring. Town projects built: %d of %d." % (done, len(PROJECTS))],
                  choices=ch)

    def proj_view(self, n, k):
        _, nm, gold, mats, desc = PROJ_BY[k]
        need = ", ".join("%d %s" % (v, self.item_label(i)) for i, v in mats.items())
        self.line(n, ["%s: %s" % (nm, desc), "Needs %dg, %s." % (gold, need)],
                  choices=[("Fund it", lambda: self.proj_build(n, k)), ("Not yet", None)])

    def proj_build(self, n, k):
        p = self.player
        _, nm, gold, mats, desc = PROJ_BY[k]
        if not self.pay_ok(gold, mats):
            self.audio.play('error')
            self.line(n, ["You're short on gold or materials. Check the list, and come back."])
            return
        self.pay(gold, mats)
        p.flags.add('proj_' + k)
        self.audio.play('trophy')
        self.stat('projects')
        self.banner = ["%s BUILT!" % nm.upper(), 0.0]
        self.banner_gold = True
        v = self.maps.get('village')
        if v is not None:
            self.apply_projects(v)
            if k == 'lanterns':
                self.refresh_digs(v)
        self.save_game(quiet=True)
        self.line(n, ["The town cheers! %s is complete. %s" % (nm, desc)])

    # ------------------------------------------------------------ colosseum
    def arena_menu(self, n):
        p = self.player
        clr = p.arena_best
        ch = []
        for i, t_ in enumerate(ARENA_TIERS):
            if i <= clr:
                tag = "  (cleared)" if i < clr else ""
                ch.append(("%s  %d waves%s" % (t_['name'], t_['waves'], tag), (lambda i=i: self.arena_go(i))))
            else:
                ch.append(("%s  (locked)" % t_['name'], None))
        ch.append(("Not today", None))
        who = n if n else [x for x in self.map.npcs if x.dlg == 'gladiator'][0]
        self.line(who, ["The Colosseum! Waves of beasts, a roaring crowd, glory and gold. Clear a tier to unlock the next. Highest cleared: %d of %d." % (clr, len(ARENA_TIERS))],
                  choices=ch)

    def arena_go(self, tier):
        self.audio.play('warn', 0.8)
        self.start_trans(lambda: self.start_arena(tier), 2.6)

    def start_arena(self, tier):
        t_ = ARENA_TIERS[tier]
        m = build_colosseum()
        m.ef = t_['ef']
        m.arena = dict(tier=tier, wave=0, state='intro', t=0.0, total=t_['waves'])
        m.bake()
        self.maps['arena'] = m
        self.enter_map(m)
        self.banner = [t_['name'].upper(), 0.0]
        self.banner_gold = True
        self.audio.play('bossintro', 0.6)

    def arena_wave(self):
        m = self.map
        a = m.arena
        t_ = ARENA_TIERS[a['tier']]
        a['wave'] += 1
        a['state'] = 'fight'
        a['t'] = 0.0
        w = a['wave']
        n = min(9, 2 + w + a['tier'])
        last = w == a['total']
        self.banner = [("FINAL WAVE" if last else "WAVE %d" % w), 0.0]
        self.banner_gold = last
        self.audio.play('roar' if last else 'warn', 0.7)
        spawn_pts = [(5, 5), (24, 5), (5, 16), (24, 16), (14, 4), (14, 17), (4, 11), (25, 11), (9, 4), (20, 4), (9, 17), (20, 17)]
        random.shuffle(spawn_pts)
        for i in range(n):
            kind = random.choice(t_['kinds'])
            if last and i == 0 and a['tier'] >= 1:
                kind = 'golem' if a['tier'] >= 2 else 'knight'
            sx, sy = spawn_pts[i % len(spawn_pts)]
            e = Enemy(kind, sx * 16 + 8, sy * 16 + 12, t_['ef'] + 0.18 * w)
            e.aggro = True
            if (last and i < 1 + a['tier'] // 2 and a['tier'] >= 1) or (a['tier'] == 3 and i == 1):
                e.make_elite()
            m.enemies.append(e)
            self.fx.burst(e.x, e.y - 6, 10, [(255, 220, 120), WHITE], 60, 0.5, 1, -20, 2)

    def arena_tick(self, dt):
        m = self.map
        a = getattr(m, 'arena', None)
        if not a or self.state != 'play':
            return
        a['t'] += dt
        if a['state'] == 'intro':
            if a['t'] > 3.0:
                self.arena_wave()
        elif a['state'] == 'fight':
            if a['t'] > 1.0 and not any(e.hp > 0 for e in m.enemies):
                if a['wave'] >= a['total']:
                    self.arena_win()
                else:
                    a['state'] = 'between'
                    a['t'] = 0.0
                    p = self.player
                    p.hp = min(p.max_hp, p.hp + int(p.max_hp * 0.2))
                    self.toast("Wave %d cleared!" % a['wave'], GOLD, 2)
                    self.audio.play('bounty', 0.7)
                    self.stat('arena_waves')
        elif a['state'] == 'between':
            if a['t'] > 3.0:
                self.arena_wave()

    def arena_win(self):
        m = self.map
        a = m.arena
        a['state'] = 'won'
        p = self.player
        tier = a['tier']
        t_ = ARENA_TIERS[tier]
        k = 1.25 if self.has_proj('grandstand') else 1.0
        gold = int(t_['gold'] * k)
        for _ in range(10):
            self.drop(p.x + random.uniform(-14, 14), p.y - 6, 'coin', max(1, gold // 10))
        for _ in range(2 + tier):
            self.drop(p.x + random.uniform(-14, 14), p.y - 6, 'item', random.choice(t_['mats']))
        self.give_xp(int(t_['xp'] * k))
        first = p.arena_best <= tier
        p.arena_best = max(p.arena_best, tier + 1)
        self.banner = ["VICTORY!", 0.0]
        self.banner_gold = True
        self.audio.play('levelup')
        self.audio.play('trophy', 0.7)
        self.shake(3)
        self.stat('arena_clears')
        self.stat('arena_tier', p.arena_best, mx=True)
        if first and t_['first']:
            p.sp += t_['first'][1]
            self.toast("First clear bonus: +%d skill point%s!" % (t_['first'][1], "s" if t_['first'][1] > 1 else ""), GOLD, 4)
        self.toast("%s cleared!  +%dg" % (t_['name'], gold), GOLD, 4)
        self.save_game(quiet=True)


def build_colosseum():
    W_, H_ = 30, 22
    m = GameMap('arena', "The Colosseum", W_, H_, 'catacomb', 'dungeon')
    m.music = 'depths'
    m.ambient = (215, 196, 176)
    m.weather = 'dust'
    t = m.tiles
    for y in range(H_):
        for x in range(W_):
            t[y][x] = WALL
    for y in range(3, H_ - 3):
        for x in range(3, W_ - 3):
            t[y][x] = FLOOR
    for x in range(13, 17):
        for y in range(H_ - 3, H_ - 1):
            t[y][x] = FLOOR
    for y in range(4, H_ - 4):
        for x in range(4, W_ - 4):
            if (x - 14.5) ** 2 / 100 + (y - 10.5) ** 2 / 42 <= 1.0 and (x - 14.5) ** 2 / 100 + (y - 10.5) ** 2 / 42 > 0.72:
                t[y][x] = CARPET
    m.spawn = (15 * 16, (H_ - 6) * 16)
    m.warps.append(dict(rect=(13 * 16, (H_ - 2) * 16, 64, 14), to='village', pos=VPOS['arena_out'], name='exit'))
    P = lambda x, y, img, **k: m.add_prop(Prop(x, y, img, **k))
    for xx in (5, 10, 19, 24):
        P(xx * 16 + 8, 3 * 16 + 4, prop_banner((200, 60, 60) if xx < 15 else (60, 90, 200)))
    for (xx, yy) in ((3, 3), (26, 3), (3, 18), (26, 18)):
        P(xx * 16 + 8, yy * 16 + 14, [prop_brazier(i) for i in range(4)], solid=(-4, -6, 8, 6), fps=9,
          light=(70, (255, 150, 60), 0.25), shd=(14, 5))
    for (xx, yy) in ((9, 8), (20, 8), (9, 13), (20, 13)):
        P(xx * 16 + 8, yy * 16 + 14, prop_pillar(), solid=(-6, -6, 12, 6), shd=(16, 5))
    m.lights.append((15 * 16, 11 * 16, 170, (255, 200, 130), 0.1, False))
    m.lights.append((8 * 16, 11 * 16, 90, (255, 170, 90), 0.1, False))
    m.lights.append((22 * 16, 11 * 16, 90, (255, 170, 90), 0.1, False))
    return m


class Game(SpellMixin, DungeonMixin, CraftMixin, VillageMixin):
    def __init__(self, screen, manual=False, mute=False):
        self.screen = screen
        self.manual = manual
        self.canvas = pygame.Surface((W, H))
        self.dark = pygame.Surface((W, H))
        self.overlay = pygame.Surface((W, H))
        self.audio = Audio()
        if mute:
            self.audio.ok = False
        self.fx = Particles()
        self.projs = []
        self.glows = []
        self.hazards, self.allies, self.timers, self.zaps, self.decoy = [], [], [], [], None
        self.hazsurf = pygame.Surface((W, H), pygame.SRCALPHA)
        self.cdsurf = pygame.Surface((16, 16), pygame.SRCALPHA)
        self.sb_slot = 0
        self.gate_sel = 0
        self.dive_t = 0.0
        self.blackout_t = 0.0
        self.blizzard_t = 0.0
        self.rift = None
        self.player = Player()
        self.maps = {}
        self.floors = {}
        self.map = None
        self.seed = random.randrange(10 ** 6)
        self.state = 'title'
        self.time = 0.0
        self.tod = 0.12
        self.cam = [0.0, 0.0]
        self.cam_off = [0, 0]
        self.shake_a = 0.0
        self.freeze = 0.0
        self.slow_t = 0.0
        self.new_diff = 1
        self.diff_sel = DEFAULT_DIFF
        self.corpses = []
        self.kick = [0.0, 0.0]
        self.look = [0.0, 0.0]
        self._trail = None
        self.fade = 1.0
        self.trans = None
        self.flash = None
        self.dlg = None
        self.shop = None
        self.toasts = []
        self.trophy_pop = []
        self.fish = None
        self.trailer = None
        self.hide_hud = False
        self.banner = None
        self.down = set()
        self.just = set()
        self.title_sel = 0
        self.title_sub = None
        self.menu_tab = 0
        self.menu_sel = 0
        self.pause_sel = 0
        self.over_t = 0.0
        self.intro_i = 0
        self.intro_t = 0.0
        self.warp_cd = 0.0
        self.dying_t = 0.0
        self.cut = None
        self.credits_t = 0.0
        self.won = False
        self.ambp = []
        self.title_parts = []
        self.pad = Gamepad()
        self.pad_down = set()
        self.pad_active = False
        self.pad_hold = {}
        self.rep_keys = {PADK[n] for n in ('up', 'down', 'left', 'right')} | {pygame.K_UP, pygame.K_DOWN, pygame.K_LEFT, pygame.K_RIGHT}
        self.touch_on = bool(os.environ.get('EMBERFALL_TOUCH') or '--touch' in sys.argv or sys.platform == 'emscripten'
                             or 'ANDROID_ARGUMENT' in os.environ or hasattr(sys, 'getandroidapilevel'))
        self.touch_mouse = self.touch_on
        self.touches = {}
        self.touch_down = set()
        self.touch_hold = {}
        self.stick = None
        self.pres = (0, 0, 3.0)
        self.ctl_page = 0
        self.fullscreen = False
        self.win_size = (W * 3, H * 3)
        self.has_save = os.path.exists(SAVE_PATH)
        self.last_save = 0.0
        self.letter = 0.0
        self.interact_target = None
        self.quit = False
        self.stars = [(random.randrange(W), random.randrange(110), random.random() * 6) for _ in range(70)]
        self.clouds = [[random.randrange(W), random.randrange(10, 70), random.uniform(3, 8), random.randrange(18, 40)]
                       for _ in range(6)]
        self.audio.music_play('title')

    # ---- input -------------------------------------------------------
    def held(self, act):
        return any(k in self.down for k in ACTIONS[act])

    def jp(self, act):
        return any(k in self.just for k in ACTIONS[act])

    def handle_event(self, e):
        if e.type == pygame.QUIT:
            self.quit = True
        elif e.type in (getattr(pygame, 'FINGERDOWN', -1), getattr(pygame, 'FINGERMOTION', -2), getattr(pygame, 'FINGERUP', -3)):
            ww, wh = (self.screen or pygame.display.get_surface()).get_size()
            self.touch_event(e.type, ('f', e.finger_id), e.x * ww, e.y * wh)
        elif e.type in (pygame.MOUSEBUTTONDOWN, pygame.MOUSEMOTION, pygame.MOUSEBUTTONUP):
            if self.touch_mouse and not getattr(e, 'touch', False):
                if e.type == pygame.MOUSEMOTION and not e.buttons[0]:
                    return
                if e.type != pygame.MOUSEMOTION and e.button != 1:
                    return
                self.touch_event(e.type, 'm', e.pos[0], e.pos[1])
        elif e.type == pygame.KEYDOWN:
            self.pad_active = False
            if not self.touch_mouse:
                self.touch_on = False
            self.down.add(e.key)
            self.just.add(e.key)
        elif e.type == pygame.KEYUP:
            self.down.discard(e.key)
        elif e.type == getattr(pygame, 'WINDOWFOCUSLOST', -1):
            self.down.clear()

    # ---- touch (phones / tablets / web) -------------------------------
    TOUCH_BTNS = (  # name, cx, cy, radius, key, label
        ('atk', 280, 138, 18, 'attack', "ATK"), ('dash', 248, 160, 13, 'dash', "DASH"),
        ('mag', 304, 106, 13, 'magic', "MAG"), ('use', 244, 128, 12, 'interact', "E"),
        ('nxt', 276, 98, 9, 'spnext', ">>"),
    )
    TOUCH_SMALL = (  # name, x, y, w, h, key, label
        ('pau', 146, 2, 26, 12, 'pause', "MENU"), ('inv', 174, 2, 26, 12, 'inv', "HERO"),
        ('hp', 5, H - 22, 26, 19, 'hp', ""), ('mp', 33, H - 22, 26, 19, 'mp', ""),
        ('el', 61, H - 22, 26, 19, 'elixir', ""), ('gd', 89, H - 22, 26, 19, 'gadget', ""),
    )
    TOUCH_KEY = {'attack': pygame.K_j, 'magic': pygame.K_k, 'dash': pygame.K_SPACE, 'interact': pygame.K_e,
                 'spnext': pygame.K_v, 'pause': pygame.K_ESCAPE, 'inv': pygame.K_i, 'hp': pygame.K_q, 'mp': pygame.K_r,
                 'elixir': pygame.K_f, 'gadget': pygame.K_g}

    def touch_event(self, typ, fid, px, py):
        self.touch_on = True
        self.touch_mouse = self.touch_mouse or fid != 'm'
        ox, oy, sc = self.pres
        x, y = (px - ox) / sc, (py - oy) / sc
        up = typ in (getattr(pygame, 'FINGERUP', -3), pygame.MOUSEBUTTONUP)
        if up:
            self.touches.pop(fid, None)
            if self.stick and self.stick[0] == fid:
                self.stick = None
            return
        if typ in (getattr(pygame, 'FINGERDOWN', -1), pygame.MOUSEBUTTONDOWN):
            if x < W * 0.42 and not any(n[0] <= x <= n[0] + n[2] and n[1] <= y <= n[1] + n[3] for n in
                                        [(b[1], b[2], b[3], b[4]) for b in self.TOUCH_SMALL]) and self.stick is None:
                self.stick = [fid, x, y, x, y]
        self.touches[fid] = (x, y)
        if self.stick and self.stick[0] == fid:
            self.stick[3], self.stick[4] = x, y

    def touch_poll(self):
        keys = set()
        for fid, (x, y) in self.touches.items():
            if self.stick and self.stick[0] == fid:
                continue
            best, bd = None, 1e9
            for nm, cx, cy, r, k, lab in self.TOUCH_BTNS:
                d = math.hypot(x - cx, y - cy)
                if d <= r + 7 and d < bd:
                    best, bd = k, d
            for nm, bx, by, bw, bh, k, lab in self.TOUCH_SMALL:
                if bx - 2 <= x <= bx + bw + 2 and by - 2 <= y <= by + bh + 2:
                    best = k
            if best:
                keys.add(self.TOUCH_KEY[best])
        if self.stick:
            dx, dy = self.stick[3] - self.stick[1], self.stick[4] - self.stick[2]
            m = math.hypot(dx, dy)
            if m > 7:
                if abs(dx) > 0.4 * m:
                    keys.add(pygame.K_RIGHT if dx > 0 else pygame.K_LEFT)
                if abs(dy) > 0.4 * m:
                    keys.add(pygame.K_DOWN if dy > 0 else pygame.K_UP)
            if m > 22:                                   # drag the base along with the thumb
                k_ = 22 / m
                self.stick[1] = self.stick[3] - dx * k_
                self.stick[2] = self.stick[4] - dy * k_
        return keys

    def draw_touch(self, surf):
        if not self.touch_on:
            return
        ov = self.overlay
        pressed = self.touch_down
        for nm, cx, cy, r, k, lab in self.TOUCH_BTNS:
            on = self.TOUCH_KEY[k] in pressed
            col = (255, 220, 120) if on else (200, 190, 230)
            pygame.draw.circle(surf, mul_c(col, 0.35 if on else 0.18), (cx, cy), r)
            pygame.draw.circle(surf, col, (cx, cy), r, 1)
            txt(surf, lab, cx, cy - 3, col, True, 'c')
        for nm, bx, by, bw, bh, k, lab in self.TOUCH_SMALL:
            if lab:
                on = self.TOUCH_KEY[k] in pressed
                surf.fill((50, 40, 80) if not on else (120, 100, 60), (bx, by, bw, bh))
                pygame.draw.rect(surf, (200, 190, 230), (bx, by, bw, bh), 1)
                txt(surf, lab, bx + bw // 2, by + 2, CREAM, True, 'c')
        if self.stick:
            _, bx, by, kx, ky = self.stick
        else:
            bx, by = 44, 138
            kx, ky = bx, by
        pygame.draw.circle(surf, (60, 50, 90), (int(bx), int(by)), 24, 1)
        pygame.draw.circle(surf, (170, 160, 210), (int(bx), int(by)), 24, 1)
        kd = math.hypot(kx - bx, ky - by)
        if kd > 22:
            kx, ky = bx + (kx - bx) * 22 / kd, by + (ky - by) * 22 / kd
        pygame.draw.circle(surf, (190, 180, 230), (int(kx), int(ky)), 8)
        pygame.draw.circle(surf, (110, 100, 160), (int(kx), int(ky)), 8, 1)

    # ---- helpers -----------------------------------------------------
    def shake(self, a):
        self.shake_a = max(self.shake_a, a)

    def toast(self, text, col=WHITE, t=2.6):
        self.toasts.append([text, col, t, t])
        if len(self.toasts) > 5:
            self.toasts.pop(0)

    def glow(self, x, y, r, col, t=0.3):
        self.glows.append([x, y, r, col, t, t])

    def start_trans(self, fn, speed=3.2):
        if self.trans is None:
            self.trans = dict(phase='out', fn=fn, speed=speed)

    def say(self, name, pal, pages, on_end=None, choices=None, pitch=1.0):
        if isinstance(pages, str):
            pages = [pages]
        self.dlg = dict(name=name, pal=pal, pages=pages, i=0, shown=0.0, on_end=on_end, choices=choices, sel=0,
                        pitch=pitch, blip=0)
        self.prev_state = self.state if self.state != 'dialog' else getattr(self, 'prev_state', 'play')
        self.state = 'dialog'

    def end_dialog(self):
        d = self.dlg
        self.dlg = None
        self.state = 'play'
        if d and d['on_end']:
            d['on_end']()

    # ---- game flow ---------------------------------------------------
    def new_game(self):
        self.player = Player()
        self.player.diff = getattr(self, 'new_diff', DEFAULT_DIFF)
        recalc_mods(self.player)
        self.floors.clear()
        self.maps.clear()
        self.seed = random.randrange(10 ** 6)
        self.won = False
        self.tod = 0.12
        self.start_intro()

    def start_intro(self):
        self.state = 'intro'
        self.intro_i = 0
        self.intro_t = 0.0
        self.audio.music_play('title')

    def begin_village(self, pos=None):
        self.enter_map(self.get_village(), pos or None)
        self.state = 'play'
        self.say("Elder Maren", PAL['elder'],
                 ["Ah, a traveler at last! I am Maren, elder of Emberfall.",
                  "Beneath our village lies Hollowdeep, an ancient crypt. For ages it slept. Now the Hollow King stirs below, and his dead walk the halls.",
                  "Take the north gate, adventurer. Fight, gather gold and loot, then return to spend it. Brann reforges steel, Zia brews potions, and Pip buys what you carry.",
                  "Speak to me again when you want work. Go well, and come back alive!",
                  "Emberfall is bigger than it looks. Farm, fish, mine, brawl in the Colosseum, hunt wisps, and fund town projects at the Hall. Press E near anything."], pitch=0.8)

    def get_village(self):
        m = self.maps.get('village')
        if m is None:
            m = build_village()
            self.populate_village(m)
            m.bake()
            self.maps['village'] = m
        return m

    def get_interior(self, kind):
        m = self.maps.get(kind)
        if m is None:
            v = self.get_village()
            cx, by = v.houses[kind]
            m = build_interior(kind, (cx, by + 14))
            m.bake()
            self.maps[kind] = m
        return m

    def get_floor(self, n):
        m = self.floors.get(n)
        if m is None:
            if n == 4:
                m = build_throne()
                k = self.player.st.get('bosses', 0)
                if k:
                    b = m.boss
                    b.maxhp = b.hp = int(b.maxhp * (1 + 0.7 * k))
                    b.dmg = int(b.dmg * (1 + 0.2 * k))
                    b.rematch = k
                m.floor_no = 4
            else:
                m = gen_dungeon(n, self.seed)
            m.bake()
            self.floors[n] = m
        return m

    def get_abyss(self, n):
        k = ('a', n)
        m = self.floors.get(k)
        if m is None:
            m = gen_dungeon(n, self.seed, abyss=True)
            m.bake()
            self.floors[k] = m
        return m

    def new_dive(self):
        self.seed = random.randrange(10 ** 6)
        self.floors.clear()
        self.player.phoenix_ready = True

    def enter_abyss(self, n, rift=None):
        def fn():
            self.new_dive()
            self.rift = rift
            recalc_mods(self.player)
            if rift:
                self.seed = rift[0] % 999983
                for _n, _d, mm in rift[1]:
                    for k, v in mm.items():
                        MODS[k] = MODS.get(k, 1.0) * v
                self.toast("Daily Rift: %s + %s" % (rift[1][0][0], rift[1][1][0]), (190, 130, 255), 4)
            self.enter_map(self.get_abyss(n))
            self.abyss_reached(n)
        self.audio.play('portal')
        self.start_trans(fn, 1.6)

    def end_rift(self):
        if getattr(self, 'rift', None):
            self.rift = None
            recalc_mods(self.player)

    def abyss_reached(self, n):
        p = self.player
        if getattr(self, 'rift', None):
            day = self.rift[0]
            key = 'rift_%d' % day
            if n > p.st.get(key, 0):
                p.st[key] = n
                self.toast("Rift depth %d" % n, (190, 130, 255), 2)
            for need, gold, mat in ((3, 300, None), (6, 800, 'e'), (10, 2000, 'e')):
                fk = 'riftr_%d_%d' % (day, need)
                if n >= need and fk not in p.flags:
                    p.flags.add(fk)
                    p.gold += gold
                    msg = "Rift reward: +%dg" % gold
                    if mat:
                        mk = random.choice([k for k in NEW_MATS if k.startswith('e_')])
                        p.inv[mk] = p.inv.get(mk, 0) + 1
                        msg += " and %s!" % LOOT[mk][0]
                    self.toast(msg, GOLD, 4)
                    self.audio.play('trophy')
            if n >= 3:
                self.stat('rifts', 1) if ('riftd_%d' % day) not in p.flags and not p.flags.add('riftd_%d' % day) else None
            self.stat('rift_best', n, mx=True)
            return
        if n > p.abyss_best:
            p.rep += 1 + n // 3
            p.abyss_best = n
            self.toast("New depth record: %d!" % n, GOLD, 3)
        self.stat('abyss', n, mx=True)
        self.bounty_event('abyss', n)

    def go_home(self):
        self.enter_map(self.get_village(), VPOS['gate_out'])

    def enter_map(self, m, pos=None):
        self.clear_spell_world()
        if m.kind == 'village':
            self.end_rift()
        self.map = m
        p = self.player
        if pos is None:
            pos = m.spawn
        p.x, p.y = pos
        p.last_safe = (p.x, p.y)
        p.reset_state_motion = True
        self.projs = []
        self.glows = []
        self.fx.p.clear()
        self.warp_cd = 0.7
        self.cam = [p.x - W / 2, p.y - H / 2]
        self.clamp_cam(True)
        m.reveal(int(p.x // T), int(p.y // T), 7)
        self.audio.music_play(m.music)
        self.banner = [m.name, 0.0]
        self.ambp = []
        self.make_ambient(m)
        if m.kind == 'village':
            if p.relics:
                self.toast("Your relics crumble to ash as you leave the dungeon.", (200, 180, 160), 4)
            p.relics = []
            p.ash_used = False
            if self.state == 'play' or True:
                self.autosave()

    def make_ambient(self, m):
        n = {'leaves': 14, 'dust': 26, 'embers': 34}.get(m.weather, 0)
        for _ in range(n):
            self.ambp.append([random.uniform(0, W), random.uniform(0, H), random.uniform(0, 6.28),
                              random.uniform(0.5, 1.5)])
        if m.kind == 'village':
            for _ in range(16):
                self.ambp.append([random.uniform(0, W), random.uniform(0, H), random.uniform(0, 6.28), -1])

    def warp(self, w):
        to = w['to']
        p = self.player
        m0 = self.map
        if m0.sealed and to in ('up', 'down'):
            self.toast("The way is sealed by dark magic!", (255, 120, 140))
            self.audio.play('error')
            self.warp_cd = 0.8
            return
        if to == 'gate':
            self.warp_cd = 1.2
            self.open_gate()
            return
        ar_ = getattr(m0, 'arena', None)
        if ar_ and to == 'village' and ar_['state'] == 'fight' and any(e.hp > 0 for e in m0.enemies):
            self.warp_cd = 1.0
            p.y -= 34

            def leave_():
                ar_['state'] = 'quit'
                self.start_trans(lambda: self.enter_map(self.get_village(), VPOS['arena_out']), 2.4)
            self.say("Colosseum Gate", self.obj_pal((150, 130, 110)), ["The gate is barred while the wave lives. Forfeit the match and leave?"],
                     choices=[("Keep fighting", None), ("Forfeit and leave", leave_)])
            return
        dg0 = getattr(m0, 'dg', None)
        if dg0 and to in ('up', 'down'):
            n0 = m0.floor_no
            if to == 'up':
                if n0 == 1:
                    fn = self.go_home
                else:
                    prev = self.get_dfloor(dg0, n0 - 1)
                    sx, sy = prev.stairs_dn
                    fn = lambda: self.enter_map(prev, (sx * 16 + 8, (sy + 1) * 16 + 12))
            else:
                nxt = self.get_dfloor(dg0, n0 + 1)

                def fn():
                    self.enter_map(nxt)
                    p.maxfloor = max(p.maxfloor, n0 + 1)
            self.audio.play('stairs')
            self.start_trans(fn)
            self.warp_cd = 1.5
            return
        if to == 'village':
            fn = lambda: self.enter_map(self.get_village(), w.get('pos'))
            snd = 'door'
        elif to in ('smith', 'alch', 'general', 'inn', 'library', 'chapel', 'hall'):
            fn = lambda: self.enter_map(self.get_interior(to))
            snd = 'door'
        elif to == 'arena':
            self.warp_cd = 1.0
            p.y += 26
            self.arena_menu(None)
            return
        elif to == 'floor1':
            def fn():
                self.new_dive()
                self.enter_map(self.get_floor(1))
                p.maxfloor = max(p.maxfloor, 1)
                self.check_trophies()
                if 'tip_dungeon' not in p.flags:
                    p.flags.add('tip_dungeon')
                    self.toast("J: sword   K: fireball   SPACE: dash   Q/R/F: potions", CREAM, 5)
            snd = 'stairs'
        elif to == 'up':
            n = m0.floor_no
            ab = m0.abyss
            if n == 1:
                fn = self.go_home
            else:
                prev = self.get_abyss(n - 1) if ab else self.get_floor(n - 1)
                sx, sy = prev.stairs_dn
                fn = lambda: self.enter_map(prev, (sx * 16 + 8, (sy + 1) * 16 + 12))
            snd = 'stairs'
        else:
            n = m0.floor_no + 1
            if m0.abyss:
                def fn():
                    self.enter_map(self.get_abyss(n))
                    self.abyss_reached(n)
            else:
                def fn():
                    self.enter_map(self.get_floor(n))
                    p.maxfloor = max(p.maxfloor, n)
                    self.check_trophies()
            snd = 'stairs'
        self.audio.play(snd)
        self.start_trans(fn)
        self.warp_cd = 1.5

    # ---- saving ------------------------------------------------------
    def autosave(self):
        self.save_game(quiet=True)

    def save_game(self, quiet=False):
        if getattr(self, 'trailer', None):
            return True
        try:
            d = dict(player=self.player.to_dict(), tod=self.tod, won=self.won, v=1)
            with open(SAVE_PATH, 'w') as f:
                json.dump(d, f)
            self.has_save = True
            if not quiet:
                self.toast("Game saved.", GREEN)
            return True
        except Exception:
            if not quiet:
                self.toast("Could not write save file.", RED)
            return False

    def load_game(self):
        try:
            with open(SAVE_PATH) as f:
                d = json.load(f)
            self.player = Player()
            self.player.from_dict(d['player'])
            self.tod = d.get('tod', 0.12)
            self.won = d.get('won', False)
            self.floors.clear()
            self.maps.clear()
            self.seed = random.randrange(10 ** 6)
            self.map = None
            self.enter_map(self.get_village(), VPOS['spawn'])
            self.state = 'play'
            self.toast("Welcome back, adventurer.", CREAM)
            return True
        except Exception:
            self.has_save = False
            return False

    # ---- combat helpers ---------------------------------------------
    def hurt_player(self, dmg, sx, sy):  # noqa
        p = self.player
        if p.inv_t > 0 or p.dash_t > 0 or p.dead or self.state not in ('play', 'bossintro'):
            return
        if p.aegis > 0:
            p.aegis -= 1
            p.inv_t = 0.6
            self.audio.play('crit', 0.6)
            self.fx.burst(p.x, p.y - 9, 12, [(150, 220, 255), WHITE], 80, 0.4, 1, 0, 2)
            self.fx.text(p.x, p.y - 24, "BLOCKED", (170, 230, 255), 0.7)
            return
        d = max(int(math.ceil(dmg * 0.3)), int(dmg - p.dfn))
        if p.has('glass'):
            d = int(math.ceil(d * 1.3))
        if p.has('ward'):
            d = max(1, int(math.ceil(d * 0.85)))
        p.hp -= d
        p.inv_t = MODS.get('ifr', 0.9)
        p.hurt_t = 0.3
        if p.drink_t >= 0 and not p.drink_done:
            p.drink_t = -1.0
            self.fx.text(p.x, p.y - 30, "Interrupted!", (255, 200, 120), 0.8)
        nx, ny = norm(p.x - sx, p.y - sy)
        p.kbx, p.kby = nx * 130, ny * 130
        p.atk_t = -1
        self.shake(4)
        self.freeze = 0.07
        self.flash = [(255, 40, 40), 0.25, 0.25, 110]
        self.audio.play('hurt')
        self.pad.rumble(0.5, 0.8, 200)
        self.fx.burst(p.x, p.y - 8, 8, [RED, (255, 140, 140)], 80, 0.4, 1, 80, 2)
        self.fx.text(p.x, p.y - 22, "-%d" % d, (255, 110, 110), 0.9, False)
        if p.hp <= 0:
            self.player_die()

    def player_die(self):
        p = self.player
        if 'phoenix' in p.charms and p.phoenix_ready and self.map.kind in ('dungeon', 'boss'):
            p.phoenix_ready = False
            p.hp = int(p.max_hp * 0.6)
            p.ghost = 0.6
            p.inv_t = 2.5
            self.audio.play('phoenix')
            self.shake(6)
            self.flash = [(255, 190, 80), 0.6, 0.6, 180]
            self.glow(p.x, p.y - 8, 120, (255, 190, 90), 0.9)
            self.fx.burst(p.x, p.y - 8, 50, [(255, 200, 80), (255, 110, 30), WHITE], 140, 0.9, 2, -40, 1.5)
            for e in self.map.enemies:
                if e.kind != 'boss' and dist(e.x, e.y, p.x, p.y) < 70:
                    e.take_hit(self, int(p.atk * 2), p.x, p.y, True, 240)
            self.banner = ["PHOENIX REBIRTH", 0.0]
            self.banner_gold = True
            return
        if p.has('ash') and not p.ash_used:
            p.ash_used = True
            p.hp = int(p.max_hp * 0.4)
            p.ghost = 0.4
            p.inv_t = 2.5
            self.audio.play('phoenix')
            self.shake(6)
            self.flash = [(255, 190, 80), 0.6, 0.6, 180]
            self.glow(p.x, p.y - 8, 120, (255, 190, 90), 0.9)
            self.fx.burst(p.x, p.y - 8, 50, [(255, 200, 80), (255, 110, 30), WHITE], 140, 0.9, 2, -40, 1.5)
            for e in self.map.enemies:
                if e.kind != 'boss' and dist(e.x, e.y, p.x, p.y) < 70:
                    e.take_hit(self, int(p.atk * 2), p.x, p.y, True, 240)
            self.banner = ["PHOENIX ASH", 0.0]
            self.banner_gold = True
            return
        p.dead = True
        p.hp = 0
        if is_iron(p):
            try:
                os.remove(SAVE_PATH)
            except OSError:
                pass
            self.has_save = False
        self.state = 'dying'
        self.dying_t = 0.0
        self.audio.music_stop()
        self.audio.play('death')
        self.fx.burst(p.x, p.y - 8, 30, [RED, WHITE, (255, 200, 120)], 110, 0.9, 2, 60, 2)

    def give_xp(self, n):
        p = self.player
        if p.level >= MAX_LEVEL:
            p.xp = 0
            return
        p.xp += max(1, int(n * p.xp_mult))
        while p.level < MAX_LEVEL and p.xp >= xp_needed(p.level):
            p.xp -= xp_needed(p.level)
            p.level += 1
            p.sp += 1
            p.hp = p.max_hp
            p.mp = p.max_mp
            p.ghost = 1.0
            self.audio.play('levelup')
            self.banner = ["LEVEL %d!" % p.level, 0.0]
            self.banner_gold = True
            self.fx.burst(p.x, p.y - 8, 28, [GOLD, WHITE, (255, 240, 160)], 100, 0.9, 2, -20, 1.5)
            self.glow(p.x, p.y - 8, 80, (255, 230, 150), 0.7)
            self.toast("Level up!  +1 skill point (open MENU)", GOLD, 3)
            self.check_spell_unlocks()
        if p.level >= MAX_LEVEL:
            p.xp = 0
        self.check_trophies()

    # ---- statistics, trophies, bounties ------------------------------------
    def stat(self, k, n=1, mx=False):
        st = self.player.st
        st[k] = max(st.get(k, 0), n) if mx else st.get(k, 0) + n
        self.check_trophies()

    def stat_value(self, k):
        p = self.player
        if k == 'nspells':
            return len(p.spells)
        if k == 'ndg':
            return len([1 for d in DUNGEONS if p.st.get('dg_' + d['id'], 0) > 0])
        if k == 'nboss':
            return len([1 for d in DUNGEONS if boss_flag(d['boss']) in p.flags])
        if k == 'kills':
            return p.kills
        if k == 'deepest':
            return p.maxfloor
        if k == 'level':
            return p.level
        if k == 'deaths':
            return p.deaths
        if k == 'rank':
            return p.rank
        if k == 'charms':
            return len(p.charms)
        if k == 'abyss':
            return p.abyss_best
        if k == 'heat':
            return p.heat
        if k == 'asc':
            return p.asc
        return p.st.get(k, 0)

    def check_trophies(self):
        p = self.player
        if p.rank > p.st.get('rank_seen', 0):
            p.st['rank_seen'] = p.rank
            self.banner = ["GUILD RANK: %s" % RANKS[p.rank][0].upper(), 0.0]
            self.banner_gold = True
            self.audio.play('levelup')
        for (tid, name, desc, key, goal, rew) in TROPHIES:
            if tid in p.trophies or self.stat_value(key) < goal:
                continue
            p.trophies.add(tid)
            if rew[0] == 'g':
                p.gold += rew[1]
                rs = "+%dg" % rew[1]
            else:
                p.sp += rew[1]
                rs = "+%d skill point%s" % (rew[1], "s" if rew[1] > 1 else "")
            self.audio.play('trophy')
            self.trophy_pop.append([name, rs, 4.0])
            self.fx.burst(p.x, p.y - 12, 14, [GOLD, WHITE], 70, 0.7, 1, -30, 2)

    def bounty_event(self, kind, key=None, n=1):
        p = self.player
        for b in p.bounties:
            if b['done'] or b['type'] != kind:
                continue
            if kind == 'kill' and key not in b['kinds']:
                continue
            if kind == 'abyss':
                b['prog'] = max(b['prog'], n)
            else:
                b['prog'] += n
            if b['prog'] >= b['n']:
                b['prog'] = b['n']
                b['done'] = True
                self.audio.play('bounty')
                self.toast("Bounty complete: %s  (see Guard Torvin)" % b['name'], GOLD, 4)

    def drop(self, x, y, kind, val=1):
        pk = Pickup(x, y, kind, val)
        self.map.pickups.append(pk)

    def kill_hooks(self, e):
        p = self.player
        m = self.map
        if 'vamp' in p.charms and p.hp < p.max_hp and not p.dead:
            p.hp = min(p.max_hp, p.hp + 3)
            self.fx.text(p.x - 6, p.y - 30, "+3", (230, 60, 90), 0.6)
        if p.has('fang') and p.hp < p.max_hp and not p.dead:
            p.hp = min(p.max_hp, p.hp + 2)
            self.fx.text(p.x + 6, p.y - 26, "+2", (255, 130, 150), 0.6)
        if p.has('bomb') and getattr(self, '_bomb_depth', 0) < 3 and not e.minion:
            self._bomb_depth = getattr(self, '_bomb_depth', 0) + 1
            self.explode(e.x, e.y - 6, max(3, int(p.atk * 0.6)), 30)
            self._bomb_depth -= 1
        if e.kind == 'necro':
            for o in m.enemies:
                if not o.dead and o.minion_of == id(e):
                    o.dead = True
                    self.corpses.append(Corpse(o, o.sprite()))
                    self.fx.burst(o.x, o.y - 8, 12, [(170, 80, 255), (210, 200, 230)], 70, 0.5, 1, -20, 2)

    def kill_enemy(self, e):
        m = self.map
        p = self.player
        e.dead = True
        p.kills += 1
        self.audio.play('edie')
        self.kill_hooks(e)
        self.corpses.append(Corpse(e, e.sprite()))
        kl_ = e.killer
        if kl_ and (kl_.get('crit') or kl_.get('combo') == 2) and not e.minion and e.kind != 'boss':
            self.freeze = max(self.freeze, 0.1)
            self.slow_t = max(self.slow_t, 0.24)
        cols = {'slime': [(96, 200, 100), WHITE], 'slime2': [(90, 150, 240), WHITE], 'bat': [(110, 76, 150), WHITE],
                'wraith': [(130, 255, 210), WHITE], 'spider': [(120, 70, 160), (230, 90, 90)],
                'golem': [(150, 150, 170), (110, 110, 130)], 'imp': [(255, 120, 50), (255, 220, 120)],
                'necro': [(170, 80, 255), (210, 190, 240)], 'knight': [(150, 160, 200), (230, 224, 204)]
                }.get(e.kind, [(230, 224, 204), (180, 172, 150)])
        self.fx.burst(e.x, e.y - 6, 16, cols, 90, 0.6, 2, 90, 2)
        self.fx.burst(e.x, e.y - 6, 6, [WHITE], 40, 0.3, 1, 0, 3)
        st = e.st
        elite = getattr(e, 'elite', None)
        fl = max(1.0, float(e.floor))
        self.give_xp(int(st['xp'] * (1 + 0.12 * (fl - 1)) * (3 if elite else 1) * (2 if getattr(e, 'warden', False) else 1)
                         * (0.2 if e.minion else 1)))
        vmul = max(1.0, (1 + 0.1 * (fl - 1)) * (2.5 if elite else 1) * (2 if getattr(e, 'warden', False) else 1))
        ncoin = random.randint(*st['gold']) // 2 + (1 if st['gold'][1] > 0 else 0) + (4 if elite else 0)
        if e.minion:
            ncoin = 0
        for _ in range(ncoin):
            self.drop(e.x, e.y - 4, 'coin', int((3 if random.random() < 0.8 else 8) * vmul))
        r = random.random()
        if r < 0.13 * MODS['drop']:
            self.drop(e.x, e.y - 4, 'heart')
        elif r < 0.13 * MODS['drop'] + 0.12:
            self.drop(e.x, e.y - 4, 'mana')
        table = {'slime': [('gel', 0.45)], 'slime2': [('gel', 0.55)], 'bat': [('wing', 0.4)],
                 'skeleton': [('bone', 0.55), ('ore', 0.3)], 'archer': [('bone', 0.4), ('ore', 0.22)],
                 'wraith': [('ectoplasm', 0.65), ('gem', 0.12)], 'spider': [('silk', 0.6), ('ore', 0.15)],
                 'golem': [('core', 0.7), ('ore', 0.8), ('gem', 0.2)], 'imp': [('embershard', 0.6), ('gem', 0.1)],
                 'knight': [('ore', 0.7), ('bone', 0.4), ('gem', 0.18)],
                 'necro': [('ectoplasm', 0.6), ('gem', 0.25), ('bone', 0.4)]
                 }.get(e.kind, []) or list(NEW_LOOT.get(e.kind, []))
        dg_ = getattr(m, 'dg', None)
        if dg_ and not e.minion and random.random() < 0.3:
            table = table + [(random.choice(dg_['mats']), 1.0)]
        fn_ = ON_DEATH.get(e.kind)
        if fn_:
            fn_(self, e)
        if e.minion:
            table = []
        for it, ch in table:
            if random.random() < ch:
                self.drop(e.x, e.y - 4, 'item', it)
        if elite:
            extra = 2 if 'horn' in p.charms else 1
            for _ in range(extra):
                self.drop(e.x, e.y - 4, 'item', random.choice(['gem', 'ore', 'ore', 'core']))
                if random.random() < 0.5:
                    self.drop(e.x, e.y - 4, 'item', 'gem')
            self.drop(e.x, e.y - 4, 'heart')
            self.stat('elites')
            p.rep += 3
            self.bounty_event('elite')
            if elite == 'volatile':
                self.glow(e.x, e.y - 6, 60, (255, 180, 60), 0.4)
                self.fx.burst(e.x, e.y - 6, 26, [(255, 200, 80), (255, 110, 30)], 110, 0.5, 2, 40, 2)
                self.audio.play('boom', 0.8)
                self.shake(4)
                if dist(e.x, e.y, p.x, p.y) < 32:
                    self.hurt_player(int(e.dmg * 1.1), e.x, e.y)
        if getattr(e, 'warden', False):
            for _ in range(3):
                self.drop(e.x, e.y - 4, 'item', 'gem')
            p.rep += 12
            self.toast("The Warden falls!", GOLD, 3)
        if p.blood_t > 0 and p.hp < p.max_hp:
            p.hp = min(p.max_hp, p.hp + int(p.max_hp * 0.05))
        if p.sk('blood') and p.hp < p.max_hp:
            h = 2 * p.sk('blood')
            p.hp = min(p.max_hp, p.hp + h)
            self.fx.text(p.x, p.y - 26, "+%d" % h, (255, 130, 160), 0.6)
        self.stat('k_' + e.kind)
        self.bounty_event('kill', e.kind)
        for qid, qs in p.q.items():
            q = QUEST_BY_ID.get(qid)
            if q and q['kind'] == 'kill' and qs['state'] == 'active' and e.kind in q['target']:
                qs['prog'] = min(q['n'], qs['prog'] + 1)
                if qs['prog'] >= q['n']:
                    qs['state'] = 'ready'
                    self.toast("Quest ready: %s" % q['name'], GOLD, 4)
                    self.audio.play('unlock')

    def boss_hit(self, b, dmg, crit):
        if b.state == 'dormant' or b.invuln > 0 or getattr(b, 'hidden', False):
            self.audio.play('hit', 0.4, 0.1)
            self.fx.burst(b.x, b.y - 18, 3, [(160, 160, 200)], 50, 0.2, 1, 0, 3)
            return False
        b.hp -= dmg
        b.hurt_t = 0.18
        b.flash = 0.08
        self.audio.play('crit' if crit else 'hit', 0.9, 0.05)
        self.fx.burst(b.x + random.uniform(-8, 8), b.y - 20, 5, [WHITE, (255, 190, 120)], 70, 0.3, 1, 0, 3)
        self.fx.text(b.x + random.uniform(-8, 8), b.y - 40, str(dmg), (255, 240, 120) if crit else WHITE, 0.7, crit)
        frac = b.hp / b.maxhp
        if b.hp <= 0:
            self.boss_die(b)
        elif (frac < 0.66 and b.phase == 1) or (frac < 0.33 and b.phase == 2):
            b.phase += 1
            b.state = 'phase'
            b.timer = 1.5
            b.invuln = 1.6
            self.projs = [pr for pr in self.projs if pr.friendly]
            self.audio.play('roar')
            self.shake(7)
            self.flash = [(180, 80, 255), 0.5, 0.5, 120]
            self.fx.burst(b.x, b.y - 20, 40, [(200, 120, 255), WHITE], 130, 0.9, 2, 0, 1.5)
            self.toast(getattr(b, 'rage_text', "The Hollow King is enraged!"), (230, 140, 255), 3)
            if hasattr(b, 'on_phase'):
                b.on_phase(self)
        return True

    def boss_die(self, b):
        p = self.player
        bid = getattr(b, 'bid', 'king')
        before = self.unlocked_set()
        b.dead = True
        b.hp = 0
        self.projs = []
        self.hazards = [h for h in self.hazards if h.owner != 'e']
        self.blackout_t = self.blizzard_t = 0.0
        self.state = 'bossdeath'
        self.dying_t = 0.0
        first = boss_flag(bid) not in p.flags
        self.cut = dict(x=b.x, y=b.y, n=0, bid=bid, xp=b.st['xp'], first=first, col=getattr(b, 'fxcol', (200, 120, 255)))
        self.audio.music_stop()
        self.audio.play('roar')
        self.map.sealed = False
        p.kills += 1
        p.flags.add(boss_flag(bid))
        if bid == 'king':
            self.stat('bosses')
        self.stat('bk_' + bid)
        if p.diff >= 4:
            self.stat('hard_bosses')
        p.rep += 25
        for s_ in SPELLS:
            if s_[6] == ('boss', bid):
                self.learn_spell(s_[0])
        dg = getattr(self.map, 'dg', None)
        if dg:
            t_ = int(self.dive_t)
            if not p.st.get('best_' + dg['id']) or t_ < p.st['best_' + dg['id']]:
                p.st['best_' + dg['id']] = t_
        if bid == 'king':
            if p.diff >= 3:
                self.stat('nm_king')
            if p.diff >= 4:
                self.stat('hollow_king')
            if is_iron(p):
                self.stat('iron_king')
            if p.heat >= 5:
                p.asc += 1
                recalc_mods(p)
                self.toast("ASCENSION %d: the pact rewards you." % p.asc, (255, 170, 70), 5)
                p.st['asc_rank'] = p.asc
        new = self.unlocked_set() - before
        for nid in sorted(new):
            self.later(2.5, lambda nid=nid: self.toast("New dungeon unlocked: %s" % DUNGEON_BY_ID[nid]['name'], GOLD, 5))

    # ---- projectiles --------------------------------------------------
    def explode(self, x, y, dmg, radius=26):
        m = self.map
        self.audio.play('fire_hit')
        self.shake(2)
        if self.player.sk('nova'):
            radius = int(radius * 1.4)
        self.fx.burst(x, y, 22, [(255, 200, 80), (255, 110, 30), WHITE, (255, 70, 20)], 110, 0.5, 2, 40, 2)
        self.glow(x, y, 60, (255, 160, 70), 0.35)
        for e in m.enemies:
            if e.dead:
                continue
            cx, cy = e.center()
            if dist(cx, cy, x, y) < radius + (14 if e.kind == 'boss' else 0):
                crit = random.random() < self.player.crit
                e.take_hit(self, int(dmg * (1.6 if crit else 1)), x, y, crit, 140)
        for pt in list(m.pots):
            if dist(pt.x, pt.y - 4, x, y) < radius:
                self.break_pot(pt)

    def update_projs(self, dt):
        m = self.map
        p = self.player
        for pr in self.projs:
            pr.t += dt
            pr.life -= dt
            if pr.home and not pr.friendly:
                nx, ny = norm(p.x - pr.x, p.y - 6 - pr.y)
                sp = math.hypot(pr.vx, pr.vy)
                pr.vx += nx * sp * pr.home * dt * 2
                pr.vy += ny * sp * pr.home * dt * 2
                k = sp / max(1, math.hypot(pr.vx, pr.vy))
                pr.vx *= k
                pr.vy *= k
            pr.x += pr.vx * dt
            pr.y += pr.vy * dt
            if pr.life <= 0:
                pr.dead = True
                if pr.kind == 'fire':
                    self.explode(pr.x, pr.y, pr.dmg)
                continue
            if pr.kind == 'fire':
                if random.random() < 0.8:
                    self.fx.add(pr.x, pr.y, random.uniform(-10, 10), random.uniform(-10, 10), 0.3,
                                random.choice([(255, 150, 40), (255, 90, 30), (255, 220, 120)]), 2, -20)
            if m.point_solid(pr.x, pr.y):
                pr.dead = True
                if pr.kind == 'fire':
                    self.explode(pr.x, pr.y, pr.dmg)
                else:
                    self.fx.burst(pr.x, pr.y, 4, [(200, 200, 220)], 40, 0.25, 1, 0, 3)
                continue
            if pr.friendly:
                for e in m.enemies:
                    if e.dead:
                        continue
                    cx, cy = e.center()
                    if dist(cx, cy, pr.x, pr.y) < pr.r + e.bw / 2 + (10 if e.kind == 'boss' else 2):
                        if pr.pierce:
                            if id(e) in pr.hits:
                                continue
                            pr.hits.add(id(e))
                            dm = pr.dmg
                            if getattr(e, 'freeze_t', 0) > 0:
                                dm = int(dm * 1.7)
                                e.freeze_t = 0
                                self.fx.burst(e.x, e.y - 8, 14, [(200, 240, 255), WHITE], 90, 0.5, 1, 40, 2)
                                self.fx.text(e.x, e.y - 28, "SHATTER!", (190, 240, 255), 0.8, True)
                            hurt_enemy(self, e, dm, pr.x - pr.vx, pr.y - pr.vy, 70)
                            self.fx.burst(pr.x, pr.y, 4, [(200, 240, 255), WHITE], 60, 0.25, 1, 0, 3)
                            continue
                        pr.dead = True
                        if pr.kind == 'fire':
                            self.explode(pr.x, pr.y, pr.dmg)
                        else:
                            e.take_hit(self, pr.dmg, pr.x - pr.vx, pr.y - pr.vy, False, 80)
                        break
            else:
                if dist(p.x, p.y - 6, pr.x, pr.y) < pr.r + 4:
                    if p.inv_t <= 0 and p.dash_t <= 0:
                        pr.dead = True
                        self.hurt_player(pr.dmg, pr.x - pr.vx * 0.1, pr.y - pr.vy * 0.1)
        self.projs = [pr for pr in self.projs if not pr.dead]

    # ---- player actions ---------------------------------------------
    def break_pot(self, pt):
        if pt not in self.map.pots:
            return
        self.map.pots.remove(pt)
        self.stat('pots')
        self.audio.play('pot')
        col = {'pot': [(170, 90, 60), (210, 130, 90)], 'crate': [(170, 120, 70), (120, 78, 46)],
               'barrel': [(150, 102, 62), (110, 70, 44)]}[pt.kind]
        self.fx.burst(pt.x, pt.y - 6, 12, col, 80, 0.6, 2, 160, 2)
        r = random.random()
        if r < 0.55:
            for _ in range(random.randint(1, 3)):
                self.drop(pt.x, pt.y - 4, 'coin', 1 if random.random() < 0.7 else 5)
        elif r < 0.7:
            self.drop(pt.x, pt.y - 4, 'heart')
        elif r < 0.82:
            self.drop(pt.x, pt.y - 4, 'mana')

    def start_attack(self):
        p = self.player
        if p.atk_t >= 0 or p.cool > 0 or p.dash_t > 0 or p.drink_t >= 0:
            return
        if p.combo_t > 0:
            p.combo = (p.combo + 1) % 3
        else:
            p.combo = 0
        p.atk_t = 0.0
        p.whirl_fx = False
        st = WSTYLE[p.wt]
        p.atk_dur = st['dur'][p.combo]
        p.atk_move = st['moves'][p.combo]
        if p.combo == 2 and p.sk('whirl'):
            p.atk_move = 'spin'
        p.atk_hit = set()
        p.atk_ang = math.atan2(p.fy, p.fx)
        p.sweep = -p.sweep if p.combo else 1
        p.lunge = st['lunge'][p.combo]
        self.audio.play(st['snd'], 0.9)

    def resolve_swing(self):
        p = self.player
        m = self.map
        st = WSTYLE[p.wt]
        mv = getattr(p, 'atk_move', 'slash')
        reach = {'slash': 25, 'overhead': 27, 'thrust': 33, 'spin': 32, 'slam': 30}.get(mv, 25)
        half = {'slash': 1.15, 'overhead': 1.0, 'thrust': 0.5, 'spin': 3.3, 'slam': 1.5}.get(mv, 1.15)
        if mv == 'slash' and p.combo == 2:
            reach, half = 32, 1.7
        reach *= st['reach']
        if p.combo == 2 and p.sk('whirl'):
            reach, half = 36, 3.3
            if not getattr(p, 'whirl_fx', False):
                p.whirl_fx = True
                for i in range(18):
                    a = i / 18 * math.tau
                    self.fx.add(p.x + math.cos(a) * 20, p.y - 7 + math.sin(a) * 20, math.cos(a) * 40,
                                math.sin(a) * 40, 0.3, (255, 240, 200), 2, 0, 3)
        ox, oy = p.x, p.y - 7
        ang = p.atk_ang
        hit_any = False
        for e in m.enemies:
            if e.dead or id(e) in p.atk_hit:
                continue
            ex, ey = e.center()
            d = dist(ex, ey, ox, oy)
            extra = 14 if e.kind == 'boss' else 4
            if d <= reach + extra:
                a = math.atan2(ey - oy, ex - ox)
                diff = abs((a - ang + math.pi) % math.tau - math.pi)
                if diff <= half or d < 12:
                    p.atk_hit.add(id(e))
                    crit = random.random() < p.crit
                    dmg = p.atk * (1.0 if p.combo < 2 else 1.45) * random.uniform(0.9, 1.1)
                    dmg = int(dmg * (p.crit_mult if crit else 1))
                    if e.kind != 'boss':
                        e.killer = dict(wt=p.wt, combo=p.combo, crit=crit, ang=p.atk_ang, mv=mv)
                    kb_ = (110 if p.combo < 2 else 190) * (1.25 if st['shape'] == 'broad' else 1.0) * \
                        (1.5 if mv == 'slam' else 1.0)
                    if e.take_hit(self, max(1, dmg), p.x, p.y, crit, kb_):
                        hit_any = True
                        self.freeze = ((0.055 if not crit else 0.09) + (0.02 if p.combo == 2 else 0)) * st['freeze']
                        self.shake((2 if p.combo < 2 else 3.5) * st['shake'])
                        self.kick = [p.fx * (3 if p.combo < 2 else 5), p.fy * (3 if p.combo < 2 else 5)]
                        tc = st['tcol']
                        self.fx.burst(ex, ey, 7 if p.combo < 2 else 12, [WHITE, lerp_c(tc, WHITE, 0.5), tc], 120, 0.22, 1, 0, 4)
                        self.weapon_hit_fx(e, ex, ey, ang)
                        self.rune_hit(e, ex, ey, dmg, crit)
                        if st['shape'] == 'flame' and e.kind != 'boss' and not e.dead:
                            e.burn_t = 2.4
                            e.burn_dmg = max(1, int(p.atk * 0.12))
        for pt in list(m.pots):
            if id(pt) in p.atk_hit:
                continue
            if dist(pt.x, pt.y - 5, ox, oy) <= reach + 4:
                a = math.atan2(pt.y - 5 - oy, pt.x - ox)
                diff = abs((a - ang + math.pi) % math.tau - math.pi)
                if diff <= half + 0.3:
                    p.atk_hit.add(id(pt))
                    self.break_pot(pt)
        for pr in self.projs:
            if not pr.friendly and pr.kind in ('arrow', 'orb', 'ember') and dist(pr.x, pr.y, ox, oy) <= reach + 6:
                pr.friendly = True
                pr.vx, pr.vy = -pr.vx * 1.3, -pr.vy * 1.3
                pr.dmg = int(p.atk)
                self.audio.play('crit', 0.6)
                self.fx.burst(pr.x, pr.y, 6, [WHITE, (150, 220, 255)], 60, 0.3, 1, 0, 3)
        return hit_any

    def weapon_hit_fx(self, e, ex, ey, ang):
        """per-weapon impact flourish: a slash mark through the foe, sparks, embers"""
        p = self.player
        st = WSTYLE[p.wt]
        sh = st['shape']
        tc = st['tcol']
        mv = getattr(p, 'atk_move', 'slash')
        if mv == 'thrust':
            ca, sa = math.cos(ang), math.sin(ang)
            for i in range(10):
                d = -8 + i * 2.2
                self.fx.add(ex + ca * d, ey + sa * d, 0, 0, 0.2, lerp_c(tc, WHITE, 0.4), 1)
            for i in range(5):
                self.fx.add(ex, ey, ca * random.uniform(60, 140), sa * random.uniform(60, 140) + random.uniform(-20, 20), 0.25, tc, 1)
            return
        a = ang + (1.1 if p.sweep > 0 else -1.1)
        ca, sa = math.cos(a), math.sin(a)
        n = 12 if sh in ('void', 'bone') else 9
        for i in range(n):
            d = -10 + i * (20.0 / n)
            col = tc if i % 2 else lerp_c(tc, WHITE, 0.55)
            self.fx.add(ex + ca * d, ey + sa * d, ca * 12, sa * 12, 0.28 if sh != 'void' else 0.42, col, 1 + (sh in ('void', 'bone')))
        if sh == 'flame':
            self.fx.burst(ex, ey, 8, [(255, 170, 50), (255, 100, 30), (255, 230, 120)], 70, 0.4, 1, -30, 2)
        elif sh == 'broad':
            self.fx.burst(ex, ey, 6, [(255, 240, 180), (220, 200, 160)], 140, 0.18, 1, 80, 3)
        elif sh == 'void':
            for i in range(8):
                b = random.random() * math.tau
                self.fx.add(ex + math.cos(b) * 12, ey + math.sin(b) * 12, -math.cos(b) * 50, -math.sin(b) * 50, 0.3,
                            (190, 110, 255), 1)
        elif sh == 'bone':
            self.fx.burst(ex, ey + 4, 8, [(232, 226, 204), (170, 160, 140)], 90, 0.4, 2, 120, 2)

    def swing_fx(self):
        """particles that ride the blade while it is moving"""
        p = self.player
        st = WSTYLE[p.wt]
        k = clamp(p.atk_t / p.atk_dur, 0, 1)
        if k < 0.14 or k > 0.75:
            return
        arm, bang, ext = self.swing_pose(k)
        ox, oy = p.x + p.dox, p.y - 9 + p.doy
        rh = 6
        hx, hy = ox + math.cos(arm) * (rh + ext), oy + math.sin(arm) * (rh + ext)
        L = st['L']
        tx, ty = hx + math.cos(bang) * L, hy + math.sin(bang) * L
        sh = st['shape']
        if sh == 'flame':
            for _ in range(2):
                f = random.random()
                self.fx.add(hx + (tx - hx) * f + random.uniform(-1, 1), hy + (ty - hy) * f + random.uniform(-1, 1),
                            random.uniform(-14, 14), random.uniform(-28, -6), 0.35 + random.random() * 0.2,
                            random.choice([(255, 170, 50), (255, 110, 30), (255, 230, 120)]), 1 + (random.random() < 0.3), -30)
            if int(p.atk_t * 60) % 4 == 0:
                self.glow(tx, ty, 26, (255, 140, 50), 0.12)
        elif sh == 'void' and random.random() < 0.6:
            self.fx.add(tx + random.uniform(-2, 2), ty + random.uniform(-2, 2), random.uniform(-8, 8),
                        random.uniform(-8, 8), 0.45, random.choice([(190, 110, 255), (230, 200, 255)]), 1)
        elif sh == 'rapier' and random.random() < 0.5:
            self.fx.add(tx, ty, random.uniform(-10, 10), random.uniform(-10, 10), 0.25, (190, 252, 255), 1)
        elif sh == 'rust' and random.random() < 0.12:
            self.fx.add(tx, ty, random.uniform(-6, 6), random.uniform(4, 14), 0.4, (150, 96, 56), 1, 60)

    def cast_fire(self):
        self.cast_spell('fire')

    def cast_fire_old(self):
        p = self.player
        if p.fire_cd > 0 or p.atk_t >= 0 and False:
            return
        if p.mp < 3:
            self.audio.play('error', 0.6, 0.3)
            self.fx.text(p.x, p.y - 22, "No MP", BLUE, 0.7)
            return
        p.mp -= 3
        p.fire_cd = 0.4
        p.cast_t = 0.2
        dmg = int((8 + p.level * 2 + p.atk * 0.45) * (1 + 0.12 * p.sk('arcana')))
        self.projs.append(Projectile(p.x + p.fx * 8, p.y - 7 + p.fy * 6, p.fx * 150, p.fy * 150, dmg, 'fire', True, 1.4))
        self.audio.play('fire')
        self.fx.burst(p.x + p.fx * 8, p.y - 7, 6, [(255, 160, 50), (255, 230, 140)], 50, 0.25, 1, 0, 3)

    def use_item(self, it, anim=False):
        p = self.player
        if it in CONSUMABLE_EXTRAS:
            if p.inv.get(it, 0) <= 0:
                self.audio.play('error', 0.6, 0.2)
                return
            if self.apply_extra(it):
                p.inv[it] -= 1
                self.audio.play('potion')
            return
        if not anim or it not in ('hp_potion', 'mp_potion', 'big_hp', 'big_mp', 'elixir'):
            return self.apply_item(it)
        if p.drink_t >= 0:
            return
        if p.inv.get(it, 0) <= 0:
            self.audio.play('error', 0.6, 0.2)
            return
        if p.potion_cd > 0:
            self.audio.play('error', 0.5, 0.3)
            self.fx.text(p.x, p.y - 24, "%.1fs" % p.potion_cd, (200, 180, 160), 0.5)
            return
        full = {'hp_potion': p.hp >= p.max_hp, 'big_hp': p.hp >= p.max_hp, 'mp_potion': p.mp >= p.max_mp,
                'big_mp': p.mp >= p.max_mp, 'elixir': p.elixir_t > 0}[it]
        if full:
            return self.apply_item(it)             # shows the usual toast
        p.drink_t, p.drink_kind, p.drink_done = 0.0, it, False
        p.atk_t = -1
        self.audio.play('cork', 0.6)

    def apply_item(self, it):
        p = self.player
        if p.inv.get(it, 0) <= 0:
            self.audio.play('error', 0.6, 0.2)
            return
        if it == 'hp_potion':
            if p.hp >= p.max_hp:
                self.toast("Health is already full.", GREY)
                return
            hv = int(50 * MODS['heal'])
            p.hp = min(p.max_hp, p.hp + hv)
            self.fx.burst(p.x, p.y - 8, 12, [GREEN, WHITE], 40, 0.6, 1, -40, 2)
            self.fx.text(p.x, p.y - 22, "+%d" % hv, GREEN, 0.9)
        elif it == 'mp_potion':
            if p.mp >= p.max_mp:
                self.toast("Mana is already full.", GREY)
                return
            p.mp = min(p.max_mp, p.mp + 18)
            self.fx.burst(p.x, p.y - 8, 12, [BLUE, WHITE], 40, 0.6, 1, -40, 2)
            self.fx.text(p.x, p.y - 22, "+18 MP", BLUE, 0.9)
        elif it == 'big_hp':
            if p.hp >= p.max_hp:
                self.toast("Health is already full.", GREY)
                return
            hv = int(130 * MODS['heal'])
            p.hp = min(p.max_hp, p.hp + hv)
            self.fx.burst(p.x, p.y - 8, 16, [GREEN, WHITE], 50, 0.7, 1, -40, 2)
            self.fx.text(p.x, p.y - 22, "+%d" % hv, GREEN, 0.9)
        elif it == 'big_mp':
            if p.mp >= p.max_mp:
                self.toast("Mana is already full.", GREY)
                return
            p.mp = min(p.max_mp, p.mp + 50)
            self.fx.burst(p.x, p.y - 8, 16, [BLUE, WHITE], 50, 0.7, 1, -40, 2)
            self.fx.text(p.x, p.y - 22, "+50 MP", BLUE, 0.9)
        elif it == 'fortune':
            if p.fortune_t > 0:
                self.toast("Fortune is already active.", GREY)
                return
            p.fortune_t = 120.0
            self.fx.burst(p.x, p.y - 8, 16, [GOLD, WHITE], 60, 0.7, 1, -50, 2)
            self.toast("Fortune smiles on you! (+50% gold, 2 min)", GOLD)
        elif it == 'stoneskin':
            if p.stone_t > 0:
                self.toast("Stoneskin is already active.", GREY)
                return
            p.stone_t = 120.0
            self.fx.burst(p.x, p.y - 8, 16, [(170, 170, 190), WHITE], 60, 0.7, 1, -50, 2)
            self.toast("Your skin turns to stone! (+4 DEF, 2 min)", (190, 190, 220))
        elif it == 'elixir':
            if p.elixir_t > 0:
                self.toast("Elixir is already active.", GREY)
                return
            p.elixir_t = 50.0
            self.fx.burst(p.x, p.y - 8, 16, [(255, 170, 40), WHITE], 60, 0.7, 1, -50, 2)
            self.toast("Strength surges through you! (+50% ATK)", (255, 190, 80))
        if it == 'big_hp':
            pass
        if p.sk('frugal') and random.random() < 0.1 * p.sk('frugal'):
            self.fx.text(p.x, p.y - 30, "Saved!", (190, 255, 190), 0.8)
        else:
            p.inv[it] -= 1
        self.audio.play('potion')

    # ---- interaction --------------------------------------------------
    def find_interact(self):
        p = self.player
        m = self.map
        px, py = p.x + p.fx * 5, p.y - 4
        best, bd = None, 1e9
        for n in m.npcs:
            d = dist(px, py, n.x, n.y - 4)
            if d < n.reach and d < bd:
                best, bd = ('npc', n, n.x, n.y - 24), d
        for a in getattr(m, 'animals', []):
            if a.kind in ('cat', 'dog'):
                d = dist(px, py, a.x, a.y - 4)
                if d < 20 and d < bd:
                    best, bd = (a.kind, a, a.x, a.y - 14), d
        for c in m.chests:
            if not c.opened:
                d = dist(px, py, c.x, c.y - 4)
                if d < 22 and d < bd:
                    best, bd = ('chest', c, c.x, c.y - 18), d
        for (x, y, r, kind, data) in m.interacts:
            d = dist(px, py, x, y - 4)
            if d < r and d < bd:
                best, bd = (kind, data, x, y - 24), d
        return best

    def interact(self):
        it = self.interact_target
        if not it:
            return
        kind, obj = it[0], it[1]
        p = self.player
        if kind == 'npc':
            dx, dy = p.x - obj.x, p.y - obj.y
            if abs(dx) > abs(dy):
                obj.dir = 3 if dx > 0 else 2
            else:
                obj.dir = 0 if dy > 0 else 1
            self.audio.play('select', 0.6)
            self.talk(obj)
        elif kind == 'cat':
            self.audio.play('talk3', 1.0)
            self.fx.burst(obj.x, obj.y - 14, 4, [(255, 120, 160)], 20, 0.8, 2, -30, 1)
            self.toast("The cat purrs. Best. Day. Ever.", (255, 190, 120))
        elif kind == 'chest':
            self.open_chest(obj)
        elif kind == 'shrine':
            self.use_shrine(obj)
        elif kind == 'pact':
            self.open_pact()
        elif kind in ('bench', 'cauldron'):
            self.open_craft(kind)
        elif kind == 'beacon':
            def home():
                self.audio.play('portal')
                self.start_trans(self.go_home, 1.6)
            self.say("Beacon", dict(tun=(120, 200, 255), bald=True, skin=(120, 200, 255)),
                     ["A crystal hums with warm light. Touch it to return to Emberfall?"],
                     choices=[("Return to the village", home), ("Stay", None)])
        elif kind == 'text':
            self.audio.play('menu')
            self.say("Sign", dict(tun=(176, 126, 80), bald=True, skin=(176, 126, 80)), obj)
        elif kind == 'dog':
            self.audio.play('talk2', 1.0)
            self.fx.burst(obj.x, obj.y - 12, 4, [(255, 190, 120)], 20, 0.8, 2, -30, 1)
            self.toast("Woof! The dog wags so hard it falls over.", (255, 200, 140))
        else:
            self.village_interact(kind, obj)

    def set_heat(self, h):
        p = self.player
        p.heat = max(0, min(heat_cap(p), h))
        recalc_mods(p)
        self.floors.clear()
        self.audio.play('shrine', 0.8)
        self.glow(self.map.pact_pos[0], self.map.pact_pos[1] - 16, 60 + 8 * p.heat, (255, 90, 50), 0.6) \
            if hasattr(self.map, 'pact_pos') else None
        self.check_trophies()
        self.save_game(quiet=True)

    def open_pact(self):
        p = self.player
        cap = heat_cap(p)

        def up():
            if p.heat < cap:
                self.set_heat(p.heat + 1)
            else:
                self.audio.play('error', 0.6)
            self.open_pact()

        def down():
            if p.heat > 0:
                self.set_heat(p.heat - 1)
            self.open_pact()
        more = "" if cap >= HEAT_MAX else "\n(Slay the Hollow King to deepen the pact.)"
        asc = "  Ascension %d" % p.asc if p.asc else ""
        self.say("Ember Pact", dict(tun=(255, 110, 50), bald=True, skin=(255, 150, 70)),
                 ["EMBER PACT   Heat %d / %d%s\n%s%s" % (p.heat, cap, asc, heat_text(p.heat), more)],
                 choices=[("Stoke the flames  (+1 Heat)", up), ("Bank the embers  (-1 Heat)", down), ("Leave", None)])

    def open_relic(self, pr):
        p = self.player
        pool = [r for r in RELICS if r[0] not in p.relics]
        if not pool:
            self.toast("You already carry every relic.", GREY)
            return
        n = min(len(pool), 3 + (1 if p.asc >= 1 else 0))
        self.relic_ui = dict(pr=pr, opts=random.sample(pool, n), sel=0, t=0.0)
        self.state = 'relic'
        self.audio.play('shrine', 0.6)

    def update_relic(self, dt):
        u = self.relic_ui
        u['t'] += dt
        n = len(u['opts'])
        if self.jp('left') or self.jp('up'):
            u['sel'] = (u['sel'] - 1) % n
            self.audio.play('menu')
        if self.jp('right') or self.jp('down'):
            u['sel'] = (u['sel'] + 1) % n
            self.audio.play('menu')
        if u['t'] < 0.25:
            return
        if self.jp('back'):
            self.state = 'play'
            self.audio.play('back')
        elif self.jp('ok'):
            rid, nm, ds, col = u['opts'][u['sel']]
            p = self.player
            m = self.map
            pr = u['pr']
            p.relics.append(rid)
            if rid == 'heart':
                p.hp = min(p.max_hp, p.hp + 25)
            pr.data['used'] = True
            pr.frames = [prop_shrine(pr.data['col'], False)]
            m.lights = [l for l in m.lights if not (l[0] == pr.x and l[1] == pr.y - 8)]
            self.audio.play('trophy')
            self.glow(pr.x, pr.y - 14, 80, col, 0.9)
            self.fx.burst(pr.x, pr.y - 14, 30, [col, WHITE], 90, 0.9, 1, -30, 2)
            self.toast("Relic: %s. %s" % (nm, ds), col, 4)
            self.stat('relics')
            self.state = 'play'

    def draw_relic(self, surf):
        u = self.relic_ui
        self.overlay.fill((6, 4, 14))
        self.overlay.set_alpha(185)
        surf.blit(self.overlay, (0, 0))
        n = len(u['opts'])
        cw = 70 if n >= 4 else 88
        gap = 6
        x0 = (W - (n * cw + (n - 1) * gap)) // 2
        big(surf, "CHOOSE A RELIC", W // 2, 14, GOLD, 1)
        for i, (rid, nm, ds, col) in enumerate(u['opts']):
            x = x0 + i * (cw + gap)
            sel = i == u['sel']
            y = 30 - (2 if sel else 0)
            panel(surf, x, y, cw, 106, None, (34, 26, 56) if sel else (22, 16, 38), col if sel else mul_c(col, 0.4))
            cx, cy = x + cw // 2, y + 22 + (int(math.sin(self.time * 4) * 1.5) if sel else 0)
            pygame.draw.polygon(surf, mul_c(col, 0.45), [(cx, cy - 11), (cx + 9, cy), (cx, cy + 11), (cx - 9, cy)])
            pygame.draw.polygon(surf, col, [(cx, cy - 9), (cx + 7, cy), (cx, cy + 9), (cx - 7, cy)])
            pygame.draw.polygon(surf, WHITE, [(cx, cy - 7), (cx + 2, cy - 3), (cx, cy), (cx - 3, cy - 3)])
            for k, ln in enumerate(self.wrap(nm, cw - 8)):
                txt(surf, ln, x + cw // 2, y + 40 + k * 9, col if sel else mul_c(col, 0.7), True, 'c')
            yy = y + 60
            for ln in self.wrap(ds, cw - 8):
                txt(surf, ln, x + cw // 2, yy, CREAM if sel else DIM, True, 'c')
                yy += 9
        txt(surf, "LEFT/RIGHT choose   ENTER take   ESC leave it", W // 2, 146, CREAM, True, 'c')
        p = self.player
        if p.relics:
            txt(surf, "Carrying: " + ", ".join(RELIC_BY[r][1] for r in p.relics), W // 2, 160, DIM, True, 'c')

    def wrap(self, s, w):
        out, cur = [], ""
        for word in s.split():
            t = (cur + " " + word).strip()
            if FONT.width(t) <= w:
                cur = t
            else:
                out.append(cur)
                cur = word
        if cur:
            out.append(cur)
        return out

    def check_perfect(self):
        """Dashing through a telegraphed attack at the last instant: slow-mo, a free dash and a damage window."""
        p = self.player
        if p.perfect_cd > 0:
            return
        hit = False
        for e in self.map.enemies:
            if e.dead:
                continue
            cx, cy = e.center()
            dd = dist(cx, cy, p.x, p.y - 6)
            if e.kind == 'boss':
                if e.state in ('charge', 'slam') and dd < 34:
                    hit = True
            elif e.state in ('attack', 'pounce', 'slam', 'hop') and dd < 19:
                hit = True
        for pr in self.projs:
            if not pr.friendly and dist(pr.x, pr.y, p.x, p.y - 6) < 13:
                hit = True
        if not hit:
            return
        p.perfect_cd = 1.4
        p.focus_t = 3.5
        p.dash_cd = 0.0
        p.inv_t = max(p.inv_t, 0.5)
        p.mp = min(p.max_mp, p.mp + 2)
        self.slow_t = 0.75
        self.flash = [(190, 225, 255), 0.3, 0.3, 100]
        self.audio.play('crit', 0.8)
        self.audio.play('levelup', 0.35)
        self.fx.text(p.x, p.y - 32, "PERFECT!", (170, 230, 255), 1.1, True)
        for i in range(16):
            a = i / 16 * math.tau
            self.fx.add(p.x + math.cos(a) * 6, p.y - 8 + math.sin(a) * 6, math.cos(a) * 80, math.sin(a) * 80, 0.35,
                        (170, 230, 255), 1, 0, 3)
        self.stat('perfects')

    def use_shrine(self, pr):
        d = pr.data
        p = self.player
        m = self.map
        if d['used']:
            self.toast("The shrine's power is spent.", GREY)
            self.audio.play('error', 0.5)
            return
        kind = d['kind']
        col, nm, ds = SHRINES[kind]
        if kind == 'relic':
            return self.open_relic(pr)
        ef = max(1.0, float(m.ef))
        if kind == 'might':
            p.power_t = 75.0
        elif kind == 'fortune':
            p.fortune_t = 120.0
        elif kind == 'life':
            p.hp, p.mp, p.ghost = p.max_hp, p.max_mp, 1.0
        elif kind == 'stone':
            p.stone_t = 150.0
        elif kind == 'blood':
            cost = int(p.hp * 0.35)
            if p.hp - cost < 8:
                self.toast("You are too weak to pay the blood price.", (255, 140, 160))
                self.audio.play('error', 0.5)
                return
            p.hp -= cost
            self.fx.text(p.x, p.y - 22, "-%d" % cost, (255, 110, 110), 0.9, False)
            tot = int(70 * ef)
            for _ in range(7):
                self.drop(pr.x, pr.y - 12, 'coin', max(1, tot // 7))
            self.give_xp(int(30 * ef))
        d['used'] = True
        pr.frames = [prop_shrine(col, False)]
        m.lights = [l for l in m.lights if not (l[0] == pr.x and l[1] == pr.y - 8)]
        self.audio.play('shrine')
        self.glow(pr.x, pr.y - 14, 70, col, 0.8)
        self.fx.burst(pr.x, pr.y - 14, 24, [col, WHITE], 80, 0.8, 1, -30, 2)
        self.toast("%s: %s" % (nm, ds), col, 3.5)
        self.stat('shrines')

    def open_chest(self, c):
        c.opened = True
        c.open_t = 0.0
        self.stat('chests')
        self.bounty_event('chest')
        self.audio.play('chest')
        self.glow(c.x, c.y - 8, 50, (255, 230, 140), 0.6)
        self.fx.burst(c.x, c.y - 10, 20, [GOLD, WHITE, (255, 240, 160)], 70, 0.8, 2, 60, 2)
        for kind, val in c.loot:
            if kind == 'gold':
                n = max(3, val // 8)
                for i in range(n):
                    self.drop(c.x, c.y - 6, 'coin', max(1, val // n))
            else:
                for _ in range(val):
                    self.drop(c.x, c.y - 6, 'item', kind)

    def talk(self, n):
        fn = getattr(self, 'talk_' + n.dlg, None)
        if fn:
            fn(n)

    def line(self, n, pages, on_end=None, choices=None):
        self.say(n.name, n.pal, pages, on_end, choices, n.pitch)

    def talk_elder(self, n):
        p = self.player
        if p.flags and 'boss_dead' in p.flags and 'elder_won' not in p.flags:
            p.flags.add('elder_won')
            self.line(n, ["You... you did it?! The Hollow King is no more!",
                          "Emberfall will sing of this for a thousand years. Thank you, hero.",
                          "The depths still hold treasure and monsters, should you ever crave more adventure.",
                          "And the Waygate under the northern arch has awakened. Eight more realms call to you, hero."])
            return
        for q in QUESTS:
            qs = p.q.get(q['id'])
            if qs and qs['state'] == 'done':
                continue
            if not qs:
                def accept(q=q):
                    p.q[q['id']] = dict(state='active', prog=0)
                    self.audio.play('unlock')
                    self.toast("Quest accepted: %s" % q['name'], GOLD, 3.5)
                    if q['kind'] == 'bring' and p.inv.get(q['item'], 0) >= q['n']:
                        p.q[q['id']]['state'] = 'ready'
                self.line(n, [q['give']], choices=[("I'll do it.", accept), ("Maybe later.", None)])
                return
            if qs['state'] == 'active' and q['kind'] == 'bring' and p.inv.get(q['item'], 0) >= q['n']:
                qs['state'] = 'ready'
            if qs['state'] == 'ready':
                def reward(q=q, qs=qs):
                    if q['kind'] == 'bring':
                        p.inv[q['item']] -= q['n']
                    qs['state'] = 'done'
                    p.gold += q['gold']
                    self.audio.play('buy')
                    self.toast("Quest complete!  +%dg  +%dxp" % (q['gold'], q['xp']), GOLD, 4)
                    self.give_xp(q['xp'])
                self.line(n, ["Splendid work! Here is your reward: %d gold." % q['gold']], on_end=reward)
                return
            have = p.inv.get(q['item'], 0) if q['kind'] == 'bring' else qs['prog']
            self.line(n, [q['prog'] % (min(have, q['n']), q['n'])])
            return
        if 'boss_dead' in p.flags:
            self.line(n, ["Rest well, hero. Emberfall is safe."])
        else:
            self.line(n, ["You've done every task I had. Only one remains: end the Hollow King on the floor below the Ember Depths.",
                          "Spells? Learn them by felling bosses, or study tomes at the Alchemy Cauldron on the plaza."])

    def talk_guard(self, n):
        p = self.player
        unlocked = 'boss_dead' in p.flags
        tips = ["Stay sharp in there. Time your attacks: three quick swings make a powerful finisher.",
                "Skeleton archers? Dash through their arrows, or strike the arrows back with your sword!",
                "Wraiths phase in and out. Hit them when they glow bright.",
                "Golems hit like a landslide. Stay out of reach when they raise their arms.",
                "Elite monsters glow with a colored outline. Kill them for rich loot.",
                "Shrines in the dungeon grant mighty boons. Use them wisely!",
                "The Waygate opens other realms once you've bested the Hollow King. Every one has a boss.",
                "Salvage everything. The Workbench and Cauldron on the plaza turn monster parts into magic.",
                "Press 1 to 4 to cast spells. V and B change your selection. G throws a gadget."]
        if unlocked:
            tips.append("A legend walks among us! I'll polish your boots for free.")
        else:
            tips.append("The Hollow King lies past the Ember Depths. Bring potions. Lots of potions.")

        def chat():
            self.line(n, [random.choice(tips)])

        def abyss():
            if not unlocked:
                self.line(n, ["The Abyss? Old tales, friend. They say a pit opens when the Hollow King falls. Come back when he has."])
            else:
                self.abyss_menu(n)
        self.line(n, ["Halt, adventurer! The Guild keeps a bounty board here. Need work, or the Abyss?"],
                  choices=[("Bounty board", lambda: self.bounty_board(n)),
                           ("The Abyss" if unlocked else "The Abyss (?)", abyss),
                           ("Daily Rift" if unlocked else "Daily Rift (?)", lambda: self.rift_menu(n)),
                           ("Just chatting", chat)])

    def refill_bounties(self):
        p = self.player
        while len(p.bounties) < 3:
            p.bounties.append(make_bounty(p.rank, p.abyss_best, 'boss_dead' in p.flags,
                                          [b['label'] for b in p.bounties]))

    def bounty_board(self, n):
        p = self.player
        done = [b for b in p.bounties if b['done']]
        if done:
            gsum, rsum, xsum = sum(b['gold'] for b in done), sum(b['rep'] for b in done), sum(b['xp'] for b in done)

            def pay():
                old = p.rank
                p.gold += gsum
                p.rep += rsum
                p.bounties = [b for b in p.bounties if not b['done']]
                self.stat('gold_earned', gsum)
                self.stat('bounties', len(done))
                self.audio.play('buy')
                self.give_xp(xsum)
                self.toast("Bounty paid: +%dg  +%d rep" % (gsum, rsum), GOLD, 3.5)
                self.refill_bounties()
            self.line(n, ["Contracts fulfilled! The Guild pays %d gold and awards %d reputation." % (gsum, rsum)], on_end=pay)
            return
        self.refill_bounties()
        nxt = RANKS[p.rank + 1][1] if p.rank + 1 < len(RANKS) else None
        pages = ["Guild rank: %s.%s" % (RANKS[p.rank][0], (" %d reputation to %s." % (nxt - p.rep, RANKS[p.rank + 1][0])) if nxt else " You stand at the very top!")]
        for b in p.bounties:
            pages.append("%s  (%d/%d)   Reward: %dg and %d rep." % (b['name'], b['prog'], b['n'], b['gold'], b['rep']))
        pages.append("Finish a contract, then speak to me to collect. Higher ranks unlock the finest gear at Brann's forge.")
        self.line(n, pages)

    def rift_menu(self, n):
        p = self.player
        if 'boss_dead' not in p.flags:
            self.line(n, ["The Rift only tears open for those who have felled the Hollow King."])
            return
        rift = rift_today()
        best = p.st.get('rift_%d' % rift[0], 0)
        txt_ = "Today's Rift: %s (%s) and %s (%s)." % (rift[1][0][0], rift[1][0][1], rift[1][1][0], rift[1][1][1])
        self.line(n, [txt_, "Same floors for everyone today. Reach depth 3, 6 and 10 for one-time rewards. Your best today: %d." % best],
                  choices=[("Enter the Rift", lambda: self.enter_abyss(1, rift)), ("Not now", None)])

    def abyss_menu(self, n):
        p = self.player
        cp = (p.abyss_best // 5) * 5
        ch = [("Descend from depth 1", lambda: self.enter_abyss(1))]
        if cp >= 5:
            ch.append(("Checkpoint: depth %d" % cp, lambda: self.enter_abyss(cp)))
        ch.append(("Not now", None))
        self.line(n, ["The Abyss: a bottomless descent. Each floor is deadlier, and richer, than the last. Your deepest: depth %d." % p.abyss_best,
                      "Beacons let you return home. Every fifth floor is guarded by a Warden. Checkpoints unlock every 5 floors."],
                  choices=ch)

    def talk_child(self, n):
        self.line(n, [random.choice(["I'm gonna be a hero when I grow up! Like you!",
                                     "Tessa says rats in the crypt are as big as dogs. Nuh-uh!",
                                     "I found a shiny rock! ...it's just a rock.",
                                     "Tag! You're it! ...oh, you're busy. Okay."])])

    def talk_woman(self, n):
        self.line(n, [random.choice(["Fresh apples! Not that you'd have time for apples.",
                                     "My husband went into the crypt years ago for a 'quick look'. Still waiting.",
                                     "Nice weather. Except at night. Then the fireflies come out, and it's lovely."])])

    def talk_fisher(self, n):
        p = self.player

        def go():
            self.start_fishing()

        def chat():
            self.line(n, [random.choice(["Shh, you'll scare the fish. ...Not that they bite anyway.",
                                         "Once caught a gem in this pond. Never caught anything else.",
                                         "Golden koi are rare, and Pip pays a fortune for them.",
                                         "Wait for the bobber to dip, then reel when the bar crosses the green."])])
        ch = [("Go fishing", go)]
        if p.rod < len(RODS) - 1:
            nm, cost = RODS[p.rod + 1]

            def up():
                if p.gold < cost:
                    self.audio.play('error')
                    self.line(n, ["The %s costs %dg. Come back when you've got the coin." % (nm, cost)])
                    return
                p.gold -= cost
                p.rod += 1
                self.audio.play('buy')
                self.line(n, ["A fine %s! Better bites, and a wider sweet spot on the reel." % nm])
            ch.append(("Buy %s (%dg)" % (nm, cost), up))
        ch.append(("Just chatting", chat))
        self.line(n, ["Care to wet a line? I'll lend you the best spot on the pond. Your rod: %s." % RODS[p.rod][0]], choices=ch)

    def start_fishing(self):
        self.state = 'fish'
        self.fish = dict(phase='ready', t=0.0, anim=0.0, wait=2.0, key=None, pos=0.0, dir=1, zone=0.5, zw=0.25,
                         spd=1.0, msg="", col=WHITE, caught=0)

    FISH_DIFF = {'minnow': (0.32, 0.9), 'carp': (0.26, 1.1), 'trout': (0.2, 1.3), 'koi': (0.12, 1.8),
                 'pearl': (0.16, 1.3), 'boot': (0.34, 0.8)}

    def pick_fish(self):
        r = self.player.rod + (1 if self.has_proj('pier') else 0)
        w = [('minnow', 40), ('carp', 26 + 4 * r), ('trout', 14 + 6 * r), ('koi', 1 + 2 * r),
             ('pearl', 2 + 2 * r), ('boot', max(2, 8 - 2 * r))]
        tot = sum(x[1] for x in w)
        v = random.uniform(0, tot)
        for k, ww in w:
            v -= ww
            if v <= 0:
                return k
        return 'minnow'

    def update_fish(self, dt):
        f = self.fish
        p = self.player
        f['t'] += dt
        f['anim'] += dt
        ph = f['phase']
        if self.jp('back') or self.jp('pause'):
            self.audio.play('back')
            if ph in ('ready', 'result'):
                self.fish = None
                self.state = 'play'
                return
            f['phase'] = 'ready'
            f['t'] = 0
            return
        ok = self.jp('ok')

        def result(msg, col, snd='error'):
            f['phase'] = 'result'
            f['msg'] = msg
            f['col'] = col
            f['t'] = 0
            self.audio.play(snd, 0.6)
        if ph == 'ready':
            if ok:
                f['phase'] = 'cast'
                f['t'] = 0
                self.audio.play('swing', 0.6)
        elif ph == 'cast':
            if f['t'] > 0.6:
                f['phase'] = 'wait'
                f['t'] = 0
                f['wait'] = random.uniform(1.4, 4.2)
                self.audio.play('splash', 0.7)
        elif ph == 'wait':
            if ok:
                result("Too early! The fish got away.", RED)
            elif f['t'] > f['wait']:
                f['phase'] = 'bite'
                f['t'] = 0
                f['key'] = self.pick_fish()
                self.audio.play('fish_bite')
        elif ph == 'bite':
            if ok:
                zw, spd = self.FISH_DIFF[f['key']]
                f['phase'] = 'reel'
                f['t'] = 0
                f['zw'] = zw + 0.03 * p.rod
                f['spd'] = spd
                f['zone'] = random.uniform(0.25, 0.75)
                f['pos'] = 0.0
                f['dir'] = 1
                self.audio.play('select')
            elif f['t'] > 0.9:
                result("It slipped off the hook...", (255, 170, 140))
        elif ph == 'reel':
            f['pos'] += f['dir'] * f['spd'] * dt
            if f['pos'] >= 1:
                f['pos'], f['dir'] = 1.0, -1
            elif f['pos'] <= 0:
                f['pos'], f['dir'] = 0.0, 1
            if ok:
                if abs(f['pos'] - f['zone']) <= f['zw'] / 2:
                    k = f['key']
                    p.inv[k] = p.inv.get(k, 0) + 1
                    nm = LOOT[k][0]
                    if k != 'boot':
                        self.stat('fish')
                        self.bounty_event('fish')
                        f['caught'] += 1
                        self.give_xp(3 + LOOT[k][1] // 8)
                    result("Caught: %s!  (%dg)" % (nm, LOOT[k][1]), GOLD if k in ('koi', 'pearl') else GREEN, 'coin')
                    if k in ('koi', 'pearl'):
                        self.audio.play('trophy', 0.6)
                else:
                    result("Missed! The line goes slack.", (255, 170, 140))
            elif f['t'] > 5:
                result("The fish tired of waiting.", (255, 170, 140))
        elif ph == 'result':
            if ok and f['t'] > 0.35:
                f['phase'] = 'ready'
                f['t'] = 0

    def draw_fish(self, surf):
        f = self.fish
        p = self.player
        if not f:
            return
        dim = self.overlay
        dim.fill((6, 8, 20))
        dim.set_alpha(170)
        surf.blit(dim, (0, 0))
        panel(surf, 30, 12, 260, 156, "FISHING  -  %s" % RODS[p.rod][0].upper())
        wx, wy, ww, wh = 40, 30, 240, 66
        pygame.draw.rect(surf, (96, 150, 210), (wx, wy, ww, 14))
        surf.fill((120, 176, 228), (wx, wy + 8, ww, 6))
        for i in range(0, ww, 3):
            col = (46, 104, 170) if (i // 3) % 2 else (54, 116, 184)
            surf.fill(col, (wx + i, wy + 14, 3, wh - 14))
        t = f['anim']
        for i in range(9):
            yy = wy + 18 + i * 5
            ox = int(math.sin(t * 1.5 + i) * 4)
            surf.fill((130, 190, 240), (wx + 12 + (i * 37) % (ww - 40) + ox, yy, 8, 1))
        # dock + rod
        surf.fill((120, 82, 50), (wx, wy + 8, 36, 4))
        surf.fill((90, 60, 38), (wx + 4, wy + 12, 3, 12))
        surf.fill((90, 60, 38), (wx + 26, wy + 12, 3, 12))
        pygame.draw.line(surf, (190, 150, 90), (wx + 20, wy + 7), (wx + 46, wy - 10), 1)
        ph = f['phase']
        bx, by = wx + 150, wy + 36
        bob = math.sin(t * 3) * 1.2
        if ph == 'cast':
            k = f['t'] / 0.6
            bx = wx + 46 + (150 - 46) * k
            by = wy - 10 + (36 + 10) * k - math.sin(k * math.pi) * 18
        elif ph == 'bite':
            bob = math.sin(t * 40) * 2 + 3
        elif ph == 'reel':
            bob = math.sin(t * 25) * 2 + 2
        if ph != 'ready':
            pygame.draw.line(surf, (230, 230, 230), (wx + 46, wy - 10), (int(bx), int(by + bob)), 1)
            surf.fill((240, 70, 70), (int(bx) - 1, int(by + bob) - 2, 3, 2))
            surf.fill(WHITE, (int(bx) - 1, int(by + bob), 3, 2))
            if ph in ('wait', 'bite', 'reel'):
                for r_ in (3, 6):
                    pygame.draw.circle(surf, (170, 210, 245), (int(bx), int(by + 2)), r_ + int(t * 4) % 3, 1)
        if ph == 'bite':
            big(surf, "!", int(bx), int(by) - 24, (255, 230, 80), 2)
        # status
        cx = 160
        msgs = {'ready': "Press ENTER to cast", 'cast': "...", 'wait': "Wait for a bite...",
                'bite': "A BITE!  Press ENTER!", 'reel': "Press ENTER in the green zone!"}
        if ph == 'result':
            txt(surf, f['msg'], cx, 104, f['col'], True, 'c', outline=True)
            txt(surf, "ENTER: cast again", cx, 116, DIM, True, 'c')
        else:
            txt(surf, msgs[ph], cx, 104, CREAM, True, 'c', outline=True)
        # reel bar
        if ph == 'reel':
            x0, y0, bw = 60, 124, 200
            surf.fill((30, 24, 50), (x0 - 1, y0 - 1, bw + 2, 12))
            surf.fill((70, 40, 50), (x0, y0, bw, 10))
            zx = int(x0 + (f['zone'] - f['zw'] / 2) * bw)
            surf.fill((80, 220, 110), (zx, y0, max(3, int(f['zw'] * bw)), 10))
            mx = int(x0 + f['pos'] * bw)
            surf.fill(WHITE, (mx - 1, y0 - 3, 3, 16))
        txt(surf, "Fish caught this session: %d      ESC: stop" % f['caught'], cx, 152, DIM, True, 'c')

    def talk_smith(self, n):
        self.line(n, [random.choice(["Welcome to the smithy! Steel and sweat, that's my trade.",
                                     "Back for more? Good. A sharp blade is a long life.",
                                     "Bring me Iron Ore and gold, and I'll sharpen any blade."])],
                  on_end=lambda: self.open_shop('smith', n))

    def talk_alch(self, n):
        self.line(n, [random.choice(["Potions, tonics, a dab of eye of newt! What'll it be, dear?",
                                     "Careful with the green ones. Joking! ...Mostly.",
                                     "Everything here is brewed fresh. Some of it is even legal."])],
                  on_end=lambda: self.open_shop('alch', n))

    def talk_general(self, n):
        self.line(n, [random.choice(["Pip's General Goods! I buy loot, I sell luck. Everybody wins!",
                                     "Got bones? Gel? Gems? Pip pays top coin!",
                                     "Charms, trinkets and treasures. Take a look!"])],
                  on_end=lambda: self.open_shop('general', n))

    def talk_inn(self, n):
        p = self.player

        def rest():
            if p.gold < 10:
                self.audio.play('error')
                self.toast("Not enough gold (10g).", RED)
                return
            p.gold -= 10

            def done():
                p.hp, p.mp = p.max_hp, p.max_mp
                p.ghost = 1.0
                self.save_game(quiet=True)
                self.audio.play('save')
                self.toast("Rested and saved. HP/MP restored.", GREEN, 3)
                if self.has_proj('suites'):
                    p.meal_id, p.meal_t = 'm_feast', 240.0
                    self.toast("The suite's breakfast: Hero's Feast!", GOLD, 3.5)
            self.start_trans(done, 1.6)
        self.line(n, ["Welcome to the Sleeping Dragon. A bed and a hot meal is 10 gold, and I'll record your deeds in the ledger (that's saving)."],
                  choices=[("Rest (10g)", rest), ("Just saving, thanks", lambda: (self.save_game(), None)[1]), ("Leave", None)])

    # ---- shops ----------------------------------------------------------
    def open_shop(self, which, npc):
        self.state = 'shop'
        self.shop = dict(id=which, tab=0, sel=0, top=0, msg='', msg_t=0.0, npc=npc, mcol=GREEN)
        self.audio.play('menu')

    def shop_tabs(self):
        return {'smith': ["BUY", "FORGE"], 'alch': ["POTIONS"], 'general': ["BUY", "SELL"], 'inn': ["ROOM"]}[
            self.shop['id']]

    def shop_items(self):
        p = self.player
        sid, tab = self.shop['id'], self.shop['tab']
        L = []

        def msg(s_, col=GREEN):
            self.shop['msg'], self.shop['mcol'], self.shop['msg_t'] = s_, col, 2.2

        def mats_ok(mm):
            return all(p.inv.get(k, 0) >= v for k, v in mm.items())

        def mats_txt(mm):
            return ", ".join("%d %s (have %d)" % (v, LOOT[k][0], p.inv.get(k, 0)) for k, v in mm.items())
        if sid == 'smith' and tab == 0:
            for kind, tbl, key_, cur in (('weapon', WEAPONS, 'w', p.wt), ('armor', ARMORS, 'a', p.at)):
                for i in range(1, 7):
                    nm, val, price, desc = tbl[i]
                    price = int(price * MODS.get('price', 1.0))
                    owned = cur >= i
                    need = GEAR_RANK.get((key_, i), 0)
                    locked = p.rank < need
                    mm = MATS.get((key_, i), {})

                    def buy(i=i, price=price, nm=nm, mm=mm, key_=key_):
                        p.gold -= price
                        for k, v in mm.items():
                            p.inv[k] -= v
                        if key_ == 'w':
                            p.wt, p.wplus = i, 0
                        else:
                            p.at, p.aplus = i, 0
                        self.audio.play('buy')
                        self.check_trophies()
                        msg("Bought %s!" % nm)
                    if kind == 'weapon':
                        stat = "ATK  %d  >  %d" % (WEAPONS[p.wt][1] + 2 * p.wplus, val)
                        sub = "ATK %d" % val
                    else:
                        stat = "DEF  %d  >  %d" % (ARMORS[p.at][1] + p.aplus, val)
                        sub = "DEF %d" % val
                    if locked:
                        sub = "Needs %s rank" % RANKS[need][0]
                    d2 = desc + (("  Needs: " + mats_txt(mm)) if mm and not owned else "")
                    L.append(dict(name=nm, ic=('sword%d' if kind == 'weapon' else 'armor%d') % i, price=price, sub=sub,
                                  desc=d2, stat=stat, owned=owned, locked=locked,
                                  ok=(not owned and not locked and p.gold >= price and mats_ok(mm)), do=buy,
                                  kind=kind, tier=i))
        elif sid == 'smith':
            n = p.wplus
            gold_c, ore_c = 70 * (n + 1), n + 1
            have = p.inv.get('ore', 0)

            def sharpen():
                p.gold -= gold_c
                p.inv['ore'] -= ore_c
                p.wplus += 1
                self.audio.play('buy')
                self.audio.play('hit', 0.8)
                msg("%s is now +%d!" % (WEAPONS[p.wt][0], p.wplus))
            L.append(dict(name="Sharpen Weapon", ic='sword%d' % p.wt, price=gold_c,
                          sub="+%d  needs %d ore" % (n + 1, ore_c), tier=p.wt, kind='weapon',
                          desc="Hone your blade for +2 ATK. Needs Iron Ore. You have %d." % have,
                          stat="ATK  %d  >  %d" % (WEAPONS[p.wt][1] + 2 * n, WEAPONS[p.wt][1] + 2 * n + 2),
                          owned=(n >= 10), ok=(n < 10 and p.gold >= gold_c and have >= ore_c), do=sharpen,
                          maxed=(n >= 10)))
            n2 = p.aplus
            gold2, ore2 = 60 * (n2 + 1), n2 + 1

            def reinforce():
                p.gold -= gold2
                p.inv['ore'] -= ore2
                p.aplus += 1
                self.audio.play('buy')
                self.audio.play('hit', 0.8)
                msg("%s is now +%d!" % (ARMORS[p.at][0], p.aplus))
            L.append(dict(name="Reinforce Armor", ic='armor%d' % p.at, price=gold2,
                          sub="+%d  needs %d ore" % (n2 + 1, ore2), tier=p.at, kind='armor',
                          desc="Add plating for +1 DEF. Needs Iron Ore. You have %d." % have,
                          stat="DEF  %d  >  %d" % (ARMORS[p.at][1] + n2, ARMORS[p.at][1] + n2 + 1),
                          owned=(n2 >= 10), ok=(n2 < 10 and p.gold >= gold2 and have >= ore2), do=reinforce,
                          maxed=(n2 >= 10)))
        elif sid == 'alch':
            defs = [('hp_potion', "Health Potion", 25, "Restores 50 HP.   [Q]"),
                    ('mp_potion', "Mana Potion", 25, "Restores 18 MP.   [R]"),
                    ('elixir', "Elixir of Might", 70, "+50% attack for 50 seconds.   [F]"),
                    ('big_hp', "Greater Health Potion", 80, "Restores 130 HP. Use from the menu."),
                    ('big_mp', "Greater Mana Potion", 75, "Restores 50 MP. Use from the menu."),
                    ('fortune', "Fortune Draught", 130, "+50% gold for 2 minutes. Use from the menu."),
                    ('stoneskin', "Stoneskin Tonic", 110, "+4 defense for 2 minutes. Use from the menu."),
                    ('tonic', "Heart Tonic", 220, "Permanently +10 max HP. (Max 3)")]
            for key, nm, price, desc in defs:
                if key == 'tonic':
                    left = 3 - p.tonics

                    def buy(price=price):
                        p.gold -= price
                        p.tonics += 1
                        p.hp += 10
                        self.audio.play('buy')
                        msg("Max HP up!")
                    L.append(dict(name=nm, ic='tonic', price=price, sub="%d left" % left, desc=desc,
                                  stat="Max HP  %d  >  %d" % (p.max_hp, p.max_hp + 10), owned=(left <= 0),
                                  ok=(left > 0 and p.gold >= price), do=buy, maxed=(left <= 0)))
                else:
                    def buy(key=key, price=price, nm=nm):
                        p.gold -= price
                        p.inv[key] = p.inv.get(key, 0) + 1
                        self.audio.play('buy')
                        msg("Bought %s." % nm)
                    L.append(dict(name=nm, ic=key, price=price, sub="You have %d" % p.inv.get(key, 0), desc=desc,
                                  stat="", owned=False, ok=(p.gold >= price and p.inv.get(key, 0) < 20), do=buy))
        elif sid == 'general' and tab == 0:
            for key, (nm, price, desc) in CHARMS.items():
                owned = key in p.charms

                def buy(key=key, price=price, nm=nm):
                    p.gold -= price
                    p.charms.add(key)
                    self.check_trophies()
                    self.audio.play('buy')
                    msg("Bought %s!" % nm)
                L.append(dict(name=nm, ic=key, price=price, sub="Owned" if owned else "Charm", desc=desc,
                              stat="Passive effect", owned=owned, ok=(not owned and p.gold >= price), do=buy))
            for key, nm, price, desc in (('hp_potion', "Health Potion", 30, "Restores 50 HP.   [Q]"),
                                         ('mp_potion', "Mana Potion", 30, "Restores 18 MP.   [R]")):
                def buy(key=key, price=price, nm=nm):
                    p.gold -= price
                    p.inv[key] = p.inv.get(key, 0) + 1
                    self.audio.play('buy')
                    msg("Bought %s." % nm)
                L.append(dict(name=nm, ic=key, price=price, sub="You have %d" % p.inv.get(key, 0), desc=desc,
                              stat="", owned=False, ok=(p.gold >= price and p.inv.get(key, 0) < 20), do=buy))
        elif sid == 'general':
            tot = 0
            for key, (nm, val) in LOOT.items():
                if key not in KEEP_LOOT:
                    tot += val * p.inv.get(key, 0)

            def sell_all():
                n = 0
                for key, (nm, val) in LOOT.items():
                    if key not in KEEP_LOOT and p.inv.get(key, 0) > 0:
                        n += val * p.inv[key]
                        p.inv[key] = 0
                if n:
                    p.gold += n
                    self.audio.play('coin')
                    self.audio.play('buy')
                    msg("Sold loot for %dg." % n, GOLD)
            L.append(dict(name="Sell All Loot", ic='coin', price=None, sub="+%dg" % tot,
                          desc="Sells everything except smithing materials (ore, cores, silk, ember).", stat="", owned=False,
                          ok=(tot > 0), do=sell_all, sell=True))
            for key, (nm, val) in LOOT.items():
                cnt = p.inv.get(key, 0)

                def sell(key=key, val=val, nm=nm):
                    p.inv[key] -= 1
                    p.gold += val
                    self.audio.play('coin')
                    msg("Sold %s for %dg." % (nm, val), GOLD)
                L.append(dict(name=nm, ic=key, price=None, sub="x%d   %dg each" % (cnt, val),
                              desc="Pip pays %dg for each." % val, stat="", owned=False, ok=(cnt > 0), do=sell,
                              sell=True, dim=(cnt <= 0)))
        return L

    def shop_update(self):
        sh = self.shop
        sh['msg_t'] = max(0, sh['msg_t'] - 1 / 60)
        L = self.shop_items()
        sh['sel'] = clamp(sh['sel'], 0, max(0, len(L) - 1))
        if self.jp('up') and L:
            sh['sel'] = (sh['sel'] - 1) % len(L)
            self.audio.play('menu')
        if self.jp('down') and L:
            sh['sel'] = (sh['sel'] + 1) % len(L)
            self.audio.play('menu')
        tabs = self.shop_tabs()
        if len(tabs) > 1 and (self.jp('left') or self.jp('right')):
            sh['tab'] = (sh['tab'] + (1 if self.jp('right') else -1)) % len(tabs)
            sh['sel'] = 0
            sh['top'] = 0
            self.audio.play('select')
        if sh['sel'] < sh['top']:
            sh['top'] = sh['sel']
        if sh['sel'] >= sh['top'] + 6:
            sh['top'] = sh['sel'] - 5
        if self.jp('ok') and L:
            it = L[sh['sel']]
            if it['ok']:
                it['do']()
            else:
                self.audio.play('error')
                if it.get('maxed') or (it.get('owned') and not it.get('sell')):
                    sh['msg'], sh['mcol'], sh['msg_t'] = ("Already maxed." if it.get('maxed') else "You already own that."), GREY, 1.6
                elif it.get('locked'):
                    sh['msg'], sh['mcol'], sh['msg_t'] = "Your guild rank is too low.", RED, 1.6
                elif it.get('sell'):
                    sh['msg'], sh['mcol'], sh['msg_t'] = "Nothing to sell.", GREY, 1.6
                elif self.player.gold < (it.get('price') or 0):
                    sh['msg'], sh['mcol'], sh['msg_t'] = "Not enough gold.", RED, 1.6
                else:
                    sh['msg'], sh['mcol'], sh['msg_t'] = "You are missing materials.", RED, 1.6
        elif self.jp('back') or self.jp('pause'):
            self.audio.play('back')
            npc = sh['npc']
            self.shop = None
            self.state = 'dialog'
            self.say(npc.name, npc.pal, [random.choice(["Come back soon!", "Safe travels, adventurer.",
                                                        "May your blade stay sharp.", "Mind the dark down there."])],
                     pitch=npc.pitch)

    # ---- menus ------------------------------------------------------------
    def open_menu(self, tab=0):
        self.state = 'menu'
        self.menu_tab = tab
        self.menu_sel = 0
        self.audio.play('menu')

    MENU_ITEMS = ['hp_potion', 'big_hp', 'mp_potion', 'big_mp', 'elixir', 'fortune', 'stoneskin']
    def menu_items(self):
        return list(self.MENU_ITEMS) + [k for k in CONSUMABLE_EXTRAS if self.player.inv.get(k, 0) > 0]

    NTABS = 7
    TAB_ORDER = [0, 1, 2, 6, 3, 4, 5]

    def skill_cost(self, sid):
        return 3 if sid in ('whirl', 'nova') else 1

    def can_learn(self, sid):
        p = self.player
        s = SKILL_BY_ID[sid]
        if p.sk(sid) >= s[2] or p.sp < self.skill_cost(sid):
            return False
        return not s[4] or p.sk(s[4][0]) >= s[4][1]

    def respec_cost(self):
        return 25 * self.player.level

    def update_menu(self):
        p = self.player
        if self.jp('back') or self.jp('pause') or self.jp('inv'):
            self.state = 'play'
            self.audio.play('back')
            return
        slider = self.menu_tab == 5 and self.menu_sel in (0, 1)
        if self.jp('left') and not slider:
            o = self.TAB_ORDER
            self.menu_tab = o[(o.index(self.menu_tab) - 1) % len(o)]
            self.menu_sel = 0
            self.audio.play('menu')
        if self.jp('right') and not slider:
            o = self.TAB_ORDER
            self.menu_tab = o[(o.index(self.menu_tab) + 1) % len(o)]
            self.menu_sel = 0
            self.audio.play('menu')
        t = self.menu_tab

        def nav(n):
            if self.jp('up'):
                self.menu_sel = (self.menu_sel - 1) % n
                self.audio.play('menu')
            if self.jp('down'):
                self.menu_sel = (self.menu_sel + 1) % n
                self.audio.play('menu')
        if t == 1:
            nav(len(self.menu_items()))
            if self.jp('ok'):
                self.use_item(self.menu_items()[self.menu_sel])
        elif t == 2:
            nav(len(SKILLS))
            sid = SKILLS[self.menu_sel][0]
            if self.jp('ok'):
                if self.can_learn(sid):
                    p.sp -= self.skill_cost(sid)
                    p.skills[sid] = p.sk(sid) + 1
                    self.audio.play('unlock')
                    self.audio.play('levelup', 0.35)
                    self.fx.burst(p.x, p.y - 10, 14, [GOLD, WHITE], 60, 0.7, 1, -30, 2)
                else:
                    self.audio.play('error', 0.6)
            if self.jp('mp'):
                if self.map.kind not in ('village', 'interior'):
                    self.toast("Skills can only be reset in the village.", GREY)
                    self.audio.play('error')
                elif not p.skills:
                    self.audio.play('error')
                elif p.gold < self.respec_cost():
                    self.toast("Resetting costs %dg." % self.respec_cost(), RED)
                    self.audio.play('error')
                else:
                    p.gold -= self.respec_cost()
                    p.sp += sum(r * self.skill_cost(k) for k, r in p.skills.items())
                    p.skills = {}
                    p.hp = min(p.hp, p.max_hp)
                    p.mp = min(p.mp, p.max_mp)
                    self.audio.play('save')
                    self.toast("Skills reset. Points refunded.", GREEN)
        elif t == 6:
            self.update_spell_tab(nav)
        elif t == 4:
            nav(len(TROPHIES))
        elif t == 5:
            nav(5)
            d = (1 if self.jp('right') else 0) - (1 if self.jp('left') else 0)
            if self.menu_sel == 0 and d:
                self.audio.music_vol = clamp(self.audio.music_vol + 0.1 * d, 0, 1)
            if self.menu_sel == 1 and d:
                self.audio.sfx_vol = clamp(self.audio.sfx_vol + 0.1 * d, 0, 1)
                self.audio.play('select')
            if self.jp('ok'):
                if self.menu_sel == 2:
                    self.toggle_fullscreen()
                elif self.menu_sel == 3:
                    if self.map.kind == 'village' or self.map.kind == 'interior':
                        self.save_game()
                    else:
                        self.toast("You can only save in the village.", GREY)
                        self.audio.play('error')
                elif self.menu_sel == 4:
                    self.go_title()

    def go_title(self):
        def fn():
            self.state = 'title'
            self.title_sel = 0
            self.title_sub = None
            self.audio.music_play('title')
            self.has_save = os.path.exists(SAVE_PATH)
        self.start_trans(fn)

    def toggle_fullscreen(self):
        try:
            if self.fullscreen:
                self.screen = pygame.display.set_mode(self.win_size, pygame.RESIZABLE)
            else:
                self.win_size = self.screen.get_size()
                self.screen = pygame.display.set_mode((0, 0), pygame.FULLSCREEN)
            self.fullscreen = not self.fullscreen
        except Exception:
            pass

    # ---- main update --------------------------------------------------------
    def apply_virtual(self, now, prev, dt, hold):
        """Feed a set of held virtual keys into down/just; direction keys auto-repeat (for menus)."""
        for k in now - prev:
            self.down.add(k)
            self.just.add(k)
            hold[k] = 0.42
        for k in prev - now:
            self.down.discard(k)
            hold.pop(k, None)
        for k in now & prev:
            if k in self.rep_keys and k in hold:
                hold[k] -= dt
                if hold[k] <= 0:
                    hold[k] = 0.11
                    self.just.add(k)

    def pad_update(self, dt):
        now = self.pad.poll(dt)
        if now - self.pad_down:
            self.pad_active = True
            self.touch_on = False
        self.apply_virtual(now, self.pad_down, dt, self.pad_hold)
        self.pad_down = now
        if self.touch_on:
            tn = self.touch_poll()
            self.apply_virtual(tn, self.touch_down, dt, self.touch_hold)
            self.touch_down = tn
        elif self.touch_down:
            for k in self.touch_down:
                self.down.discard(k)
            self.touch_down = set()

    def update(self, dt):
        self.time += dt
        self.pad_update(dt)
        self.audio.update(dt)
        if self.jp('mute'):
            self.audio.muted = not self.audio.muted
            self.toast("Sound " + ("OFF" if self.audio.muted else "ON"), GREY, 1.2)
        if self.jp('full'):
            self.toggle_fullscreen()
        # transitions
        if self.trans:
            t = self.trans
            if t['phase'] == 'out':
                self.fade = min(1.0, self.fade + dt * t['speed'])
                if self.fade >= 1.0:
                    t['fn']()
                    t['phase'] = 'in'
            else:
                self.fade = max(0.0, self.fade - dt * t['speed'])
                if self.fade <= 0:
                    self.trans = None
        elif self.fade > 0 and self.state != 'title_boot':
            self.fade = max(0.0, self.fade - dt * 1.6)
        for tp in self.trophy_pop:
            tp[2] -= dt
        self.trophy_pop = [tp for tp in self.trophy_pop if tp[2] > 0]
        for t in self.toasts:
            t[2] -= dt
        self.toasts = [t for t in self.toasts if t[2] > 0]
        if self.banner:
            self.banner[1] += dt
            if self.banner[1] > 3.0:
                self.banner = None
                self.banner_gold = False
        if self.flash:
            self.flash[1] -= dt
            if self.flash[1] <= 0:
                self.flash = None
        for g_ in self.glows:
            g_[4] -= dt
        self.glows = [g_ for g_ in self.glows if g_[4] > 0]
        self.shake_a = max(0, self.shake_a - 14 * dt)
        if self.slow_t > 0:
            self.slow_t = max(0.0, self.slow_t - dt)
            dt *= 0.35
        st = self.state
        if self.trans and self.trans['phase'] == 'out' and st == 'play':
            self.fx.update(dt)
            return
        if st == 'title':
            self.update_title(dt)
        elif st == 'intro':
            self.update_intro(dt)
        elif st in ('play', 'bossintro', 'dying', 'bossdeath'):
            self.update_play(dt)
        elif st == 'dialog':
            self.update_dialog(dt)
            self.world_idle(dt)
        elif st == 'shop':
            self.shop_update()
            self.world_idle(dt)
        elif st == 'relic':
            self.update_relic(dt)
            self.world_idle(dt)
        elif st == 'gate':
            self.update_gate()
            self.world_idle(dt)
        elif st == 'craft':
            self.update_craft(dt)
            self.world_idle(dt)
        elif st == 'fish':
            self.update_fish(dt)
            self.world_idle(dt)
        elif st == 'menu':
            self.update_menu()
        elif st == 'pause':
            self.update_pause()
        elif st == 'gameover':
            self.update_gameover(dt)
        elif st == 'credits':
            self.update_credits(dt)
        self.just.clear()

    def world_idle(self, dt):
        self.time += 0
        self.fx.update(dt)
        if self.map:
            for n in self.map.npcs:
                n.t += dt

    # ---- title / intro ---------------------------------------------------------
    def title_items(self):
        it = []
        if self.has_save:
            it.append('Continue')
        it += ['New Game', 'Controls', 'Quit']
        return it

    def open_diff(self):
        self.title_sub = 'diff'
        self.diff_sel = getattr(self, 'new_diff', DEFAULT_DIFF)

    def update_title(self, dt):
        if self.title_sub == 'controls':
            if self.jp('left') or self.jp('right'):
                self.ctl_page = 1 - self.ctl_page
                self.audio.play('menu')
            elif self.jp('ok'):
                if self.ctl_page == 0:
                    self.ctl_page = 1
                    self.audio.play('select')
                else:
                    self.title_sub = None
                    self.audio.play('back')
            elif self.jp('back'):
                self.title_sub = None
                self.audio.play('back')
            return
        if self.title_sub == 'diff':
            if self.jp('up'):
                self.diff_sel = (self.diff_sel - 1) % len(DIFFS)
                self.audio.play('menu')
            elif self.jp('down'):
                self.diff_sel = (self.diff_sel + 1) % len(DIFFS)
                self.audio.play('menu')
            elif self.jp('back'):
                self.title_sub = None
                self.audio.play('back')
            elif self.jp('ok'):
                self.new_diff = self.diff_sel
                self.title_sub = None
                self.audio.play('select')
                self.start_trans(self.new_game)
            return
        if self.title_sub == 'confirm':
            if self.jp('back'):
                self.title_sub = None
                self.audio.play('back')
            elif self.jp('ok'):
                self.open_diff()
                self.audio.play('select')
            return
        items = self.title_items()
        if self.jp('up'):
            self.title_sel = (self.title_sel - 1) % len(items)
            self.audio.play('menu')
        if self.jp('down'):
            self.title_sel = (self.title_sel + 1) % len(items)
            self.audio.play('menu')
        for c in self.clouds:
            c[0] -= c[2] * dt
            if c[0] < -60:
                c[0] = W + 20
        if random.random() < 0.5:
            self.title_parts.append([random.uniform(0, W), H + 2, random.uniform(-6, 6), random.uniform(-30, -12),
                                     random.uniform(2, 5)])
        for p in self.title_parts:
            p[0] += p[2] * dt
            p[1] += p[3] * dt
            p[4] -= dt
        self.title_parts = [p for p in self.title_parts if p[4] > 0 and p[1] > 0]
        if self.jp('ok'):
            pick = items[self.title_sel]
            self.audio.play('select')
            if pick == 'Continue':
                self.start_trans(lambda: self.load_game())
            elif pick == 'New Game':
                if self.has_save:
                    self.title_sub = 'confirm'
                else:
                    self.open_diff()
            elif pick == 'Controls':
                self.title_sub = 'controls'
                self.ctl_page = 1 if self.pad_active else 0
            elif pick == 'Quit':
                self.quit = True

    INTRO = ["Long before Emberfall had a name, a king ruled the valley beneath the mountain.",
             "He feared death above all things, and bargained with the dark for more time.",
             "The dark kept its word. He never died.\nHe only hollowed, and the crypt of Hollowdeep swallowed his court.",
             "Now the old bargain frays. Bones stir.\nLanterns gutter. The village waits.",
             "You arrive at Emberfall at dusk, with a worn sword,\na few coins, and no good reason to be brave.",
             "Yet here you are."]

    def update_intro(self, dt):
        if self.intro_i >= len(self.INTRO):
            return
        self.intro_t += dt
        full = len(self.INTRO[self.intro_i].replace("\n", ""))
        if self.jp('ok'):
            if self.intro_t * 30 < full:
                self.intro_t = full / 30 + 0.01
            else:
                self.intro_i += 1
                self.intro_t = 0
                self.audio.play('menu')
                if self.intro_i >= len(self.INTRO):
                    self.start_trans(self.begin_village)
        elif self.jp('back') or self.jp('pause'):
            self.start_trans(self.begin_village)

    # ---- dialog -----------------------------------------------------------
    def update_dialog(self, dt):
        d = self.dlg
        page = d['pages'][d['i']]
        full = len(page)
        old = int(d['shown'])
        if d['shown'] < full:
            d['shown'] = min(full, d['shown'] + dt * 48)
            if int(d['shown']) // 2 != old // 2 and int(d['shown']) < full:
                ch = page[min(full - 1, int(d['shown']))]
                if ch != ' ':
                    self.audio.play('talk%d' % (1 + (int(d['shown']) // 2) % 3), 0.6 * d['pitch'] ** 0, 0.03)
        done = d['shown'] >= full
        last = d['i'] == len(d['pages']) - 1
        if done and last and d['choices']:
            if self.jp('up'):
                d['sel'] = (d['sel'] - 1) % len(d['choices'])
                self.audio.play('menu')
            if self.jp('down'):
                d['sel'] = (d['sel'] + 1) % len(d['choices'])
                self.audio.play('menu')
        if self.jp('ok'):
            if not done:
                d['shown'] = full
            elif not last:
                d['i'] += 1
                d['shown'] = 0
                self.audio.play('menu', 0.5)
            else:
                if d['choices']:
                    fn = d['choices'][d['sel']][1]
                    self.audio.play('select')
                    self.dlg = None
                    self.state = 'play'
                    if fn:
                        fn()
                else:
                    self.audio.play('back', 0.5)
                    self.end_dialog()

    # ---- gameover / credits ---------------------------------------------------
    def update_gameover(self, dt):
        self.over_t += dt
        self.fx.update(dt)
        if self.over_t > 1.5 and self.jp('ok'):
            p = self.player

            def fn():
                if is_iron(p):
                    self.go_title()
                    return
                lost = int(p.gold * MODS['death'])
                p.gold -= lost
                p.deaths += 1
                p.hp, p.mp = p.max_hp, p.max_mp
                p.ghost = 1.0
                p.reset_state()
                self.floors.clear()
                self.state = 'play'
                self.enter_map(self.get_village(), VPOS['spawn'])
                self.toast("You awaken in the village, lighter by %dg." % lost, (255, 160, 140), 4)
            self.start_trans(fn)

    def update_credits(self, dt):
        self.credits_t += dt
        self.fx.update(dt)
        if self.credits_t > 6 and (self.jp('ok') or self.jp('back')) or self.credits_t > 48:
            self.start_trans(self.after_win)

    def after_win(self):
        self.state = 'play'
        p = self.player
        p.hp, p.mp = p.max_hp, p.max_mp
        p.reset_state()
        self.floors.clear()
        self.enter_map(self.get_village(), VPOS['spawn'])
        self.toast("Torvin speaks of a bottomless Abyss... and the throne can be challenged again.", GOLD, 6)
        self.save_game(quiet=True)

    def update_pause(self):
        items = 4
        if self.jp('up'):
            self.pause_sel = (self.pause_sel - 1) % items
            self.audio.play('menu')
        if self.jp('down'):
            self.pause_sel = (self.pause_sel + 1) % items
            self.audio.play('menu')
        if self.jp('pause') or self.jp('back'):
            self.state = 'play'
            self.audio.play('back')
        elif self.jp('ok'):
            s_ = self.pause_sel
            if s_ == 0:
                self.state = 'play'
            elif s_ == 1:
                self.open_menu(0)
            elif s_ == 2:
                self.open_menu(3)
            else:
                self.go_title()

    # ---- gameplay --------------------------------------------------------------
    def update_play(self, dt):
        p = self.player
        m = self.map
        st = self.state
        if self.freeze > 0:
            self.freeze -= dt
            return
        self.tod = (self.tod + dt / DAY_LEN) % 1.0
        p.t += dt
        p.playtime += dt
        m.t += dt
        if st == 'play':
            if self.jp('pause'):
                self.state = 'pause'
                self.pause_sel = 0
                self.audio.play('menu')
                return
            if self.jp('inv'):
                self.open_menu(0)
                return
        slow = 1.0
        if st == 'dying':
            self.dying_t += dt
            slow = 0.35
            if self.dying_t > 1.6:
                self.state = 'gameover'
                self.over_t = 0
                self.audio.music_play('gameover', loop=False)
            dt *= slow
        if st == 'bossdeath':
            self.update_bossdeath(dt)
            return
        if st == 'bossintro':
            self.update_bossintro(dt)
        # player
        if st == 'play':
            self.update_player(dt)
        elif st == 'dying':
            pass
        p.inv_t = max(0, p.inv_t - dt)
        p.ghost = lerp(p.ghost, p.hp / p.max_hp, min(1, dt * 2.5)) if p.ghost > p.hp / p.max_hp + 0.002 else p.hp / p.max_hp
        self.interact_target = self.find_interact() if st == 'play' else None
        # world
        for n in m.npcs:
            n.update(self, dt)
        for a in getattr(m, 'animals', []):
            a.update(self, dt)
        m.dyn = [(n, n.rect()) for n in m.npcs] + [(c, c.rect()) for c in m.chests] + [(pt, pt.rect()) for pt in m.pots]
        self.update_enemies(dt)
        self.update_projs(dt)
        self.update_spell_world(dt)
        self.update_village(dt)
        self.arena_tick(dt)
        self.dive_t += dt
        self.blackout_t = max(0.0, self.blackout_t - dt)
        self.blizzard_t = max(0.0, self.blizzard_t - dt)
        self.update_pickups(dt)
        self.update_traps(dt)
        for c in m.chests:
            if c.opened:
                c.open_t += dt
        self.fx.update(dt)
        for cp in self.corpses:
            cp.update(self, dt)
        self.corpses = [cp for cp in self.corpses if not cp.dead]
        self.kick[0] *= max(0.0, 1 - 14 * dt)
        self.kick[1] *= max(0.0, 1 - 14 * dt)
        # ambient
        for a in self.ambp:
            if a[3] < 0:
                a[2] += dt
                a[0] += math.cos(a[2] * 0.7) * 6 * dt
                a[1] += math.sin(a[2] * 0.9) * 5 * dt
            elif m.weather == 'leaves':
                a[0] += (14 + math.sin(a[2] + self.time) * 8) * dt * a[3]
                a[1] += (9 + math.cos(a[2] + self.time * 1.3) * 4) * dt * a[3]
            elif m.weather == 'embers':
                a[0] += math.sin(a[2] + self.time) * 6 * dt
                a[1] -= (10 + 12 * a[3]) * dt
            else:
                a[0] += math.sin(a[2] + self.time * 0.5) * 3 * dt
                a[1] += math.cos(a[2] + self.time * 0.4) * 2 * dt
            a[0] %= W
            a[1] %= H
        # warps
        if self.warp_cd > 0:
            self.warp_cd -= dt
        elif st == 'play' and not self.trans:
            pr = p.rect()
            for w in m.warps:
                if overlap(pr, w['rect']):
                    self.warp(w)
                    break
        # boss trigger
        if m.trigger and m.boss and m.boss.state == 'dormant' and st == 'play' and overlap(p.rect(), m.trigger):
            self.start_bossintro()
        # camera
        self.update_camera(dt)
        if p.hp > p.max_hp:
            p.hp = p.max_hp
        m.reveal(int(p.x // T), int((p.y - 4) // T), 6) if m.kind in ('dungeon', 'boss') else None
        if st == 'play' and m.kind == 'village' and self.time - self.last_save > 9999:
            pass

    def update_player(self, dt):
        p = self.player
        m = self.map
        ix = (1 if self.held('right') else 0) - (1 if self.held('left') else 0)
        iy = (1 if self.held('down') else 0) - (1 if self.held('up') else 0)
        if p.rev_t > 0:
            ix, iy = -ix, -iy
        nx, ny = norm(ix, iy)
        attacking = p.atk_t >= 0
        p.moving = bool(ix or iy)
        if p.moving and not attacking and p.dash_t <= 0:
            p.fx, p.fy = nx, ny
            if abs(ix) > 0 and (abs(iy) == 0 or p.dir in (2, 3)):
                p.dir = 3 if ix > 0 else 2
            elif iy:
                p.dir = 0 if iy > 0 else 1
        p.hurt_t = max(0, p.hurt_t - dt)
        p.cast_t = max(0, p.cast_t - dt)
        p.potion_cd = max(0, p.potion_cd - dt)
        if p.moving and not attacking and p.dash_t <= 0 and p.drink_t < 0:
            p.walk_ph += dt * 10.0 * (p.speed / 58.0)
        # timers
        p.cool = max(0, p.cool - dt)
        p.combo_t = max(0, p.combo_t - dt) if p.atk_t < 0 else p.combo_t
        p.dash_cd = max(0, p.dash_cd - dt)
        p.fire_cd = max(0, p.fire_cd - dt)
        self.craft_tick(dt)
        for bt in ('power_t', 'fortune_t', 'stone_t', 'focus_t', 'perfect_cd', 'swift_t', 'brew_t', 'meal_t', 'gad_cd'):
            if getattr(p, bt) > 0:
                setattr(p, bt, max(0, getattr(p, bt) - dt))
        if p.elixir_t > 0:
            p.elixir_t -= dt
            if int(p.t * 12) % 3 == 0:
                self.fx.add(p.x + random.uniform(-4, 4), p.y - 4, 0, -16, 0.4, (255, 170, 40), 1)
        if 'ring' in p.charms and p.hp < p.max_hp:
            p.regen_t += dt
            if p.regen_t > 3.0:
                p.regen_t = 0
                p.hp = min(p.max_hp, p.hp + 2)
        p.mp_t += dt
        if p.mp_t > (2.6 if 'crystal' in p.charms else 4.2) / (1 + 0.2 * p.sk('well')) / (2 if p.has('well') else 1) / MODS.get('mpr', 1.0) and p.mp < p.max_mp:
            p.mp_t = 0
            p.mp = min(p.max_mp, p.mp + 1)
        # actions
        if self.jp('attack'):
            self.start_attack()
        if self.jp('magic'):
            self.cast_current()
        for i_, k_ in enumerate(('sp1', 'sp2', 'sp3', 'sp4')):
            if self.jp(k_):
                self.cast_slot(i_)
        if self.jp('spnext'):
            self.cycle_spell(1)
        if self.jp('spprev'):
            self.cycle_spell(-1)
        if self.jp('gadget'):
            self.throw_gadget()
        if self.jp('gadnext'):
            self.cycle_gadget()
        if self.jp('dash') and p.dash_cd <= 0 and p.dash_t <= 0:
            d = (nx, ny) if (nx or ny) else (p.fx, p.fy)
            p.dvx, p.dvy = d
            if p.drink_t >= 0:
                p.drink_t = -1.0
            p.dash_t = 0.24 if p.has('wind') else 0.17
            p.dash_cd = p.dash_cdmax
            p.inv_t = max(p.inv_t, 0.35 if p.has('wind') else 0.2)
            p.atk_t = -1
            self.audio.play('dash')
        if self.jp('interact') and self.interact_target:
            self.interact()
            return
        if self.jp('hp'):
            self.use_item('hp_potion', True)
        if self.jp('mp'):
            self.use_item('mp_potion', True)
        if self.jp('elixir'):
            self.use_item('elixir', True)
        # drinking a potion
        if p.drink_t >= 0:
            p.drink_t += dt
            col = self.POTION_COL.get(p.drink_kind, (230, 60, 80))
            if p.drink_t > 0.3 and random.random() < dt * 22:
                self.fx.add(p.x + random.uniform(-4, 4), p.y - 14, random.uniform(-6, 6), -24, 0.6, col, 1)
            if not p.drink_done and p.drink_t >= 0.34:
                p.drink_done = True
                self.apply_item(p.drink_kind)
                p.potion_cd = MODS['pcd']
                self.audio.play('glug', 0.7)
            if p.drink_t >= 0.62:
                p.drink_t = -1.0
        # attack progress
        if p.atk_t >= 0:
            p.atk_t += dt
            self.swing_fx()
            if p.combo == 2 and not getattr(p, 'slam_fx', False) and p.atk_t >= p.atk_dur * 0.58:
                p.slam_fx = True
                st_ = WSTYLE[p.wt]
                self.shake(2.5 * (st_['shake'] if getattr(p, 'atk_move', '') in ('slam', 'overhead') else 1.0))
                self.fx.burst(p.x + p.fx * 18, p.y - 2, 10, [(190, 180, 160), (150, 190, 120)], 60, 0.4, 1, 10, 3)
                if getattr(p, 'atk_move', '') == 'slam':
                    ix, iy = p.x + p.fx * 22, p.y - 2
                    self.audio.play('slam', 0.9)
                    for i in range(28):
                        a = i / 28 * math.tau
                        self.fx.add(ix + math.cos(a) * 6, iy + math.sin(a) * 3, math.cos(a) * 95, math.sin(a) * 48,
                                    0.4, (236, 226, 200), 2, 0, 3)
                    self.fx.burst(ix, iy, 14, [(190, 180, 160), (232, 226, 204)], 90, 0.5, 2, 60, 2)
                    self.glow(ix, iy, 50, (255, 230, 190), 0.2)
                    for e_ in self.map.enemies:
                        if not e_.dead and e_.kind != 'boss' and dist(e_.x, e_.y, ix, iy) < 36 and id(e_) not in p.atk_hit:
                            e_.killer = dict(wt=p.wt, combo=2, crit=False, ang=math.atan2(e_.y - iy, e_.x - ix), mv='slam')
                            e_.take_hit(self, max(1, int(p.atk * 0.55)), ix, iy, False, 170)
            if p.atk_t < 0.02:
                p.slam_fx = False
            if p.atk_dur * 0.14 <= p.atk_t <= p.atk_dur * 0.64:
                self.resolve_swing()
            if p.atk_t >= p.atk_dur:
                p.atk_t = -1
                p.cool = 0.04
                p.combo_t = 0.38
        # movement
        vx = vy = 0.0
        if p.dash_t > 0:
            p.dash_t -= dt
            self.check_perfect()
            vx, vy = p.dvx * 200, p.dvy * 200
            if int(p.t * 60) % 2 == 0:
                p.after.append([p.x, p.y, 0.22, p.dir])
                self.fx.add(p.x, p.y - 1, random.uniform(-8, 8), random.uniform(-8, 0), 0.3, (200, 190, 170), 2)
        elif p.drink_t >= 0:
            vx, vy = nx * p.speed * 0.3, ny * p.speed * 0.3
        elif attacking:
            vx, vy = nx * p.speed * 0.35, ny * p.speed * 0.35
            if p.lunge > 0:
                vx += p.fx * p.lunge
                vy += p.fy * p.lunge
                p.lunge = max(0, p.lunge - 520 * dt)
        else:
            vx, vy = nx * p.speed, ny * p.speed
        if abs(p.kbx) + abs(p.kby) > 3:
            vx += p.kbx
            vy += p.kby
            p.kbx *= max(0, 1 - 10 * dt)
            p.kby *= max(0, 1 - 10 * dt)
        if vx or vy:
            p.step(m, vx * dt, vy * dt, 'player')
        p.after = [[a[0], a[1], a[2] - dt, a[3]] for a in p.after if a[2] - dt > 0]
        # footsteps
        if p.moving and not attacking and p.dash_t <= 0:
            pi_ = int(p.walk_ph)
            if pi_ != p.last_ph:
                p.last_ph = pi_
                if pi_ % 2 == 0:
                    self.audio.play('step', 0.5 if m.kind != 'village' else 0.3)
                    dc = (190, 180, 160) if m.kind != 'village' else (150, 190, 120)
                    for _ in range(2):
                        self.fx.add(p.x - p.fx * 2 + random.uniform(-3, 3), p.y, -p.fx * random.uniform(4, 12),
                                    random.uniform(-9, -3), 0.32, dc, 1)
        # hazards
        tx, ty = int(p.x // T), int((p.y - 2) // T)
        tl = m.tile(tx, ty)
        if tl == LAVA:
            if p.inv_t <= 0:
                self.hurt_player(9, p.x, p.y + 6)
                p.x, p.y = p.last_safe
                self.fx.burst(p.x, p.y - 4, 10, [(255, 150, 40), (255, 80, 20)], 70, 0.5, 2, 60, 2)
        elif tl in (FLOOR, WOOD, GRASS, FLOWER, PATH, COBBLE, CARPET, SAND) and not any(
                m.tile(tx + a, ty + b) == LAVA for a in (-1, 0, 1) for b in (-1, 0, 1)):
            p.last_safe = (p.x, p.y)

    def update_enemies(self, dt):
        m = self.map
        p = self.player
        if self.state in ('dying',):
            return
        for e in m.enemies:
            if e.dead:
                continue
            d = dist(e.x, e.y, p.x, p.y)
            if e.kind != 'boss' and d > 330 and not e.aggro:
                continue
            if e.spawn_t > 0:
                e.spawn_t -= dt
                continue
            if self.state == 'bossintro' and e.kind != 'boss':
                continue
            e.update(self, dt)
        m.enemies = [e for e in m.enemies if not e.dead]
        near = [e for e in m.enemies if dist(e.x, e.y, p.x, p.y) < 200 and e.kind != 'boss']
        for i in range(len(near)):
            a = near[i]
            for j in range(i + 1, len(near)):
                b = near[j]
                dx, dy = a.x - b.x, a.y - b.y
                d2 = dx * dx + dy * dy
                if 0 < d2 < 64:
                    d = math.sqrt(d2)
                    a.step(m, dx / d * 20 * dt, dy / d * 20 * dt, 'enemy')
                    b.step(m, -dx / d * 20 * dt, -dy / d * 20 * dt, 'enemy')

    def update_pickups(self, dt):
        m = self.map
        p = self.player
        rad = 34 + (36 if 'amulet' in p.charms else 0)
        for pk in m.pickups:
            pk.age += dt
            if pk.z > 0 or pk.vz > 0:
                pk.vz -= 330 * dt
                pk.z += pk.vz * dt
                if pk.z <= 0:
                    pk.z = 0
                    pk.vz = -pk.vz * 0.4 if pk.vz < -40 else 0
                    pk.vx *= 0.4
                    pk.vy *= 0.4
                nx, ny = pk.x + pk.vx * dt, pk.y + pk.vy * dt
                if not m.blocked((nx - 3, ny - 4, 6, 4), 'enemy'):
                    pk.x, pk.y = nx, ny
            d = dist(pk.x, pk.y, p.x, p.y - 4)
            if pk.age > 0.45 and d < rad:
                pk.magnet = True
            if pk.magnet:
                nx, ny = norm(p.x - pk.x, p.y - 4 - pk.y)
                sp = 90 + (rad - min(d, rad)) * 3 + pk.age * 20
                pk.x += nx * sp * dt
                pk.y += ny * sp * dt
                pk.z = max(0, pk.z - 60 * dt)
            if pk.age > 0.3 and d < 9:
                pk.dead = True
                self.collect(pk)
            if pk.age > 40:
                pk.dead = True
        m.pickups = [pk for pk in m.pickups if not pk.dead]

    def collect(self, pk):
        p = self.player
        if pk.kind == 'coin':
            v = max(1, int(round(pk.val * p.gold_mult)))
            p.gold += v
            self.stat('gold_earned', v)
            self.audio.play('coin', 0.6, 0.04)
            self.fx.text(p.x, p.y - 20, "+%d" % v, GOLD, 0.6)
        elif pk.kind == 'heart':
            p.hp = min(p.max_hp, p.hp + 20)
            self.audio.play('heart')
            self.fx.text(p.x, p.y - 20, "+20", GREEN, 0.8)
        elif pk.kind == 'mana':
            p.mp = min(p.max_mp, p.mp + 6)
            self.audio.play('mana')
            self.fx.text(p.x, p.y - 20, "+6 MP", BLUE, 0.8)
        else:
            it = pk.val
            p.inv[it] = p.inv.get(it, 0) + 1
            self.audio.play('pickup')
            nm = LOOT.get(it, (ITEM_NAMES.get(it, it),))[0]
            self.toast("Got %s" % nm, CREAM, 2.2)
            for qid, qs in p.q.items():
                q = QUEST_BY_ID.get(qid)
                if q and q['kind'] == 'bring' and q['item'] == it and qs['state'] == 'active' \
                        and p.inv.get(it, 0) >= q['n']:
                    qs['state'] = 'ready'
                    self.toast("Quest ready: %s" % q['name'], GOLD, 4)

    def update_traps(self, dt):
        m = self.map
        p = self.player
        for t in m.traps:
            old = t.state()
            t.t += dt
            s_ = t.state()
            if s_ == 2 and old != 2 and dist(t.x, t.y, p.x, p.y) < 150:
                self.audio.play('spike', 0.6)
            if s_ != 2:
                t.hit = False
            elif not t.hit and overlap(p.rect(), t.rect()) and p.inv_t <= 0 and p.dash_t <= 0:
                t.hit = True
                self.hurt_player(11, t.x, t.y + 4)

    def update_camera(self, dt):
        p = self.player
        m = self.map
        lk = (p.fx * 16, p.fy * 9) if (p.moving and self.state == 'play') else (0.0, 0.0)
        self.look[0] += (lk[0] - self.look[0]) * min(1.0, dt * 2.5)
        self.look[1] += (lk[1] - self.look[1]) * min(1.0, dt * 2.5)
        tx, ty = p.x - W / 2 + self.cam_off[0] + self.look[0], p.y - 10 - H / 2 + self.cam_off[1] + self.look[1]
        k = min(1.0, dt * 6)
        self.cam[0] += (tx - self.cam[0]) * k
        self.cam[1] += (ty - self.cam[1]) * k
        self.clamp_cam()

    def clamp_cam(self, snap=False):
        m = self.map
        mw, mh = m.w * T, m.h * T
        if snap:
            self.cam[0] = self.player.x - W / 2 + self.cam_off[0]
            self.cam[1] = self.player.y - 10 - H / 2 + self.cam_off[1]
        self.cam[0] = (mw - W) / 2 if mw <= W else clamp(self.cam[0], 0, mw - W)
        self.cam[1] = (mh - H) / 2 if mh <= H else clamp(self.cam[1], 0, mh - H)

    # ---- boss cutscenes --------------------------------------------------------
    def start_bossintro(self):
        b = self.map.boss
        self.state = 'bossintro'
        self.cut = dict(t=0.0, step=0)
        self.audio.music_stop()
        self.map.sealed = True
        self.projs = []
        self.audio.play('bossintro')

    def update_bossintro(self, dt):
        c = self.cut
        c['t'] += dt
        b = self.map.boss
        p = self.player
        # camera pans to boss
        tx, ty = b.x - W / 2, b.y - 20 - H / 2
        self.cam[0] += (tx - self.cam[0]) * min(1, dt * 3)
        self.cam[1] += (ty - self.cam[1]) * min(1, dt * 3)
        self.clamp_cam()
        if c['step'] == 0 and c['t'] > 1.4:
            c['step'] = 1
            self.audio.play('roar')
            self.shake(6)
            self.flash = [(200, 100, 255), 0.4, 0.4, 100]
            self.fx.burst(b.x, b.y - 20, 40, [(180, 100, 255), WHITE], 120, 0.9, 2, 0, 1.4)
        if c['t'] > 4.0:
            self.state = 'play'
            b.state = 'idle'
            b.timer = 1.0
            b.t = 0
            self.audio.music_play('boss')
            self.cut = None

    def update_bossdeath(self, dt):
        c = self.cut
        self.dying_t += dt
        b = None
        self.fx.update(dt)
        self.shake(3)
        if int(self.dying_t * 14) != c['n']:
            c['n'] = int(self.dying_t * 14)
            self.fx.burst(c['x'] + random.uniform(-16, 16), c['y'] - random.uniform(8, 36), 8,
                          [(255, 200, 80), (255, 110, 30), WHITE, c.get('col', (200, 120, 255))], 90, 0.6, 2, 30, 2)
            if c['n'] % 3 == 0:
                self.audio.play('fire_hit', 0.5)
        tx, ty = c['x'] - W / 2, c['y'] - 20 - H / 2
        self.cam[0] += (tx - self.cam[0]) * min(1, dt * 3)
        self.cam[1] += (ty - self.cam[1]) * min(1, dt * 3)
        self.clamp_cam()
        if self.dying_t > 0.1 and self.map.boss in self.map.enemies:
            self.map.enemies = [e for e in self.map.enemies if e.kind != 'boss']
        if self.dying_t > 3.0 and not c.get('flash'):
            c['flash'] = True
            self.flash = [WHITE, 0.9, 0.9, 255]
            for e in self.map.enemies:
                e.dead = True
            self.map.enemies = []
            self.glow(c['x'], c['y'], 130, (255, 240, 200), 1.0)
        if self.dying_t > 3.6 and not c.get('loot'):
            c['loot'] = True
            rk = self.player.st.get('bosses', 1) - 1
            for i in range(30):
                self.drop(c['x'], c['y'] - 6, 'coin', int(10 * (1 + 0.5 * rk)))
            for it in ('gem', 'gem', 'gem', 'ore', 'ore'):
                self.drop(c['x'], c['y'] - 6, 'item', it)
            self.drop(c['x'], c['y'] - 6, 'heart')
            self.give_xp(c.get('xp', ENEMY['boss']['xp']))
            bid_ = c.get('bid', 'king')
            ess = 'e_king' if bid_ == 'king' else BOSSES[bid_]['essence']
            for _ in range(2 if c.get('first') else 1):
                self.drop(c['x'], c['y'] - 6, 'item', ess)
            dg_ = getattr(self.map, 'dg', None)
            for _ in range(7 if dg_ else 0):
                self.drop(c['x'], c['y'] - 6, 'item', random.choice(dg_['mats']))
            self.audio.music_play('victory', loop=False)
            self.audio.play('levelup')
        if self.dying_t > 4.0:
            self.update_pickups(dt)
        if self.dying_t > 8.5 and c.get('bid', 'king') != 'king':
            self.start_trans(self.after_boss2, 2.0)
        elif self.dying_t > 8.5:
            if 'credits_seen' in self.player.flags:
                self.start_trans(self.after_win, 2.0)
            else:
                self.player.flags.add('credits_seen')
                self.state = 'credits'
                self.credits_t = 0
                self.won = True
                self.audio.music_play('victory', loop=False)
                self.start_trans(lambda: None, 2.5)

    # ---- world draw ---------------------------------------------------------------
    def ambient_color(self):
        m = self.map
        if m.kind == 'village':
            return tod_color(self.tod)
        return m.ambient

    def draw_world(self, surf):
        m = self.map
        p = self.player
        shx = shy = 0
        if self.shake_a > 0.2:
            shx = int(random.uniform(-1, 1) * self.shake_a)
            shy = int(random.uniform(-1, 1) * self.shake_a)
        shx += int(self.kick[0])
        shy += int(self.kick[1])
        cx, cy = int(round(self.cam[0])) + shx, int(round(self.cam[1])) + shy
        surf.fill((8, 6, 12))
        surf.blit(m.base, (-cx, -cy))
        fr = int(self.time * 5) % 4
        x0, y0 = cx // T - 1, cy // T - 1
        x1, y1 = (cx + W) // T + 1, (cy + H) // T + 1
        for (tx, ty, k, mask) in m.anim_tiles:
            if x0 <= tx <= x1 and y0 <= ty <= y1:
                im = m.ts.water(fr, mask) if k == 'w' else m.ts.lava(fr)
                surf.blit(im, (tx * T - cx, ty * T - cy))
        # traps (ground)
        for t in m.traps:
            if abs(t.x - cx - W / 2) < W / 2 + 20 and abs(t.y - cy - H / 2) < H / 2 + 20:
                surf.blit(prop_spikes(t.state()), (int(t.x - 8 - cx), int(t.y - 14 - cy)))
        self.draw_spell_ground(surf, cx, cy)
        # after-images
        for a in p.after:
            im = tinted(person_sprite(a[3], 1, hero_palette(p.at)), (60, 80, 140)).copy()
            im.set_alpha(int(110 * a[2] / 0.22))
            surf.blit(im, (int(a[0] - 8 - cx), int(a[1] - 18 - cy)))
        out = []
        vx0, vx1, vy0, vy1 = cx - 60, cx + W + 60, cy - 60, cy + H + 90
        for pr in m.props:
            if pr.ground:
                continue
            if vx0 < pr.x < vx1 and vy0 < pr.y < vy1:
                im = pr.img(self.time)
                out.append((pr.y, im, pr.x - im.get_width() / 2, pr.y - im.get_height()))
        for n in m.npcs:
            sp = n.sprite()
            out.append((n.y - 0.5, shadow(10), n.x - 5, n.y - 1))
            out.append((n.y, sp, n.x - 8, n.y - 18 + n.dy))
        for a in getattr(m, 'animals', []):
            sp = a.sprite()
            out.append((a.y, sp, a.x - sp.get_width() / 2, a.y - sp.get_height() + 1))
        for c in m.chests:
            im = prop_chest(c.opened, c.tier)
            if c.opened and c.open_t < 0.26:
                im = flashed(im)
            out.append((c.y, im, c.x - 8, c.y - 15 - (2 if c.opened and c.open_t < 0.12 else 0)))
        for pt in m.pots:
            im = prop_pot() if pt.kind == 'pot' else (prop_crate() if pt.kind == 'crate' else prop_barrel())
            out.append((pt.y - 0.5, shadow(12), pt.x - 6, pt.y - 3))
            out.append((pt.y, im, pt.x - im.get_width() / 2, pt.y - im.get_height() + 2))
        for e in m.enemies:
            if vx0 < e.x < vx1 and vy0 < e.y < vy1:
                e.draw(self, out, cx, cy)
        for cp in self.corpses:
            out.append((cp.y, cp.draw, None, 0))
        for pk in m.pickups:
            bob = math.sin((self.time + pk.t0) * 5) * 1.5 if pk.z <= 0 else 0
            if pk.kind == 'coin':
                f = int((self.time * 8 + pk.t0)) % 4
                wd = [8, 5, 2, 5][f]
                im = S(10, 10)
                pygame.draw.ellipse(im, (255, 200, 60), (5 - wd // 2, 1, max(2, wd), 8))
                R(im, (255, 244, 170), 5 - wd // 2 + 1, 2, 1, 3)
                outline(im)
            elif pk.kind == 'heart':
                im = S(9, 8)
                heart_icon(im, 1, 1)
                outline(im)
            elif pk.kind == 'mana':
                im = S(9, 9)
                pygame.draw.circle(im, BLUE, (4, 4), 3)
                R(im, WHITE, 3, 2, 1, 1)
                outline(im)
            else:
                im = pygame.transform.scale(icon(pk.val), (12, 12)) if pk.val not in ('hp_potion', 'mp_potion') \
                    else pygame.transform.scale(icon(pk.val), (12, 12))
            out.append((pk.y + 1, shadow(7, 3, 70), pk.x - 3.5, pk.y - 1))
            out.append((pk.y + 1, im, pk.x - im.get_width() / 2, pk.y - im.get_height() / 2 - 3 - pk.z - bob))
        for a_ in self.allies:
            a_.draw(self, out)
        # wisp companion
        if 'wisp_pet' in p.flags and not p.dead:
            wx, wy = self.wisp_pos()
            out.append((wy + 30, prop_wisp(int(self.time * 6) % 4), wx - 6, wy - 8))
        # player
        if not (p.dead and self.state != 'dying'):
            out.append((p.y - 0.5, shadow(10), p.x - 5, p.y - 1))
            if not (p.inv_t > 0 and int(self.time * 20) % 2 == 0 and p.dash_t <= 0):
                out.append((p.y, self.hero_draw, self, 0))
        out.sort(key=lambda o: o[0])
        for (sy_, im, a, b_) in out:
            if im is None:
                _, bx, by, bw, ratio = a
                bar(surf, bx - cx, by - cy, bw, 2, ratio, RED)
            elif callable(im):
                im(surf, cx, cy)
            else:
                surf.blit(im, (int(a - cx), int(b_ - cy)))
        # ground decals/gfx on top: boss effects
        b = m.boss
        if b and b.slam_r >= 0:
            pygame.draw.circle(surf, (230, 160, 255), (int(b.x - cx), int(b.y - cy)), int(b.slam_r), 2)
            pygame.draw.circle(surf, (120, 60, 180), (int(b.x - cx), int(b.y - cy)), max(1, int(b.slam_r) - 3), 1)
        if b:
            for w in b.warns:
                k = 1 - clamp(w[2] / 0.9, 0, 1)
                r = int(16 * (0.4 + k * 0.6))
                col = (255, 80 + int(120 * k), 60)
                pygame.draw.circle(surf, col, (int(w[0] - cx), int(w[1] - cy)), r, 1)
                pygame.draw.circle(surf, col, (int(w[0] - cx), int(w[1] - cy)), max(1, r // 2), 1)
        # projectiles
        for pr in self.projs:
            x, y = int(pr.x - cx), int(pr.y - cy)
            if pr.kind == 'fire':
                pygame.draw.circle(surf, (255, 90, 20), (x, y), 5)
                pygame.draw.circle(surf, (255, 170, 40), (x, y), 3)
                pygame.draw.circle(surf, (255, 250, 190), (x, y), 1)
            elif pr.kind == 'lance':
                nx, ny = norm(pr.vx, pr.vy)
                pygame.draw.line(surf, (110, 190, 255), (x - nx * 9, y - ny * 9), (x + nx * 6, y + ny * 6), 3)
                pygame.draw.line(surf, (220, 250, 255), (x - nx * 6, y - ny * 6), (x + nx * 8, y + ny * 8), 1)
                surf.fill(WHITE, (x + int(nx * 8) - 1, y + int(ny * 8) - 1, 2, 2))
            elif pr.kind == 'arrow':
                nx, ny = norm(pr.vx, pr.vy)
                pygame.draw.line(surf, (120, 84, 50), (x - nx * 5, y - ny * 5), (x + nx * 4, y + ny * 4), 1)
                surf.fill(WHITE, (x + int(nx * 4), y + int(ny * 4), 1, 1))
                surf.fill((220, 80, 80), (int(x - nx * 5), int(y - ny * 5), 1, 1))
            else:
                col = PROJ.get(pr.kind, ((120, 255, 210), 4))[0]
                pygame.draw.circle(surf, mul_c(col, 0.6), (x, y), pr.r)
                pygame.draw.circle(surf, col, (x, y), pr.r - 1)
                surf.fill(WHITE, (x - 1, y - 1, 2, 2))
        self.draw_spell_fx(surf, cx, cy)
        # sword swing
        self.fx.draw(surf, cx, cy)
        # lighting
        self.draw_lighting(surf, cx, cy)
        self.fx.draw_text(surf, cx, cy)
        # ambient screen particles
        self.draw_ambient(surf)
        # interact bubble
        if self.interact_target and self.state == 'play':
            _, _, ix, iy = self.interact_target
            bob = math.sin(self.time * 6) * 1.5
            bx, by = int(ix - cx), int(iy - cy - 6 + bob)
            panel(surf, bx - 6, by - 2, 13, 13, None, (30, 24, 54), GOLD)
            if self.pad_active:
                pygame.draw.line(surf, (130, 190, 255), (bx - 2, by + 2), (bx + 3, by + 7), 1)
                pygame.draw.line(surf, (130, 190, 255), (bx + 3, by + 2), (bx - 2, by + 7), 1)
            else:
                txt(surf, "E", bx + 1, by + 1, WHITE, False, 'c')
            lab = self.interact_label(self.interact_target)
            if lab:
                lx = int(clamp(bx + 1, FONT.width(lab) // 2 + 4, W - FONT.width(lab) // 2 - 4))
                txt(surf, lab, lx, by - 10, CREAM, True, 'c', outline=True)

    SWORD_LEN = (12, 13, 15, 17, 18, 19, 21)
    POTION_COL = {'hp_potion': (230, 60, 80), 'big_hp': (240, 70, 110), 'mp_potion': (80, 130, 255),
                  'big_mp': (90, 160, 255), 'elixir': (255, 170, 40)}

    def hero_frame(self):
        """returns (pose frame, body offset x, body offset y)"""
        p = self.player
        ox = oy = 0.0
        if p.drink_t >= 0:
            f = 10
        elif p.atk_t >= 0:
            k = clamp(p.atk_t / p.atk_dur, 0, 1)
            st_ = WSTYLE[p.wt]
            mv_ = getattr(p, 'atk_move', 'slash')
            w0 = {'overhead': 0.30, 'slam': 0.40, 'thrust': 0.22}.get(mv_, 0.16)
            f = 7 if k < w0 else (8 if k < 0.58 else 9)
            back_ = -2.6 if mv_ in ('overhead', 'slam') else (-2.2 if mv_ == 'thrust' else -1.6)
            lu = back_ if k < w0 else (2.8 if k < 0.58 else 1.2 * (1 - (k - 0.58) / 0.42))
            lu *= st_['lean']
            ox, oy = p.fx * lu, p.fy * lu * 0.6
        elif p.dash_t > 0:
            f = 12
        elif p.hurt_t > 0:
            f = 11
            ox, oy = clamp(p.kbx, -1, 1) * 0.6, clamp(p.kby, -1, 1) * 0.3
        elif p.cast_t > 0:
            f = 13
        elif p.moving:
            f = (1, 5, 3, 6)[int(p.walk_ph) % 4]
        else:
            tt = p.t
            if tt % 3.9 < 0.12:
                f = 16
            else:
                f = 4 if int(tt / 0.7) % 2 else 0
        return f, ox, oy

    def hero_draw(self, surf, cx, cy):
        p = self.player
        pal = hero_palette(p.at)
        if self.state == 'dying':
            im = person_sprite(p.dir, 0, pal)
            k = clamp(self.dying_t / 1.2, 0, 1)
            im = pygame.transform.scale(im, (16, max(2, int(20 * (1 - k * 0.7)))))
            surf.blit(tinted(im, (120, 0, 0)), (int(p.x - 8 - cx), int(p.y - 1 - im.get_height() - cy)))
            return
        f, ox, oy = self.hero_frame()
        im = person_sprite(p.dir, f, pal)
        if p.hurt_t > 0.2:
            im = flashed(im)
        p.dox, p.doy = ox, oy
        surf.blit(im, (int(p.x - 8 + ox - cx), int(p.y - 18 + oy - cy)))
        if p.atk_t >= 0:
            self.draw_swing(surf, cx, cy)
        elif p.drink_t >= 0:
            self.draw_drink(surf, cx, cy)
        elif p.dash_t <= 0 and p.dir != 1:
            # sword resting at the hip, swaying a little when walking
            sway = int(math.sin(p.walk_ph * math.pi / 2 * 2) * 1) if p.moving else 0
            hx = int(p.x - cx) + (-5 if p.dir == 2 else 5 if p.dir == 3 else -5)
            hy = int(p.y - 9 - cy) + sway
            tilt = 0.3 if p.dir == 3 else -0.3
            draw_blade(surf, hx, hy, math.pi / 2 + tilt, p.wt, self.time, 0.42)

    def swing_pose(self, k):
        """(arm angle, blade angle, hand extension) at swing progress k in 0..1"""
        p = self.player
        st = WSTYLE[p.wt]
        mv = getattr(p, 'atk_move', 'slash')
        dr = 1 if p.sweep > 0 else -1
        if mv == 'thrust':
            if k < 0.22:
                e = -3.5 * ease_out(k / 0.22)
            elif k < 0.5:
                u = (k - 0.22) / 0.28
                e = -3.5 + 15.5 * (u * u * (3 - 2 * u))
            else:
                u = (k - 0.5) / 0.5
                e = 12.0 * (1 - u * u)
            a = p.atk_ang + dr * 0.10 * math.sin(k * math.pi)
            return a, a, e
        c = p.combo
        sw = 6.0 if (c == 2 and p.sk('whirl')) else st['sweep'][c]
        back = st['back'][c]
        w0, w1 = {'overhead': (0.30, 0.58), 'spin': (0.12, 0.68), 'slam': (0.40, 0.64)}.get(mv, (0.16, 0.58))
        ease = 1.0 if mv == 'spin' else st['ease']

        def ang(kk):
            a0 = p.atk_ang - dr * sw / 2
            if kk < w0:
                return a0 - dr * back * math.sin(max(0.0, kk) / w0 * math.pi / 2)
            if kk < w1:
                u = ((kk - w0) / (w1 - w0)) ** ease
                u = u * u * (3 - 2 * u)
                return a0 - dr * back + dr * (sw + back) * u
            u = (kk - w1) / (1 - w1)
            return a0 + dr * sw + dr * 0.3 * (1 - (1 - u) ** 2)
        arm = ang(k)
        blade = ang(max(0.0, k - st['lag']))
        if mv in ('overhead', 'slam'):
            if k < w0:
                e = -2.5 * math.sin(k / w0 * math.pi / 2)
            elif k < w1:
                u = (k - w0) / (w1 - w0)
                e = -2.5 + 6.0 * u * u
            else:
                e = 3.5 * (1 - (k - w1) / (1 - w1))
        else:
            e = 0.0
        return arm, blade, e

    def swing_angle(self, k):
        return self.swing_pose(k)[1]

    def draw_swing(self, surf, cx, cy):
        p = self.player
        st = WSTYLE[p.wt]
        mv = getattr(p, 'atk_move', 'slash')
        k = clamp(p.atk_t / p.atk_dur, 0, 1)
        arm, bang, ext = self.swing_pose(k)
        ox, oy = p.x + p.dox - cx, p.y - 9 + p.doy - cy
        L = st['L']
        rh = 6
        tcol = st['tcol']
        if p.combo == 2:
            tcol = lerp_c(tcol, (255, 255, 255), 0.25)
        if self._trail is None:
            self._trail = pygame.Surface((92, 92))
        tr = self._trail
        tr.fill((0, 0, 0))
        c0 = 46
        gain = 1.7 * (0.55 + 0.45 * st['tw'])
        if mv == 'thrust':
            # a stretched streak of afterimages along the stab line
            for j in range(7):
                kk = k - j * 0.035
                if kk < 0.2:
                    break
                e_ = self.swing_pose(kk)[2]
                a_ = self.swing_pose(kk)[1]
                fade = (1 - j / 7.0) ** 1.4
                col = tuple(min(255, int(v * fade * 1.5)) for v in tcol)
                x0, y0 = c0 + math.cos(a_) * (rh + e_ + 2), c0 + math.sin(a_) * (rh + e_ + 2)
                x1, y1 = c0 + math.cos(a_) * (rh + e_ + L + 4), c0 + math.sin(a_) * (rh + e_ + L + 4)
                pygame.draw.line(tr, col, (x0, y0), (x1, y1), 2 if j < 3 else 1)
        else:
            N = 11 if st['tw'] >= 1 else 9
            prev = None
            for j in range(N + 1):
                kk = k - j * 0.028
                if kk < 0.12:
                    break
                a, e_ = self.swing_pose(kk)[1], self.swing_pose(kk)[2]
                rout = rh + e_ + L + 3 - j * 0.3
                rin = rh + e_ + 1 + j * 0.5 + (L - 4) * (1 - min(1.0, st['tw'])) * 0.55
                cur = ((c0 + math.cos(a) * rin, c0 + math.sin(a) * rin), (c0 + math.cos(a) * rout, c0 + math.sin(a) * rout))
                if prev:
                    fade = (1 - j / (N + 1)) ** 1.3
                    col = tuple(min(255, int(v * fade * gain)) for v in tcol)
                    pygame.draw.polygon(tr, col, [prev[0], prev[1], cur[1], cur[0]])
                    if j <= 2:
                        pygame.draw.line(tr, tuple(min(255, int(v * 1.2)) for v in tcol), prev[1], cur[1], 2 if st['tw'] >= 1 else 1)
                prev = cur
            if prev and k > 0.12:
                a = bang
                pygame.draw.line(tr, (235, 240, 255), (c0 + math.cos(a) * (rh + ext + 6), c0 + math.sin(a) * (rh + ext + 6)),
                                 (c0 + math.cos(a) * (rh + ext + L + 3), c0 + math.sin(a) * (rh + ext + L + 3)), 1)
        surf.blit(tr, (int(ox - c0), int(oy - c0)), special_flags=pygame.BLEND_RGB_ADD)
        # arm(s) and blade
        ca, sa = math.cos(arm), math.sin(arm)
        hx, hy = ox + ca * (rh + ext), oy + sa * (rh + ext)
        sleeve = hero_palette(p.at)['tun']
        if st['two']:
            bx_, by_ = ox - sa * 2.5, oy + ca * 2.5
            pygame.draw.line(surf, OUT, (bx_, by_), (hx, hy), 3)
            pygame.draw.line(surf, sleeve, (bx_, by_), (hx, hy), 1)
        pygame.draw.line(surf, OUT, (ox, oy), (hx, hy), 3)
        pygame.draw.line(surf, sleeve, (ox, oy), (hx, hy), 1)
        draw_blade(surf, hx, hy, bang, p.wt, self.time)
        surf.fill(SKIN, (int(hx), int(hy), 2 if st['two'] else 1, 1))
        if p.wt >= 4 and 0.16 < k < 0.7:
            tx, ty = hx + math.cos(bang) * L, hy + math.sin(bang) * L
            surf.fill(mul_c(tcol, 0.8), (int(tx - 1), int(ty - 1), 3, 3))
            surf.fill(WHITE, (int(tx), int(ty), 1, 1))

    def draw_drink(self, surf, cx, cy):
        p = self.player
        k = clamp(p.drink_t / 0.62, 0, 1)
        col = self.POTION_COL.get(p.drink_kind, (230, 60, 80))
        hxo = {0: 3, 1: 4, 2: -4, 3: 4}[p.dir]
        u = ease_out(clamp(k / 0.3, 0, 1))
        low = clamp((k - 0.6) / 0.4, 0, 1)
        px = p.x - cx + hxo * (0.4 + 0.6 * u)
        py = p.y - cy - 5 - 6 * u + 4 * low
        bx, by = int(px), int(py)
        tilt = 0.32 < k < 0.62
        liquid = 3 if k < 0.34 else (2 if k < 0.45 else (1 if k < 0.55 else 0))
        if not tilt:
            surf.fill(OUT, (bx - 2, by - 5, 5, 8))
            surf.fill((200, 226, 236), (bx - 1, by - 4, 3, 6))
            surf.fill((200, 226, 236), (bx, by - 6, 1, 2))
            surf.fill((130, 90, 56), (bx - 1, by - 7, 3, 1))
            if liquid:
                surf.fill(col, (bx - 1, by + 2 - liquid + 1, 3, liquid))
        else:
            sg = -1 if p.dir == 2 else 1
            surf.fill(OUT, (bx - 3, by - 3, 7, 5))
            surf.fill((200, 226, 236), (bx - 2, by - 2, 5, 3))
            if liquid:
                surf.fill(col, (bx - 2 + (0 if sg > 0 else 3 - liquid + 1), by - 1, liquid + 1, 2))
            surf.fill((130, 90, 56), (bx + 3 * -sg - (1 if sg < 0 else 0), by - 2, 1, 3))
        if p.drink_t > 0.34:
            u2 = clamp((p.drink_t - 0.34) / 0.3, 0, 1)
            r = int(5 + u2 * 16)
            c2 = mul_c(col, 1 - u2 * 0.8)
            pygame.draw.circle(surf, c2, (int(p.x - cx), int(p.y - 9 - cy)), r, 1)
            if r > 9:
                pygame.draw.circle(surf, mul_c(c2, 0.6), (int(p.x - cx), int(p.y - 9 - cy)), r - 4, 1)

    def draw_lighting(self, surf, cx, cy):
        amb = self.ambient_color()
        if amb is None:
            return
        village = self.map.kind == 'village'
        if village and min(amb) > 244:
            return
        night = clamp((255 - min(amb)) / 140.0, 0, 1) if village else 1.0
        bo = clamp(self.blackout_t / 0.8, 0, 1) if self.blackout_t > 0 else 0.0
        bz = clamp(self.blizzard_t / 1.0, 0, 1) if self.blizzard_t > 0 else 0.0
        if bz:
            amb = lerp_c(amb, (120, 150, 205), 0.4 * bz)
        if bo:
            amb = mul_c(amb, 1.0 - 0.6 * bo)
        dk = self.dark
        dk.fill(amb)
        p = self.player
        t = self.time
        pr = 54 + math.sin(t * 7) * 2 if not village else 40 + 22 * night
        if p.hurt_t > 0:
            pr += 10 * clamp(p.hurt_t / 0.3, 0, 1)
        if bo:
            pr = pr * (1.0 - 0.55 * bo)
        pcol = (255, 220, 160) if not village else lerp_c((40, 36, 30), (255, 220, 160), night)
        self._add_light(dk, p.x - cx, p.y - 8 - cy, pr, pcol)
        for (x, y, r, col, fl, night_only) in self.map.lights:
            if x < cx - 100 or x > cx + W + 100 or y < cy - 100 or y > cy + H + 100:
                continue
            k = 1.0
            if night_only:
                if not village:
                    pass
                else:
                    k = night
                    if k < 0.05:
                        continue
            rr = r * (1 + fl * math.sin(t * 9 + x * 0.37) * 0.5)
            c = col if k >= 0.99 else tuple(int(v * k) for v in col)
            self._add_light(dk, x - cx, y - cy, rr, c)
        for pj in self.projs:
            col = {'fire': (255, 150, 60)}.get(pj.kind) or (PROJ[pj.kind][0] if pj.kind in PROJ else None)
            if col:
                self._add_light(dk, pj.x - cx, pj.y - cy, 26, col)
        for hz in self.hazards:
            if not hz.light or hz.dead or hz.shape in ('outside', 'rect') or hz.name == 'smoke':
                continue
            if hz.x + hz.a < cx - 60 or hz.x - hz.a > cx + W + 60 or hz.y + hz.a < cy - 60 or hz.y - hz.a > cy + H + 60:
                continue
            if hz.warn > 0:
                k = 0.18 + 0.2 * (1 - hz.warn / hz.warn0)
            else:
                k = 0.55 * clamp(hz.life / hz.life0, 0, 1) if hz.tick <= 0 else 0.45
            rr = hz.a * 1.5 if hz.shape in ('circle', 'ring') else min(70, hz.a * 0.6 + 14)
            self._add_light(dk, hz.x - cx, hz.y - cy, rr, tuple(int(v * k) for v in hz.col))
        for pts, zc, zl, zl0 in self.zaps:
            for (zx, zy) in pts[::2]:
                self._add_light(dk, zx - cx, zy - cy, 20, tuple(int(v * 0.6 * zl / zl0) for v in zc))
        for al in self.allies:
            if al.kind == 'wolf':
                self._add_light(dk, al.x - cx, al.y - 6 - cy, 20, (60, 100, 150))
            elif al.kind == 'sentry':
                self._add_light(dk, al.x - cx, al.y - 10 - cy, 22, (170, 130, 60))
            else:
                self._add_light(dk, al.x - cx, al.y - 10 - cy, 18, (140, 120, 70))
        if 'wisp_pet' in p.flags and not p.dead:
            wx, wy = self.wisp_pos()
            self._add_light(dk, wx - cx, wy - cy, 44 + 4 * math.sin(t * 5), (255, 170, 80))
        if p.aegis > 0:
            self._add_light(dk, p.x - cx, p.y - 9 - cy, 30, (60, 100, 140))
        if p.blood_t > 0:
            self._add_light(dk, p.x - cx, p.y - 9 - cy, 30, (130, 20, 40))
        if p.blades_t > 0:
            self._add_light(dk, p.x - cx, p.y - 9 - cy, 34, (80, 90, 120))
        for g_ in self.glows:
            k = g_[4] / g_[5]
            self._add_light(dk, g_[0] - cx, g_[1] - cy, g_[2] * (0.6 + 0.4 * k), tuple(int(v * k) for v in g_[3]))
        for pk in self.map.pickups:
            if pk.kind in ('coin', 'item'):
                self._add_light(dk, pk.x - cx, pk.y - 4 - cy, 10, (110, 96, 50))
        for e in self.map.enemies:
            if e.kind == 'wraith':
                self._add_light(dk, e.x - cx, e.y - 14 - cy, 24, (60, 140, 120))
            elif e.kind == 'boss':
                bc_ = getattr(e, 'fxcol', None)
                if bc_ is None or getattr(e, 'hidden', False):
                    bc_ = (140, 70, 200) if bc_ is None else None
                if bc_ is not None:
                    self._add_light(dk, e.x - cx, e.y - 20 - cy, 66, mul_c(bc_, 0.6))
            elif e.kind == 'imp':
                self._add_light(dk, e.x - cx, e.y - 14 - cy, 22, (200, 90, 40))
            elif e.kind == 'golem':
                self._add_light(dk, e.x - cx, e.y - 10 - cy, 16, (160, 80, 30))
            if e.elite:
                self._add_light(dk, e.x - cx, e.y - 8 - cy, 20, mul_c(ELITE_COL[e.elite], 0.5))
        surf.blit(dk, (0, 0), special_flags=pygame.BLEND_RGB_MULT)
        if not village:
            surf.blit(self.vignette(), (0, 0), special_flags=pygame.BLEND_RGB_MULT)

    def vignette(self):
        v = getattr(self, '_vig', None)
        if v is None:
            v = pygame.Surface((W, H))
            v.fill((255, 255, 255))
            n = 22
            for i in range(n):
                k = (1 - i / n) ** 2
                c = 255 - int(70 * k)
                pygame.draw.rect(v, (c, c, c), (i, i, W - 2 * i, H - 2 * i), 1)
            self._vig = v
        return v

    def _add_light(self, dk, x, y, r, col):
        r = max(8, int(r // 4 * 4))
        if x < -r or x > W + r or y < -r or y > H + r:
            return
        dk.blit(light(r, col), (int(x - r), int(y - r)), special_flags=pygame.BLEND_RGB_ADD)

    def draw_ambient(self, surf):
        m = self.map
        night = 0
        if m.kind == 'village':
            night = clamp((255 - min(tod_color(self.tod))) / 140.0, 0, 1)
        for a in self.ambp:
            x, y = int(a[0]), int(a[1])
            if a[3] < 0:
                if night > 0.25:
                    k = 0.5 + 0.5 * math.sin(a[2] * 3)
                    surf.fill(lerp_c((60, 80, 20), (230, 255, 120), k), (x, y, 2, 2))
            elif m.weather == 'leaves':
                surf.fill((200, 150, 60) if int(a[2]) % 2 else (130, 180, 70), (x, y, 2, 1))
            elif m.weather == 'embers':
                surf.fill((255, 150, 60) if int(a[2] * 3) % 2 else (255, 90, 30), (x, y, 1, 1))
            else:
                surf.fill((120, 120, 150), (x, y, 1, 1))

    # ---- HUD ----------------------------------------------------------------------
    def draw_hud(self, surf):
        p = self.player
        m = self.map
        self.draw_spellbar(surf)
        # status panel
        panel(surf, 3, 3, 98, 31, None, (22, 16, 40))
        txt(surf, "LV%d" % p.level, 8, 7, GOLD)
        bar(surf, 28, 8, 68, 5, p.hp / p.max_hp, RED, ghost=p.ghost)
        txt(surf, "%d/%d" % (max(0, int(p.hp)), p.max_hp), 62, 7, WHITE, True, 'c')
        bar(surf, 28, 17, 68, 4, p.mp / p.max_mp, BLUE)
        txt(surf, "%d" % p.mp, 8, 15, (140, 180, 255))
        bar(surf, 8, 27, 88, 2, p.xp / xp_needed(p.level), (255, 210, 90), back=(50, 40, 30))
        # gold
        g_ = "%d" % p.gold
        wdt = FONT.width(g_) + 20
        panel(surf, W - wdt - 3, 3, wdt, 15, None, (22, 16, 40))
        surf.blit(pygame.transform.scale(icon('coin'), (12, 12)), (W - wdt, 4))
        txt(surf, g_, W - 7, 7, GOLD, True, 'r')
        # potions
        x = 5
        hks = ('R2', 'L2', 'L3') if self.pad_active else ('Q', 'R', 'F')
        for key, hk in zip(('hp_potion', 'mp_potion', 'elixir'), hks):
            panel(surf, x, H - 22, 26, 19, None, (22, 16, 40), (150, 130, 80))
            surf.blit(icon(key), (x + 2, H - 21))
            n = p.inv.get(key, 0)
            txt(surf, "%d" % n, x + 24, H - 13, WHITE if n else (130, 110, 110), True, 'r')
            txt(surf, hk, x + 3, H - 21, (200, 190, 150))
            x += 28
        if p.gsel in GADGETS and p.inv.get(p.gsel, 0) > 0:
            panel(surf, x, H - 22, 26, 19, None, (22, 30, 40), (120, 160, 130))
            surf.blit(icon(p.gsel), (x + 2, H - 21))
            txt(surf, "%d" % p.inv[p.gsel], x + 24, H - 13, WHITE, True, 'r')
            txt(surf, "R3" if self.pad_active else "G", x + 3, H - 21, (170, 220, 180))
            x += 28
        for lab, val, mx_, col in (("MIGHT", p.elixir_t, 50, (255, 170, 40)), ("RAGE", p.power_t, 75, (255, 90, 70)),
                                   ("LUCK", p.fortune_t, 120, GOLD), ("STONE", p.stone_t, 150, (150, 200, 255)),
                                   ("FOCUS", p.focus_t, 3.5, (170, 230, 255)), ("WIND", p.swift_t, 90, (120, 240, 200)),
                                   ("BREW", p.brew_t, 90, (190, 120, 255)), ("MEAL", p.meal_t, 200, (255, 214, 140))):
            if val > 0:
                if x < 190:
                    bar(surf, x + 2, H - 15, 22, 3, min(1, val / mx_), col)
                    txt(surf, lab, x + 2, H - 22, col)
                    x += 28
        if p.sp > 0 and self.state == 'play' and int(self.time * 2) % 2 == 0:
            txt(surf, "SKILL POINT!", 5, 37, GOLD, True, 'l', outline=True)
        dn, _, dc, _ = DIFFS[p.diff]
        txt(surf, dn.upper(), 105, 6, mul_c(dc, 0.85))
        if p.heat or p.asc:
            hs = ("HEAT %d" % p.heat if p.heat else "") + (("  ASC %d" % p.asc) if p.asc else "")
            txt(surf, hs, 105, 14, (255, 130 + int(40 * math.sin(self.time * 5)), 60))
        for i, r in enumerate(p.relics):
            rc = RELIC_BY[r][3]
            surf.fill(INK, (4 + i * 8, H - 31, 8, 8))
            surf.fill(rc, (5 + i * 8, H - 30, 6, 6))
            surf.fill(WHITE, (6 + i * 8, H - 29, 2, 1))
        # minimap
        if m.kind in ('dungeon', 'boss'):
            mw, mh = 40, 30
            tx, ty = int(p.x // T), int(p.y // T)
            sub = S(mw, mh)
            sub.blit(m.mm, (0, 0), (tx - mw // 2, ty - mh // 2, mw, mh)) if False else sub.blit(m.mm, (mw // 2 - tx, mh // 2 - ty))
            big_ = pygame.transform.scale(sub, (mw * 2, mh * 2))
            bx, by = W - mw * 2 - 6, 22
            panel(surf, bx - 2, by - 2, mw * 2 + 4, mh * 2 + 4, None, (10, 8, 20), (110, 100, 150))
            surf.blit(big_, (bx, by))
            if int(self.time * 3) % 2 == 0:
                surf.fill(WHITE, (bx + mw - 1, by + mh - 1, 3, 3))
            surf.fill(RED, (bx + mw, by + mh, 1, 1)) if False else None
            txt(surf, "ARENA" if m.key == 'arena' else (("A%d" if m.abyss else "F%d") % m.floor_no), bx + mw * 2 - 1, by + mh * 2 + 3, DIM, True, 'r') if m.kind == 'dungeon' else None
        if m.kind == 'village':
            self.draw_vmap(surf)
        # quest tracker
        if m.kind == 'village':
            for qid, qs in p.q.items():
                if qs['state'] in ('active', 'ready'):
                    q = QUEST_BY_ID[qid]
                    have = p.inv.get(q['item'], 0) if q['kind'] == 'bring' else qs['prog']
                    s_ = "%s %d/%d" % (q['name'], min(have, q['n']), q['n']) if qs['state'] == 'active' else \
                        "%s: turn in!" % q['name']
                    txt(surf, s_, W - 5, 62, GOLD if qs['state'] == 'ready' else CREAM, True, 'r', outline=True)
                    break
        # boss bar
        b = m.boss
        if b and b.state not in ('dormant',) and not b.dead and self.state in ('play', 'bossintro'):
            bw = 196
            bx = 108
            panel(surf, bx - 6, H - 22, bw + 12, 18, None, (26, 12, 36), (160, 80, 200))
            bar(surf, bx, H - 14, bw, 6, b.hp / b.maxhp, getattr(b, 'fxcol', (190, 50, 200)), ghost=None)
            txt(surf, getattr(b, 'name', "The Hollow King").upper() + (" +%d" % b.rematch if getattr(b, 'rematch', 0) else ""),
                bx + bw // 2, H - 21, lerp_c(b.fxcol, WHITE, 0.5) if hasattr(b, 'fxcol') else (230, 180, 255), True, 'c')
        # toasts
        y = H - 34 if not (b and b.state != 'dormant') else H - 40
        for t in reversed(self.toasts):
            a = clamp(t[2] / 0.5, 0, 1)
            col = mul_c(t[1], 0.4 + 0.6 * a)
            txt(surf, t[0], W // 2, y, col, True, 'c', outline=True)
            y -= 11
        # trophy popup
        if self.trophy_pop:
            tp = self.trophy_pop[0]
            k = clamp(min(tp[2], 4.0 - tp[2]) / 0.4, 0, 1)
            yy = int(-24 + 28 * ease_out(k))
            panel(surf, W // 2 - 70, yy, 140, 22, None, (36, 26, 12), GOLD)
            txt(surf, "TROPHY: " + tp[0], W // 2, yy + 4, GOLD, True, 'c')
            txt(surf, tp[1], W // 2, yy + 13, CREAM, True, 'c')
        # banner
        if self.banner:
            tt = self.banner[1]
            k = ease_out(clamp(tt / 0.5, 0, 1)) * (1 - clamp((tt - 2.4) / 0.6, 0, 1))
            if k > 0:
                gold = getattr(self, 'banner_gold', False)
                yy = int(36 - (1 - k) * 12)
                txt_ = self.banner[0]
                sc_ = 2 if FONT.width(txt_) * 2 < 170 else 1
                if sc_ == 2:
                    big(surf, txt_, W // 2, yy, GOLD if gold else CREAM, 2)
                else:
                    txt(surf, txt_, W // 2, yy + 6, GOLD if gold else CREAM, True, 'c', outline=True)
                if not gold and self.map.kind != 'village':
                    pass

    # ---- full draw ------------------------------------------------------------------
    def draw(self):
        s = self.canvas
        st = self.state
        if st == 'title':
            self.draw_title(s)
        elif st == 'intro':
            self.draw_intro(s)
        elif st == 'credits':
            self.draw_credits(s)
        elif self.map:
            self.draw_world(s)
            if st in ('play', 'dialog', 'shop', 'bossintro', 'dying', 'menu', 'pause', 'bossdeath', 'relic', 'gate', 'craft') and not self.hide_hud:
                self.draw_hud(s)
            if st == 'bossintro' and self.cut:
                tt = self.cut['t']
                k = clamp(tt / 0.6, 0, 1)
                hh = int(22 * k)
                s.fill(BLACK, (0, 0, W, hh))
                s.fill(BLACK, (0, H - hh, W, hh))
                if tt > 1.6:
                    a = clamp((tt - 1.6) / 0.5, 0, 1) * (1 - clamp((tt - 3.5) / 0.5, 0, 1))
                    bb_ = self.map.boss
                    big(s, getattr(bb_, 'name', "The Hollow King").upper(), W // 2, H // 2 + 26,
                        mul_c(getattr(bb_, 'fxcol', (235, 150, 255)), 0.4 + 0.6 * a), 2 if len(getattr(bb_, 'name', 'x' * 14)) < 17 else 1)
            if st == 'dialog':
                self.draw_dialog(s)
            elif st == 'shop':
                self.draw_shop(s)
            elif st == 'relic':
                self.draw_relic(s)
            elif st == 'gate':
                self.draw_gate(s)
            elif st == 'craft':
                self.draw_craft(s)
            elif st == 'menu':
                self.draw_menu(s)
            elif st == 'fish':
                self.draw_fish(s)
            elif st == 'pause':
                self.draw_pause(s)
            elif st == 'gameover':
                self.draw_gameover(s)
        if self.flash:
            col, t, mx, alpha = self.flash
            self.overlay.fill(col)
            self.overlay.set_alpha(int(alpha * clamp(t / mx, 0, 1)))
            s.blit(self.overlay, (0, 0))
        if self.fade > 0.001:
            self.overlay.fill(BLACK)
            self.overlay.set_alpha(int(255 * clamp(self.fade, 0, 1)))
            s.blit(self.overlay, (0, 0))
        if self.trailer:
            self.trailer.overlay(s)
        self.draw_touch(s)
        # present: scale the 320x180 canvas to fit the window, keeping 16:9
        scr = pygame.display.get_surface() or self.screen
        self.screen = scr
        ww, wh = scr.get_size()
        sc = min(ww / W, wh / H)
        if sc >= 2 and sc - int(sc) < 0.35:
            sc = float(int(sc))              # snap to crisp whole-number scale when close
        tw, th = max(W, int(W * sc)), max(H, int(H * sc))
        im = pygame.transform.scale(s, (tw, th))
        if (tw, th) != (ww, wh):
            scr.fill(BLACK)
        scr.blit(im, ((ww - tw) // 2, (wh - th) // 2))
        self.pres = ((ww - tw) // 2, (wh - th) // 2, tw / W)
        pygame.display.flip()

    def draw_dialog(self, surf):
        d = self.dlg
        if not d:
            return
        bh = 56
        y = H - bh - 6
        panel(surf, 8, y, W - 16, bh, None, (24, 18, 44))
        # portrait
        pw = 54
        panel(surf, 13, y + 5, pw, bh - 10, None, (40, 30, 70), (150, 130, 80))
        pal = d['pal']
        if pal:
            im = pygame.transform.scale(person_sprite(0, 0, pal), (48, 60))
            surf.blit(im, (16, y + 3 + 2 - 4), (0, 0, 48, bh - 12 + 8)) if False else surf.blit(
                pygame.transform.scale(person_sprite(0, 4 if int(self.time * 2) % 2 else 0, pal).subsurface((0, 0, 16, 16)) if hasattr(pygame.Surface, 'subsurface') and False else person_sprite(0, 0, pal), (40, 50)),
                (20, y + 6))
        # name tag
        nm = d['name']
        tw = FONT.width(nm) + 10
        surf.fill((60, 40, 90), (13 + pw // 2 - tw // 2, y - 5, tw, 11))
        pygame.draw.rect(surf, GOLD, (13 + pw // 2 - tw // 2, y - 5, tw, 11), 1)
        txt(surf, nm, 13 + pw // 2, y - 3, GOLD, True, 'c')
        page = d['pages'][d['i']]
        shown = page[:int(d['shown'])]
        lines = FONT.wrap(page, W - 16 - pw - 28)
        n_shown = len(shown)
        cnt = 0
        ty = y + 8
        for ln in lines:
            part = ln[:max(0, n_shown - cnt)]
            txt(surf, part, 13 + pw + 8, ty, CREAM)
            cnt += len(ln) + 1
            ty += 10
        done = d['shown'] >= len(page)
        last = d['i'] == len(d['pages']) - 1
        if done and last and d['choices']:
            cw = max(FONT.width(c[0]) for c in d['choices']) + 22
            ch = len(d['choices']) * 11 + 8
            cx_, cy_ = W - 16 - cw, y - ch - 2
            panel(surf, cx_, cy_, cw, ch, None, (30, 22, 56))
            for i, (lab, fn) in enumerate(d['choices']):
                sel = i == d['sel']
                txt(surf, lab, cx_ + 14, cy_ + 5 + i * 11, GOLD if sel else CREAM)
                if sel:
                    txt(surf, ">", cx_ + 5 + int(math.sin(self.time * 8) * 1), cy_ + 5 + i * 11, GOLD)
        elif done:
            if int(self.time * 3) % 2 == 0:
                txt(surf, "v", W - 22, y + bh - 12, GOLD)

    def draw_shop(self, surf):
        sh = self.shop
        if not sh:
            return
        p = self.player
        dim = self.overlay
        dim.fill((8, 4, 18))
        dim.set_alpha(190)
        surf.blit(dim, (0, 0))
        names = {'smith': "BRANN'S SMITHY", 'alch': "ZIA'S APOTHECARY", 'general': "PIP'S GENERAL GOODS"}
        L = self.shop_items()
        sel = clamp(sh['sel'], 0, max(0, len(L) - 1))
        panel(surf, 6, 8, 188, 164, names[sh['id']])
        # tabs
        tabs = self.shop_tabs()
        tx = 14
        for i, t_ in enumerate(tabs):
            on = i == sh['tab']
            wdt = FONT.width(t_) + 12
            surf.fill((70, 50, 110) if on else (34, 26, 58), (tx, 17, wdt, 11))
            pygame.draw.rect(surf, GOLD if on else (90, 80, 110), (tx, 17, wdt, 11), 1)
            txt(surf, t_, tx + wdt // 2, 19, GOLD if on else DIM, True, 'c')
            tx += wdt + 3
        if len(tabs) > 1:
            txt(surf, "< >", 186, 19, DIM, True, 'r')
        # list
        y = 33
        for i in range(sh['top'], min(len(L), sh['top'] + 6)):
            it = L[i]
            on = i == sel
            if on:
                surf.fill((64, 46, 100), (10, y - 2, 180, 20))
                pygame.draw.rect(surf, GOLD, (10, y - 2, 180, 20), 1)
            im = icon(it['ic'])
            if it.get('owned') and not it.get('sell') or it.get('dim'):
                im = im.copy()
                im.fill((110, 110, 110), special_flags=pygame.BLEND_RGB_MULT)
            surf.blit(im, (13, y))
            col = CREAM if it['ok'] else (140, 130, 150)
            if on:
                col = WHITE if it['ok'] else (180, 170, 190)
            txt(surf, shorten(it['name'], 22), 33, y, col)
            txt(surf, it['sub'], 33, y + 9, (170, 190, 230) if it['ok'] else (110, 110, 130))
            if it.get('price') is not None:
                if it.get('maxed'):
                    txt(surf, "MAX", 186, y + 4, DIM, True, 'r')
                elif it.get('owned'):
                    txt(surf, "OWNED", 186, y + 4, GREEN, True, 'r')
                else:
                    txt(surf, "%dg" % it['price'], 186, y + 4, GOLD if p.gold >= it['price'] else RED, True, 'r')
            y += 21
        if len(L) > 6:
            ph = 118
            surf.fill((40, 32, 70), (190, 34, 2, ph))
            thumb = max(8, int(ph * 6 / len(L)))
            surf.fill(GOLD, (190, 34 + int((ph - thumb) * sh['top'] / max(1, len(L) - 6)), 2, thumb))
        if sh['msg_t'] > 0:
            txt(surf, sh['msg'], 100, 160, sh['mcol'], True, 'c')
        # detail panel
        panel(surf, 198, 8, 116, 164, "DETAILS")
        if L:
            it = L[sel]
            big_ic = pygame.transform.scale(icon(it['ic']), (32, 32))
            panel(surf, 205, 18, 38, 38, None, (40, 30, 70), (150, 130, 80))
            surf.blit(big_ic, (208, 21))
            if sh['id'] == 'smith' and it.get('kind') == 'armor':
                hp_ = pygame.transform.scale(person_sprite(0, 0, hero_palette(it['tier'])), (32, 40))
                surf.blit(hp_, (272, 16))
            elif sh['id'] == 'smith':
                hp_ = pygame.transform.scale(person_sprite(0, 0, hero_palette(p.at)), (32, 40))
                surf.blit(hp_, (272, 16))
            txt(surf, shorten(it['name'], 17), 250, 22, GOLD) if False else None
            ty = 60
            for ln in FONT.wrap(it['desc'], 100):
                txt(surf, ln, 206, ty, CREAM)
                ty += 9
            if it.get('stat'):
                ty += 4
                txt(surf, it['stat'], 206, ty, (140, 230, 160))
                ty += 11
        txt(surf, "Gold", 206, 148, DIM)
        surf.blit(pygame.transform.scale(icon('coin'), (10, 10)), (260, 147))
        txt(surf, "%d" % p.gold, 306, 148, GOLD, True, 'r')
        txt(surf, "ENTER buy  ESC leave", 256, 161, DIM, True, 'c')

    def draw_pause(self, surf):
        dim = self.overlay
        dim.fill((6, 4, 14))
        dim.set_alpha(150)
        surf.blit(dim, (0, 0))
        panel(surf, W // 2 - 60, 50, 120, 84, "PAUSED")
        for i, lab in enumerate(["Resume", "Hero & Items", "Options", "Quit to Title"]):
            on = i == self.pause_sel
            txt(surf, lab, W // 2, 66 + i * 16, GOLD if on else CREAM, True, 'c')
            if on:
                txt(surf, ">", W // 2 - 46 + int(math.sin(self.time * 8)), 66 + i * 16, GOLD)
        txt(surf, "M: mute   F11: fullscreen", W // 2, 124, DIM, True, 'c')

    def draw_menu(self, surf):
        p = self.player
        dim = self.overlay
        dim.fill((8, 4, 18))
        dim.set_alpha(215)
        surf.blit(dim, (0, 0))
        panel(surf, 8, 8, W - 16, H - 16, None)
        tabs = ["HERO", "ITEMS", "SKILLS", "QUESTS", "TROPHIES", "OPTIONS", "SPELLS"]
        tx = 14
        for i in self.TAB_ORDER:
            t_ = tabs[i]
            on = i == self.menu_tab
            wdt = FONT.width(t_) + 6
            surf.fill((70, 50, 110) if on else (34, 26, 58), (tx, 13, wdt, 12))
            pygame.draw.rect(surf, GOLD if on else (90, 80, 110), (tx, 13, wdt, 12), 1)
            txt(surf, t_, tx + wdt // 2, 16, GOLD if on else DIM, True, 'c')
            if i == 2 and p.sp > 0 and int(self.time * 3) % 2 == 0:
                surf.fill(GOLD, (tx + wdt - 3, 11, 3, 3))
            tx += wdt + 3
        t = self.menu_tab
        if t == 0:
            panel(surf, 16, 32, 80, 120, None, (36, 28, 62), (150, 130, 80))
            im = pygame.transform.scale(person_sprite(0, 4 if int(self.time * 1.6) % 2 else 0, hero_palette(p.at)), (48, 60))
            surf.blit(im, (32, 42))
            txt(surf, "Adventurer", 56, 106, CREAM, True, 'c')
            txt(surf, "Level %d%s" % (p.level, " (MAX)" if p.level >= MAX_LEVEL else ""), 56, 116, GOLD, True, 'c')
            bar(surf, 24, 130, 64, 4, p.xp / xp_needed(p.level) if p.level < MAX_LEVEL else 1, (255, 210, 90), back=(50, 40, 30))
            txt(surf, ("%d / %d XP" % (p.xp, xp_needed(p.level))) if p.level < MAX_LEVEL else "MAX LEVEL", 56, 138, DIM, True, 'c')
            rows = [("HP", "%d / %d" % (p.hp, p.max_hp), RED), ("MP", "%d / %d" % (p.mp, p.max_mp), BLUE),
                    ("Attack", "%d" % p.atk, CREAM), ("Defense", "%d" % p.dfn, CREAM),
                    ("Speed", "%d%%" % (100 * p.speed / 58), CREAM), ("Crit", "%d%% x%.1f" % (p.crit * 100, p.crit_mult), CREAM),
                    ("Kills", "%d" % p.kills, CREAM), ("Deepest", "Floor %d" % p.maxfloor if p.maxfloor else "-", CREAM),
                    ("Abyss", "Depth %d" % p.abyss_best if p.abyss_best else "-", CREAM),
                    ("Guild", "%s (%d)" % (RANKS[p.rank][0], p.rep), GOLD),
                    ("Skill pts", "%d" % p.sp, GOLD if p.sp else CREAM),
                    ("Time", "%d:%02d" % (p.playtime // 3600, (p.playtime // 60) % 60), CREAM)]
            for i, (a, b_, c) in enumerate(rows):
                txt(surf, a, 104, 33 + i * 10, DIM)
                txt(surf, b_, 192, 33 + i * 10, c, True, 'r')
            panel(surf, 198, 32, 106, 60, "GEAR")
            surf.blit(icon('sword%d' % p.wt), (204, 38))
            txt(surf, shorten(WEAPONS[p.wt][0], 14) + (" +%d" % p.wplus if p.wplus else ""), 222, 40, CREAM)
            txt(surf, "ATK %d" % (WEAPONS[p.wt][1] + 2 * p.wplus), 224, 49, (140, 230, 160))
            surf.blit(icon('armor%d' % p.at), (204, 62))
            txt(surf, shorten(ARMORS[p.at][0], 14) + (" +%d" % p.aplus if p.aplus else ""), 222, 64, CREAM)
            txt(surf, "DEF %d" % (ARMORS[p.at][1] + p.aplus), 224, 73, (140, 230, 160))
            panel(surf, 198, 96, 106, 56, "CHARMS")
            for i, k in enumerate(ALL_CHARMS):
                x = 202 + (i % 6) * 17
                y = 104 + (i // 6) * 16
                im = icon(k)
                if k not in p.charms:
                    im = im.copy()
                    im.fill((50, 50, 60), special_flags=pygame.BLEND_RGB_MULT)
                surf.blit(im, (x, y))
            txt(surf, "%d/%d" % (len([k for k in ALL_CHARMS if k in p.charms]), len(ALL_CHARMS)), 203, 138, DIM, True, 'l')
            txt(surf, "Tonics %d/3" % p.tonics, 300, 138, (255, 150, 190), True, 'r')
            if p.rune:
                surf.blit(pygame.transform.scale(icon('rune_' + p.rune), (10, 10)), (204, 79))
                txt(surf, RUNES[p.rune][0], 217, 81, RUNES[p.rune][1])
            else:
                txt(surf, "No rune imbued", 204, 81, (110, 100, 130))
        elif t == 1:
            names = {'hp_potion': "Health Potion", 'big_hp': "Greater Health", 'mp_potion': "Mana Potion",
                     'big_mp': "Greater Mana", 'elixir': "Elixir of Might", 'fortune': "Fortune Draught",
                     'stoneskin': "Stoneskin Tonic"}
            descs = {'hp_potion': "Restore 50 HP", 'big_hp': "Restore 130 HP", 'mp_potion': "Restore 18 MP",
                     'big_mp': "Restore 50 MP", 'elixir': "+50% ATK for 50 seconds",
                     'fortune': "+50% gold for 2 minutes", 'stoneskin': "+4 DEF for 2 minutes"}
            ML = self.menu_items()
            mtop = clamp(self.menu_sel - 3, 0, max(0, len(ML) - 7))
            for i in range(mtop, min(len(ML), mtop + 7)):
                k = ML[i]
                y = 33 + (i - mtop) * 15
                on = i == self.menu_sel
                if on:
                    surf.fill((64, 46, 100), (16, y - 2, 142, 15))
                    pygame.draw.rect(surf, GOLD, (16, y - 2, 142, 15), 1)
                surf.blit(icon(k), (19, y - 2))
                n = p.inv.get(k, 0)
                txt(surf, shorten(names.get(k, ITEM_NAMES.get(k, k)), 19), 38, y + 2, CREAM if n else DIM)
                txt(surf, "x%d" % n, 154, y + 2, WHITE if n else DIM, True, 'r')
            if len(ML) > 7:
                txt(surf, "%d/%d" % (self.menu_sel + 1, len(ML)), 158, 31, DIM, True, 'r')
            sk_ = ML[self.menu_sel]
            dd = descs.get(sk_) or (EXTRA_ITEMS[sk_][1] if sk_ in EXTRA_ITEMS else "")
            txt(surf, shorten(dd, 30) + ("  (ENTER)" if len(dd) < 24 else ""), 16, 142, (170, 190, 230))
            panel(surf, 164, 30, 140, 122, "LOOT")
            owned = [(k, v) for k, v in LOOT.items() if p.inv.get(k, 0) > 0]
            if not owned:
                txt(surf, "Nothing yet.", 234, 80, DIM, True, 'c')
            for i, (k, (nm, val)) in enumerate(owned[:40]):
                x = 168 + (i % 5) * 26
                y = 40 + (i // 5) * 13
                surf.blit(pygame.transform.scale(icon(k), (11, 11)), (x, y - 1))
                txt(surf, "%d" % p.inv[k], x + 24, y + 2, WHITE, True, 'r')
        elif t == 2:
            txt(surf, "Skill points: %d" % p.sp, 18, 31, GOLD)
            top = clamp(self.menu_sel - 4, 0, max(0, len(SKILLS) - 9))
            for j in range(top, min(len(SKILLS), top + 9)):
                s_ = SKILLS[j]
                y = 41 + (j - top) * 12
                on = j == self.menu_sel
                if on:
                    surf.fill((64, 46, 100), (16, y - 2, 146, 12))
                    pygame.draw.rect(surf, GOLD, (16, y - 2, 146, 12), 1)
                r_ = p.sk(s_[0])
                locked = s_[4] and p.sk(s_[4][0]) < s_[4][1]
                col = GREEN if r_ >= s_[2] else (DIM if locked else CREAM)
                txt(surf, s_[1], 20, y, col)
                for k in range(s_[2]):
                    surf.fill(GOLD if k < r_ else (60, 50, 80), (112 + k * 9, y + 1, 7, 5))
            s_ = SKILLS[self.menu_sel]
            panel(surf, 168, 30, 136, 122, s_[1].upper())
            r_ = p.sk(s_[0])
            y = 44
            for ln in FONT.wrap(s_[3] + " per rank.", 122):
                txt(surf, ln, 174, y, CREAM)
                y += 9
            y += 4
            txt(surf, "Rank %d / %d" % (r_, s_[2]), 174, y, GOLD)
            y += 11
            if s_[4]:
                ok_ = p.sk(s_[4][0]) >= s_[4][1]
                txt(surf, "Requires %s %d" % (SKILL_BY_ID[s_[4][0]][1], s_[4][1]), 174, y, GREEN if ok_ else RED)
                y += 10
            txt(surf, "Cost: %d point%s" % (self.skill_cost(s_[0]), "s" if self.skill_cost(s_[0]) > 1 else ""), 174, y, DIM)
            y += 12
            if r_ >= s_[2]:
                txt(surf, "MASTERED", 174, y, GREEN)
            elif self.can_learn(s_[0]):
                txt(surf, "ENTER: learn", 174, y, (140, 230, 160))
            else:
                txt(surf, "Cannot learn yet", 174, y, (200, 120, 120))
            txt(surf, "R: reset (%dg)" % self.respec_cost(), 174, 142, DIM)
        elif t == 3:
            y = 33
            txt(surf, "MAIN QUEST", 18, y, GOLD)
            y += 10
            done = 'boss_dead' in p.flags
            txt(surf, "Slay the Hollow King" + ("  (DONE)" if done else ""), 18, y, GREEN if done else CREAM)
            y += 9
            txt(surf, "Hollowdeep has 3 floors.", 18, y, DIM)
            y += 13
            txt(surf, "SIDE QUESTS (Elder Maren)", 18, y, GOLD)
            y += 11
            any_ = False
            for q in QUESTS:
                qs = p.q.get(q['id'])
                if not qs:
                    continue
                any_ = True
                have = p.inv.get(q['item'], 0) if q['kind'] == 'bring' else qs['prog']
                st_ = {'active': "In progress", 'ready': "Turn in!", 'done': "Done"}[qs['state']]
                col = {'active': CREAM, 'ready': GOLD, 'done': GREEN}[qs['state']]
                txt(surf, q['name'], 18, y, col)
                txt(surf, st_, 152, y, col, True, 'r')
                if qs['state'] != 'done':
                    bar(surf, 18, y + 9, 134, 2, min(have, q['n']) / q['n'], GOLD)
                y += 16
            if not any_:
                txt(surf, "None yet.", 18, y, DIM)
            panel(surf, 160, 30, 144, 122, "GUILD BOUNTIES")
            nxt = RANKS[p.rank + 1] if p.rank + 1 < len(RANKS) else None
            txt(surf, "Rank: %s" % RANKS[p.rank][0], 166, 42, GOLD)
            if nxt:
                lo = RANKS[p.rank][1]
                bar(surf, 166, 52, 132, 3, (p.rep - lo) / (nxt[1] - lo), (120, 200, 255))
                txt(surf, "%d / %d to %s" % (p.rep, nxt[1], nxt[0]), 166, 58, DIM)
            else:
                txt(surf, "Highest rank!", 166, 58, GREEN)
            y = 72
            if not p.bounties:
                txt(surf, "Speak to Guard Torvin.", 166, y, DIM)
            for b in p.bounties:
                col = GREEN if b['done'] else CREAM
                txt(surf, shorten(b['name'], 31), 166, y, col)
                bar(surf, 166, y + 9, 132, 2, b['prog'] / b['n'], GREEN if b['done'] else GOLD)
                txt(surf, ("Turn in!" if b['done'] else "%d/%d" % (b['prog'], b['n'])) + "   %dg" % b['gold'], 166, y + 12, DIM)
                y += 25
        elif t == 4:
            n_ = len(TROPHIES)
            txt(surf, "Trophies: %d / %d" % (len(p.trophies), n_), 18, 31, GOLD)
            top = clamp(self.menu_sel - 2, 0, max(0, n_ - 6))
            for j in range(top, min(n_, top + 6)):
                tid, nm, ds, key, goal, rew = TROPHIES[j]
                y = 42 + (j - top) * 19
                on = j == self.menu_sel
                done = tid in p.trophies
                if on:
                    surf.fill((64, 46, 100), (14, y - 3, 284, 19))
                    pygame.draw.rect(surf, GOLD, (14, y - 3, 284, 19), 1)
                txt(surf, nm, 20, y, GOLD if done else CREAM)
                txt(surf, ds, 20, y + 7, DIM) if False else None
                have = min(goal, self.stat_value(key))
                rs = ("%dg" % rew[1]) if rew[0] == 'g' else ("%d SP" % rew[1])
                txt(surf, "Done" if done else "%d/%d" % (have, goal), 292, y, GREEN if done else DIM, True, 'r')
                txt(surf, ds + "  [" + rs + "]", 20, y + 8, (150, 140, 170))
            if n_ > 6:
                surf.fill((40, 32, 70), (300, 40, 2, 108))
                th = max(8, int(108 * 6 / n_))
                surf.fill(GOLD, (300, 40 + int((108 - th) * top / max(1, n_ - 6)), 2, th))
        elif t == 6:
            self.draw_spell_tab(surf)
        else:
            items = [("Music volume", self.audio.music_vol), ("Effects volume", self.audio.sfx_vol),
                     ("Fullscreen (F11)", None), ("Save game (village only)", None), ("Quit to title", None)]
            for i, (lab, v) in enumerate(items):
                y = 38 + i * 20
                on = i == self.menu_sel
                if on:
                    surf.fill((64, 46, 100), (16, y - 3, W - 48, 17))
                    pygame.draw.rect(surf, GOLD, (16, y - 3, W - 48, 17), 1)
                txt(surf, lab, 24, y + 1, CREAM if on else DIM)
                if v is not None:
                    bar(surf, 190, y + 3, 90, 5, v, (120, 200, 255))
                    txt(surf, "%d%%" % round(v * 100), 292, y + 1, WHITE, True, 'r')
            txt(surf, "Arrows adjust, ENTER selects.", W // 2, 150, DIM, True, 'c')

    def draw_gameover(self, surf):
        k = clamp(self.over_t / 1.2, 0, 1)
        self.overlay.fill((40, 0, 8))
        self.overlay.set_alpha(int(210 * k))
        surf.blit(self.overlay, (0, 0))
        big(surf, "YOU DIED", W // 2, 60, mul_c((230, 50, 60), 0.3 + 0.7 * k), 4)
        if self.over_t > 1.4:
            lost = int(self.player.gold * MODS['death'])
            if is_iron(self.player):
                txt(surf, "IMPOSSIBLE: this tale ends here. The save is gone.", W // 2, 108, (255, 120, 130), True, 'c')
                if int(self.time * 2) % 2 == 0:
                    txt(surf, "Press ENTER to return to the title", W // 2, 128, GOLD, True, 'c')
            else:
                txt(surf, "The dead keep %d%% of your gold (%dg)." % (int(MODS['death'] * 100), lost), W // 2, 108, CREAM, True, 'c')
                if int(self.time * 2) % 2 == 0:
                    txt(surf, "Press ENTER to awaken in Emberfall", W // 2, 128, GOLD, True, 'c')

