        (3, ['skeleton', 'skeleton', 'slime', 'bat'], 10, 3, 0, (20, 5, 5, 4, ('boots', 'clover', 'amulet', 'ring')), {'might': 4, 'whirl': 1}, "WHIRLWIND"),
        (2, ['archer'], 5, 2, 0, (19, 5, 4, 4, ('boots', 'clover', 'amulet')), {'swift': 2}, "PERFECT DODGE"),
        (3, ['slime', 'skeleton', 'imp', 'bat'], 9, 3, 0, (21, 5, 5, 5, ('boots', 'clover', 'amulet', 'ring', 'crystal')), {'arcana': 5, 'nova': 1}, "FIRE NOVA"),
