    def sh_montage(self, t, first):
        g = self.g
        k = min(len(self.MONT) - 1, int(t / 2.0))
        lt = t - k * 2.0
        if first or k != self.sub:
            self.sub = k
            fl, kinds, n, ef, elite, hero, sk, cap = self.MONT[k]
            self.ts, self.ts_t = 1.0, 0.0
            if k:
                self.cut_fx('flash' if k % 3 else 'hard')
            self.new_hero(*hero[:4], charms=hero[4], skills=sk)
            g.seed = 700 + k * 17
            m = g.get_floor(fl)
            m.enemies = []
            self.teleport_room(m)
            p = g.player
            if kinds:
                if k == 8:
                    self.spawn(kinds, n, ef, 0, 28, 60)
                elif k == 9:
                    self.spawn(kinds, n, ef, 0, 52, 85)
                    for e_ in m.enemies:
                        e_.cd = random.uniform(0.05, 0.7)
                    self.zin = (self.t, 1.8, 1.0, 1.3)
                elif k in (1, 5):
                    self.spawn(kinds, n, ef, 0, 26, 48)
                    self.zin = (self.t, 1.8, 1.0, 1.3)
                    for e_ in m.enemies:
                        if k == 1:
                            e_.maxhp = e_.hp = int(e_.hp * 0.6)
                            e_.state = 'chase'
                        else:
                            e_.summon_cd = 0.25
                            e_.state = 'kite'
                else:
                    self.spawn(kinds, n, ef, elite)
            self.my_chests = []
            if k == 4:
                for dx in (-34, 0, 34):
                    c = Chest(p.x + dx, p.y - 30 + abs(dx) * 0.4, [('gold', 300), ('gem', 1), ('ore', 2)], 0)
                    m.chests.append(c)
                    self.my_chests.append(c)
                for dx in (-62, 62):
                    m.pots.append(Pot(p.x + dx, p.y + 18, 'barrel'))
                self.chest_i = 0
            if k == 11:
                p.xp = xp_needed(p.level) - 1
                self.allow_banner = True
                self.fin = False
            if k in (3, 7, 11):
                for e in m.enemies:
                    pass
            if cap:
                self.cap(cap, 0.15, 1.85, (255, 236, 200), 3, 'slam', H - 40)
        p = g.player
        m = g.map
        k = self.sub
        if k == 4:
            ts = [0.2, 0.7, 1.2]
            if self.chest_i < 3 and lt > ts[self.chest_i]:
                g.open_chest(self.my_chests[self.chest_i])
                self.chest_i += 1
            if lt > 1.5:
                for pt in list(m.pots):
                    g.break_pot(pt)
            p.fx, p.fy = 0, -1
            return
        kinds = self.MONT[k][1]
        self.bot.tick(self.dt, fire=(k != 8))
        if k == 0 and lt > 0.06 and 'dr' not in self.cue:
            self.cue['dr'] = 1
            p.hp = int(p.max_hp * 0.38)
            self.press('hp')
        if k == 9:
            if lt > 0.25 and 'pd' not in self.cue and p.dash_cd <= 0 and p.dash_t <= 0:
                for pr in g.projs:
                    if not pr.friendly and dist(pr.x, pr.y, p.x, p.y - 6) < 46:
                        self.cue['pd'] = pr
                        p.fx, p.fy = norm(-pr.vy, pr.vx)
                        self.press('dash')
                        break
            pr = self.cue.get('pd')
            if pr and p.dash_t > 0 and 'pd2' not in self.cue:
                self.cue['pd2'] = 1
                pr.x, pr.y = p.x - pr.vx * 0.03, p.y - 6 - pr.vy * 0.03
            if g.slow_t > 0 and 'pz' not in self.cue:
                self.cue['pz'] = 1
                self.zoom_pulse(0.22, 0.9)
        if k == 11 and not self.fin:
            alive = [e for e in m.enemies if not e.dead]
            if not alive or p.level > self.MONT[11][5][0]:
                self.fin = True
                self.ts, self.ts_t = 0.35, 0.8
                self.zoom_pulse(0.3, 0.9)
                self.sfx('shimmer', 0.8)
        if k not in (11,):
            self.refill(lt, kinds, self.MONT[k][3], 3)

    def sh_services(self, t, first):
        g = self.g
        if first:
            p = self.new_hero(22, 4, 3, 6, ('amulet', 'boots', 'clover', 'ring', 'crystal'))
            p.rep, p.gold, p.sp = 700, 4820, 3
            p.trophies = set(t_[0] for t_ in TROPHIES[:19])
            p.st.update({'kills': 0, 'k_slime': 50, 'k_bat': 40, 'k_skeleton': 50})
            p.kills = 640
            p.maxfloor = 3
            p.abyss_best = 12
            p.skills = {'might': 4, 'keen': 3, 'deadly': 2, 'arcana': 3, 'vital': 3, 'whirl': 1}
            p.inv.update({'core': 9, 'embershard': 11, 'silk': 7, 'ore': 8, 'gem': 4})
            g.tod = 0.4
            self.phase = -1
            self.cap("FORGE YOUR LEGEND", 0.2, 1.9, (255, 190, 100), 2, 'slam')
        phases = [(0.0, 'smith'), (2.0, 'alch')]
        ph = max(i for i, (a, _) in enumerate(phases) if t >= a)
        if ph != self.phase:
            self.phase = ph
            kind = phases[ph][1]
            if ph:
                self.flashv = 0.7
                self.sfx('whoosh', 0.6)
            if kind in ('smith', 'alch'):
                m = g.get_interior(kind)
                g.enter_map(m)
                g.hide_hud = True
                g.open_shop(kind, m.npcs[0])
                g.shop['sel'] = 3 if kind == 'smith' else 4
                if kind == 'alch':
                    self.cap("BREW", 0.1, 1.8, (140, 255, 200), 2, 'slam')
            elif kind == 'skills':
                g.shop = None
                g.enter_map(g.get_village(), VPOS['spawn'])
                g.open_menu(2)
                g.menu_sel = 0
                self.cap("MASTER", 0.1, 1.8, (140, 220, 255), 2, 'slam')
            else:
                g.menu_tab = 4
                g.menu_sel = 0
                g.trophy_pop = [["Kingslayer", "+1 skill point", 4.0]]
                self.allow_pop = True
                self.cap("EARN GLORY", 0.1, 1.9, GOLD, 2, 'slam')
        kind = phases[self.phase][1]
        a0 = phases[self.phase][0]
        if kind in ('smith', 'alch') and g.shop:
            g.shop['sel'] = min(len(g.shop_items()) - 1, 2 + int((t - a0) * 2.6))
            g.shop['top'] = max(0, g.shop['sel'] - 5)
            g.shop['tab'] = 0
        elif kind == 'skills':
            g.menu_sel = int((t - 4.0) * 3.5) % len(SKILLS)
        elif kind == 'trophy':
            g.menu_sel = int((t - 8.0) * 4) % len(TROPHIES)

    # weapon, enemy, forced combo step, caption, colour
    ARMS = [(2, 'skeleton', 0, "STEEL SWORD", (170, 205, 255)),
            (3, 'archer', 0, "MITHRIL EDGE", (150, 245, 255)),
            (4, 'knight', 2, "EMBERBRAND", (255, 160, 80)),
            (5, 'skeleton', 2, "VOIDSTEEL", (200, 130, 255)),
            (6, 'knight', 2, "DRAGONBONE", (255, 240, 210))]

    def sh_anim(self, t, first):
        """6 s: five weapons, five swings, five different deaths"""
        g = self.g
        if first:
            self.sub = -1
        si = min(4, int(t / 1.2))
        lt = t - si * 1.2
        if si != self.sub:
            self.sub = si
            self.cue = {}
            self.ts, self.ts_t = 1.0, 0.0
            if si:
                self.flashv = 0.8
                self.sfx('whoosh', 0.7)
            wt, kind, step, name, col = self.ARMS[si]
            p = self.new_hero(22, wt, 4, 5, ('boots', 'clover'))
            g.hide_hud = True
            for sd in (4242, 11, 12, 13, 14, 15, 16, 17):
                g.seed = sd
                g.floors.pop(1, None)
                m = g.get_floor(1)
                rr = max([r_ for r_ in m.rooms[1:] if r_[2] * r_[3] > 60] or m.rooms, key=lambda r_: r_[2] * r_[3])
                cx_, cy_ = (rr[0] + rr[2] // 2) * 16 + 8, (rr[1] + rr[3] // 2) * 16 + 8
                if not any(dist(i_[0], i_[1], cx_, cy_) < 90 for i_ in m.interacts):
                    break
            m.enemies = []
            self.teleport_room(m)
            p.dir = 3
            p.fx, p.fy = 1.0, 0.0
            p.combo = step - 1 if step else 0
            p.combo_t = 0.5 if step else 0.0
            e = Enemy(kind, p.x + (24 if wt == 3 else 21), p.y, 2)
            setattr(e, 'ai_' + kind, lambda *a: None)
            e.dir = 2
            e.stun = 9.0
            e.maxhp = e.hp = 900
            m.enemies.append(e)
            self.dummy = e
            g.glow(e.x, e.y - 8, 90, (255, 226, 180), 2.4)
            self.zin = (self.t, 1.2, 1.3, 1.85)
            self.cap(name, 0.05, 1.15, col, 2, 'slam', H - 36)
        g.hide_hud = True
        p = g.player
        if lt >= 0.12 and 'sw' not in self.cue:
            self.cue['sw'] = 1
            p.fx, p.fy = 1.0, 0.0
            self.dummy.hp = 1
            self.press('attack')
            self.zoom_pulse(0.12, 0.7)

    def sh_world(self, t, first):
        g = self.g
        if first:
            self.sub = -1
            self.new_hero(26, 5, 5, 8, ('boots', 'clover', 'ring', 'crystal', 'amulet'),
                          {'might': 4, 'keen': 4, 'vital': 4, 'arcana': 4})
            self.g.seed = 5150
        si = min(2, int(t / 2.0))
        if si != self.sub:
            self.sub = si
            if si:
                self.flashv = 0.8
                self.sfx('whoosh', 0.7)
            if si == 0:
                g.hide_hud = True
                m = g.get_abyss(6)
                m.enemies = []
                r = self.teleport_room(m)
                p = g.player
                kinds = ['slime', 'bat', 'spider', 'skeleton', 'archer', 'imp', 'wraith', 'golem', 'knight', 'necro']
                self.lineup = []
                cx, cy = p.x, p.y - 24
                for i, kd in enumerate(kinds):
                    e = Enemy(kd, cx - 137 + i * 30.5, cy + (i % 2) * 6, 3)
                    e.update = (lambda gg, dd: None)
                    m.enemies.append(e)
                    self.lineup.append(e)
                self.look = (cx, cy)
                p.x, p.y = cx, cy + 62
                self.cap("NEW HORRORS", 0.2, 1.9, (255, 120, 120), 2, 'slam')
            elif si == 1:
                g.hide_hud = False
                self.lineup = []
                self.cue = {}
                p = g.player
                p.relics = ['fang']
                m = g.get_floor(3)
                m.enemies = []
                al = [i for i in m.interacts if i[3] == 'shrine' and i[4].data['kind'] == 'relic']
                x_, y_ = (al[0][0], al[0][1] + 14) if al else (m.spawn[0], m.spawn[1])
                g.enter_map(m, (x_, y_))
                g.banner = None
                if al:
                    g.open_relic(al[0][4])
                    g.relic_ui['t'] = 1.0
                self.cap("CLAIM A RELIC", 0.1, 1.9, (255, 214, 120), 2, 'slam', H - 22)
            else:
                self.lineup = []
                self.cue = {}
                p = g.player
                p.st['bosses'] = 2
                p.heat = 1
                E_ = recalc_mods(p)
                g.tod = 0.88
                g.enter_map(g.get_village(), VPOS['spawn'])
                g.banner = None
                g.hide_hud = False
                bp = getattr(g.map, 'pact_pos', None)
                if bp:
                    p.x, p.y = bp[0] + 2, bp[1] + 18
                    g.cam = [p.x - W / 2, p.y - H / 2]
                g.open_pact()
                self.cap("STOKE THE EMBER PACT", 0.1, 1.9, (255, 150, 90), 2, 'slam', 40)
        if si == 0:
            p = g.player
            g.cam_off = [self.look[0] - p.x, self.look[1] - p.y - 6]
        else:
            g.cam_off = [0, 0]
        lt = t - si * 2.0
        if si == 1 and g.state == 'relic':
            g.relic_ui['sel'] = min(len(g.relic_ui['opts']) - 1, int(lt * 3.2))
            if lt > 1.35 and 'pick' not in self.cue:
                self.cue['pick'] = 1
                self.press('ok')
                self.zoom_pulse(0.2, 0.6)
        if si == 2:
            if g.dlg:
                g.dlg['shown'] = 999
            for i, tt in enumerate((0.5, 1.0, 1.5)):
                if lt >= tt and i not in self.cue and g.state == 'dialog':
                    self.cue[i] = 1
                    self.press('ok')
                    self.zoom_pulse(0.16, 0.5)
                    self.flashv = max(self.flashv, 0.35)

    def sh_boss(self, t, first):
        g = self.g
        if first:
            p = self.new_hero(17, 4, 4, 4, ('boots', 'clover', 'ring', 'crystal'), {'might': 2, 'keen': 2, 'vital': 3})
            g.tod = 0.4
            m = g.get_floor(4)
            g.enter_map(m, (13 * 16, 17 * 16 + 8))
            m.boss.hp = int(m.boss.maxhp * 0.9)
            g.banner = None
            self.cap("FACE THE HOLLOW KING", 0.2, 3.4, (235, 150, 255), 2, 'slam')
            self.roared = False
            self.zoomed = False
        p = g.player
        b = g.map.boss
        p.hp = max(p.hp, p.max_hp * 0.5)
        if t < 12.2 and not b.dead and b.hp < b.maxhp * 0.12:
            b.hp = int(b.maxhp * 0.12)
        if t > 12.2 and not b.dead and b.hp > 1:
            b.hp = 1
        if t > 12.9 and not b.dead and g.state == 'play':
            g.boss_hit(b, 99999, True)
        if g.state == 'play':
            if b.state == 'dormant':
                self.hold('up')
            else:
                self.bot.tick(self.dt, fire=True)
        if t > 7.5 and not self.roared:
            self.roared = True
            self.cap("NO ONE RETURNS.", 0.1, 2.4, (255, 120, 120), 2, 'slam')
        if t > 13.4 and 'fall' not in self.cue:
            self.cue['fall'] = 1
            self.cap("THE KING FALLS.", 0.0, 2.4, GOLD, 2, 'slam')
        if b.dead and not self.zoomed:
            self.zoomed = True
            self.zoom_pulse(0.35, 1.2)
            self.ts, self.ts_t = 0.45, 1.6

    def sh_abyss(self, t, first):
        g = self.g
        if first:
            self.new_hero(30, 6, 6, 10, ('boots', 'clover', 'ring', 'crystal', 'amulet', 'horn', 'phoenix'),
                          {'might': 5, 'keen': 5, 'deadly': 4, 'whirl': 1, 'vital': 5, 'arcana': 5, 'nova': 1, 'swift': 3})
            p = g.player
            p.abyss_best = 4
            g.seed = 31337
            self.sub = -1
            self.cap("THEN THE FLOOR OPENED...", 0.2, 3.0, (150, 220, 255), 2, 'type')
        subs = [(0.0, 5, "DEPTH 5"), (4.0, 10, "DEPTH 10"), (8.0, 20, "DEPTH 20")]
        si = max(i for i, s in enumerate(subs) if t >= s[0])
        if si != self.sub:
            self.sub = si
            _, depth, lab = subs[si]
            self.sfx('portal', 0.9)
            self.cut_fx('hard' if si else 'flash')
            m = g.get_abyss(depth)
            self.teleport_room(m)
            self.spawn(['spider', 'golem', 'imp', 'wraith', 'skeleton', 'archer'], 7, 3 + 0.55 * depth, 2)
            g.banner = [m.name, 0.0]
            self.depth_txt = (lab, self.st)
            if si == 1:
                sh = [i for i in m.interacts if i[3] == 'shrine']
                if sh:
                    g.use_shrine(sh[0][4])
        self.bot.tick(self.dt)
        g.player.hp = max(g.player.hp, g.player.max_hp * 0.5)
        if t > 9.0 and 'lv' not in self.cue:
            self.cue['lv'] = 1
            self.allow_pop = True
            g.trophy_pop.append(["Beyond the Veil", "+3 skill points", 3.5])
            self.sfx('trophy', 0.8)
        if t > 9.7 and 'end' not in self.cue:
            self.cue['end'] = 1
            self.cap("BUT THE DEPTHS HAVE NO END.", 0.0, 2.35, (255, 235, 200), 2, 'type')
        self.refill(t, ['spider', 'imp', 'wraith', 'skeleton'], 3 + 0.55 * 10, 4, 90, 130)

    def sh_predrop(self, t, first):
        if first:
            self.scene = self.scene_predrop
            self.g.hide_hud = True
            self.g.state = 'title'
            self.cue = {}
        for i, tt in enumerate((0.25, 0.375, 0.75, 0.875, 1.25, 1.375, 1.625, 1.75)):
            if t >= tt and i not in self.cue:
                self.cue[i] = 1
                self.sfx('heartbeat', 0.9)

    def sh_title(self, t, first):
        g = self.g
        if first:
            g.state = 'title'
            g.hide_hud = True
            g.title_sel = 0
            g.title_sub = None
            self.sfx('boom', 1.0)
            self.sfx('impact', 1.0)
            self.flashv = 1.0
            g.shake(6)
            self.zoom_pulse(0.22, 0.6)
            self.scene = self.scene_title
        g.hide_hud = True
        g.state = 'title'
        if t >= 0.0 and 'b' not in self.cue and t > 2.0:
            self.cue['b'] = 1
            self.sfx('whoosh', 0.6)
        for tt, key in ((4.9, 'c'), (7.6, 'd')):
            if t >= tt and key not in self.cue:
                self.cue[key] = 1
                self.sfx('impact', 0.7)
                self.flashv = 0.35
        if t > 9.9:
            self.fadev = max(self.fadev, clamp((t - 9.9) / 0.8, 0, 1))
            self.fadev += 0.0

